// ═════════════════════════════════════════════════════════════════════
// app.js — Lógica de la app extraída desde index.html en Refactor Fase 2
// El orden de definición se mantiene EXACTAMENTE como estaba en el HTML
// ═════════════════════════════════════════════════════════════════════

// ── Etiqueta de versión: muestra el ?v= del app.js realmente cargado, para
//    poder verificar de un vistazo si el navegador tiene la última versión o
//    está sirviendo una en caché. ──
(function _showAppVersion(){
  function set(){
    try{
      const s=[...document.getElementsByTagName('script')].find(x=>/assets\/js\/app\.js/.test(x.src||''));
      const m=s && (s.src||'').match(/[?&]v=([^&]+)/);
      const el=document.getElementById('appVersionBadge');
      if(el) el.textContent = m ? ('v·'+decodeURIComponent(m[1])) : 'v·(sin versión)';
    }catch(_){}
  }
  if(document.readyState!=='loading') set();
  else document.addEventListener('DOMContentLoaded', set);
})();

// ── Bloque A (original: líneas 1733-18150 del index.html monolítico) ──
if(window.pdfjsLib){pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'}
function toggleLoadPanel(){
  const body=$('loadPanelBody');
  const chevron=$('loadChevron');
  const bar=$('loadBar');
  if(!body) return;
  const isOpen=!body.classList.contains('collapsed');
  body.classList.toggle('collapsed', isOpen);
  if(chevron) chevron.classList.toggle('closed', isOpen);
  if(bar) bar.classList.toggle('load-bar-open', !isOpen);
}

/* Colapsa el panel de carga y actualiza la etiqueta con el nombre de la carrera */
function _collapseLoadPanel(){
  const body=$('loadPanelBody');
  const chevron=$('loadChevron');
  const bar=$('loadBar');
  const label=$('loadBarLabel');
  if(!body) return;
  // Actualizar texto con el nombre de la carrera
  const raceName=$('raceName')?.value||'';
  const raceDate=$('raceDate')?.value||'';
  if(label){
    label.innerHTML=raceName
      ? `✅ <b>${escapeHtml(raceName)}</b>${raceDate?` · <span style="color:#667085;font-weight:400">${escapeHtml(raceDate)}</span>`:''}`
      : '📂 Cargar / editar clasificación';
  }
  body.classList.add('collapsed');
  if(chevron) chevron.classList.add('closed');
  if(bar) bar.classList.remove('load-bar-open');
}

function openLoadPanelForNew(){
  // Limpiar todos los campos del formulario
  ['raceName','raceDate','raceKm','raceAvg','raceLocalidad','raceCircuitType','pastedText','pastedInscritos'].forEach(id=>{
    const el=$(id); if(el) el.value='';
  });
  if($('raceChallengeCV')) $('raceChallengeCV').checked = false;
  if($('raceCCAA')) $('raceCCAA').value = '';
  const fn=$('fileName'); if(fn) fn.textContent='';
  const fnI=$('fileNameInscritos'); if(fnI) fnI.textContent='';
  // Reset inscritos (Tier 1)
  if(typeof inscritos !== 'undefined') inscritos = [];
  if(typeof _updateInscritosUI === 'function') _updateInscritosUI();
  const badge=$('avgCalcBadge'); if(badge) badge.style.display='none';
  const hint=$('raceDateHint'); if(hint) hint.textContent='';
  const sb=$('successBanner'); if(sb) sb.style.display='none';
  // Resetear datos
  riders=[]; filtered=[];
  renderStats && renderStats();
  // Abrir panel
  const body=$('loadPanelBody');
  const chevron=$('loadChevron');
  const bar=$('loadBar');
  if(body){ body.classList.remove('collapsed'); }
  if(chevron){ chevron.classList.remove('closed'); }
  if(bar){ bar.classList.add('load-bar-open'); }
  // Ir a la vista de carga si no estamos ya
  showView('view-carga');
  setTimeout(()=>{ const dz=$('dropZone'); if(dz) dz.scrollIntoView({behavior:'smooth',block:'nearest'}); },100);
}

// ═══════════════════════════════════════════════════════════════════════════
// SECCIONES DEL MENÚ (Paso 3 del rediseño UX) — colapsar/expandir
// ═══════════════════════════════════════════════════════════════════════════
function _navToggleSection(sectionId){
  const sec = document.querySelector(`.nav-section[data-section="${sectionId}"]`);
  if(!sec) return;
  sec.classList.toggle('collapsed');
  // Persistir estado
  try{
    const collapsed = {};
    document.querySelectorAll('.nav-section[data-section]').forEach(s=>{
      collapsed[s.dataset.section] = s.classList.contains('collapsed');
    });
    localStorage.setItem('nav_sections_collapsed', JSON.stringify(collapsed));
  }catch(_){}
}
function _navRestoreSections(){
  try{
    const raw = localStorage.getItem('nav_sections_collapsed');
    if(!raw) return;
    const collapsed = JSON.parse(raw);
    Object.entries(collapsed).forEach(([id, val])=>{
      const sec = document.querySelector(`.nav-section[data-section="${id}"]`);
      if(sec && val) sec.classList.add('collapsed');
    });
  }catch(_){}
}
// Auto-expandir la sección que contiene la vista activa
function _navAutoExpandActive(viewId){
  const btn = document.querySelector(`.nav-btn[data-view="${viewId}"]`);
  if(!btn) return;
  const sec = btn.closest('.nav-section');
  if(sec && sec.classList.contains('collapsed')){
    sec.classList.remove('collapsed');
    // No persistimos esta auto-expansión (solo al click del usuario)
  }
}
// Llamar tras DOM ready
if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded', _navRestoreSections);
} else {
  setTimeout(_navRestoreSections, 0);
}

// ═══════════════════════════════════════════════════════════════════════════
// FILTROS GLOBALES (Paso 2 del rediseño UX)
// ═══════════════════════════════════════════════════════════════════════════
const _GF_YEAR_IDS   = ['evolYearFilter','prYearFilter','trendYearFilter','selYearFilter','selTeamYearFilter','resumenYear'];
const _GF_REGION_IDS = ['prRegionFilter','trendRegionFilter','selRegionFilter','selTeamRegionFilter'];
const _GF_VIEWS_USING_HISTORY = ['view-inicio','view-evolucion','view-powerranking','view-laboratorio','view-tendencias','view-seleccion','view-resumen','view-historial','view-calendario','view-informe-plantilla','view-challenge','view-equipos-ccaa','view-ciclistas-cat','view-tabla','view-analisis','view-comparativo','view-equipos','view-graficos','view-top10','view-tactica','view-simulador'];

let _globalFilters = {
  year:     localStorage.getItem('gf_year')     || '',
  region:   localStorage.getItem('gf_region')   || '',
  cat:      localStorage.getItem('gf_cat')      || 'cadete',
  modality: localStorage.getItem('gf_modality') || 'carretera',
  gender:   localStorage.getItem('gf_gender')   || 'masculino'
};

// ── Detectores de coincidencia con los filtros globales ──────────────────
// Reciben un "blob" de texto (categoría guardada + nombre de la prueba, etc.)
// y deciden si esa prueba/corredor encaja con la Categoría/Modalidad globales.
// Lógica: si aparece MI categoría → SÍ. Si aparece OTRA categoría exclusiva y
// NO la mía → NO. Si no se detecta nada → SÍ (permisivo, no escondemos por
// falta de dato).
const _GF_CAT_TOKENS = {
  cadete:   /\bcadet|\bcad[-\s.]?\d|\bcad\b/i,
  junior:   /\bj[uú]nior|\bjuvenil|\bjun[-\s.]?\d|\bjun\b/i,
  sub23:    /\bsub.?23\b|\bs23\b/i,
  elite:    /\b[eé]lite\b|\bel\b/i,
  master:   /\bmaster\b|\bm[-\s]?\d{2}/i,
  femenino: /\bfemenin|\bfem\b|\bfem\./i
};
const _GF_MOD_TOKENS = {
  // OJO: NO incluir "ruta" en carretera — aparece en nombres de pruebas que
  // no son de carretera (ej. "MARCHA CICLOTURISTA RUTA 99").
  carretera:    /\bcarretera\b/i,
  btt:          /\bbtt\b|\bmtb\b|monta[ñn]a/i,
  cx:           /ciclo.?cross|cyclo.?cross|\bcx\b/i,
  pista:        /\bpista\b/i,
  trial:        /\btrial\b/i,
  // Las 3 siguientes NO están en el desplegable del filtro pero las
  // incluimos para que el detector reconozca esas pruebas como "otra
  // modalidad" y las EXCLUYA cuando el filtro es Carretera/BTT/etc.
  bmx:          /\bbmx\b/i,
  cicloturismo: /cicloturis|ciclodeportiv|ciclismo\s+para\s+todos|ciclodep|a\s+partir\s+de\s+\d+\s*a[ñn]?o?s?|gran\s+fondo|\bmarcha\b/i,
  escuelas:     /\bescuela|\bescola/i
};
// Categorías "menores" que NO deben mezclarse con las adultas competitivas
// (regla de negocio: una prueba de Cadete mezclada con Escuela/Infantil/
// Alevín NO es una prueba de cadete "pura" y debe descartarse).
const _GF_MENOR_RE = /\bescuela|\bescola|\binfantil|\balev[ií]n|\bprincipiant|\bpromesa|\bbenjam[ií]n|\bpre.?infantil|\bpre.?benjam|\bprincipiant/i;
function _gfMatchesGlobalCat(blob){
  const gfCat = (typeof _globalFilters!=='undefined' && _globalFilters && _globalFilters.cat) || '';
  if(!gfCat) return true;
  const t = String(blob||'');
  // Exclusión: si el filtro es una categoría adulta competitiva, descartar
  // pruebas que mezclen escuela/infantil/alevín/principiantes/promesas.
  const adultas = ['cadete','junior','sub23','elite','master'];
  if(adultas.includes(gfCat) && _GF_MENOR_RE.test(t)) return false;
  const myRe = _GF_CAT_TOKENS[gfCat];
  if(myRe && myRe.test(t)) return true;          // contiene MI categoría
  for(const k in _GF_CAT_TOKENS){                 // ¿contiene OTRA exclusiva?
    if(k===gfCat) continue;
    if(_GF_CAT_TOKENS[k].test(t)) return false;
  }
  return true;                                    // nada claro → permisivo
}
// Categoría por defecto al IMPORTAR (cuando el archivo no trae categoría):
// usamos la del FILTRO GLOBAL activo, para no asignar 'CADETE' a todo el mundo.
const _CAT_IMPORT_LABEL = { cadete:'CADETE', junior:'JUNIOR', sub23:'SUB-23', elite:'ELITE', master:'MASTER', femenino:'FEMENINO' };
function _defaultImportCat(){
  const c=(typeof _globalFilters!=='undefined' && _globalFilters && _globalFilters.cat) || '';
  return _CAT_IMPORT_LABEL[c] || '';   // '' si el filtro global es "Todas"
}
function _gfMatchesGlobalMod(blob){
  const gfMod = (typeof _globalFilters!=='undefined' && _globalFilters && _globalFilters.modality) || '';
  if(!gfMod) return true;
  const t = String(blob||'');
  const myRe = _GF_MOD_TOKENS[gfMod];
  if(myRe && myRe.test(t)) return true;
  for(const k in _GF_MOD_TOKENS){
    if(k===gfMod) continue;
    if(_GF_MOD_TOKENS[k].test(t)) return false;
  }
  return true;
}

// Detector de género. catField = lista de categorías (ej: "Cadete, Cadete
// Fem."), nameField = nombre de la prueba.
//  - masculino: pasa si hay al menos UNA categoría NO femenina (un equipo
//    masculino puede correr una prueba mixta que también tenga cat. femenina).
//  - femenino: pasa solo si hay al menos una categoría femenina.
//  - mixto / "" : no filtra.
const _GF_FEM_RE = /\bfem(en[ií]n[oa]?)?\b|\bfem\.|femeni|\bmujer|\bdona\b|\bdones\b/i;

// ── Detector COMBINADO categoría + género ────────────────────────────────
// Comprueba que la prueba tenga AL MENOS UNA categoría que cumpla a la vez
// la categoría Y el género globales. Resuelve el caso "Cadete Fem., Elite":
// tiene "cadete" y tiene algo "masculino" (Elite) por separado, pero NINGUNA
// categoría es "cadete masculino" → debe excluirse para un director cadete-M.
function _gfMatchesCatGender(catField, nameField){
  const gfCat = (typeof _globalFilters!=='undefined' && _globalFilters && _globalFilters.cat) || '';
  const gfGen = (typeof _globalFilters!=='undefined' && _globalFilters && _globalFilters.gender) || '';
  const blob = `${catField||''} ${nameField||''}`;
  // Exclusión escuela/infantil/alevín si el filtro es categoría adulta
  const adultas = ['cadete','junior','sub23','elite','master'];
  if(gfCat && adultas.includes(gfCat) && _GF_MENOR_RE.test(blob)) return false;
  // Tokens de la lista de categorías (descartando basura "..." y vacíos)
  const tokens = String(catField||'').split(/[,;]/)
    .map(s=>s.trim())
    .filter(s=> s.length>=2 && /[a-záéíóúñ]/i.test(s));
  const catRe = gfCat ? _GF_CAT_TOKENS[gfCat] : null;
  const tokenOK = (tk)=>{
    if(catRe && !catRe.test(tk)) return false;          // no es mi categoría
    if(gfGen && gfGen!=='mixto'){
      const isFem = _GF_FEM_RE.test(tk);
      if(gfGen==='masculino' && isFem) return false;     // pedida M, token es F
      if(gfGen==='femenino'  && !isFem) return false;    // pedida F, token es M
    }
    return true;
  };
  if(tokens.length){
    // Con lista de categorías: exige al menos un token que cumpla cat+género
    return tokens.some(tokenOK);
  }
  // Sin lista de categorías: caemos a detección por nombre (permisiva)
  if(!_gfMatchesGlobalCat(blob)) return false;
  if(!_gfMatchesGlobalGender(catField||'', nameField||'')) return false;
  return true;
}
function _gfMatchesGlobalGender(catField, nameField){
  const g = (typeof _globalFilters!=='undefined' && _globalFilters && _globalFilters.gender) || '';
  if(!g || g==='mixto') return true;
  const cat = String(catField||'');
  const name = String(nameField||'');
  // Estrategia 1: lista de categorías (lo más fiable).
  // Filtramos tokens basura: "..." de truncado, vacíos, o sin letras —
  // antes "..." se contaba como categoría masculina y colaba pruebas fem.
  const tokens = cat.split(/[,;]/)
    .map(s=>s.trim())
    .filter(s=> s.length>=2 && /[a-záéíóúñ]/i.test(s));
  if(tokens.length){
    const femTokens  = tokens.filter(tk=>_GF_FEM_RE.test(tk));
    const maleTokens = tokens.filter(tk=>!_GF_FEM_RE.test(tk));
    if(g==='masculino') return maleTokens.length>0;
    if(g==='femenino')  return femTokens.length>0;
  }
  // Estrategia 2: nombre de la prueba
  const nameFem = _GF_FEM_RE.test(name);
  if(g==='masculino') return !nameFem;
  if(g==='femenino')  return nameFem;
  return true;
}

// Restaurar valores de los 3 nuevos filtros en los selects al iniciar
function _gfDefaultsApplyToSelects(){
  const cat = document.getElementById('gfCat');
  const mod = document.getElementById('gfMod');
  const gen = document.getElementById('gfGen');
  if(cat && [...cat.options].some(o=>o.value===_globalFilters.cat)) cat.value = _globalFilters.cat;
  if(mod && [...mod.options].some(o=>o.value===_globalFilters.modality)) mod.value = _globalFilters.modality;
  if(gen && [...gen.options].some(o=>o.value===_globalFilters.gender)) gen.value = _globalFilters.gender;
}

// Fase B: aplica los filtros globales (cat/modality/gender) a los selectores
// LOCALES de las vistas que los usan. De momento sincroniza el panel FCCV
// del Calendario, cuyos valores coinciden 1:1 con los del filtro global.
function _gfApplyDefaultsToView(viewId){
  try{
    const {cat, modality, gender} = _globalFilters;
    if(viewId === 'view-calendario'){
      const c = document.getElementById('fccvCat');
      const m = document.getElementById('fccvMod');
      const g = document.getElementById('fccvGen');
      if(c && [...c.options].some(o=>o.value===cat))      c.value = cat;
      if(m && [...m.options].some(o=>o.value===modality)) m.value = modality;
      if(g && [...g.options].some(o=>o.value===gender))   g.value = gender;
    }
  }catch(e){ console.warn('[gf] aplicar defaults a vista falló:', e); }
}

// Al cambiar Categoría / Modalidad / Género: persistir y disparar cascada
async function _gfDefaultsOnChange(){
  _globalFilters.cat      = document.getElementById('gfCat')?.value || '';
  _globalFilters.modality = document.getElementById('gfMod')?.value || '';
  _globalFilters.gender   = document.getElementById('gfGen')?.value || '';
  try{
    localStorage.setItem('gf_cat',      _globalFilters.cat);
    localStorage.setItem('gf_modality', _globalFilters.modality);
    localStorage.setItem('gf_gender',   _globalFilters.gender);
  }catch(_){}
  // Persistencia por usuario en Supabase (silently ignora si las columnas no existen)
  if(_sb && _rbacUser?.email){
    try{
      await _sb.from('app_users').update({
        my_cat:      _globalFilters.cat,
        my_modality: _globalFilters.modality,
        my_gender:   _globalFilters.gender
      }).eq('email', _rbacUser.email);
    }catch(_){}
  }
  _gfUpdateStatus();
  // Sincronizar los selectores locales de la vista activa (si procede)
  try{
    const activeView = document.querySelector('.spa-view.active');
    if(activeView) _gfApplyDefaultsToView(activeView.id);
  }catch(_){}
  _gfTriggerCurrentViewRerender();
  // Notificar al resto de la app
  try{ window.dispatchEvent(new CustomEvent('myfilters:changed', {detail:{..._globalFilters}})); }catch(_){}
}

// ═══════════════════════════════════════════════════════════════════════════
// MI EQUIPO GLOBAL — selector persistente en la barra de filtros
// (Fase 1 del rediseño: ubicación + autocompletar + persistencia + cascada)
// ═══════════════════════════════════════════════════════════════════════════
function _gfMyTeamInit(){
  // Restaurar valor desde la variable global ya existente (que se carga
  // desde localStorage al arrancar el script — ver definición de `myTeam`).
  const inp = document.getElementById('gfMyTeam');
  if(!inp) return;
  inp.value = (typeof myTeam!=='undefined' && myTeam) ? myTeam : '';
  _gfMyTeamUpdateChip(inp.value);
}

function _gfMyTeamGetAvailableTeams(){
  // Lista única de equipos del histórico (más frecuente primero)
  const counts = new Map();
  if(typeof _cachedHistory !== 'undefined' && Array.isArray(_cachedHistory)){
    for(const race of _cachedHistory){
      for(const r of (race.riders||[])){
        const t = (r.team||'').trim();
        if(!t) continue;
        counts.set(t, (counts.get(t)||0)+1);
      }
    }
  }
  return [...counts.entries()].sort((a,b)=>b[1]-a[1]).map(([t,n])=>({team:t, n}));
}

function _gfMyTeamSearch(){
  const inp = document.getElementById('gfMyTeam');
  const dd  = document.getElementById('gfMyTeamDropdown');
  if(!inp || !dd) return;
  const q = (inp.value||'').toLowerCase().trim();
  const all = _gfMyTeamGetAvailableTeams();
  const matches = q ? all.filter(x=>x.team.toLowerCase().includes(q)) : all;
  const top = matches.slice(0, 50);
  if(!top.length){
    dd.innerHTML = `<div style="padding:10px 14px;color:#9ca3af;font-size:12px">Sin coincidencias en el histórico.</div>`;
  } else {
    dd.innerHTML = top.map(x=>{
      const safe = escapeHtml(x.team);
      return `<div onclick="_gfMyTeamPick('${escapeAttr(x.team)}')" style="padding:7px 12px;cursor:pointer;font-size:12px;border-bottom:1px solid #fef3c7;display:flex;justify-content:space-between;gap:8px" onmouseenter="this.style.background='#fffbeb'" onmouseleave="this.style.background=''"><span style="font-weight:700;color:#78350f">${safe}</span><span style="font-size:10px;color:#92400e;font-weight:700;background:#fef3c7;padding:1px 6px;border-radius:4px">×${x.n}</span></div>`;
    }).join('');
  }
  dd.style.display = 'block';
}

function _gfMyTeamPick(team){
  const inp = document.getElementById('gfMyTeam');
  if(inp) inp.value = team;
  _gfMyTeamCloseDropdown();
  // Marcar el botón Guardar como "pendiente" (cambio sin guardar)
  const btn = document.getElementById('gfMyTeamSaveBtn');
  if(btn){ btn.style.background = '#f59e0b'; btn.title = 'Hay cambios sin guardar — pulsa para confirmar'; }
}

function _gfMyTeamCloseDropdown(){
  const dd = document.getElementById('gfMyTeamDropdown');
  if(dd) dd.style.display = 'none';
}

function _gfMyTeamUseLastRace(){
  // "Ajustar con el equipo de la última prueba cargada"
  // Estrategia: si hay una prueba activa en memoria (`riders`), busca el equipo
  // más frecuente entre esos riders. Si no, toma la última del histórico.
  let pickedTeam = '';
  try{
    if(typeof riders !== 'undefined' && Array.isArray(riders) && riders.length){
      const c = new Map();
      for(const r of riders){
        const t = (r.team||'').trim();
        if(t) c.set(t, (c.get(t)||0)+1);
      }
      const sorted = [...c.entries()].sort((a,b)=>b[1]-a[1]);
      if(sorted.length) pickedTeam = sorted[0][0];
    }
    if(!pickedTeam && typeof _cachedHistory!=='undefined' && Array.isArray(_cachedHistory) && _cachedHistory.length){
      // Tomar la prueba más reciente y su equipo más representado
      const sorted = [..._cachedHistory].sort((a,b)=>{
        const da = _parseSpanishDate(a.raceDate)||a.raceDate||'';
        const db = _parseSpanishDate(b.raceDate)||b.raceDate||'';
        return db.localeCompare(da);
      });
      const last = sorted[0];
      if(last){
        const c = new Map();
        for(const r of (last.riders||[])){
          const t = (r.team||'').trim();
          if(t) c.set(t, (c.get(t)||0)+1);
        }
        const s = [...c.entries()].sort((a,b)=>b[1]-a[1]);
        if(s.length) pickedTeam = s[0][0];
      }
    }
  }catch(e){ console.warn(e); }
  if(!pickedTeam){
    alert('No se pudo deducir el equipo: no hay prueba cargada ni histórico disponible.');
    return;
  }
  _gfMyTeamPick(pickedTeam);
}

async function _gfMyTeamSave(){
  const inp = document.getElementById('gfMyTeam');
  if(!inp) return;
  const val = (inp.value||'').trim();
  // Actualizar variable global existente
  if(typeof setMyTeam === 'function'){
    setMyTeam(val);
  } else {
    // Fallback directo a localStorage si setMyTeam aún no está definido
    try{ localStorage.setItem('myTeam', val); }catch(_){}
    try{ myTeam = val; }catch(_){}
  }
  // Persistencia adicional por usuario en Supabase (si la columna existe)
  if(_sb && _rbacUser?.email){
    try{
      await _sb.from('app_users').update({my_team: val}).eq('email', _rbacUser.email);
    }catch(_){ /* columna no existe aún — solo se persiste local */ }
  }
  // Visual: botón vuelve a verde
  const btn = document.getElementById('gfMyTeamSaveBtn');
  if(btn){ btn.style.background = '#10b981'; btn.title = 'Guardar selección'; }
  _gfMyTeamUpdateChip(val);
  // Emitir evento para que los módulos que escuchan se refresquen en cascada
  try{ window.dispatchEvent(new CustomEvent('myteam:changed', {detail:{team:val}})); }catch(_){}
  // Refrescar la vista activa
  _gfTriggerCurrentViewRerender();
  // Toast confirmación
  try{
    const t=document.createElement('div');
    t.style.cssText='position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#10b981;color:#fff;padding:12px 18px;border-radius:10px;font-weight:700;box-shadow:0 6px 18px rgba(0,0,0,.25);z-index:99999;font-size:13px';
    t.textContent = val ? `🏆 Mi Equipo: ${val}` : '🏆 Mi Equipo desactivado (verás datos globales)';
    document.body.appendChild(t);
    setTimeout(()=>t.remove(),3000);
  }catch(_){}
}

function _gfMyTeamUpdateChip(val){
  const inp = document.getElementById('gfMyTeam');
  if(!inp) return;
  if(val){
    inp.style.background = '#fffbeb';
    inp.style.color = '#78350f';
    inp.style.borderColor = '#fcd34d';
  } else {
    inp.style.background = '#fff';
    inp.style.color = '#9ca3af';
    inp.style.borderColor = '#e5e7eb';
  }
}

// ── Cascada Fase 3: escuchar el evento global myteam:changed ──
// Cualquier módulo que necesite reaccionar al cambio de equipo puede
// suscribirse aquí. Sincroniza el chip visual + invalida caches relevantes.
window.addEventListener('myteam:changed', (ev)=>{
  // Refrescar el chip visual del selector (por si el cambio viene de otro sitio)
  try{ _gfMyTeamUpdateChip((ev?.detail?.team)||''); }catch(_){}
  // Invalidar cache que dependa del equipo (no del histórico bruto)
  try{ if(typeof invalidateTeamRegionDB==='function') invalidateTeamRegionDB(); }catch(_){}
  // Re-render de la vista activa (idempotente — Save también lo invoca)
  try{ if(typeof _gfTriggerCurrentViewRerender==='function') _gfTriggerCurrentViewRerender(); }catch(_){}
});
let _gfReady = false;
let _gfSyncing = false; // evitar loops cuando propagamos

function _gfPopulateYears(){
  const sel = document.getElementById('gfYear');
  if(!sel) return;
  const years = new Set();
  if(typeof _cachedHistory !== 'undefined' && Array.isArray(_cachedHistory)){
    _cachedHistory.forEach(race=>{
      const y = (_parseSpanishDate(race.raceDate)||'').slice(0,4);
      if(y) years.add(y);
    });
  }
  // Incluir año actual si no hay datos
  if(!years.size) years.add(String(new Date().getFullYear()));
  const sortedYears = [...years].sort().reverse();
  const currentValue = _globalFilters.year || '';
  sel.innerHTML = '<option value="">Todos los años</option>' + sortedYears.map(y=>`<option value="${y}">${y}</option>`).join('');
  if([...sel.options].some(o=>o.value===currentValue)) sel.value = currentValue;
}

function _gfPopulateRegions(){
  const sel = document.getElementById('gfRegion');
  if(!sel) return;
  // Lista de CCAA canónicas del mapa global
  const regions = new Set();
  if(typeof _REGION_MAP_GLOBAL === 'object' && _REGION_MAP_GLOBAL){
    Object.values(_REGION_MAP_GLOBAL).forEach(r=>regions.add(r));
  }
  // Añadir las que aparezcan en el historial (por si hay alguna no mapeada)
  if(typeof _cachedHistory !== 'undefined' && Array.isArray(_cachedHistory)){
    _cachedHistory.forEach(race=>(race.riders||[]).forEach(r=>{
      if(r.region) regions.add(typeof canonicalRegion==='function' ? canonicalRegion(r.region) : r.region);
    }));
  }
  const sorted = [...regions].filter(Boolean).sort((a,b)=>a.localeCompare(b));
  const currentValue = _globalFilters.region || '';
  sel.innerHTML = '<option value="">Todas las CCAA</option>' + sorted.map(r=>`<option value="${escapeHtml(r)}">${escapeHtml(r)}</option>`).join('');
  if([...sel.options].some(o=>o.value===currentValue)) sel.value = currentValue;
}

function _gfApplyToLocalFilters(){
  // Propaga el valor global a TODOS los selects locales que existan
  _gfSyncing = true;
  _GF_YEAR_IDS.forEach(id=>{
    const el = document.getElementById(id);
    if(el && [...el.options].some(o=>o.value===_globalFilters.year)){
      if(el.value !== _globalFilters.year){ el.value = _globalFilters.year; }
    }
  });
  _GF_REGION_IDS.forEach(id=>{
    const el = document.getElementById(id);
    if(el && [...el.options].some(o=>o.value===_globalFilters.region)){
      if(el.value !== _globalFilters.region){ el.value = _globalFilters.region; }
    }
  });
  _gfSyncing = false;
}

function _gfTriggerCurrentViewRerender(){
  const v = document.querySelector('.spa-view.active');
  if(!v) return;
  const id = v.id;
  try{
    // Vistas que dependen del histórico/filtros globales
    if(id==='view-inicio'      && typeof renderInicio==='function')      renderInicio();
    if(id==='view-evolucion'   && typeof renderEvolucion==='function')   renderEvolucion();
    if(id==='view-powerranking'&& typeof renderPowerRanking==='function')renderPowerRanking();
    if(id==='view-tendencias'  && typeof renderTendencias==='function')  renderTendencias();
    if(id==='view-seleccion'   && typeof renderSeleccion==='function')   renderSeleccion();
    if(id==='view-disponibilidad' && typeof _dispInit==='function')      _dispInit();
    if(id==='view-laboratorio' && typeof _labInit==='function')          _labInit();
    if(id==='view-resumen'     && typeof renderResumen==='function'){    renderResumen();
      // Si está abierta la pestaña "Seguimiento", refrescarla con el nuevo filtro
      const _sp=document.getElementById('resPanelScout');
      if(_sp && _sp.style.display!=='none' && typeof _scoutRender==='function') _scoutRender();
      // Igual para la pestaña "Mapa de calor"
      const _hp=document.getElementById('resPanelHeat');
      if(_hp && _hp.style.display!=='none' && typeof _resRenderHeat==='function') _resRenderHeat();
    }
    if(id==='view-historial'   && typeof renderHistory==='function')     renderHistory();
    if(id==='view-tactica'     && typeof renderTactica==='function')     renderTactica();
    if(id==='view-informe-plantilla' && typeof _ipInit==='function')     _ipInit();
    if(id==='view-challenge'         && typeof _chgInit==='function')    _chgInit();
    if(id==='view-equipos-ccaa'      && typeof _eqCcaaInit==='function') _eqCcaaInit();
    if(id==='view-ciclistas-cat'     && typeof _riderCatInit==='function') _riderCatInit();
    if(id==='view-calendario'  && typeof _calRender==='function')        _calRender();
    if(id==='view-simulador'   && typeof renderSimulador==='function')    renderSimulador();
    // Vistas que dependen de la prueba ACTIVA cargada (riders[])
    if(riders && riders.length){
      if(id==='view-tabla'      && typeof renderAll==='function')        renderAll();
      if(id==='view-analisis'   && typeof initAnalisis==='function')     initAnalisis();
      if(id==='view-comparativo'&& typeof initComparativo==='function')  initComparativo();
      if(id==='view-equipos'    && typeof renderTeamComparison==='function') renderTeamComparison(false);
      if(id==='view-graficos'   && typeof renderCharts==='function')     renderCharts();
      if(id==='view-top10'      && typeof renderTop10==='function')      renderTop10();
      if(id==='view-validacion' && typeof detectAnomalies==='function')  detectAnomalies();
    }
  }catch(e){ console.warn('[gf] error re-renderizando',id,e); }
}

function _gfOnChange(){
  _globalFilters.year   = document.getElementById('gfYear')?.value   || '';
  _globalFilters.region = document.getElementById('gfRegion')?.value || '';
  localStorage.setItem('gf_year',   _globalFilters.year);
  localStorage.setItem('gf_region', _globalFilters.region);
  _gfApplyToLocalFilters();
  _gfUpdateStatus();
  _gfTriggerCurrentViewRerender();
}

function _gfReset(){
  _globalFilters = {year:'', region:''};
  localStorage.removeItem('gf_year');
  localStorage.removeItem('gf_region');
  const y = document.getElementById('gfYear');   if(y) y.value='';
  const r = document.getElementById('gfRegion'); if(r) r.value='';
  _gfApplyToLocalFilters();
  _gfUpdateStatus();
  _gfTriggerCurrentViewRerender();
}

function _gfUpdateStatus(){
  const st = document.getElementById('gfStatus');
  if(!st) return;
  const parts = [];
  if(_globalFilters.year)   parts.push(`Año: ${_globalFilters.year}`);
  if(_globalFilters.region) parts.push(`CCAA: ${_globalFilters.region}`);
  st.textContent = parts.length ? `Filtrando por ${parts.join(' · ')}` : '(sin filtros aplicados)';
}

function _gfShowHideBar(viewId){
  const bar = document.getElementById('globalFilterBar');
  if(!bar) return;
  const shouldShow = _GF_VIEWS_USING_HISTORY.includes(viewId);
  bar.style.display = shouldShow ? 'flex' : 'none';
  if(shouldShow && !_gfReady){
    _gfPopulateYears();
    _gfPopulateRegions();
    _gfMyTeamInit();
    _gfDefaultsApplyToSelects();
    _gfUpdateStatus();
    _gfReady = true;
  } else if(shouldShow){
    // Repoblar por si llegaron nuevos datos
    _gfPopulateYears();
    _gfPopulateRegions();
    _gfMyTeamInit();
    _gfDefaultsApplyToSelects();
    _gfUpdateStatus();
  }
  if(shouldShow) _gfApplyToLocalFilters();
}

function showView(viewId){
  // RBAC: check permission
  if(_rbacUser && !_rbacPerms.has(viewId)){
    document.querySelectorAll('.spa-view').forEach(v=>v.classList.remove('active'));
    const blocked = document.getElementById(viewId);
    if(blocked){
      blocked.innerHTML = `<div class="rbac-access-denied"><h3>🔒 Acceso denegado</h3><p>No tienes autorización para ver esta sección.<br>Contacta con el administrador.</p><span style="font-size:40px">🚫</span></div>`;
      blocked.classList.add('active');
    }
    document.querySelectorAll('.nav-btn').forEach(b=>b.classList.remove('active'));
    return;
  }
  // Vistas que requieren una prueba cargada (riders[]).
  // Si el usuario intenta entrar sin prueba: redirigir a Historial y avisar.
  // NOTA: 'view-tactica' se quita de aquí porque su renderTactica ya muestra
  // un estado global (top equipos del histórico) cuando no hay riders ni equipo
  // configurado — Fase 2 no-bloqueo.
  const VIEWS_REQUIRE_RACE = ['view-tabla','view-analisis','view-comparativo','view-equipos','view-graficos','view-top10','view-validacion'];
  if(VIEWS_REQUIRE_RACE.includes(viewId) && (!riders || !riders.length)){
    if(typeof showToast === 'function'){
      showToast('Primero carga una prueba desde el Historial', 'warn', 4500);
    }
    return showView('view-historial');
  }
  document.querySelectorAll('.spa-view').forEach(v=>v.classList.toggle('active',v.id===viewId));
  document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===viewId));
  // Auto-expandir sección del menú si la vista activa está dentro
  if(typeof _navAutoExpandActive === 'function') _navAutoExpandActive(viewId);
  // Filtros globales: mostrar/ocultar barra y sincronizar con filtros locales
  if(typeof _gfShowHideBar === 'function') _gfShowHideBar(viewId);
  // Auto-abrir panel de carga solo si no hay datos cargados
  if(viewId==='view-carga' && !hasValidData){
    const body=$('loadPanelBody');
    const chevron=$('loadChevron');
    const bar=$('loadBar');
    if(body && body.classList.contains('collapsed')){
      body.classList.remove('collapsed');
      if(chevron) chevron.classList.remove('closed');
      if(bar) bar.classList.add('load-bar-open');
    }
  }
  setTimeout(()=>{
    try{
      if(riders && riders.length){
        if(viewId==='view-tabla' && (!filtered || filtered.length===0)) {
          applyFilters();
        } else if(viewId==='view-tabla') {
          renderTable();
        }
        renderCharts();
        renderTeamComparison(false);
        renderTeamTimeRanking();
        if(viewId==='view-comparativo') initComparativo();
        if(viewId==='view-analisis') initAnalisis();
        if(viewId==='view-validacion') detectAnomalies();
        if(viewId==='view-top10') renderTop10();
      }
      // view-tactica: se renderiza SIEMPRE (con o sin riders) para mostrar
      // su estado vacío amable (Fase 2 no-bloqueo).
      if(viewId==='view-tactica') renderTactica();
      if(viewId==='view-simulador' && typeof renderSimulador==='function') renderSimulador();
      if(viewId==='view-inicio') renderInicio();
      if(viewId==='view-calendario') { if(typeof _calInit==='function') _calInit(); if(typeof _gfApplyDefaultsToView==='function') _gfApplyDefaultsToView('view-calendario'); }
      if(viewId==='view-informe-plantilla') { if(typeof _ipInit==='function') _ipInit(); }
      if(viewId==='view-challenge') { if(typeof _chgInit==='function') _chgInit(); }
      if(viewId==='view-equipos-ccaa') { if(typeof _eqCcaaInit==='function') _eqCcaaInit(); }
      if(viewId==='view-ciclistas-cat') { if(typeof _riderCatInit==='function') _riderCatInit(); }
      if(viewId==='view-disponibilidad') { if(typeof _dispInit==='function') _dispInit(); }
      if(viewId==='view-radiovuelta') { if(typeof _rvInit==='function') _rvInit(); }
      if(viewId==='view-laboratorio') { if(typeof _labInit==='function') _labInit(); }
      if(viewId==='view-historial') renderHistory();
      if(viewId==='view-evolucion') renderEvolucion();
      if(viewId==='view-resumen'){ renderResumen(); }
      if(viewId==='view-gestion'){ _gSetTab('users'); }
    }catch(e){console.warn('No se pudo refrescar la vista',e)}
    // Estas vistas se renderizan fuera del try/catch para que nunca queden bloqueadas por otros errores
    if(viewId==='view-powerranking') renderPowerRanking();
    if(viewId==='view-tendencias') renderTendencias();
    if(viewId==='view-seleccion'){ _selFiltersReady=false; _selSelectedCats=new Set(); renderSeleccion(); }
    updateRaceHeader(viewId);
  },80);
  const layout=document.querySelector('.spa-layout');
  if(layout) layout.scrollIntoView({behavior:'smooth',block:'start'});
}

