// Roles editables (SUPERADMIN always has everything, not shown)
const EDITABLE_ROLES = ['ADMIN','DIRECTOR','CICLISTA','LECTOR'];

// Local permissions cache — initialized from defaults
let _localPerms = {};
function _initLocalPerms(){
  const defaults = {
    ADMIN:    ALL_VIEWS.map(v=>v.id),
    DIRECTOR: ALL_VIEWS.filter(v=>v.id!=='view-gestion').map(v=>v.id),
    CICLISTA: ['view-carga','view-tabla','view-analisis','view-equipos'],
    LECTOR:   ['view-carga','view-tabla']
  };
  EDITABLE_ROLES.forEach(r=>{
    _localPerms[r] = {};
    ALL_VIEWS.forEach(v=>{ _localPerms[r][v.id] = (defaults[r]||[]).includes(v.id); });
  });
}
_initLocalPerms();

async function _gLoadPermissions(){
  const tbody = document.getElementById('gPermsTbody');
  if(!tbody) return;
  tbody.innerHTML = '<tr><td colspan="5" style="text-align:center;padding:20px;color:#9ca3af">Cargando...</td></tr>';
  // Try loading from Supabase
  if(_sb){
    const {data} = await _sb.from('app_permissions').select('role, view_id, allowed');
    if(data && data.length > 0){
      EDITABLE_ROLES.forEach(r=>{ _localPerms[r]={}; });
      data.forEach(p=>{
        if(_localPerms[p.role] !== undefined) _localPerms[p.role][p.view_id]=p.allowed;
      });
    }
  }
  tbody.innerHTML = ALL_VIEWS.map(v=>`
    <tr style="border-bottom:1px solid #f3f4f6">
      <td style="padding:10px 14px;font-weight:700;font-size:13px">${v.icon} ${escapeHtml(v.label)}</td>
      ${EDITABLE_ROLES.map(r=>`<td style="padding:10px 14px;text-align:center">
        <input type="checkbox" data-role="${r}" data-view="${v.id}"
          ${(_localPerms[r]?.[v.id])?'checked':''}
          ${v.id==='view-gestion'?'disabled title="Solo SUPERADMIN"':''}
          onchange="_gTogglePerm('${r}','${v.id}',this.checked)"
          style="width:16px;height:16px;cursor:pointer">
      </td>`).join('')}
    </tr>`).join('');
}

function _gTogglePerm(role, viewId, allowed){
  if(!_localPerms[role]) _localPerms[role]={};
  _localPerms[role][viewId] = allowed;
  // Apply immediately to current session if it's the user's role
  if(_rbacUser && _rbacUser.role === role){
    if(allowed) _rbacPerms.add(viewId); else _rbacPerms.delete(viewId);
    _rbacRenderMenu();
  }
  const msg = document.getElementById('gPermsMsg');
  if(msg){ msg.textContent='⚠️ Cambios pendientes de guardar en Supabase'; msg.style.color='#d97706'; }
}

async function _gSavePermissions(){
  const msg = document.getElementById('gPermsMsg');
  if(!_sb){
    if(msg){msg.textContent='⚠️ Sin Supabase — permisos aplicados solo en esta sesión. Ejecuta el SQL para persistirlos.';msg.style.color='#d97706';}
    return;
  }
  const upserts = [];
  EDITABLE_ROLES.forEach(r=>{
    ALL_VIEWS.forEach(v=>{
      upserts.push({role:r, view_id:v.id, allowed:!!(_localPerms[r]?.[v.id]), updated_at:new Date().toISOString()});
    });
  });
  const {error} = await _sb.from('app_permissions').upsert(upserts, {onConflict:'role,view_id'});
  if(error){
    if(msg){msg.textContent='❌ Error: '+error.message;msg.style.color='#dc2626';}
    return;
  }
  if(_rbacUser){ await _rbacLoadPerms(_rbacUser.role); _rbacRenderMenu(); }
  if(msg){msg.textContent='✅ Permisos guardados correctamente. Cambios aplicados a todos los usuarios.';msg.style.color='#059669';}
}

