let _cachedHistory = null;

// ── ESTADO DE UNA PRUEBA: SOLO POR FECHA ──────────────────────────────────
// Una prueba está "realizada" si HOY >= su fecha, INDEPENDIENTEMENTE de que se
// hayan subido inscritos o la clasificación. Antes de su fecha está "pendiente"
// (próxima), aunque ya tenga startlist u horarios cargados con antelación.
function _raceIsRealizadaISO(iso){
  if(!iso || !/^\d{4}-\d{2}-\d{2}$/.test(iso)) return false;
  return iso <= new Date().toISOString().slice(0,10);   // hoy o pasado
}
function _raceIsRealizada(dateStr){
  return _raceIsRealizadaISO(_parseSpanishDate(dateStr));
}

function _parseSpanishDate(str){
  if(!str) return null;
  str = String(str).trim();
  if(/^\d{4}-\d{2}-\d{2}$/.test(str)) return str;
  const m = str.match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})$/);
  if(m){
    const [,d,mo,y] = m;
    const year = y.length===2 ? '20'+y : y;
    if(Number(y)>=1990 || Number('20'+y)>=2000){
      return `${year}-${mo.padStart(2,'0')}-${d.padStart(2,'0')}`;
    }
  }
  // "3 de mayo de 2026" o "3 mayo 2026"
  const _MES={'enero':1,'febrero':2,'marzo':3,'abril':4,'mayo':5,'junio':6,
    'julio':7,'agosto':8,'septiembre':9,'octubre':10,'noviembre':11,'diciembre':12};
  const mt=str.toLowerCase().match(/^(\d{1,2})\s+(?:de\s+)?([a-zà-ü]+)(?:\s+de\s+|\s+)(\d{2,4})$/);
  if(mt && _MES[mt[2]]){
    const year=mt[3].length===2?'20'+mt[3]:mt[3];
    return `${year}-${String(_MES[mt[2]]).padStart(2,'0')}-${mt[1].padStart(2,'0')}`;
  }
  return null;
}
const parseRaceDate = _parseSpanishDate;
function formatDateDisplay(iso){
  if(!iso) return '';
  const m=iso.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return m ? `${m[3]}/${m[2]}/${m[1]}` : iso;
}

function _normalizeCat(raw){
  const c = (raw||'').trim().toLowerCase();
  if(/cadete|cad[12]?|c[12]\b|1[ºo]?\s*a[ñn]|2[ºo]?\s*a[ñn]/.test(c)) return 'CAD';
  if(/juvenil|junior|jun\b|juv\b/.test(c)) return 'JUV';
  if(/sub.?23|s-?23/.test(c)) return 'SUB23';
  if(/\belite\b|absolut/.test(c)) return 'ELITE';
  return raw||'';
}

function _computeTeamRankingsLocal(ridersList, raceId){
  const byCat = {};
  ridersList.forEach(r=>{
    const cat = _normalizeCat(r.cat);
    if(!byCat[cat]) byCat[cat]=[];
    byCat[cat].push(r);
  });
  const rows = [];
  Object.entries(byCat).forEach(([cat, members])=>{
    const byTeam = {};
    members.forEach(r=>{
      const t = r.team||'Sin equipo';
      if(!byTeam[t]) byTeam[t]=[];
      byTeam[t].push(r);
    });
    const teamScores = Object.entries(byTeam).map(([team, rs])=>{
      const top3 = rs.sort((a,b)=>a.pos-b.pos).slice(0,3);
      return {team, score: top3.reduce((s,r)=>s+r.pos,0)};
    });
    teamScores.sort((a,b)=>a.score-b.score);
    teamScores.forEach((t, i)=>{
      rows.push({race_id:raceId, team:t.team, rank:i+1, score:t.score, cat_filter:cat});
    });
  });
  return rows;
}

async function _sbLoadHistory(){
  if(!_sb) return [];
  const {data, error} = await _sb.from('races')
    .select('id, name, date, notes, race_results(id, pos, bib, name, team, cat, time, gap_seconds, total_seconds)')
    .eq('race_type','clasificacion')
    .order('date', {ascending: false});
  if(error){ console.warn('Supabase historial error:', error); return []; }
  return (data||[]).map(race=>{
    let extra = {};
    try{ extra = JSON.parse(race.notes||'{}'); }catch(e){}
    return {
      id: race.id,
      raceName: race.name,
      raceDate: formatDateDisplay(_parseSpanishDate(extra.raceDate||race.date||''))||extra.raceDate||race.date||'',
      km: extra.km || '',
      avg: extra.avg || '',
      localidad: extra.localidad || '',
      circuitType: extra.circuitType || '',
      raceTypeTag: extra.raceTypeTag || '',   // Fase 1.B: tipo de prueba manual (cri/montana/circuito/llana)
      challengeCV: !!extra.challengeCV,
      raceCat: extra.raceCat || '',   // categoría FORZADA de la prueba (override manual)
      ccaa: extra.ccaa || '',
      route: extra.route || null,
      // Meteo (Open-Meteo) — opcionales, leídos desde notes
      hora_inicio: extra.hora_inicio || '',
      weather: extra.weather || null,
      lat: extra.lat || null,
      lon: extra.lon || null,
      inscritos: Array.isArray(extra.inscritos) ? extra.inscritos : [],
      riders: (race.race_results||[]).sort((a,b)=>a.pos-b.pos).map(r=>{
        const normName=normalizeRiderName(r.name);
        // Si la carrera está marcada como Challenge, calculamos en el momento
        // los puntos correspondientes a esta posición. Es un campo DERIVADO
        // (no se persiste en Supabase), así el sistema funciona sin alterar
        // el esquema de la tabla race_results.
        const isChallenge = !!extra.challengeCV;
        const challengePoints = (isChallenge && r.pos > 0) ? calcularPuntosChallenge(r.pos) : null;
        return {
          id:r.id, raceId:race.id, // ← claves para poder borrar la fila individual
          pos:r.pos, bib:r.bib, name:normName, team:r.team, cat:r.cat,
          time:normalizeTimeStr(r.time),
          gapSeconds:r.gap_seconds, totalSeconds:r.total_seconds,
          region:(extra.regions||{})[r.name]||(extra.regions||{})[normName]||'',
          challengePoints
        };
      })
    };
  });
}

async function _ensureHistory(){
  if(_cachedHistory === null) _cachedHistory = await _sbLoadHistory();
  return _cachedHistory;
}

if(_sb){ _sbLoadHistory().then(h=>{ _cachedHistory = h; if(typeof invalidateTeamRegionDB==='function') invalidateTeamRegionDB(); if(typeof _gfPopulateYears==='function'){ _gfPopulateYears(); _gfPopulateRegions(); } if(typeof _yearRiderIdxKey!=='undefined'){ _yearRiderIdxKey=null; _yearRiderIdxCache=null; } if(typeof _finishStatsCacheKey!=='undefined'){ _finishStatsCacheKey=null; _finishStatsCache=null; } }); }

// Sincronización bidireccional: si el usuario cambia un filtro LOCAL,
// actualizamos el global para que persista al cambiar de vista.
document.addEventListener('change', e=>{
  if(typeof _gfSyncing!=='undefined' && _gfSyncing) return; // evitar loops
  const id = e.target?.id;
  if(!id) return;
  if(_GF_YEAR_IDS && _GF_YEAR_IDS.includes(id)){
    _globalFilters.year = e.target.value;
    localStorage.setItem('gf_year', _globalFilters.year);
    const g = document.getElementById('gfYear'); if(g && g.value!==e.target.value && [...g.options].some(o=>o.value===e.target.value)) g.value = e.target.value;
    _gfApplyToLocalFilters();
    _gfUpdateStatus();
  } else if(_GF_REGION_IDS && _GF_REGION_IDS.includes(id)){
    _globalFilters.region = e.target.value;
    localStorage.setItem('gf_region', _globalFilters.region);
    const g = document.getElementById('gfRegion'); if(g && g.value!==e.target.value && [...g.options].some(o=>o.value===e.target.value)) g.value = e.target.value;
    _gfApplyToLocalFilters();
    _gfUpdateStatus();
  }
});
