function processPastedText(){
  // COMENTARIO: permite analizar una clasificación pegada como texto, sin PDF/CSV/Excel.
  const text=$('pastedText') ? $('pastedText').value : '';
  if(!cleanSpaces(text)){alert('Pega primero una clasificación en el recuadro de texto.');return}
  // Opción A · Mejora #1: validación previa rápida
  const validation = _cargaValidatePastedText(text);
  if(!validation.ok){
    const proceed = confirm(`⚠️ El texto pegado NO parece una clasificación válida.\n\nMotivo: ${validation.reason}\n\n¿Procesarlo de todos modos?`);
    if(!proceed) return;
  }
  $('fileName').textContent='Clasificación cargada desde texto pegado';
  parseText(text);
}

// Validación previa: detecta si el texto parece una clasificación
function _cargaValidatePastedText(text){
  const lines = (text||'').split(/\r?\n/).map(l=>l.trim()).filter(Boolean);
  if(lines.length < 3) return {ok:false, reason: 'menos de 3 líneas no vacías'};
  // Contar líneas que tienen formato "número ... texto"
  let likelyDataLines = 0;
  for(const line of lines){
    if(/^\s*\d{1,3}[\s\.,;:\t]+\S/.test(line)) likelyDataLines++;
  }
  if(likelyDataLines < 2){
    return {ok:false, reason: 'no se detectan posiciones numéricas seguidas de texto'};
  }
  // ¿Hay nombres? (al menos 2 palabras alfabéticas en alguna línea)
  const hasNames = lines.some(l => /[A-ZÁÉÍÓÚÑ][a-záéíóúñ]{2,}.*[A-ZÁÉÍÓÚÑ][a-záéíóúñ]{2,}/.test(l));
  if(!hasNames){
    return {ok:false, reason: 'no se detectan nombres de corredores (al menos 2 palabras)'};
  }
  return {ok:true, lines: likelyDataLines};
}

async function handleFile(file){if(!file)return;$('fileName').textContent='Archivo cargado: '+file.name;const ext=file.name.split('.').pop().toLowerCase();showLoading('Procesando '+file.name,'Leyendo y ordenando la clasificación…');try{let text=''; if(ext==='pdf') text=await readPDF(file); else if(ext==='csv') text=await file.text(); else text=await readExcel(file); parseText(text); }catch(err){alert('No he podido leer el archivo. Prueba con CSV o Excel. Error: '+err.message)}finally{hideLoading();}}
function showLoading(title,detail){$('loadingText').textContent=title||'Procesando archivo…';$('loadingDetail').textContent=detail||'Puede tardar unos segundos.';$('loadingOverlay').classList.remove('hidden')}
function hideLoading(){$('loadingOverlay').classList.add('hidden')}
async function readPDF(file){
  const buf=await file.arrayBuffer();
  const pdf=await pdfjsLib.getDocument({data:buf}).promise;
  let out='';
  for(let i=1;i<=pdf.numPages;i++){$('loadingDetail').textContent='Leyendo página '+i+' de '+pdf.numPages+'…';
    const page=await pdf.getPage(i);
    const tc=await page.getTextContent();
    const pageWidth=page.view[2];
    const leftLimit=pageWidth*0.54;
    const lines=new Map();
    for(const item of tc.items){
      const str=String(item.str||'').trim();
      if(!str) continue;
      const x=item.transform[4], y=Math.round(item.transform[5]);
      if(x>leftLimit && !/XXIX|XXX|Km:|Vmedia|CLASIFICACIÓN GENERAL/i.test(str)) continue;
      if(!lines.has(y)) lines.set(y,[]);
      lines.get(y).push({x,str});
    }
    [...lines.keys()].sort((a,b)=>b-a).forEach(y=>{
      out += lines.get(y).sort((a,b)=>a.x-b.x).map(it=>it.str).join(' ')+'\n';
    });
  }
  return out;
}
async function readExcel(file){const buf=await file.arrayBuffer();const wb=XLSX.read(buf,{type:'array'});let out='';wb.SheetNames.forEach(s=>{const rows=XLSX.utils.sheet_to_json(wb.Sheets[s],{header:1,raw:false});out+=rows.map(r=>r.map(c=>String(c==null?'':c).replace(/\t/g,' ').replace(/ /g,' ')).join('\t')).join('\n')+'\n'});return out}
function cleanSpaces(s){return (s||'').replace(/[ \t]+/g,' ').trim()}
function parseText(text){
  // COMENTARIO: validación robusta tras cargar archivo; no se permite continuar con menos de 3 corredores.
  text=(text||'').replace(/\r/g,'\n');
  extractMeta(text);
  canonicalTeams=extractCanonicalTeams(text);
  riders=parseRiders(text);
  const hasTabularHeader=/(pos\.?|puesto|clasif|\bpl\.?)\s*[\t;|, ].*dorsal[\t;|, ].*(nombre|ciclista)/i.test(text);
  if(hasTabularHeader){const tabular=parseCSVLike(text);if(tabular.length>=3)riders=tabular;}
  riders=riders.map(r=>({...r,team:normalizeTeamName(r.team,canonicalTeams)}));
  const winnerTime=extractWinnerTime(text);
  if(!winnerTime) console.warn('COMENTARIO: no se ha detectado el tiempo del ganador; se calcularán gaps relativos si existe alguna referencia temporal posterior.');
  riders=riders.map(r=>(r.pos===1&&!r.time&&winnerTime)?({...r,time:winnerTime}):r);
  riders=detectSameTimes(riders);
  riders=enrichRiders(riders);
  selectedCompare=[];
  hasValidData=riders.length>=3;
  if(!hasValidData){
    alert(`No se pudieron detectar suficientes corredores (se encontraron ${riders.length}). ¿El archivo tiene el formato correcto? Prueba con CSV/Excel.`);
    riders=[];filtered=[];renderAll();
    return;
  }
  clearAllFilters();
  setTimeout(_collapseLoadPanel, 80);
  showView('view-tabla');
  // ===== BLOQUE 1: Banner de éxito y datalist equipo =====
  showSuccessBanner();
  updateMyTeamSuggestions();
  // Refrescar UI de inscritos (banner + DNF) si ya había una lista cargada
  if(typeof _updateInscritosUI === 'function') _updateInscritosUI();
  // Calcular velocidad media automáticamente si hay km y ganador con tiempo
  setTimeout(_calcAvgSpeed, 50);
  // Preguntar si hay columnas sin mapear que podrían ser CCAA
  setTimeout(_checkUnmappedRegionCol, 120);
  // Auto-completar desde la BD (silencioso): categoría exacta (CAD-1/CAD-2…),
  // dorsal CV y CCAA de los corredores que ya tienen historial en la Comunitat.
  // No pisa valores ya presentes; los de fuera de la CV no reciben dorsal CV.
  if(typeof enrichFromHistory==='function' && _sb){
    setTimeout(()=>{ try{ enrichFromHistory(true); }catch(_){} }, 200);
  }
}
