function updateFloatingBar(){
  const bar=$('floatingBar');
  const count=$('floatingCount');
  if(!bar) return;
  const n=_compFilled().length;
  if(n > 0){
    bar.style.display='flex';
    count.textContent=n;
  } else {
    bar.style.display='none';
  }
}

function toggleComparativoFromTable(key, checked){
  if(checked){
    const r=riders.find(x=>getRiderKey(x)===key);
    if(!r) return;
    if(_compFilled().some(x=>getRiderKey(x)===key)) return;
    const emptyIdx=comparativoRiders.findIndex(x=>x===null);
    if(emptyIdx<0){ alert('Máximo 6 ciclistas.'); return; }
    comparativoRiders[emptyIdx]=r;
  } else {
    const idx=comparativoRiders.findIndex(x=>x&&getRiderKey(x)===key);
    if(idx>=0) comparativoRiders[idx]=null;
  }
  _destroyCompCharts();
  updateFloatingBar();
  renderComparativo();
}

// Sobrescribir addToComparativo para que actualice la barra
const originalAddToComp=addToComparativo;
addToComparativo=function(){
  originalAddToComp();
  updateFloatingBar();
  renderTable(); // Refrescar checkboxes
}

const originalRemoveFromComp=removeFromComparativo;
removeFromComparativo=function(key){
  originalRemoveFromComp(key);
  updateFloatingBar();
  renderTable(); // Refrescar checkboxes
}

const originalClearComp=clearComparativo;
clearComparativo=function(){
  originalClearComp();
  updateFloatingBar();
  renderTable(); // Refrescar checkboxes
}

