// ===== POWER RANKING DE TEMPORADA =====
/* ══════════════════════════════════════════════════════════
   ADN DEL CICLISTA — clustering ligero (ML)
══════════════════════════════════════════════════════════ */
function _computeADN(positions, raceHistory){
  // positions: array of numbers (pos, chronological)
  // raceHistory: optional array of {raceDate, pos}
  const n = positions.length;
  if(!n) return {label:'Todoterreno',color:'#1286c7',icon:'🚵',consistency:0,
    desc:'Sin historial suficiente para clasificar'};
  const avg = positions.reduce((s,v)=>s+v,0)/n;
  const variance = positions.reduce((s,v)=>s+(v-avg)**2,0)/n;
  const stdDev = Math.sqrt(variance);
  const podiums = positions.filter(p=>p<=3).length;
  const inRange = positions.filter(p=>Math.abs(p-avg)<=Math.max(stdDev,3)).length;
  const consistencyPct = Math.round(inRange/n*100);

  // Regla 1 — Hombre de Hierro
  if(n>4 && stdDev<6){
    return {label:'Hombre de Hierro',color:'#6b7280',icon:'🏋️',consistency:consistencyPct,
      desc:`IA: consistencia del ${consistencyPct}% basándose en su desviación de puestos (σ=${stdDev.toFixed(1)})`};
  }
  // Regla 2 — Rematador
  if(avg>15 && podiums>=2){
    return {label:'Rematador',color:'#d97706',icon:'⚡',consistency:consistencyPct,
      desc:`IA: media ${avg.toFixed(1)}º pero ${podiums} podio${podiums!==1?'s':''} — alta variabilidad con picos de nivel`};
  }
  // Regla 3 — Rising Star (regresión lineal últimos 2 meses)
  if(raceHistory && raceHistory.length>=3){
    const now=new Date();
    const cutoff=new Date(now); cutoff.setMonth(cutoff.getMonth()-2);
    const recent=raceHistory
      .filter(r=>r.raceDate)
      .map(r=>({pos:r.pos,date:new Date((_parseSpanishDate(r.raceDate)||r.raceDate||'').replace(/(\d{4})-(\d{2})-(\d{2})/,'$1-$2-$3'))}))
      .filter(r=>!isNaN(r.date.getTime())&&r.date>=cutoff)
      .sort((a,b)=>a.date-b.date);
    if(recent.length>=2){
      const pts=recent.map(r=>r.pos);
      const rn=pts.length;
      const xs=pts.map((_,i)=>i+1);
      const sx=xs.reduce((a,v)=>a+v,0),sy=pts.reduce((a,v)=>a+v,0);
      const sxx=xs.reduce((a,v)=>a+v*v,0),sxy=xs.map((x,i)=>x*pts[i]).reduce((a,v)=>a+v,0);
      const den=rn*sxx-sx*sx;
      if(den!==0){
        const slope=(rn*sxy-sx*sy)/den;
        const meanR=sy/rn;
        if(slope<0&&meanR>0&&Math.abs(slope)/meanR>0.15){
          const imp=Math.round(Math.abs(slope)/meanR*100);
          return {label:'Rising Star',color:'#059669',icon:'🌱',consistency:consistencyPct,
            desc:`IA: mejora del ${imp}% en tendencia reciente (regresión lineal — últimos 2 meses)`};
        }
      }
    }
  }
  // Default — Todoterreno
  return {label:'Todoterreno',color:'#1286c7',icon:'🚵',consistency:consistencyPct,
    desc:`IA: perfil equilibrado — media ${avg.toFixed(1)}º · consistencia ${consistencyPct}%`};
}

function _adnBadgeHtml(adn,size='normal'){
  if(!adn) return '';
  // size: 'normal' = ficha individual, 'small' = selección cards, 'pr' = power ranking rows
  const styles = {
    normal: {fs:'12px', p:'4px 11px', bw:'2px'},
    small:  {fs:'10px', p:'3px 9px',  bw:'1.5px'},
    pr:     {fs:'10px', p:'2px 8px',  bw:'1.5px'}
  };
  const s = styles[size]||styles.normal;
  // Use data-adn-tip for custom fast tooltip (not browser title)
  // En Power Ranking solo mostramos el icono para no tapar el nombre
  const showLabel = size !== 'pr';
  const tipFull = `${adn.icon} ${adn.label} — ${adn.desc}`;
  return `<span class="adn-badge" data-adn-tip="${escapeHtml(tipFull)}" style="display:inline-flex;align-items:center;justify-content:center;padding:${showLabel?s.p:'2px 5px'};background:${adn.color};border:${s.bw} solid ${adn.color};border-radius:20px;font-size:${showLabel?s.fs:'13px'};font-weight:800;color:#fff;cursor:help;white-space:nowrap;vertical-align:middle;line-height:1;text-shadow:0 1px 1px #0003">${showLabel?adn.icon+' '+escapeHtml(adn.label):adn.icon}</span>`;
}

/* Custom ADN tooltip — shows instantly on hover, no browser delay */
(function(){
  const tip=document.createElement('div');
  tip.id='adn-tip';
  tip.style.cssText='position:fixed;z-index:99999;background:#1e293b;color:#f8fafc;font-size:12px;font-weight:500;padding:7px 12px;border-radius:9px;max-width:280px;line-height:1.5;pointer-events:none;display:none;box-shadow:0 6px 20px #0005;border:1px solid #334155';
  document.addEventListener('DOMContentLoaded',()=>document.body.appendChild(tip));
  document.addEventListener('mouseover',e=>{
    const el=e.target.closest('[data-adn-tip]');
    if(el){tip.textContent=el.dataset.adnTip;tip.style.display='block';}
  });
  document.addEventListener('mousemove',e=>{
    if(tip.style.display==='block'){
      const x=Math.min(e.clientX+14,window.innerWidth-290);
      const y=e.clientY-tip.offsetHeight-10;
      tip.style.left=x+'px';tip.style.top=(y<4?e.clientY+16:y)+'px';
    }
  });
  document.addEventListener('mouseleave',()=>{tip.style.display='none';},true);
  document.addEventListener('mouseout',e=>{
    if(!e.relatedTarget?.closest('[data-adn-tip]'))tip.style.display='none';
  });
})();

let _prFiltersReady = false;
let _prSelectedCats  = new Set(); // categorías activas (vacío = todas)

// ════════════════════════════════════════════════════════════════════════════
// SCOUTING POR GENERACIÓN (1º / 2º año) — lentes analíticas del Power Ranking
// ════════════════════════════════════════════════════════════════════════════
// 'general' = tarjetas de equipo de siempre. 'g1' = solo 1er año (Promesas).
// 'g2' = solo 2º año (Veteranos). Filtrado y re-ranking 100% en el cliente.
let _prGenMode = 'general';
function _prSetGenMode(m){
  _prGenMode = m || 'general';
  document.querySelectorAll('.pr-gen-tab').forEach(b=>{
    b.classList.toggle('pr-gen-tab-on', b.dataset.gen===_prGenMode);
  });
  // Mostrar los filtros de equipo solo en las lentes individuales
  const gf=document.getElementById('prGenFilters');
  if(gf) gf.style.display = (_prGenMode==='g1'||_prGenMode==='g2') ? '' : 'none';
  renderPowerRanking();
}

// Generación a partir de la categoría exacta (CAD-1/CAD-2, JUV-1/JUV-2…).
// Devuelve '1' (primer año), '2' (segundo año) o '' (sin año / no aplica).
function _prGeneration(cat){
  const c=(cat||'').toString().toUpperCase().replace(/\s+/g,'');
  if(!c) return '';
  if(/(PRIMER|1ER|1AÑO|1ºAÑO)/.test(c) || /[-_]?1º?$/.test(c)) return '1';
  if(/(SEGUND|2DO|2AÑO|2ºAÑO)/.test(c) || /[-_]?2º?$/.test(c)) return '2';
  return '';
}

// Tendencia (curva de aprendizaje): pendiente de los últimos 5 puestos en orden
// cronológico. Como "menos puesto = mejor", una pendiente NEGATIVA significa que
// el ciclista mejora. Devuelve {icon,label,slope}.
function _prTrend(raceHistory){
  const pts=(raceHistory||[])
    .filter(h=>h && h.pos>0)
    .map(h=>({ k:(_parseSpanishDate(h.raceDate)||h.raceDate||''), pos:h.pos }))
    .sort((a,b)=>String(a.k).localeCompare(String(b.k)))
    .slice(-5);
  if(pts.length<3) return {icon:'—', label:'Pocos datos (mín. 3 carreras)', slope:0};
  const n=pts.length; let sx=0,sy=0,sxx=0,sxy=0;
  pts.forEach((p,i)=>{ sx+=i; sy+=p.pos; sxx+=i*i; sxy+=i*p.pos; });
  const den=(n*sxx - sx*sx)||1;
  const slope=(n*sxy - sx*sy)/den;   // puestos por carrera
  if(slope<=-1.0) return {icon:'🔥', label:'En plena progresión (mejora fuerte)', slope};
  if(slope<=-0.3) return {icon:'📈', label:'Mejorando', slope};
  if(slope< 0.3)  return {icon:'➡️', label:'Estable', slope};
  return {icon:'📉', label:'A la baja', slope};
}

// Construye la lista individual a partir del riderMap del Power Ranking.
function _prBuildIndividuals(riderMap){
  return Object.values(riderMap).map(s=>{
    const races=s.raceIds.size;
    const sum=s.positions.reduce((a,p)=>a+(p||0),0);
    const avg= races ? sum/races : 9999;
    return {
      name:s.name, team:s.team, cat:s.cat, gen:_prGeneration(s.cat),
      races, avg, raceHistory:(s.raceHistory||[]).slice(),
      adn:(typeof _computeADN==='function')?_computeADN(s.positions,s.raceHistory):null
    };
  });
}

// Renderiza la TABLA INDIVIDUAL de una generación (Promesas/Veteranos), con
// posiciones re-calculadas dentro de la generación, columna Tendencia y el
// distintivo 🌟 Matagigantes (1er año que se cuela en el Top-15 absoluto).
function _prRenderGenerationTable(riderMap, totalRaces, mode, adnFilter){
  const wrap=document.getElementById('prIndivWrap');
  const grid=document.getElementById('prGrid');
  const ircEl=document.getElementById('prIRCBars');
  if(grid) grid.style.display='none';
  if(ircEl) ircEl.style.display='none';
  if(!wrap) return;
  wrap.style.display='';

  let all=_prBuildIndividuals(riderMap);
  if(adnFilter) all=all.filter(r=>r.adn && r.adn.label===adnFilter);

  // Ranking GENERAL absoluto (todas las generaciones) para 2 cosas:
  //  (a) el corte del Top-15 (Matagigantes)  (b) el "iba Nº en la general".
  const ranked=[...all].filter(r=>r.races>=2).sort((a,b)=>a.avg-b.avg);
  const absRank=new Map(); ranked.forEach((r,i)=>absRank.set(r.name+'|||'+r.team, i+1));
  const top15cut = ranked.length ? ranked[Math.min(14,ranked.length-1)].avg : Infinity;

  const genWanted = mode==='g2' ? '2' : '1';
  let list=all.filter(r=>r.gen===genWanted);
  list.sort((a,b)=>a.avg-b.avg);
  // Posición DENTRO de la generación (1..N), antes de filtrar por equipo, para
  // que al elegir un equipo siga viéndose "este va 5º de toda la generación".
  list.forEach((r,i)=>{ r.genRank=i+1; });

  // ── Filtro por equipo / "solo mi equipo" ──
  const teamSel=document.getElementById('prGenTeamFilter');
  const mineOnly=document.getElementById('prGenMineOnly')?.checked;
  const myCanon=(typeof myTeam!=='undefined')?getCanonicalTeam(myTeam||'').toLowerCase():'';
  // Poblar el desplegable con los equipos presentes en esta generación
  if(teamSel){
    const prev=teamSel.value;
    const teams=[...new Set(list.map(r=>r.team))].sort((a,b)=>a.localeCompare(b));
    teamSel.innerHTML='<option value="">Todos los equipos</option>'+
      teams.map(t=>`<option value="${escapeAttr(t)}">${escapeHtml(t)}</option>`).join('');
    if(teams.includes(prev)) teamSel.value=prev; else teamSel.value='';
  }
  const teamPick=teamSel?teamSel.value:'';
  let view=list.slice();
  if(mineOnly && myCanon) view=view.filter(r=>String(r.team||'').toLowerCase()===myCanon);
  else if(teamPick)       view=view.filter(r=>r.team===teamPick);

  const titleGen = genWanted==='1' ? '🌱 Promesas · 1er año' : '🎖️ Veteranos · 2º año';
  const scopeTxt = (mineOnly&&myCanon) ? ' · ⭐ solo mi equipo' : (teamPick?` · ${teamPick}`:'');
  const info=$('prInfo');
  if(info) info.textContent = `${titleGen}${scopeTxt} · ${view.length}/${list.length} ciclista${list.length!==1?'s':''}`;

  if(!view.length){
    wrap.innerHTML=`<div class="pr-empty-msg" style="padding:24px">No hay ciclistas de ${genWanted==='1'?'1er':'2º'} año con los filtros actuales.<br>
      <span style="font-size:12px">El año de generación se toma de la categoría exacta (p.ej. CAD-1 / CAD-2). Revisa que las clasificaciones traigan esa categoría.</span></div>`;
    return;
  }

  const rows=view.map((r)=>{
    const i=r.genRank-1;
    const gen1 = r.gen==='1';
    const giant = gen1 && r.races>=2 && r.avg<=top15cut;
    const tr=_prTrend(r.raceHistory);
    const aRank=absRank.get(r.name+'|||'+r.team);
    const mine = (typeof myTeam!=='undefined') && getCanonicalTeam(myTeam||'').toLowerCase()===String(r.team||'').toLowerCase();
    return `<tr class="pr-gen-row${mine?' pr-gen-row-mine':''}" onclick="prGoToRider('${escapeAttr(r.name)}','${escapeAttr(r.team)}')" title="Ver trayectoria de ${escapeHtml(r.name)}">
      <td class="pr-gen-pos">${i+1}º</td>
      <td class="pr-gen-name">
        ${giant?'<span title="Matagigantes: pelea de tú a tú con los de 2º año (entra en el Top-15 absoluto)">🌟 </span>':''}${escapeHtml(_evolNormName(r.name))}
        ${r.adn?` ${_adnBadgeHtml(r.adn,'pr')}`:''}
        ${mine?' <span style="font-size:10px;color:#1d4ed8;font-weight:800">⭐ MI EQUIPO</span>':''}
      </td>
      <td class="pr-gen-team">${escapeHtml(r.team)}</td>
      <td class="pr-gen-cat">${escapeHtml(r.cat||'—')}</td>
      <td class="pr-gen-avg" title="Posición media en ${r.races} carrera${r.races!==1?'s':''}">${r.avg<9999?r.avg.toFixed(1):'—'} Ø</td>
      <td class="pr-gen-races">${r.races}/${totalRaces}</td>
      <td class="pr-gen-trend" title="${tr.label}">${tr.icon}</td>
      <td class="pr-gen-gral" title="Posición en la clasificación GENERAL absoluta (todas las generaciones)">${aRank?('#'+aRank):'—'}</td>
    </tr>`;
  }).join('');

  wrap.innerHTML=`
    <div class="pr-gen-legend">
      <span><b>${titleGen}</b> — posiciones recalculadas SOLO entre los de esta generación.</span>
      <span>🌟 <b>Matagigantes</b>: 1er año con media de Top-15 absoluto · 📈/🔥 mejora · ➡️ estable · 📉 baja · columna <b>Gral</b> = puesto en la general absoluta.</span>
    </div>
    <div class="pr-gen-tablewrap">
      <table class="pr-gen-table">
        <thead><tr>
          <th>#</th><th>Ciclista</th><th>Equipo</th><th>Cat.</th>
          <th title="Posición media (menos es mejor)">Media</th>
          <th title="Carreras disputadas">Carr.</th>
          <th title="Tendencia de los últimos 5 puestos">Tend.</th>
          <th title="Puesto en la clasificación general absoluta">Gral</th>
        </tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`;
}

const _PR_PALETTE = [
  '#0b2f6b','#1d4ed8','#6d28d9','#be185d','#b45309',
  '#047857','#0e7490','#9333ea','#c2410c','#15803d',
  '#1e40af','#7c3aed','#9f1239','#065f46','#92400e',
  '#1a56db','#5521b5','#770ba1','#0e9f6e','#e3a008'
];

function _prTeamColor(teamName){
  let h = 0;
  for(let i=0;i<teamName.length;i++) h=(h*31+teamName.charCodeAt(i))&0xffff;
  return _PR_PALETTE[h % _PR_PALETTE.length];
}

function _prIsFemine(cat){
  if(!cat) return false;
  const c = (cat||'').toUpperCase().trim();
  return c.startsWith('F-') || c.includes('FEM');
}

function _prToggleCat(cat){
  if(cat === '__all__'){
    _prSelectedCats.clear();
  } else {
    if(_prSelectedCats.has(cat)) _prSelectedCats.delete(cat);
    else _prSelectedCats.add(cat);
  }
  _prRenderCatPills(); // re-render pill states
  renderPowerRanking();
}

function _prRenderCatPills(){
  const container = $('prCatPills');
  if(!container) return;
  const allActive = _prSelectedCats.size === 0;
  container.querySelectorAll('.pr-cat-pill').forEach(pill=>{
    const cat = pill.dataset.cat;
    if(cat === '__all__'){
      pill.classList.toggle('pr-pill-active', allActive);
    } else {
      pill.classList.toggle('pr-pill-active', _prSelectedCats.has(cat));
    }
  });
}

function _initPrFilters(history){
  const currentYear = String(new Date().getFullYear());

  // Años
  const years = [...new Set(
    history.map(h=>(_parseSpanishDate(h.raceDate)||h.raceDate||'').slice(0,4)).filter(Boolean)
  )].sort().reverse();
  const ySel = $('prYearFilter');
  if(ySel){
    const prev = ySel.value;
    ySel.innerHTML = '<option value="">Todos</option>' +
      years.map(y=>`<option value="${y}"${y===currentYear?' selected':''}>${y}</option>`).join('');
    if(prev && years.includes(prev)) ySel.value = prev;
  }

  // CCAA — inferida por equipo (mayoría de corredores)
  const teamRegionCounts = {};
  for(const race of history){
    for(const r of (race.riders||[])){
      if(!(r.region||'')) continue;
      const team = getCanonicalTeam(r.team||'').trim();
      if(!team) continue;
      if(!teamRegionCounts[team]) teamRegionCounts[team] = {};
      teamRegionCounts[team][r.region] = (teamRegionCounts[team][r.region]||0) + 1;
    }
  }
  const allInferredRegions = new Set();
  for(const counts of Object.values(teamRegionCounts)){
    const sorted = Object.entries(counts).sort((a,b)=>b[1]-a[1]);
    if(sorted.length) allInferredRegions.add(sorted[0][0]);
  }
  const regions = [...allInferredRegions].sort();
  const rSel = $('prRegionFilter');
  if(rSel){
    const prev = rSel.value;
    const hasVLC = regions.includes('VLC');
    rSel.innerHTML = '<option value="">Todas</option>' +
      regions.map(r=>`<option value="${r}"${!prev && r==='VLC' && hasVLC?' selected':''}>${r}</option>`).join('');
    if(prev && regions.includes(prev)) rSel.value = prev;
  }

  // Categorías como pills
  const cats = [...new Set(
    history.flatMap(h=>{
      const y=(_parseSpanishDate(h.raceDate)||'').slice(0,4);
      return (h.riders||[]).map(r=>getRiderCorrectCat(r.name,y?parseInt(y):null,r.cat)||'').filter(Boolean);
    })
  )].sort();

  const container = $('prCatPills');
  if(container){
    const allActive = _prSelectedCats.size === 0;
    container.innerHTML =
      `<span class="pr-cat-pill pr-pill-all${allActive?' pr-pill-active':''}" data-cat="__all__" onclick="_prToggleCat('__all__')">Todas</span>` +
      cats.map(c=>`<span class="pr-cat-pill${_prSelectedCats.has(c)?' pr-pill-active':''}" data-cat="${escapeHtml(c)}" onclick="_prToggleCat('${escapeHtml(c).replace(/'/g,"\\'")}')">
        ${escapeHtml(c)}
      </span>`).join('');
  }
}

// Construye mapa equipo → región inferida y equipo → género desde las carreras filtradas por año
function _prBuildTeamMeta(races){
  const regionCounts = {}; // team → {reg → n}
  const catCounts    = {}; // team → {fem: n, masc: n}

  for(const race of races){
    const raceYear = (_parseSpanishDate(race.raceDate)||race.raceDate||'').slice(0,4);
    for(const r of (race.riders||[])){
      const team = getCanonicalTeam(r.team||'').trim();
      if(!team) continue;
      if(r.region){
        if(!regionCounts[team]) regionCounts[team] = {};
        regionCounts[team][r.region] = (regionCounts[team][r.region]||0) + 1;
      }
      const rcat = getRiderCorrectCat(r.name, raceYear ? parseInt(raceYear) : null, r.cat);
      if(!catCounts[team]) catCounts[team] = {fem:0, masc:0};
      if(_prIsFemine(rcat)) catCounts[team].fem++; else catCounts[team].masc++;
    }
  }

  const teamRegion = {};
  for(const [team, counts] of Object.entries(regionCounts)){
    const sorted = Object.entries(counts).sort((a,b)=>b[1]-a[1]);
    if(sorted.length) teamRegion[team] = sorted[0][0];
  }
  const teamGender = {};
  for(const [team, counts] of Object.entries(catCounts)){
    teamGender[team] = counts.fem > counts.masc ? 'F' : 'M';
  }
  return { teamRegion, teamGender };
}

async function renderPowerRanking(){
  const grid = $('prGrid');
  if(!grid) return;
  grid.innerHTML = '<div class="pr-loading">⏳ Cargando datos de temporada...</div>';

  let history;
  try {
    history = _historyForGlobalCat(await _ensureHistory());
  } catch(e) {
    grid.innerHTML = `<div style="padding:20px;color:#dc2626;font-weight:700">
      ❌ ${e.message||e}<br>
      <small style="font-weight:400;color:#6b7280;display:block;margin:6px 0">El proyecto Supabase puede estar en pausa. Espera 30 segundos y pulsa Reintentar.</small>
      <button onclick="_cachedHistory=null;renderPowerRanking()" style="margin-top:10px;padding:8px 18px;background:#1f6feb;color:#fff;border:none;border-radius:8px;cursor:pointer;font-weight:700">🔄 Reintentar</button>
    </div>`;
    return;
  }
  if(!history || !history.length){
    grid.innerHTML = '<div class="pr-empty-msg">No hay datos en el historial.<br><span style="font-size:12px">Carga carreras primero desde "Carga y Resumen".</span></div>';
    const _b=document.getElementById('prIRCBars'); if(_b) _b.innerHTML='';
    return;
  }

  // IRC actual (estado de forma) de mi equipo — barras horizontales arriba.
  try{ _prRenderIRCBars(history); }catch(_){}

  if(!_prFiltersReady){
    _initPrFilters(history);
    _prFiltersReady = true;
  }

  try {
  const year   = $('prYearFilter')?.value  || '';
  const region = $('prRegionFilter')?.value || '';
  const gender = $('prGenderFilter')?.value  || '';
  const selCats = _prSelectedCats; // Set con categorías activas (vacío = todas)
  const adnFilter = $('prAdnFilter')?.value || '';

  // Filtrar carreras por año
  const filteredRaces = history.filter(race => {
    const ry = (_parseSpanishDate(race.raceDate)||race.raceDate||'').slice(0,4);
    return !year || ry === year;
  });

  // CARRERAS REALES de la categoría: history ya viene filtrado por el grupo
  // global (cadete/juvenil…) con _historyForGlobalCat, así que race.riders solo
  // contiene corredores de ESE grupo. Exigimos ≥3 para que NO cuenten como
  // "carrera del calendario" las pruebas donde solo apareció 1-2 corredores del
  // grupo (p.ej. el CRI con 1 cadete suelto). Así el "X/N" es honesto y NUNCA
  // mezcla otra categoría. Numerador y denominador usan el MISMO conjunto.
  const statRaces = filteredRaces.filter(r => (r.riders||[]).length >= 3);
  const totalRacesInPeriod = statRaces.length;

  // Penalización por carrera no disputada:
  // igual al mayor campo de participantes visto + 1 (siempre peor que el último)
  const maxFieldSize = statRaces.reduce((m,r)=>Math.max(m,(r.riders||[]).length),50);
  const missedRacePenalty = maxFieldSize + 1;

  // Inferir región y género de cada equipo (año filtrado, sin otros filtros)
  const { teamRegion, teamGender } = _prBuildTeamMeta(filteredRaces);

  // Acumular estadísticas por rider
  const riderMap = {};

  for(const race of statRaces){
    const raceYear = (_parseSpanishDate(race.raceDate)||race.raceDate||'').slice(0,4);

    for(const r of (race.riders||[])){
      const team = getCanonicalTeam(r.team||'').trim();
      if(!team) continue;

      if(region && teamRegion[team] !== region) continue;
      if(gender && teamGender[team] !== gender) continue;

      const rcat = getRiderCorrectCat(r.name, raceYear ? parseInt(raceYear) : null, r.cat);
      if(selCats.size && !selCats.has(rcat)) continue;

      const nameKey = normalizeRiderName(r.name||'').trim();
      if(!nameKey) continue;
      const mapKey = nameKey + '|||' + team;

      if(!riderMap[mapKey]){
        riderMap[mapKey] = { name:nameKey, team, positions:[], raceIds:new Set(), cat:rcat, raceHistory:[] };
      }
      riderMap[mapKey].positions.push(r.pos);
      riderMap[mapKey].raceIds.add(race.id || race.raceName);
      riderMap[mapKey].raceHistory.push({raceDate:race.raceDate||'', pos:r.pos});
    }
  }

  // ── LENTE DE GENERACIÓN (scouting 1º/2º año) ──────────────────────────────
  // Si el director ha elegido "Promesas" o "Veteranos", mostramos la tabla
  // individual re-rankeada y salimos (las tarjetas de equipo son la vista General).
  if(_prGenMode==='g1' || _prGenMode==='g2'){
    _prRenderGenerationTable(riderMap, totalRacesInPeriod, _prGenMode, adnFilter);
    return;
  }
  // Modo General: asegurar que se ven las tarjetas de equipo y se oculta la tabla.
  { const _w=document.getElementById('prIndivWrap'); if(_w) _w.style.display='none';
    if(grid) grid.style.display='';
    const _irc=document.getElementById('prIRCBars'); if(_irc) _irc.style.display=''; }

  // Agrupar por equipo
  const teamMap = {};
  for(const stats of Object.values(riderMap)){
    if(!teamMap[stats.team]) teamMap[stats.team] = [];
    const racesParticipated = stats.raceIds.size;
    const rawReg = stats.positions.reduce((s,p)=>s+p, 0);
    // Penalizar las carreras no disputadas
    const missedRaces = Math.max(0, totalRacesInPeriod - racesParticipated);
    const penalizedReg = rawReg + missedRaces * missedRacePenalty;

    const avgNum = racesParticipated ? rawReg / racesParticipated : 9999;
    teamMap[stats.team].push({
      name:         stats.name,
      team:         stats.team,
      regularidad:  rawReg,          // suma bruta (para ranking de equipo)
      penalized:    penalizedReg,    // suma penalizada (para orden del ranking)
      avgNum,                        // media numérica (para orden en tarjeta)
      avgStr:       racesParticipated ? avgNum.toFixed(1) : '—',
      races:        racesParticipated,
      cat:          stats.cat,
      adn:          _computeADN(stats.positions, stats.raceHistory)
    });
  }

  for(const t of Object.keys(teamMap)) teamMap[t].sort((a,b)=>a.penalized-b.penalized);

  // Score de equipo = suma de penalized de los top-3
  const myTeamCanon = getCanonicalTeam(myTeam||'').toLowerCase();
  let teams = Object.entries(teamMap).map(([team, riders])=>{
    const top3penalized = riders.slice(0,3).reduce((s,r)=>s+r.penalized, 0);
    const top3raw       = riders.slice(0,3).reduce((s,r)=>s+r.regularidad, 0);
    return {
      team, riders, score: top3penalized, rawScore: top3raw,
      region: teamRegion[team] || '',
      gender: teamGender[team] || 'M'
    };
  });

  // Calcular rango natural (sin forzar mi equipo primero)
  const sortedForRank = [...teams].sort((a,b)=>a.score-b.score);
  const myTeamRealRank = myTeamCanon
    ? sortedForRank.findIndex(t=>t.team.toLowerCase()===myTeamCanon) + 1
    : null;

  // Ordenar para visualización: mi equipo primero, luego por score penalizado
  teams.sort((a,b)=>{
    const am = myTeamCanon && a.team.toLowerCase()===myTeamCanon;
    const bm = myTeamCanon && b.team.toLowerCase()===myTeamCanon;
    if(am && !bm) return -1;
    if(!am && bm)  return 1;
    return a.score - b.score;
  });

  // Filtrar por ADN si está seleccionado
  if(adnFilter){
    teams = teams.map(ts=>({
      ...ts,
      riders: ts.riders.filter(r=>r.adn && r.adn.label===adnFilter)
    })).filter(ts=>ts.riders.length>0);
    // Recalcular scores
    teams.forEach(ts=>{
      ts.score = ts.riders.slice(0,3).reduce((s,r)=>s+r.penalized,0);
      ts.rawScore = ts.riders.slice(0,3).reduce((s,r)=>s+r.regularidad,0);
    });
    teams.sort((a,b)=>a.score-b.score);
  }

  if(!teams.length){
    grid.innerHTML = '<div class="pr-empty-msg">No hay datos para los filtros seleccionados.<br><span style="font-size:12px">Comprueba que hay carreras guardadas en el historial con datos de CCAA.</span></div>';
    const info=$('prInfo'); if(info) info.textContent='';
    return;
  }

  const totalRiders = Object.keys(riderMap).length;
  const info = $('prInfo');
  const catsLabel = selCats.size ? ` · cats: ${[...selCats].join('+')}` : '';
  if(info) info.textContent = `${totalRacesInPeriod} carrera${totalRacesInPeriod!==1?'s':''} · ${teams.length} equipos · ${totalRiders} ciclistas${catsLabel}`;

  let rivalRank = 0;
  grid.innerHTML = teams.map(ts=>{
    const isMine  = myTeamCanon && ts.team.toLowerCase()===myTeamCanon;
    const color   = _prTeamColor(ts.team);
    let badgeText;
    if(isMine){
      badgeText = myTeamRealRank
        ? `⭐ MI EQUIPO · #${myTeamRealRank}º`
        : '⭐ MI EQUIPO';
    } else {
      const rn = ++rivalRank;
      badgeText = '#'+rn+' · '+ts.rawScore+'pts';
    }
    const isFem  = ts.gender === 'F';
    const ccaaBadge = ts.region
      ? `<span class="pr-ccaa-badge${isFem?' pr-fem-badge':''}">📍${ts.region}</span>`
      : '';

    // ── Top 6 por CALIDAD MEDIA con umbral mínimo de participación ────────
    // Umbral: ≥ 33 % de las carreras del ciclista más activo del equipo
    const allTeamMaxRaces = ts.riders.reduce((m,r)=>Math.max(m,r.races), 0);
    const minRacesThreshold = Math.max(1, Math.ceil(allTeamMaxRaces * 0.33));
    const eligible = ts.riders
      .filter(r => r.races >= minRacesThreshold)
      .sort((a,b) => a.avgNum - b.avgNum);  // menor media = mejor
    const top6 = eligible.slice(0, 6);

    // Líder de Calidad: mejor media del equipo, pero con menos carreras que el
    // ciclista más activo entre los elegibles → corredor "explosivo"
    const maxEligibleRaces = eligible.reduce((m,r)=>Math.max(m,r.races), 0);
    const qualityLeaderName = top6.length ? top6[0].name : null;

    const ridersHtml = top6.map((r,i)=>{
      const isQL   = r.name === qualityLeaderName && r.races < maxEligibleRaces;
      const lowPart = r.races < allTeamMaxRaces;
      return `<div class="pr-rider-row" onclick="prGoToRider('${escapeAttr(r.name)}','${escapeAttr(r.team)}')">
        <span class="pr-rider-num">${i+1}.</span>
        <span class="pr-rider-name" title="${escapeHtml(r.name)}">${isQL?'⚡ ':''}${escapeHtml(_evolNormName(r.name))}</span>
        ${r.adn?`<span style="flex-shrink:0">${_adnBadgeHtml(r.adn,'pr')}</span>`:''}
        <span class="pr-rider-score" title="Posición media · ${r.races} carrera${r.races!==1?'s':''}">${r.avgStr} Ø</span>
        <span class="pr-rider-races" style="${lowPart?'color:#b45309;font-weight:700':''}" title="${r.races} de ${totalRacesInPeriod} carreras disponibles">(${r.races}/${totalRacesInPeriod})</span>
      </div>`;
    }).join('');

    return `<div class="pr-card${isMine?' pr-myteam':''}">
      <div class="pr-card-hdr" style="background:${color}" title="Ver historial de ${escapeHtml(ts.team)}" onclick="prGoToTeam('${escapeAttr(ts.team)}')">
        <span class="pr-card-hdr-name">${escapeHtml(ts.team)}</span>
        <span class="pr-card-badge">${badgeText}</span>
      </div>
      <div class="pr-card-body">
        ${ridersHtml || '<div style="font-size:11px;color:#9ca3af;padding:4px 2px">Sin datos</div>'}
      </div>
      <div class="pr-team-meta">${ccaaBadge}${ts.riders.length} ciclista${ts.riders.length!==1?'s':''} · top3 Σ${ts.rawScore}</div>
    </div>`;
  }).join('');
  } catch(e) {
    grid.innerHTML = `<div style="padding:20px;color:#dc2626;font-weight:700">❌ Error calculando ranking: ${e.message||e}<br><small style="font-weight:400;color:#6b7280">${e.stack||''}</small></div>`;
  }
}

function prGoToTeam(teamName){
  const tf = $('teamFilter');
  if(tf){
    const opts = Array.from(tf.options);
    const found = opts.find(o=>o.value===teamName) || opts.find(o=>o.value.toLowerCase()===teamName.toLowerCase());
    tf.value = found ? found.value : teamName;
  }
  showView('view-tabla');
}

function prGoToRider(riderName, teamName){
  _prOpenRiderModal(riderName, teamName);
}

function closePrRiderModal(){
  const m = $('prRiderModal');
  if(m) m.style.display='none';
}

async function exportPrRiderImg(){
  const modalEl = document.querySelector('#prRiderModal .pr-modal');
  if(!modalEl) return;

  const exportBtn = $('prModalExportBtn');
  const footer    = $('prModalFooter');
  const riderName = $('prModalName')?.textContent || 'ciclista';
  const teamName  = $('prModalSub')?.textContent  || '';

  // Ocultar elementos interactivos para la captura
  if(exportBtn) exportBtn.style.visibility = 'hidden';
  if(footer)    footer.style.display       = 'none';

  try {
    const canvas = await html2canvas(modalEl, {
      scale: 2,
      useCORS: true,
      backgroundColor: '#ffffff',
      logging: false
    });

    // Añadir cabecera con degradado al canvas final
    const PAD = 0; // sin padding extra; la modal ya lleva su propio header
    const out = document.createElement('canvas');
    out.width  = canvas.width;
    out.height = canvas.height + PAD;
    const ctx = out.getContext('2d');
    ctx.drawImage(canvas, 0, PAD);

    const link = document.createElement('a');
    const safeName = riderName.normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-zA-Z0-9_]/g,'_');
    link.download = `informe_${safeName}.png`;
    link.href = out.toDataURL('image/png');
    link.click();
  } catch(e){
    console.error('Error exportando imagen del ciclista:', e);
    alert('No se pudo generar la imagen. Revisa la consola.');
  } finally {
    if(exportBtn) exportBtn.style.visibility = '';
    if(footer)    footer.style.display       = '';
  }
}

async function _prOpenRiderModal(riderName, teamName){
  const modal = $('prRiderModal');
  if(!modal) return;

  // Mostrar modal con skeleton mientras carga
  modal.style.display = 'flex';
  $('prModalName').textContent = _evolNormName(riderName);
  $('prModalSub').textContent  = escapeHtml(teamName);
  $('prModalKpis').innerHTML   = '<div style="grid-column:1/-1;text-align:center;color:#9ca3af;padding:12px">Cargando...</div>';
  $('prModalBody').innerHTML   = '';
  $('prModalFooter').innerHTML = '';

  const history = await _ensureHistory();
  const nameKeyTarget = normalizeForMatching(riderName);

  // Buscar todas las participaciones de este ciclista en el historial
  const entries = [];
  for(const race of history){
    const raceYear = (_parseSpanishDate(race.raceDate)||race.raceDate||'').slice(0,4);
    const rider = (race.riders||[]).find(r=>normalizeForMatching(r.name)===nameKeyTarget);
    if(!rider) continue;
    const rcat = getRiderCorrectCat(rider.name, raceYear?parseInt(raceYear):null, rider.cat);
    entries.push({
      raceName: race.raceName||'—',
      raceDate: race.raceDate||'',
      localidad: race.localidad||'',
      pos:       rider.pos,
      total:     (race.riders||[]).length,
      cat:       rcat,
      time:      rider.time||'—'
    });
  }

  // Ordenar cronológico
  entries.sort((a,b)=>(_parseSpanishDate(b.raceDate)||'').localeCompare(_parseSpanishDate(a.raceDate)||''));

  // Año activo en el PR para destacar
  const prYear = $('prYearFilter')?.value || '';

  // Filtrar al año seleccionado para KPIs
  const yearEntries = prYear ? entries.filter(e=>(_parseSpanishDate(e.raceDate)||e.raceDate||'').slice(0,4)===prYear) : entries;

  // KPIs
  const positions = yearEntries.map(e=>e.pos).filter(p=>p>0);
  const best = positions.length ? Math.min(...positions) : '—';
  const avg  = positions.length ? (positions.reduce((s,p)=>s+p,0)/positions.length).toFixed(1) : '—';
  const last3 = positions.slice(-3);
  let trend = '→'; let trendColor = '#667085';
  if(last3.length>=2){
    if(last3[last3.length-1]<last3[0]){ trend='↗'; trendColor='#067647'; }
    else if(last3[last3.length-1]>last3[0]){ trend='↘'; trendColor='#b42318'; }
  }

  $('prModalKpis').innerHTML = `
    <div class="pr-modal-kpi"><div class="pr-modal-kpi-val">${positions.length}</div><div class="pr-modal-kpi-lbl">Carreras</div></div>
    <div class="pr-modal-kpi"><div class="pr-modal-kpi-val">${best}º</div><div class="pr-modal-kpi-lbl">Mejor</div></div>
    <div class="pr-modal-kpi"><div class="pr-modal-kpi-val">${avg} Ø</div><div class="pr-modal-kpi-lbl">Media</div></div>
    <div class="pr-modal-kpi"><div class="pr-modal-kpi-val" style="color:${trendColor}">${trend}</div><div class="pr-modal-kpi-lbl">Tendencia</div></div>`;

  // Tabla de carreras
  if(!yearEntries.length){
    $('prModalBody').innerHTML = '<div style="text-align:center;color:#9ca3af;padding:20px">No hay datos para el período seleccionado.</div>';
  } else {
    $('prModalBody').innerHTML =
      `<div style="font-size:11px;font-weight:700;color:#475467;text-transform:uppercase;margin-bottom:6px">${prYear||'Historial completo'} · ${yearEntries.length} carrera${yearEntries.length!==1?'s':''}</div>` +
      yearEntries.map((e,i)=>{
        const prevPos = i>0 ? yearEntries[i-1].pos : null;
        const trendIcon = prevPos===null?'':e.pos<prevPos?'🔼':e.pos>prevPos?'🔽':'➡️';
        const pct = e.total>0 ? Math.round((1-(e.pos-1)/(e.total-1||1))*100) : 0;
        const barColor = pct>=75?'#067647':pct>=50?'#1f6feb':'#b45309';
        return `<div class="pr-modal-race-row">
          <div>
            <div class="pr-modal-race-name">${escapeHtml(e.raceName)}</div>
            <div class="pr-modal-race-date">${escapeHtml(e.raceDate)}${e.localidad?' · 📍'+escapeHtml(e.localidad):''} · ${escapeHtml(e.cat)}</div>
            <div style="background:#eef2f6;border-radius:999px;height:4px;margin-top:3px;overflow:hidden">
              <div style="height:4px;background:${barColor};width:${pct}%;border-radius:999px"></div>
            </div>
          </div>
          <span class="pr-modal-race-date">${escapeHtml(e.time)}</span>
          <span class="pr-modal-race-pos">${e.pos}º<span style="font-size:9px;font-weight:400;color:#9ca3af">/${e.total}</span></span>
          <span class="pr-modal-race-trend">${trendIcon}</span>
        </div>`;
      }).join('');
  }

  // Footer con acciones
  const myTeamCanon = getCanonicalTeam(myTeam||'').toLowerCase();
  const riderTeam   = getCanonicalTeam(teamName||'').toLowerCase();
  const isOwn       = myTeamCanon && riderTeam===myTeamCanon;

  let footerBtns = `<button class="btn secondary" style="font-size:12px;padding:7px 13px" onclick="closePrRiderModal()">Cerrar</button>`;
  if(isOwn){
    footerBtns += `<button class="btn" style="font-size:12px;padding:7px 13px;background:#0b2f6b" onclick="closePrRiderModal();_prNavToEvolucion('${escapeAttr(riderName)}')">📈 Ver Trayectoria</button>`;
  }
  if(hasValidData){
    footerBtns += `<button class="btn light" style="font-size:12px;padding:7px 13px" onclick="closePrRiderModal();_prNavToAnalisis('${escapeAttr(riderName)}')">👤 Análisis Individual</button>`;
  }
  $('prModalFooter').innerHTML = footerBtns;
}

function _prNavToAnalisis(riderName){
  if($('analysisSearchInput')) $('analysisSearchInput').value = riderName;
  if($('searchInput')) $('searchInput').value = riderName;
  showView('view-analisis');
  setTimeout(analyseSelectedRider, 150);
}

function _prNavToEvolucion(riderName){
  showView('view-evolucion');
  setTimeout(()=>{
    showEvolTab('riders');
    setTimeout(()=>{
      const sel = $('evolRiderSelect');
      if(!sel||!sel.options.length) return;
      const norm = riderName.toLowerCase();
      let found = Array.from(sel.options).find(o=>{
        const base = o.text.toLowerCase().split('(')[0].trim();
        return base===norm||base.includes(norm)||norm.includes(base);
      });
      if(!found){
        const part = norm.split(/[\s,]/)[0];
        found = Array.from(sel.options).find(o=>o.text.toLowerCase().includes(part));
      }
      if(found&&found.value){sel.value=found.value;evolSelectRider(found.value);}
    },400);
  },200);
}

async function exportPowerRankingImg(){
  const btn = $('prExportBtn');
  if(btn){ btn.textContent='⏳ Generando...'; btn.disabled=true; }

  let wrapper = null;
  try{
    // ── Recopilar valores de filtros activos ──────────────────────────────
    const year    = $('prYearFilter')?.value  || 'Todos los años';
    const region  = $('prRegionFilter')?.value || 'Todas las CCAA';
    const genderRaw = $('prGenderFilter')?.value || '';
    const genderLabel = genderRaw==='M' ? 'Masculino' : genderRaw==='F' ? 'Femenino' : 'Todos los géneros';
    const selCatsArr = [..._prSelectedCats];
    const catsLabel  = selCatsArr.length ? selCatsArr.join(' · ') : 'Todas las categorías';
    const infoEl     = $('prInfo');
    const infoText   = infoEl ? infoEl.textContent : '';
    const dateStr    = new Date().toLocaleDateString('es-ES',{day:'2-digit',month:'long',year:'numeric'});

    // ── Clonar el grid ───────────────────────────────────────────────────
    const gridWrap = document.querySelector('.pr-grid-wrap');
    if(!gridWrap) throw new Error('No hay datos para exportar.');
    const gridClone = gridWrap.cloneNode(true);

    // ── Construir wrapper temporal con cabecera ──────────────────────────
    wrapper = document.createElement('div');
    wrapper.style.cssText = [
      'position:fixed','top:0','left:-9999px','z-index:-1',
      'background:#f4f7fb','padding:20px 20px 16px',
      'font-family:Arial,Helvetica,sans-serif',
      'width:'+(gridWrap.offsetWidth+40)+'px',
      'box-sizing:border-box'
    ].join(';');

    // Cabecera
    const header = document.createElement('div');
    header.style.cssText = 'background:linear-gradient(135deg,#0b2f6b,#1286c7);border-radius:14px 14px 0 0;padding:16px 20px 14px;color:#fff;margin-bottom:0';
    header.innerHTML = `
      <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:16px">
        <div>
          <div style="font-size:22px;font-weight:900;letter-spacing:-.3px;margin-bottom:4px">🏆 Power Ranking de Temporada</div>
          <div style="font-size:13px;opacity:.85;font-weight:600">${infoText}</div>
        </div>
        <div style="text-align:right;flex-shrink:0">
          <div style="font-size:11px;opacity:.7;margin-bottom:6px">Generado el ${dateStr}</div>
          ${myTeam ? `<div style="font-size:12px;font-weight:800;background:rgba(255,255,255,.18);padding:4px 10px;border-radius:8px">⭐ ${escapeHtml(myTeam)}</div>` : ''}
        </div>
      </div>
      <div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:12px">
        <span style="background:rgba(255,255,255,.2);border-radius:999px;padding:4px 12px;font-size:12px;font-weight:700">📅 ${year}</span>
        <span style="background:rgba(255,255,255,.2);border-radius:999px;padding:4px 12px;font-size:12px;font-weight:700">🗺️ ${region}</span>
        <span style="background:rgba(255,255,255,.2);border-radius:999px;padding:4px 12px;font-size:12px;font-weight:700">⚧ ${genderLabel}</span>
        <span style="background:rgba(255,255,255,.2);border-radius:999px;padding:4px 12px;font-size:12px;font-weight:700">🎽 ${escapeHtml(catsLabel)}</span>
      </div>`;

    // Grid clonado (sin bordes redondeados en la parte superior)
    gridClone.style.borderRadius = '0';
    gridClone.style.paddingTop   = '14px';
    gridClone.style.paddingBottom = '14px';

    // ── Leyenda metodológica ─────────────────────────────────────────────
    const legend = document.createElement('div');
    legend.style.cssText = [
      'background:#1e3a5f','border-radius:0 0 14px 14px',
      'padding:14px 20px','color:#e2e8f0',
      'font-family:Arial,Helvetica,sans-serif','font-size:11px','line-height:1.6'
    ].join(';');
    legend.innerHTML = `
      <div style="font-size:12px;font-weight:800;color:#93c5fd;margin-bottom:8px;letter-spacing:.3px;text-transform:uppercase">
        📐 Metodología de clasificación
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px 24px">
        <div>
          <span style="color:#fbbf24;font-weight:700">Puntuación ciclista (X.X Ø)</span><br>
          Media aritmética de las posiciones obtenidas en cada prueba. <b style="color:#fff">Menor valor = mejor rendimiento.</b>
          El formato <b style="color:#fff">X.X Ø (Y/Z)</b> indica: media de posición · carreras disputadas / carreras totales del período.
        </div>
        <div>
          <span style="color:#fbbf24;font-weight:700">Clasificación de equipos</span><br>
          Se calcula sumando la puntuación penalizada de los <b style="color:#fff">3 mejores ciclistas</b> del equipo.
          Los ciclistas que no participan en una prueba reciben una penalización equivalente al máximo de participantes + 1, evitando que equipos con pocas carreras aparezcan mejor clasificados.
        </div>
        <div>
          <span style="color:#fbbf24;font-weight:700">⚡ Líder de calidad</span><br>
          Icono asignado al ciclista con <b style="color:#fff">mejor media de posición</b> del equipo, aunque no sea el que más carreras ha disputado. Indica rendimiento excepcional por participaciones.
        </div>
        <div>
          <span style="color:#fbbf24;font-weight:700">Umbral de participación (33%)</span><br>
          Solo se incluyen en el Top 6 del equipo los ciclistas que hayan participado en al menos el <b style="color:#fff">33% de las carreras</b> del compañero más activo. Evita que aparezcan ciclistas con una única carrera muy buena.
        </div>
      </div>
      <div style="margin-top:10px;padding-top:8px;border-top:1px solid rgba(255,255,255,.12);color:#94a3b8;font-size:10px">
        Generado con <b style="color:#93c5fd">Cycling Director</b> · Datos: ${infoText} · ${dateStr}
      </div>`;

    wrapper.appendChild(header);
    wrapper.appendChild(gridClone);
    wrapper.appendChild(legend);
    document.body.appendChild(wrapper);

    // Esperar un tick para que el DOM se pinte
    await new Promise(r=>setTimeout(r,80));

    const canvas = await html2canvas(wrapper, {
      backgroundColor: '#f4f7fb',
      scale: 2,
      useCORS: true,
      logging: false,
      width: wrapper.offsetWidth,
      height: wrapper.offsetHeight
    });

    const a = document.createElement('a');
    a.href = canvas.toDataURL('image/png');
    a.download = `power-ranking-${year.replace(/\s+/g,'-')}-${region.replace(/\s+/g,'-')}.png`;
    a.click();

  }catch(e){
    console.error(e);
    alert('No se pudo generar la imagen: '+(e.message||e));
  }finally{
    if(wrapper && wrapper.parentNode) wrapper.parentNode.removeChild(wrapper);
    if(btn){ btn.textContent='📸 Generar Informe (Imagen)'; btn.disabled=false; }
  }
}
// ===== FIN POWER RANKING =====

// ===== TENDENCIAS DE TEMPORADA =====
let _trendFiltersReady  = false;
let _trendSelectedCats  = new Set(['CAD-1','CAD-2']); // independiente del PR
let _trendSelectedRiders = [];  // array de {name, color}
let _trendSelectedTeams  = [];  // array de {name, color}
let _trendActiveTab      = 'riders';
let _trendMainTab        = 'evol'; // 'evol' | 'comp'
let _trendChartRiders    = null;
let _trendChartTeams     = null;
let _trendChartRadar     = null;
let _trendChartDistri    = null;

const TREND_PALETTE = [
  '#1f6feb','#12b76a','#f79009','#b42318','#667085',
  '#6d28d9','#be185d','#0e7490','#b45309','#047857',
  '#c2410c','#1e40af','#15803d','#9333ea','#0b2f6b'
];
function _trendColor(name){
  let h=0; for(let i=0;i<name.length;i++) h=(h*31+name.charCodeAt(i))&0xffff;
  return TREND_PALETTE[h % TREND_PALETTE.length];
}

function trendSwitchMainTab(tab){
  _trendMainTab = tab;
  $('trendMainTabEvol').classList.toggle('active', tab==='evol');
  $('trendMainTabComp').classList.toggle('active', tab==='comp');
  $('trendPanelEvol').style.display = tab==='evol' ? '' : 'none';
  $('trendPanelComp').style.display = tab==='comp' ? '' : 'none';
  if(tab==='comp'){ _trendRenderChipsComp(); trendDrawComp(); }
}

function trendSwitchTab(tab){
  _trendActiveTab = tab;
  $('trendTabRiders').classList.toggle('active', tab==='riders');
  $('trendTabTeams').classList.toggle('active',  tab==='teams');
  $('trendPanelRiders').style.display = tab==='riders' ? '' : 'none';
  $('trendPanelTeams').style.display  = tab==='teams'  ? '' : 'none';
}

function _trendToggleCat(cat){
  if(cat==='__all__'){ _trendSelectedCats.clear(); }
  else { _trendSelectedCats.has(cat) ? _trendSelectedCats.delete(cat) : _trendSelectedCats.add(cat); }
  _trendRenderCatPills();
  renderTendencias();
}

function _trendRenderCatPills(){
  const container = $('trendCatPills'); if(!container) return;
  container.querySelectorAll('.pr-cat-pill').forEach(p=>{
    const cat = p.dataset.cat;
    if(cat==='__all__') p.classList.toggle('pr-pill-active', _trendSelectedCats.size===0);
    else p.classList.toggle('pr-pill-active', _trendSelectedCats.has(cat));
  });
}

function _initTrendFilters(history){
  const currentYear = String(new Date().getFullYear());
  // Años
  const years = [...new Set(history.map(h=>(_parseSpanishDate(h.raceDate)||'').slice(0,4)).filter(Boolean))].sort().reverse();
  const ySel = $('trendYearFilter');
  if(ySel){
    ySel.innerHTML = '<option value="">Todos los años</option>' +
      years.map(y=>`<option value="${y}"${y===currentYear?' selected':''}>${y}</option>`).join('');
  }
  // CCAA inferida por equipo
  const teamRegionCounts = {};
  for(const race of history){
    for(const r of (race.riders||[])){
      if(!(r.region||'')) continue;
      const team = getCanonicalTeam(r.team||'').trim(); if(!team) continue;
      if(!teamRegionCounts[team]) teamRegionCounts[team]={};
      teamRegionCounts[team][r.region] = (teamRegionCounts[team][r.region]||0)+1;
    }
  }
  const allRegions = new Set();
  for(const counts of Object.values(teamRegionCounts)){
    const best = Object.entries(counts).sort((a,b)=>b[1]-a[1])[0];
    if(best) allRegions.add(best[0]);
  }
  const regions = [...allRegions].sort();
  const rSel = $('trendRegionFilter');
  if(rSel){
    const hasVLC = regions.includes('VLC');
    rSel.innerHTML = '<option value="">Todas las CCAA</option>' +
      regions.map(r=>`<option value="${r}"${(!rSel.value && r==='VLC' && hasVLC)?' selected':''}>${r}</option>`).join('');
  }
  // Cats pills
  const cats = [...new Set(history.flatMap(h=>{
    const y = (_parseSpanishDate(h.raceDate)||'').slice(0,4);
    return (h.riders||[]).map(r=>getRiderCorrectCat(r.name, y?parseInt(y):null, r.cat)||'').filter(Boolean);
  }))].sort();
  const pillsEl = $('trendCatPills');
  if(pillsEl){
    const allActive = _trendSelectedCats.size===0;
    pillsEl.innerHTML =
      `<span class="pr-cat-pill pr-pill-all${allActive?' pr-pill-active':''}" data-cat="__all__" onclick="_trendToggleCat('__all__')">Todas</span>` +
      cats.map(c=>`<span class="pr-cat-pill${_trendSelectedCats.has(c)?' pr-pill-active':''}" data-cat="${escapeHtml(c)}" onclick="_trendToggleCat('${escapeAttr(c)}')">${escapeHtml(c)}</span>`).join('');
  }
  // Datalists
  const allRiders = [...new Set(history.flatMap(h=>(h.riders||[]).map(r=>normalizeRiderName(r.name||'')).filter(Boolean)))].sort();
  const rdl = $('trendRiderDatalist');
  if(rdl) rdl.innerHTML = allRiders.map(r=>`<option value="${escapeHtml(r)}">`).join('');
  const allTeams = [...new Set(history.flatMap(h=>(h.riders||[]).map(r=>getCanonicalTeam(r.team||'')).filter(Boolean)))].sort();
  const tdl = $('trendTeamDatalist');
  if(tdl) tdl.innerHTML = allTeams.map(t=>`<option value="${escapeHtml(t)}">`).join('');
  // Auto-cargar el mejor ciclista de mi equipo si la lista está vacía
  if(_trendSelectedRiders.length===0 && _trendSelectedTeams.length===0 && myTeam){
    const myCanon = getCanonicalTeam(myTeam||'').toLowerCase();
    // Buscar el ciclista con mejor posición media del equipo
    const riderStats = {};
    for(const race of history){
      for(const r of (race.riders||[])){
        if(getCanonicalTeam(r.team||'').toLowerCase()!==myCanon) continue;
        const nk = normalizeRiderName(r.name||'').trim();
        if(!nk || !r.pos || r.pos<=0) continue;
        if(!riderStats[nk]) riderStats[nk]={name:r.name, total:0, count:0};
        riderStats[nk].total += r.pos;
        riderStats[nk].count++;
      }
    }
    const best = Object.values(riderStats)
      .filter(s=>s.count>=1)
      .sort((a,b)=>(a.total/a.count)-(b.total/b.count))[0];
    if(best){
      _trendAddRiderByName(normalizeRiderName(best.name)||best.name);
    } else if(myCanon){
      // Sin historial: mostrar el equipo como fallback
      _trendAddTeamByName(getCanonicalTeam(myTeam));
    }
    // Asegurar que la pestaña Ciclistas está activa
    trendSwitchTab('riders');
  }
}

function _trendAddRiderByName(name){
  if(!name || _trendSelectedRiders.find(r=>r.name===name)) return;
  _trendSelectedRiders.push({name, color:_trendColor(name)});
}
function _trendAddTeamByName(name){
  if(!name || _trendSelectedTeams.find(t=>t.name===name)) return;
  _trendSelectedTeams.push({name, color:_trendColor(name)});
}

function trendAddRider(){
  const inp = $('trendRiderInput'); if(!inp) return;
  const val = inp.value.trim(); if(!val) return;
  _trendAddRiderByName(normalizeRiderName(val)||val);
  inp.value = '';
  _trendRenderChips();
  _trendDrawRidersChart(_trendLastHistory||[]);
}
function trendAddTeam(){
  const inp = $('trendTeamInput'); if(!inp) return;
  const val = inp.value.trim(); if(!val) return;
  _trendAddTeamByName(getCanonicalTeam(val)||val);
  inp.value = '';
  _trendRenderChips();
  _trendDrawTeamsChart(_trendLastHistory||[]);
}
function trendRemoveRider(name){
  _trendSelectedRiders = _trendSelectedRiders.filter(r=>r.name!==name);
  _trendRenderChips();
  _trendDrawRidersChart(_trendLastHistory||[]);
}
function trendRemoveTeam(name){
  _trendSelectedTeams = _trendSelectedTeams.filter(t=>t.name!==name);
  _trendRenderChips();
  _trendDrawTeamsChart(_trendLastHistory||[]);
}
function trendClearRiders(){ _trendSelectedRiders=[]; _trendRenderChips(); _trendDrawRidersChart(_trendLastHistory||[]); }
function trendClearTeams(){  _trendSelectedTeams=[]; _trendRenderChips(); _trendDrawTeamsChart(_trendLastHistory||[]); }

function _trendRenderChips(){
  const rHtml = _trendSelectedRiders.map(r=>
    `<span class="trend-chip" style="background:${r.color}">${escapeHtml(_evolNormName(r.name))}
      <button class="trend-chip-remove" onclick="trendRemoveRider('${escapeAttr(r.name)}')">✕</button>
    </span>`).join('');
  const tHtml = _trendSelectedTeams.map(t=>
    `<span class="trend-chip" style="background:${t.color}">${escapeHtml(t.name)}
      <button class="trend-chip-remove" onclick="trendRemoveTeam('${escapeAttr(t.name)}')">✕</button>
    </span>`).join('');
  if($('trendRiderChips')) $('trendRiderChips').innerHTML = rHtml;
  if($('trendTeamChips'))  $('trendTeamChips').innerHTML  = tHtml;
  _trendRenderChipsComp();
}

function _trendRenderChipsComp(){
  const rHtml = _trendSelectedRiders.map(r=>
    `<span class="trend-chip" style="background:${r.color}">${escapeHtml(_evolNormName(r.name))}
      <button class="trend-chip-remove" onclick="trendRemoveRider('${escapeAttr(r.name)}');trendDrawComp()">✕</button>
    </span>`).join('');
  const tHtml = _trendSelectedTeams.map(t=>
    `<span class="trend-chip" style="background:${t.color}">${escapeHtml(t.name)}
      <button class="trend-chip-remove" onclick="trendRemoveTeam('${escapeAttr(t.name)}');trendDrawComp()">✕</button>
    </span>`).join('');
  if($('trendRiderChipsComp')) $('trendRiderChipsComp').innerHTML = rHtml;
  if($('trendTeamChipsComp'))  $('trendTeamChipsComp').innerHTML  = tHtml;
}

function trendAddRiderComp(){
  const inp=$('trendRiderInputComp'); if(!inp) return;
  const val=inp.value.trim(); if(!val) return;
  _trendAddRiderByName(normalizeRiderName(val)||val);
  inp.value=''; _trendRenderChipsComp(); trendDrawComp();
}
function trendAddTeamComp(){
  const inp=$('trendTeamInputComp'); if(!inp) return;
  const val=inp.value.trim(); if(!val) return;
  _trendAddTeamByName(getCanonicalTeam(val)||val);
  inp.value=''; _trendRenderChipsComp(); trendDrawComp();
}

let _trendLastHistory = null;

async function renderTendencias(){
  const container = $('view-tendencias'); if(!container) return;
  const history = _historyForGlobalCat(await _ensureHistory());
  if(!_trendFiltersReady){
    _initTrendFilters(history);
    _trendFiltersReady = true;
  }
  // Auto-cargar mejor ciclista de Mi Equipo si la lista está vacía
  if(_trendSelectedRiders.length===0 && _trendSelectedTeams.length===0 && myTeam){
    const myCanon = getCanonicalTeam(myTeam||'').toLowerCase();
    const riderStats = {};
    for(const race of history){
      for(const r of (race.riders||[])){
        if(getCanonicalTeam(r.team||'').toLowerCase()!==myCanon) continue;
        const nk = normalizeRiderName(r.name||'').trim();
        if(!nk || !r.pos || r.pos<=0) continue;
        if(!riderStats[nk]) riderStats[nk]={name:r.name, total:0, count:0};
        riderStats[nk].total += r.pos;
        riderStats[nk].count++;
      }
    }
    const best = Object.values(riderStats)
      .filter(s=>s.count>=1)
      .sort((a,b)=>(a.total/a.count)-(b.total/b.count))[0];
    if(best){
      _trendAddRiderByName(normalizeRiderName(best.name)||best.name);
      trendSwitchTab('riders');
    }
  }
  const year   = $('trendYearFilter')?.value  || '';
  const region = $('trendRegionFilter')?.value || '';
  const gender = $('trendGenderFilter')?.value || '';
  // Calcular metadatos de región/género de equipos
  const {teamRegion, teamGender} = _prBuildTeamMeta(history);
  // Filtrar carreras
  let filtered = history.filter(race=>{
    const ry = (_parseSpanishDate(race.raceDate)||race.raceDate||'').slice(0,4);
    if(year && ry!==year) return false;
    if(region || gender){
      const hasValidRider = (race.riders||[]).some(r=>{
        const team = getCanonicalTeam(r.team||'').trim();
        if(region && teamRegion[team]!==region) return false;
        if(gender && teamGender[team]!==gender) return false;
        return true;
      });
      if(!hasValidRider) return false;
    }
    if(_trendSelectedCats.size>0){
      const ry2 = (_parseSpanishDate(race.raceDate)||'').slice(0,4);
      const hasValidCat = (race.riders||[]).some(r=>{
        const rcat = getRiderCorrectCat(r.name, ry2?parseInt(ry2):null, r.cat);
        return _trendSelectedCats.has(rcat);
      });
      if(!hasValidCat) return false;
    }
    return true;
  });
  // Ordenar cronológicamente
  filtered.sort((a,b)=>(_parseSpanishDate(a.raceDate)||'').localeCompare(_parseSpanishDate(b.raceDate)||''));
  _trendLastHistory = filtered;
  _trendRenderChips();
  _trendDrawRidersChart(filtered);
  _trendDrawTeamsChart(filtered);
}

/* ── Parte un nombre largo en máx. 2 líneas para el eje X ── */
function _trendWrapLabel(s, maxLen){
  if(!s) return [''];
  s = s.trim();
  if(s.length <= maxLen) return [s];
  // Buscar el espacio más cercano al centro
  const mid = Math.floor(s.length/2);
  let best = -1, bestDist = Infinity;
  for(let i=0;i<s.length;i++){
    if(s[i]===' '){ const d=Math.abs(i-mid); if(d<bestDist){bestDist=d;best=i;} }
  }
  if(best===-1) return [s.slice(0,maxLen), s.slice(maxLen)];
  return [s.slice(0,best), s.slice(best+1)];
}

/* ── Interpola la posición esperada en una carrera no disputada ── */
function _trendInterpolate(data, i){
  let prev=null, next=null, pi=-1, ni=-1;
  for(let j=i-1;j>=0;j--){ if(data[j]!==null){prev=data[j];pi=j;break;} }
  for(let j=i+1;j<data.length;j++){ if(data[j]!==null){next=data[j];ni=j;break;} }
  if(prev===null && next===null) return null;
  if(prev===null) return next;
  if(next===null) return prev;
  const ratio = (i-pi)/(ni-pi);
  return Math.round(prev + (next-prev)*ratio);
}

/* ── Plugin inline para bandas grises en carreras no disputadas ── */
function _trendNpBandsPlugin(raceList, npSet){
  return {
    id:'npBands',
    beforeDraw(chart){
      if(!npSet.size) return;
      const {ctx, scales:{x,y}} = chart;
      if(!x||!y) return;
      const bw = x.width / raceList.length;
      ctx.save();
      ctx.fillStyle = 'rgba(160,160,160,0.09)';
      npSet.forEach(idx=>{
        const px = x.getPixelForValue(idx);
        ctx.fillRect(px-bw/2, y.top, bw, y.height);
      });
      ctx.restore();
    }
  };
}

/* ── Genera los tres datasets por ciclista: línea principal + NP markers + media Ø ── */
function _trendRiderDatasets(entry, raceList){
  const nk = normalizeForMatching(entry.name);
  const participated = raceList.map(race=>{
    const rider = (race.riders||[]).find(r=>normalizeForMatching(r.name)===nk);
    return rider ? rider.pos : null;
  });
  // NP: posición interpolada entre los resultados adyacentes
  const npData = participated.map((v,i)=>{
    if(v!==null) return null;
    return _trendInterpolate(participated, i);
  });
  // Media acumulada (solo carreras disputadas) — carry-forward para que llegue al final
  const cumAvg=[]; let sum=0,cnt=0;
  participated.forEach(v=>{ if(v!==null){sum+=v;cnt++;cumAvg.push(+(sum/cnt).toFixed(1));}else cumAvg.push(null); });
  // Propagar hacia adelante el último valor conocido (línea punteada nunca se corta)
  let lastKnown=null;
  for(let i=0;i<cumAvg.length;i++){
    if(cumAvg[i]!==null) lastKnown=cumAvg[i];
    else if(lastKnown!==null) cumAvg[i]=lastKnown;
  }

  return {
    participated, npData, cumAvg,
    datasets:[
      // 1. Línea principal — spanGaps:true, puntos sólidos solo donde participó
      {
        label: _evolNormName(entry.name),
        data: participated,
        borderColor: entry.color, backgroundColor: entry.color+'22',
        tension:0.35, fill:false, spanGaps:true,
        pointRadius:     participated.map(v=>v!==null?5:0),
        pointHoverRadius:participated.map(v=>v!==null?8:0),
        pointBackgroundColor: entry.color,
        pointBorderColor:'#fff', pointBorderWidth:2,
        _isMain:true, _riderName:entry.name
      },
      // 2. Marcadores NP — cruz semitransparente en posición interpolada
      {
        label: '​'+_evolNormName(entry.name), // zero-width space → ocultar de leyenda
        data: npData,
        type:'scatter', showLine:false,
        pointStyle:'crossRot', pointRadius:9, pointHoverRadius:11,
        pointBorderColor: entry.color+'99', pointBackgroundColor:'transparent',
        pointBorderWidth:2.5,
        _isNP:true, _riderName:entry.name
      },
      // 3. Media acumulada punteada
      {
        label: _evolNormName(entry.name)+' (media Ø)',
        data: cumAvg,
        borderColor:entry.color, borderDash:[5,4],
        tension:0.35, fill:false, pointRadius:0, borderWidth:1.5, spanGaps:false
      }
    ]
  };
}

function _trendDrawRidersChart(filtered){
  const wrap = $('trendRiderChart'); if(!wrap) return;
  if(_trendSelectedRiders.length===0){
    if(_trendChartRiders){ _trendChartRiders.destroy(); _trendChartRiders=null; }
    wrap.innerHTML = '<div class="trend-empty">Selecciona al menos un ciclista para ver su evolución carrera a carrera.<br><span style="font-size:11px;color:#b0b8c4">Usa el buscador de arriba para añadir ciclistas.</span></div>';
    return;
  }
  const raceList = [...new Map(filtered.map(r=>[r.raceName+'|'+r.raceDate, r])).values()];
  const labels   = raceList.map(r=>_trendWrapLabel(r.raceName||'', 26));
  const datasets = [];
  const statsRows = [];
  const npIndicesAll = new Set(); // unión de todas las ausencias

  for(const entry of _trendSelectedRiders){
    const {participated, npData, datasets:ds} = _trendRiderDatasets(entry, raceList);
    datasets.push(...ds);
    participated.forEach((v,i)=>{ if(v===null) npIndicesAll.add(i); });
    const valid = participated.filter(v=>v!==null);
    statsRows.push({
      name:_evolNormName(entry.name), color:entry.color,
      races:valid.length,
      best:  valid.length?Math.min(...valid):'—',
      worst: valid.length?Math.max(...valid):'—',
      avg:   valid.length?(valid.reduce((s,v)=>s+v,0)/valid.length).toFixed(1):'—'
    });
  }

  if(_trendChartRiders){ _trendChartRiders.destroy(); _trendChartRiders=null; }
  wrap.innerHTML = `
    <div class="trend-chart-title">🚴 Evolución de posición por carrera
      <span style="font-size:10px;font-weight:500;color:#9ca3af;margin-left:10px">✕ = No Participó (NP) · ---- = Media acumulada</span>
    </div>
    <div class="trend-canvas-wrap"><canvas id="trendCanvasRiders"></canvas></div>
    <div style="display:grid;grid-template-columns:auto 1fr;gap:16px;margin-top:14px;align-items:start">
      <div class="trend-stats-row" id="trendStatsRiders"></div>
      <div id="trendHeatmapRiders"></div>
    </div>`;
  const ctx = $('trendCanvasRiders'); if(!ctx) return;

  _trendChartRiders = new Chart(ctx,{
    type:'line',
    data:{labels, datasets},
    plugins:[ _trendNpBandsPlugin(raceList, npIndicesAll) ],
    options:{
      responsive:true, maintainAspectRatio:false,
      scales:{
        y:{reverse:true, title:{display:true,text:'Posición (↑ mejor)'},
           ticks:{stepSize:1}, grid:{color:'#f0f0f0'}},
        x:{ticks:{maxRotation:0, minRotation:0, font:{size:10}, autoSkip:false}, grid:{display:false}}
      },
      plugins:{
        legend:{
          position:'top',
          labels:{
            font:{size:11}, boxWidth:14,
            // ocultar datasets NP (zero-width space) y media Ø de la leyenda visible
            filter: item => !item.text.startsWith('​') && !item.text.includes('(media Ø)')
          }
        },
        tooltip:{
          mode:'index', intersect:false,
          callbacks:{
            label(item){
              if(item.dataset._isNP && item.parsed.y!==null)
                return `${_evolNormName(item.dataset._riderName)}: ❌ No Participó (NP)`;
              if(item.dataset._isMain && item.parsed.y!==null)
                return `${item.dataset.label}: ${item.parsed.y}º`;
              if(item.dataset.label.includes('(media Ø)') && item.parsed.y!==null)
                return `Media acum.: ${item.parsed.y} Ø`;
              return null;
            },
            // Quitar filas con null del tooltip
            filter: item => item.parsed.y !== null
          }
        }
      }
    }
  });

  const sr = $('trendStatsRiders');
  if(sr) sr.innerHTML = statsRows.map(s=>`
    <div class="trend-stat-card" style="border-left-color:${s.color}">
      <div class="trend-stat-name" style="color:${s.color}">${escapeHtml(s.name)}</div>
      <div class="trend-stat-kpis">
        <div class="trend-stat-kpi"><div class="trend-stat-val">${s.races}</div><div class="trend-stat-lbl">Carreras</div></div>
        <div class="trend-stat-kpi"><div class="trend-stat-val" style="color:#067647">${s.best===1?'🥇':s.best+'º'}</div><div class="trend-stat-lbl">Mejor</div></div>
        <div class="trend-stat-kpi"><div class="trend-stat-val" style="color:#b42318">${s.worst}º</div><div class="trend-stat-lbl">Peor</div></div>
        <div class="trend-stat-kpi"><div class="trend-stat-val">${s.avg} Ø</div><div class="trend-stat-lbl">Media</div></div>
      </div>
    </div>`).join('');

  // Mapa de calor
  const hm = $('trendHeatmapRiders');
  if(hm) hm.innerHTML = _trendBuildHeatmap(_trendSelectedRiders, raceList);
}

function _trendDrawTeamsChart(filtered){
  const wrap = $('trendTeamChart'); if(!wrap) return;
  if(_trendSelectedTeams.length===0){
    if(_trendChartTeams){ _trendChartTeams.destroy(); _trendChartTeams=null; }
    wrap.innerHTML = '<div class="trend-empty">Selecciona al menos un equipo para ver su ranking carrera a carrera.<br><span style="font-size:11px;color:#b0b8c4">Usa el buscador de arriba para añadir equipos.</span></div>';
    return;
  }
  const raceList = [...new Map(filtered.map(r=>[r.raceName+'|'+r.raceDate, r])).values()];
  const labels   = raceList.map(r=>_trendWrapLabel(r.raceName||'', 26));
  const datasets = [];
  const statsRows = [];
  const catFilter = _trendSelectedCats.size===1 ? [..._trendSelectedCats][0] : null;
  const npIndicesAll = new Set();

  for(const entry of _trendSelectedTeams){
    const teamCanon = getCanonicalTeam(entry.name).toLowerCase();
    const participated = raceList.map(race=>{
      const allRanks = _evolAllTeamRanks(race.riders||[], catFilter);
      const found = allRanks.find(t=>(getCanonicalTeam(t.team||'')||'').toLowerCase()===teamCanon);
      return found ? found.rank : null;
    });
    const npData = participated.map((v,i)=>v!==null?null:_trendInterpolate(participated,i));
    participated.forEach((v,i)=>{ if(v===null) npIndicesAll.add(i); });
    const valid = participated.filter(v=>v!==null);

    datasets.push(
      {
        label: entry.name,
        data: participated,
        borderColor:entry.color, backgroundColor:entry.color+'22',
        tension:0.35, fill:false, spanGaps:true,
        pointRadius:     participated.map(v=>v!==null?5:0),
        pointHoverRadius:participated.map(v=>v!==null?8:0),
        pointBackgroundColor:entry.color, pointBorderColor:'#fff', pointBorderWidth:2,
        _isMain:true, _riderName:entry.name
      },
      {
        label:'​'+entry.name,
        data:npData, type:'scatter', showLine:false,
        pointStyle:'crossRot', pointRadius:9, pointHoverRadius:11,
        pointBorderColor:entry.color+'99', pointBackgroundColor:'transparent',
        pointBorderWidth:2.5, _isNP:true, _riderName:entry.name
      }
    );
    statsRows.push({
      name:entry.name, color:entry.color, races:valid.length,
      best:  valid.length?Math.min(...valid):'—',
      worst: valid.length?Math.max(...valid):'—',
      avg:   valid.length?(valid.reduce((s,v)=>s+v,0)/valid.length).toFixed(1):'—'
    });
  }

  if(_trendChartTeams){ _trendChartTeams.destroy(); _trendChartTeams=null; }
  wrap.innerHTML = `
    <div class="trend-chart-title">👥 Evolución de ranking por equipo
      <span style="font-size:10px;font-weight:500;color:#9ca3af;margin-left:10px">✕ = Sin datos (NP)</span>
    </div>
    <div class="trend-canvas-wrap"><canvas id="trendCanvasTeams"></canvas></div>
    <div style="display:grid;grid-template-columns:auto 1fr;gap:16px;margin-top:14px;align-items:start">
      <div class="trend-stats-row" id="trendStatsTeams"></div>
      <div id="trendHeatmapTeams"></div>
    </div>`;
  const ctx = $('trendCanvasTeams'); if(!ctx) return;

  _trendChartTeams = new Chart(ctx,{
    type:'line',
    data:{labels, datasets},
    plugins:[ _trendNpBandsPlugin(raceList, npIndicesAll) ],
    options:{
      responsive:true, maintainAspectRatio:false,
      scales:{
        y:{reverse:true, title:{display:true,text:'Ranking equipo (↑ mejor)'},
           ticks:{stepSize:1}, grid:{color:'#f0f0f0'}},
        x:{ticks:{maxRotation:0, minRotation:0, font:{size:10}, autoSkip:false}, grid:{display:false}}
      },
      plugins:{
        legend:{
          position:'top',
          labels:{font:{size:11}, boxWidth:14,
            filter: item => !item.text.startsWith('​')
          }
        },
        tooltip:{
          mode:'index', intersect:false,
          callbacks:{
            label(item){
              if(item.dataset._isNP && item.parsed.y!==null)
                return `${item.dataset._riderName}: ❌ No Participó (NP)`;
              if(item.dataset._isMain && item.parsed.y!==null)
                return `${item.dataset.label}: ${item.parsed.y}º`;
              return null;
            },
            filter: item => item.parsed.y !== null
          }
        }
      }
    }
  });

  const sr = $('trendStatsTeams');
  if(sr) sr.innerHTML = statsRows.map(s=>`
    <div class="trend-stat-card" style="border-left-color:${s.color}">
      <div class="trend-stat-name" style="color:${s.color}">${escapeHtml(s.name)}</div>
      <div class="trend-stat-kpis">
        <div class="trend-stat-kpi"><div class="trend-stat-val">${s.races}</div><div class="trend-stat-lbl">Carreras</div></div>
        <div class="trend-stat-kpi"><div class="trend-stat-val" style="color:#067647">${s.best===1?'🥇':s.best+'º'}</div><div class="trend-stat-lbl">Mejor</div></div>
        <div class="trend-stat-kpi"><div class="trend-stat-val" style="color:#b42318">${s.worst}º</div><div class="trend-stat-lbl">Peor</div></div>
        <div class="trend-stat-kpi"><div class="trend-stat-val">${s.avg} Ø</div><div class="trend-stat-lbl">Media</div></div>
      </div>
    </div>`).join('');

  // Mapa de calor de equipos
  const hmt = $('trendHeatmapTeams');
  if(hmt) hmt.innerHTML = _trendBuildTeamHeatmap(_trendSelectedTeams, raceList, catFilter);
}
/* ══════════════════════════════════════════════════════════════════
   MAPA DE CALOR DE RENDIMIENTO
   ══════════════════════════════════════════════════════════════════ */

function _trendPosColor(pos){
  if(pos<=3)  return '#12b76a';  // podio
  if(pos<=10) return '#1d4ed8';  // top-10
  if(pos<=20) return '#f79009';  // top-20
  return '#b42318';              // resto
}

/* Colores para ranking de equipo (escala comprimida: hay menos equipos que ciclistas) */
function _trendRankColor(rank){
  if(rank===1)  return '#12b76a'; // 1º
  if(rank<=3)   return '#0e7490'; // podio
  if(rank<=5)   return '#1d4ed8'; // top-5
  if(rank<=7)   return '#f79009'; // top-7
  return '#b42318';               // fuera de top-7
}

function _trendBuildTeamHeatmap(teams, raceList, catFilter){
  if(!teams.length) return '';
  const n = raceList.length;
  // Grid: col 1 = nombre (auto = se adapta al más largo), resto = tiles fijos 36px
  let html = `<div class="trend-heatmap-section">
    <div class="trend-heatmap-title">🌡️ Mapa de ranking por carrera</div>
    <div style="display:grid;grid-template-columns:auto repeat(${n},36px);gap:4px;align-items:center">`;

  for(const entry of teams){
    const teamCanon = getCanonicalTeam(entry.name).toLowerCase();
    html += `<div style="font-size:11px;font-weight:800;color:${entry.color};white-space:nowrap;padding-right:6px">${escapeHtml(entry.name)}</div>`;
    for(const race of raceList){
      const allRanks = _evolAllTeamRanks(race.riders||[], catFilter||null);
      const found = allRanks.find(t=>(getCanonicalTeam(t.team||'')||'').toLowerCase()===teamCanon);
      const tip = `${race.raceName||''}\n${race.raceDate||''}`;
      if(found){
        const bg = _trendRankColor(found.rank);
        html += `<div class="trend-heatmap-tile" style="background:${bg}" title="${escapeHtml(tip)} · ${found.rank}º de ${allRanks.length}">${found.rank}º</div>`;
      } else {
        html += `<div class="trend-heatmap-tile" style="background:#e5e7eb;color:#9ca3af" title="${escapeHtml(tip)}\nSin datos (NP)">NP</div>`;
      }
    }
  }

  html += `</div>
    <div class="trend-heatmap-legend">
      <span><i style="background:#12b76a"></i> 1º</span>
      <span><i style="background:#0e7490"></i> Podio (2-3)</span>
      <span><i style="background:#1d4ed8"></i> Top 5 (4-5)</span>
      <span><i style="background:#f79009"></i> Top 7 (6-7)</span>
      <span><i style="background:#b42318"></i> Resto (&gt;7)</span>
      <span><i style="background:#e5e7eb;border:1px solid #d0d5dd"></i> Sin datos</span>
    </div></div>`;
  return html;
}

function _trendBuildHeatmap(riders, raceList){
  if(!riders.length) return '';
  const n = raceList.length;
  // Grid: col 1 = nombre (auto = se adapta al más largo), resto = tiles fijos 36px
  let html = `<div class="trend-heatmap-section">
    <div class="trend-heatmap-title">🌡️ Mapa de rendimiento carrera a carrera</div>
    <div style="display:grid;grid-template-columns:auto repeat(${n},36px);gap:4px;align-items:center">`;

  for(const entry of riders){
    const nk = normalizeForMatching(entry.name);
    html += `<div style="font-size:11px;font-weight:800;color:${entry.color};white-space:nowrap;padding-right:6px">${escapeHtml(_evolNormName(entry.name))}</div>`;
    for(const race of raceList){
      const rider = (race.riders||[]).find(r=>normalizeForMatching(r.name)===nk);
      const tip = `${race.raceName||''}\n${race.raceDate||''}`;
      if(rider){
        html += `<div class="trend-heatmap-tile" style="background:${_trendPosColor(rider.pos)}" title="${escapeHtml(tip)} · ${rider.pos}º">${rider.pos}º</div>`;
      } else {
        html += `<div class="trend-heatmap-tile" style="background:#e5e7eb;color:#9ca3af" title="${escapeHtml(tip)}\nNo Participó (NP)">NP</div>`;
      }
    }
  }

  html += `</div>
    <div class="trend-heatmap-legend">
      <span><i style="background:#12b76a"></i> Podio (1–3)</span>
      <span><i style="background:#1d4ed8"></i> Top 10 (4–10)</span>
      <span><i style="background:#f79009"></i> Top 20 (11–20)</span>
      <span><i style="background:#b42318"></i> Resto (&gt;20)</span>
      <span><i style="background:#e5e7eb;border:1px solid #d0d5dd"></i> No Participó</span>
    </div></div>`;
  return html;
}

/* ══════════════════════════════════════════════════════════════════
   EXPORTAR IMAGEN — Evolución o Comparativa
   ══════════════════════════════════════════════════════════════════ */

/* Convierte un <canvas> de Chart.js en <img> para que html2canvas lo capture */
function _canvasToImg(canvasEl, w, h){
  const img = document.createElement('img');
  img.src   = canvasEl.toDataURL('image/png');
  img.style.cssText = `width:${w||canvasEl.offsetWidth}px;height:${h||canvasEl.offsetHeight}px;display:block`;
  return img;
}

async function exportTrendImg(section){
  const dateStr = new Date().toLocaleDateString('es-ES',{day:'2-digit',month:'long',year:'numeric'});
  const year   = $('trendYearFilter')?.value  || 'Todos';
  const region = $('trendRegionFilter')?.value || 'Todas';
  const cats   = _trendSelectedCats.size ? [..._trendSelectedCats].join('+') : 'Todas';

  let tmpWrap = null;
  try{
    // ── EVOLUCIÓN ──────────────────────────────────────────────────
    if(section==='evol'){
      const isRiders    = _trendActiveTab==='riders';
      const chartInst   = isRiders ? _trendChartRiders : _trendChartTeams;
      const statsEl     = $(isRiders ? 'trendStatsRiders'  : 'trendStatsTeams');
      const heatmapEl   = $(isRiders ? 'trendHeatmapRiders' : 'trendHeatmapTeams');
      const wrapEl      = $(isRiders ? 'trendRiderChart'   : 'trendTeamChart');
      const title       = isRiders ? '🚴 Evolución de Ciclistas' : '👥 Evolución de Equipos';
      if(!chartInst || !wrapEl) return;

      const W = wrapEl.offsetWidth;
      tmpWrap = document.createElement('div');
      tmpWrap.style.cssText = `position:fixed;top:0;left:-9999px;z-index:-1;background:#f4f7fb;padding:20px;font-family:Arial,sans-serif;width:${W+40}px;box-sizing:border-box`;

      // Cabecera
      tmpWrap.appendChild(_trendExportHeader(title, year, region, cats, dateStr));

      // Cuerpo blanco
      const body = document.createElement('div');
      body.style.cssText = 'background:#fff;border-radius:0 0 14px 14px;padding:18px';

      // Gráfico como imagen (evita el canvas en blanco)
      const chartCanvas = chartInst.canvas;
      body.appendChild(_canvasToImg(chartCanvas, W-36, chartCanvas.offsetHeight||310));

      // Stats + Heatmap
      const grid = document.createElement('div');
      grid.style.cssText = 'display:grid;grid-template-columns:auto 1fr;gap:16px;align-items:start;margin-top:14px';
      if(statsEl)   grid.appendChild(statsEl.cloneNode(true));
      if(heatmapEl) grid.appendChild(heatmapEl.cloneNode(true));
      body.appendChild(grid);

      // Nota explicativa al pie
      const note = document.createElement('div');
      note.style.cssText = 'margin-top:14px;padding:10px 14px;background:#f8fbff;border:1px solid #dbeafe;border-radius:10px;font-size:11px;color:#374151;line-height:1.7;font-family:Arial,sans-serif';
      if(isRiders){
        note.innerHTML = `
          <b style="font-size:12px;color:#0b2f6b">📖 Cómo leer esta imagen</b><br>
          <b>📈 Gráfico de evolución:</b> muestra la posición real del ciclista en cada carrera. El eje Y está invertido — cuanto más arriba, mejor posición. La línea discontinua (---) representa la media acumulada.<br>
          <b>✕ No Participó (NP):</b> la banda gris indica una prueba en la que el ciclista no estuvo presente; la línea continúa interpolada.<br>
          <b>🌡️ Mapa de rendimiento:</b>
          <span style="display:inline-flex;align-items:center;gap:4px;margin-left:4px">
            <i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#12b76a"></i> Podio (1–3)
          </span> ·
          <span style="display:inline-flex;align-items:center;gap:4px">
            <i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#1d4ed8"></i> Top 10 (4–10)
          </span> ·
          <span style="display:inline-flex;align-items:center;gap:4px">
            <i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#f79009"></i> Top 20 (11–20)
          </span> ·
          <span style="display:inline-flex;align-items:center;gap:4px">
            <i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#b42318"></i> Resto (&gt;20)
          </span> ·
          <span style="display:inline-flex;align-items:center;gap:4px">
            <i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#e5e7eb;border:1px solid #d0d5dd"></i> No Participó
          </span>`;
      } else {
        note.innerHTML = `
          <b style="font-size:12px;color:#0b2f6b">📖 Cómo leer esta imagen</b><br>
          <b>📈 Gráfico de evolución:</b> muestra el ranking del equipo en cada carrera. El eje Y está invertido — cuanto más arriba, mejor posición. El ranking se calcula sumando las posiciones de los 3 mejores ciclistas del equipo en cada prueba.<br>
          <b>🌡️ Mapa de ranking por carrera:</b> cada casilla muestra la posición del equipo en esa prueba.
          <span style="display:inline-flex;align-items:center;gap:4px;margin-left:4px">
            <i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#12b76a"></i> 1º
          </span> ·
          <span style="display:inline-flex;align-items:center;gap:4px">
            <i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#0e7490"></i> Podio (2–3)
          </span> ·
          <span style="display:inline-flex;align-items:center;gap:4px">
            <i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#1d4ed8"></i> Top 5 (4–5)
          </span> ·
          <span style="display:inline-flex;align-items:center;gap:4px">
            <i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#f79009"></i> Top 7 (6–7)
          </span> ·
          <span style="display:inline-flex;align-items:center;gap:4px">
            <i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#b42318"></i> Resto (&gt;7)
          </span> ·
          <span style="display:inline-flex;align-items:center;gap:4px">
            <i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#e5e7eb;border:1px solid #d0d5dd"></i> Sin datos (NP)
          </span>`;
      }
      body.appendChild(note);

      tmpWrap.appendChild(body);
      document.body.appendChild(tmpWrap);
      await new Promise(r=>setTimeout(r,60));

      const cv = await html2canvas(tmpWrap,{scale:2,useCORS:true,backgroundColor:'#f4f7fb',logging:false});
      _trendDownload(cv,'evolucion-tendencias');

    // ── COMPARATIVA ────────────────────────────────────────────────
    } else {
      const radarInst  = _trendChartRadar;
      const distriInst = _trendChartDistri;
      const radarWrap  = $('trendRadarWrap');
      const distriWrap = $('trendDistriWrap');
      if(!radarWrap || !distriWrap) return;

      const W = (radarWrap.offsetWidth + distriWrap.offsetWidth + 16) + 40;
      tmpWrap = document.createElement('div');
      tmpWrap.style.cssText = `position:fixed;top:0;left:-9999px;z-index:-1;background:#f4f7fb;padding:20px;font-family:Arial,sans-serif;width:${W}px;box-sizing:border-box`;

      tmpWrap.appendChild(_trendExportHeader('📊 Análisis Comparativo', year, region, cats, dateStr));

      const body = document.createElement('div');
      body.style.cssText = 'background:#fff;border-radius:0 0 14px 14px;padding:18px';

      const grid = document.createElement('div');
      grid.style.cssText = 'display:grid;grid-template-columns:1fr 1fr;gap:16px';

      // Clonar títulos + convertir canvas a img para cada gráfico
      for(const [inst, wrap] of [[radarInst,radarWrap],[distriInst,distriWrap]]){
        const cell = document.createElement('div');
        cell.style.cssText = 'background:#f8fbff;border:1px solid #dbeafe;border-radius:12px;padding:14px';
        const titleEl = wrap.querySelector('.trend-chart-title');
        if(titleEl){ const t=titleEl.cloneNode(true); t.style.marginBottom='10px'; cell.appendChild(t); }
        if(inst){
          cell.appendChild(_canvasToImg(inst.canvas, wrap.offsetWidth-30, 270));
        } else {
          // Sin gráfico: clonar contenido tal cual
          cell.appendChild(wrap.cloneNode(true));
        }
        grid.appendChild(cell);
      }
      body.appendChild(grid);

      // Nota explicativa al pie — Comparativa
      const noteComp = document.createElement('div');
      noteComp.style.cssText = 'margin-top:14px;padding:10px 14px;background:#f8fbff;border:1px solid #dbeafe;border-radius:10px;font-size:11px;color:#374151;line-height:1.7;font-family:Arial,sans-serif';
      noteComp.innerHTML = `
        <b style="font-size:12px;color:#0b2f6b">📖 Cómo leer esta imagen</b><br>
        <b>🕸️ Perfil de rendimiento (Radar):</b> cada eje representa una métrica normalizada de 0 a 100. Cuanto mayor el área, mejor rendimiento global. Métricas: Rendimiento medio (posición relativa al campo), % Podios, % Top 10, Regularidad (inverso de la desviación típica) y % Participación.<br>
        <b>📊 Distribución de resultados:</b> muestra el porcentaje de carreras en cada banda de resultado —
        <span style="display:inline-flex;align-items:center;gap:4px;margin-left:2px"><i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#12b76a"></i> Podio (1–3)</span> ·
        <span style="display:inline-flex;align-items:center;gap:4px"><i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#1d4ed8"></i> Top 10 (4–10)</span> ·
        <span style="display:inline-flex;align-items:center;gap:4px"><i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#f79009"></i> Top 20 (11–20)</span> ·
        <span style="display:inline-flex;align-items:center;gap:4px"><i style="display:inline-block;width:12px;height:12px;border-radius:3px;background:#b42318"></i> Resto (&gt;20)</span>`;
      body.appendChild(noteComp);

      tmpWrap.appendChild(body);
      document.body.appendChild(tmpWrap);
      await new Promise(r=>setTimeout(r,60));

      const cv = await html2canvas(tmpWrap,{scale:2,useCORS:true,backgroundColor:'#f4f7fb',logging:false});
      _trendDownload(cv,'comparativa-tendencias');
    }
  }catch(e){
    console.error('Error exportando tendencias:',e);
    alert('No se pudo generar la imagen. Revisa la consola.');
  }finally{
    if(tmpWrap && tmpWrap.parentNode) tmpWrap.parentNode.removeChild(tmpWrap);
  }
}

function _trendExportHeader(title, year, region, cats, dateStr){
  const hdr = document.createElement('div');
  hdr.style.cssText = 'background:linear-gradient(135deg,#0b2f6b,#1286c7);border-radius:14px 14px 0 0;padding:14px 20px 12px;color:#fff;font-family:Arial,sans-serif';
  hdr.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:flex-start">
      <div style="font-size:20px;font-weight:900">${title}</div>
      <div style="font-size:11px;opacity:.7">${dateStr}</div>
    </div>
    <div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:10px">
      <span style="background:rgba(255,255,255,.2);border-radius:999px;padding:3px 11px;font-size:11px;font-weight:700">📅 ${year}</span>
      <span style="background:rgba(255,255,255,.2);border-radius:999px;padding:3px 11px;font-size:11px;font-weight:700">🗺️ ${region}</span>
      <span style="background:rgba(255,255,255,.2);border-radius:999px;padding:3px 11px;font-size:11px;font-weight:700">🎽 ${cats}</span>
    </div>`;
  return hdr;
}

function _trendDownload(canvas, filename){
  const a = document.createElement('a');
  a.href = canvas.toDataURL('image/png');
  a.download = `${filename}-${new Date().toISOString().slice(0,10)}.png`;
  a.click();
}

// ─── Export imagen PNG de Trayectoria de un corredor (vista Evolución) ─────
async function exportEvolRiderImage(){
  const sel=document.getElementById('evolRiderSelect');
  if(!sel||!sel.value){ alert('Primero selecciona un corredor.'); return; }
  const riderMap=window._evolRiderMap;
  const entry=riderMap?.get(sel.value);
  if(!entry){ alert('No se han encontrado datos del corredor.'); return; }

  const chartCanvas=document.getElementById('evolRiderChart');
  const content=document.getElementById('evolRiderContent');
  const tableEl=content?.querySelector('table');
  if(!chartCanvas||!tableEl){ alert('Aún no se ha renderizado el gráfico. Cambia de corredor y vuelve a pulsar.'); return; }

  const races=entry.races.slice();
  const positions=races.map(r=>r.pos);
  const best=Math.min(...positions);
  const avg=(positions.reduce((s,n)=>s+n,0)/positions.length).toFixed(1);
  const totalCarreras=races.length;
  // Fechas: primera y última (cronológico)
  const sortedByDate=races.slice().sort((a,b)=>(_parseSpanishDate(a.raceDate)||'0000').localeCompare(_parseSpanishDate(b.raceDate)||'0000'));
  const firstDate=sortedByDate[0]?.raceDate||'';
  const lastDate=sortedByDate[sortedByDate.length-1]?.raceDate||'';
  const dateStr=new Date().toLocaleDateString('es-ES',{day:'2-digit',month:'long',year:'numeric'});
  const periodoStr=firstDate&&lastDate ? `${firstDate} → ${lastDate}` : '—';

  // Equipo/categoría detectados (de la carrera más reciente)
  const lastRace=sortedByDate[sortedByDate.length-1]||{};
  const teamGuess=(riders||[]).find(r=>(r.name||'').toLowerCase()===entry.displayName.toLowerCase())?.team||'';
  const catGuess=lastRace.cat||'';

  const tmpWrap=document.createElement('div');
  const W=Math.max(820, (chartCanvas.offsetWidth||820));
  tmpWrap.style.cssText=`position:fixed;top:0;left:-9999px;z-index:-1;background:#f4f7fb;font-family:Arial,sans-serif;width:${W+40}px;box-sizing:border-box`;

  // Header MFPP estilo gradiente azul
  const hdr=document.createElement('div');
  hdr.style.cssText='background:linear-gradient(135deg,#0b2f6b,#1286c7);padding:16px 22px 14px;color:#fff;border-radius:14px 14px 0 0';
  hdr.innerHTML=`
    <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:14px">
      <div>
        <div style="font-size:22px;font-weight:900;line-height:1.2">🚴 Trayectoria — ${escapeHtml(entry.displayName)}</div>
        <div style="font-size:12px;opacity:.85;margin-top:4px">Periodo: ${escapeHtml(periodoStr)}</div>
      </div>
      <div style="font-size:11px;opacity:.75;text-align:right">Generado: ${dateStr}<br>MFPP Cycling Specialist</div>
    </div>
    <div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:12px">
      <span style="background:rgba(255,255,255,.2);border-radius:999px;padding:4px 12px;font-size:12px;font-weight:700">🏁 ${totalCarreras} carreras</span>
      <span style="background:rgba(255,255,255,.2);border-radius:999px;padding:4px 12px;font-size:12px;font-weight:700">🥇 Mejor: ${best}º</span>
      <span style="background:rgba(255,255,255,.2);border-radius:999px;padding:4px 12px;font-size:12px;font-weight:700">📊 Media: ${avg}º</span>
      ${teamGuess?`<span style="background:rgba(255,255,255,.2);border-radius:999px;padding:4px 12px;font-size:12px;font-weight:700">🚴 ${escapeHtml(teamGuess)}</span>`:''}
      ${catGuess?`<span style="background:rgba(255,255,255,.2);border-radius:999px;padding:4px 12px;font-size:12px;font-weight:700">🎽 ${escapeHtml(catGuess)}</span>`:''}
    </div>`;

  // Cuerpo blanco
  const body=document.createElement('div');
  body.style.cssText='background:#fff;padding:18px 20px;border-radius:0 0 14px 14px';

  // Gráfico como imagen
  const chartImg=_canvasToImg(chartCanvas, W, Math.min(360, chartCanvas.offsetHeight||320));
  chartImg.style.borderRadius='8px';
  chartImg.style.background='#fff';
  body.appendChild(chartImg);

  // Tabla clonada (con estilos básicos)
  const tableClone=tableEl.cloneNode(true);
  tableClone.style.cssText='width:100%;border-collapse:collapse;font-size:12px;margin-top:14px';
  tableClone.querySelectorAll('th,td').forEach(c=>{
    c.style.padding='7px 10px';
    c.style.borderBottom='1px solid #e5e7eb';
    c.style.textAlign='left';
  });
  tableClone.querySelectorAll('th').forEach(th=>{
    th.style.background='#f3f4f6';
    th.style.fontWeight='800';
    th.style.color='#374151';
  });
  body.appendChild(tableClone);

  // Footer
  const footer=document.createElement('div');
  footer.style.cssText='text-align:center;font-size:10px;color:#6b7280;margin-top:12px;padding-top:10px;border-top:1px solid #e5e7eb';
  footer.textContent=`Resumen de trayectoria deportiva · Director Ciclismo MFPP · ${dateStr}`;
  body.appendChild(footer);

  tmpWrap.appendChild(hdr);
  tmpWrap.appendChild(body);
  document.body.appendChild(tmpWrap);

  try{
    const btn=document.getElementById('evolExportImgBtn');
    const origText=btn?.textContent;
    if(btn){ btn.disabled=true; btn.textContent='⏳ Generando…'; }

    const cv=await html2canvas(tmpWrap,{scale:2, backgroundColor:'#f4f7fb', useCORS:true, logging:false});
    const slug=entry.displayName.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
    _trendDownload(cv, `trayectoria-${slug}`);

    if(btn){ btn.disabled=false; btn.textContent=origText||'📸 Crear imagen'; }
  }catch(err){
    console.error('Error generando imagen de trayectoria:', err);
    alert('No se ha podido generar la imagen. Revisa la consola.');
    const btn=document.getElementById('evolExportImgBtn');
    if(btn){ btn.disabled=false; btn.textContent='📸 Crear imagen'; }
  }finally{
    tmpWrap.remove();
  }
}

/* ══════════════════════════════════════════════════════════════════
   PESTAÑA COMPARATIVA — Radar + Distribución de resultados
   ══════════════════════════════════════════════════════════════════ */

function trendDrawComp(){
  const filtered = _trendLastHistory || [];
  _trendDrawRadarChart(filtered);
  _trendDrawDistriChart(filtered);
}

/* ── Calcula métricas normalizadas [0-100] para un nombre de ciclista ── */
function _trendRiderMetrics(nameKey, filtered){
  const positions=[];
  let maxField=0;
  for(const race of filtered){
    const rider=(race.riders||[]).find(r=>normalizeForMatching(r.name)===nameKey);
    const total=(race.riders||[]).length;
    if(total>maxField) maxField=total;
    if(rider) positions.push({pos:rider.pos, total});
  }
  if(!positions.length) return null;
  const poses=positions.map(p=>p.pos);
  const n=poses.length;
  const avg=poses.reduce((s,v)=>s+v,0)/n;
  const maxPos=Math.max(...positions.map(p=>p.total));
  const rendimiento=maxPos>1?Math.max(0,Math.round((1-(avg-1)/(maxPos-1))*100)):50;
  const top3=Math.round(poses.filter(p=>p<=3).length/n*100);
  const top10=Math.round(poses.filter(p=>p<=10).length/n*100);
  const participacion=Math.round(n/filtered.length*100);
  const stdDev=n>1?Math.sqrt(poses.map(p=>Math.pow(p-avg,2)).reduce((s,v)=>s+v)/n):0;
  const cv=avg>0?stdDev/avg:0;
  const consistencia=Math.round(Math.max(0,100-cv*120));
  return {rendimiento, top3, top10, participacion, consistencia, n, avg:avg.toFixed(1), poses};
}

/* ── Métricas para un equipo: promedio de los 3 mejores por carrera ── */
function _trendTeamMetrics(teamCanon, filtered, catFilter){
  const rankList=[];
  for(const race of filtered){
    const allRanks=_evolAllTeamRanks(race.riders||[], catFilter||null);
    const found=allRanks.find(t=>(getCanonicalTeam(t.team||'')||'').toLowerCase()===teamCanon);
    if(found) rankList.push({rank:found.rank, total:allRanks.length});
  }
  if(!rankList.length) return null;
  const ranks=rankList.map(r=>r.rank);
  const n=ranks.length;
  const avg=ranks.reduce((s,v)=>s+v,0)/n;
  const maxRank=Math.max(...rankList.map(r=>r.total));
  const rendimiento=maxRank>1?Math.max(0,Math.round((1-(avg-1)/(maxRank-1))*100)):50;
  const top3=Math.round(ranks.filter(r=>r<=3).length/n*100);
  const top5=Math.round(ranks.filter(r=>r<=5).length/n*100);
  const participacion=Math.round(n/filtered.length*100);
  const stdDev=n>1?Math.sqrt(ranks.map(r=>Math.pow(r-avg,2)).reduce((s,v)=>s+v)/n):0;
  const cv=avg>0?stdDev/avg:0;
  const consistencia=Math.round(Math.max(0,100-cv*120));
  return {rendimiento, top3, top10:top5, participacion, consistencia, n, avg:avg.toFixed(1), poses:ranks};
}

function _trendDrawRadarChart(filtered){
  const wrap=$('trendRadarWrap'); if(!wrap) return;
  const hasRiders=_trendSelectedRiders.length>0;
  const hasTeams=_trendSelectedTeams.length>0;
  if(!hasRiders && !hasTeams){
    if(_trendChartRadar){_trendChartRadar.destroy();_trendChartRadar=null;}
    wrap.innerHTML='<div class="trend-empty">Añade ciclistas o equipos para ver el perfil de rendimiento.</div>';
    return;
  }
  const catFilter=_trendSelectedCats.size===1?[..._trendSelectedCats][0]:null;
  const LABELS=['Rendimiento','Podios (%)','Top-10 (%)','Participación','Consistencia'];
  const datasets=[];

  for(const entry of _trendSelectedRiders){
    const nk=normalizeForMatching(entry.name);
    const m=_trendRiderMetrics(nk, filtered);
    if(!m) continue;
    datasets.push({
      label:_evolNormName(entry.name),
      data:[m.rendimiento,m.top3,m.top10,m.participacion,m.consistencia],
      backgroundColor:entry.color+'30',borderColor:entry.color,
      pointBackgroundColor:entry.color,pointBorderColor:'#fff',
      borderWidth:2,pointRadius:4
    });
  }
  for(const entry of _trendSelectedTeams){
    const tc=getCanonicalTeam(entry.name).toLowerCase();
    const m=_trendTeamMetrics(tc, filtered, catFilter);
    if(!m) continue;
    datasets.push({
      label:entry.name+' (equipo)',
      data:[m.rendimiento,m.top3,m.top10,m.participacion,m.consistencia],
      backgroundColor:entry.color+'30',borderColor:entry.color,
      pointBackgroundColor:entry.color,pointBorderColor:'#fff',
      borderWidth:2,pointRadius:4,borderDash:[4,3]
    });
  }

  if(!datasets.length){
    wrap.innerHTML='<div class="trend-empty">Sin datos para los filtros actuales.</div>'; return;
  }
  if(_trendChartRadar){_trendChartRadar.destroy();_trendChartRadar=null;}
  wrap.innerHTML=`
    <div class="trend-chart-title">📡 Perfil de rendimiento</div>
    <div style="position:relative;height:270px"><canvas id="trendCanvasRadar"></canvas></div>`;
  const ctx=$('trendCanvasRadar'); if(!ctx) return;
  _trendChartRadar=new Chart(ctx,{
    type:'radar',
    data:{labels:LABELS,datasets},
    options:{
      responsive:true,maintainAspectRatio:false,
      scales:{r:{
        angleLines:{color:'#e5e7eb'},grid:{color:'#f3f4f6'},
        pointLabels:{font:{size:11},color:'#374151'},
        min:0,max:100,ticks:{stepSize:25,font:{size:9},backdropColor:'transparent',color:'#9ca3af'}
      }},
      plugins:{
        legend:{position:'bottom',labels:{font:{size:11},boxWidth:14,padding:10}},
        tooltip:{callbacks:{
          label(ctx){
            const v=ctx.parsed.r;
            const lbl=ctx.dataset.label;
            const axis=LABELS[ctx.dataIndex];
            return `${lbl} · ${axis}: ${v}`;
          }
        }}
      }
    }
  });
}

function _trendDrawDistriChart(filtered){
  const wrap=$('trendDistriWrap'); if(!wrap) return;
  const all=[..._trendSelectedRiders,..._trendSelectedTeams.map(t=>({...t,_isTeam:true}))];
  if(!all.length){
    if(_trendChartDistri){_trendChartDistri.destroy();_trendChartDistri=null;}
    wrap.innerHTML='<div class="trend-empty">Añade ciclistas o equipos para ver la distribución de resultados.</div>';
    return;
  }
  const catFilter=_trendSelectedCats.size===1?[..._trendSelectedCats][0]:null;
  const labels=[];
  const bandPodio=[],bandTop10=[],bandTop20=[],bandResto=[];
  const colors=[];

  for(const entry of all){
    let poses=[];
    if(entry._isTeam){
      const tc=getCanonicalTeam(entry.name).toLowerCase();
      for(const race of filtered){
        const allRanks=_evolAllTeamRanks(race.riders||[],catFilter||null);
        const found=allRanks.find(t=>(getCanonicalTeam(t.team||'')||'').toLowerCase()===tc);
        if(found) poses.push(found.rank);
      }
    } else {
      const nk=normalizeForMatching(entry.name);
      for(const race of filtered){
        const rider=(race.riders||[]).find(r=>normalizeForMatching(r.name)===nk);
        if(rider) poses.push(rider.pos);
      }
    }
    if(!poses.length) continue;
    const n=poses.length;
    const pct=v=>Math.round(v/n*100);
    labels.push(entry._isTeam?entry.name:_evolNormName(entry.name));
    bandPodio.push(pct(poses.filter(p=>p<=3).length));
    bandTop10.push(pct(poses.filter(p=>p>3&&p<=10).length));
    bandTop20.push(pct(poses.filter(p=>p>10&&p<=20).length));
    bandResto.push(pct(poses.filter(p=>p>20).length));
    colors.push(entry.color);
  }

  if(!labels.length){
    wrap.innerHTML='<div class="trend-empty">Sin datos para los filtros actuales.</div>'; return;
  }
  if(_trendChartDistri){_trendChartDistri.destroy();_trendChartDistri=null;}
  wrap.innerHTML=`
    <div class="trend-chart-title">📊 Distribución de resultados <span style="font-size:10px;font-weight:500;color:#9ca3af">% de carreras por banda</span></div>
    <div style="position:relative;height:270px"><canvas id="trendCanvasDistri"></canvas></div>`;
  const ctx=$('trendCanvasDistri'); if(!ctx) return;
  _trendChartDistri=new Chart(ctx,{
    type:'bar',
    data:{
      labels,
      datasets:[
        {label:'🥇 Podio (1-3)',data:bandPodio,backgroundColor:'#12b76a',borderRadius:3,stack:'s'},
        {label:'🏅 Top 10',data:bandTop10,backgroundColor:'#1d4ed8',borderRadius:3,stack:'s'},
        {label:'📈 Top 20',data:bandTop20,backgroundColor:'#f79009',borderRadius:3,stack:'s'},
        {label:'📉 Resto',data:bandResto,backgroundColor:'#d0d5dd',borderRadius:3,stack:'s'}
      ]
    },
    options:{
      responsive:true,maintainAspectRatio:false,
      indexAxis:'y',
      scales:{
        x:{stacked:true,max:100,ticks:{callback:v=>v+'%',font:{size:10}},grid:{color:'#f3f4f6'}},
        y:{stacked:true,ticks:{font:{size:11}},grid:{display:false}}
      },
      plugins:{
        legend:{position:'bottom',labels:{font:{size:11},boxWidth:12,padding:10}},
        tooltip:{callbacks:{
          label:ctx=>`${ctx.dataset.label}: ${ctx.parsed.x}%`
        }}
      }
    }
  });
}
// ===== FIN TENDENCIAS =====

/* ═══════════════════════════════════════════════════════════════════════
   SELECCIÓN AUTONÓMICA VLC
   ═══════════════════════════════════════════════════════════════════════ */

let _selFiltersReady    = false;
let _selSelectedCats    = new Set(); // vacío = todas las categorías
let _convoMode          = 'vlc';   // 'vlc' | 'myteam'
let _convoTitularCount  = 4;       // 4 para VLC, 6 para Mi Equipo
let _selManualOverrides = [null,null,null,null,null,null]; // nameKey por slot (size = _convoTitularCount+2)
let _selPickerSlot      = -1;
let _selPickerAllRiders = [];   // candidatos disponibles para el picker
let _selRadarChart      = null;
let _selCurrentSlots    = [];   // array 6 de rider objects (con overrides aplicados)
let _selLastHistory     = null;

// Patrones que identifican la Comunitat Valenciana en los datos
const _VLC_PATTERNS = [/^vlc$/i, /valenc/i, /^cv$/i, /c\.?\s*v\.?$/i, /pais\s*val/i, /p\.?\s*v\.?$/i];
function _isVlcRegion(s){ return _VLC_PATTERNS.some(p=>p.test((s||'').trim())); }

function _initSelFilters(history){
  const years = [...new Set(history.map(r=>(_parseSpanishDate(r.raceDate)||'').slice(0,4)).filter(Boolean))].sort().reverse();

  // Regiones: combinar rider-level + team-inferred
  const rawRegions = new Set();
  for(const race of history) for(const r of (race.riders||[])){ if(r.region) rawRegions.add(r.region); }
  const {teamRegion} = _prBuildTeamMeta(history);
  for(const reg of Object.values(teamRegion)) rawRegions.add(reg);
  const regions = [...rawRegions].filter(Boolean).sort();

  const allCats = new Set();
  for(const race of history) for(const r of (race.riders||[])){
    const ry = (_parseSpanishDate(race.raceDate)||'').slice(0,4);
    const c = getRiderCorrectCat(r.name, ry?parseInt(ry):null, r.cat);
    if(c) allCats.add(c);
  }
  const cats = [...allCats].sort();

  const ySel = $('selYearFilter');
  if(ySel){
    const curYear = new Date().getFullYear().toString();
    ySel.innerHTML = '<option value="">Todos</option>' +
      years.map(y=>`<option value="${y}"${y===curYear?' selected':''}>${y}</option>`).join('');
  }

  const rSel = $('selRegionFilter');
  if(rSel){
    // Si ya existe VLC en los datos, usarlo; si no, añadir la opción sintética (solo visual)
    const hasRealVlc = regions.some(_isVlcRegion);
    let opts = regions;
    if(!hasRealVlc) opts = ['Comunitat Valenciana', ...regions];
    rSel.innerHTML = '<option value="">Todas las CCAA</option>' +
      opts.map(r=>`<option value="${escapeHtml(r)}">${escapeHtml(r)}</option>`).join('');
    // Seleccionar siempre VLC por defecto
    const vlcOpt = [...rSel.options].find(o=>_isVlcRegion(o.value));
    if(vlcOpt) rSel.value = vlcOpt.value;
  }

  // Pills de categoría — VLC toolbar
  const pillsEl = $('selCatPills');
  if(pillsEl){
    const allActive = _selSelectedCats.size === 0;
    pillsEl.innerHTML =
      `<span class="pr-cat-pill pr-pill-all${allActive?' pr-pill-active':''}" data-cat="__all__" onclick="_selToggleCat('__all__')">Todas</span>` +
      cats.map(c=>`<span class="pr-cat-pill${_selSelectedCats.has(c)?' pr-pill-active':''}" data-cat="${escapeHtml(c)}" onclick="_selToggleCat('${escapeAttr(c)}')">${escapeHtml(c)}</span>`).join('');
  }

  // ── Inicializar filtros del toolbar de Mi Equipo ──────────────────────────
  const tySel = $('selTeamYearFilter');
  if(tySel && tySel.options.length<=1){
    tySel.innerHTML = '<option value="">Todos</option>' +
      years.map(y=>`<option value="${y}">${y}</option>`).join('');
    // Seleccionar año actual por defecto si existe
    const curYear = new Date().getFullYear().toString();
    const cyOpt = [...tySel.options].find(o=>o.value===curYear);
    if(cyOpt) tySel.value = curYear;
  }

  const trSel = $('selTeamRegionFilter');
  if(trSel && trSel.options.length<=1){
    trSel.innerHTML = '<option value="">Todas las CCAA</option>' +
      regions.map(r=>`<option value="${escapeHtml(r)}">${escapeHtml(r)}</option>`).join('');
    // Por defecto "Todas" en Mi Equipo (el equipo puede tener corredores de varias CCAA)
  }

  // Pills de categoría — Mi Equipo toolbar (mismos datos, mismo Set _selSelectedCats)
  const teamPillsEl = $('selTeamCatPills');
  if(teamPillsEl){
    const allActive2 = _selSelectedCats.size === 0;
    teamPillsEl.innerHTML =
      `<span class="pr-cat-pill pr-pill-all${allActive2?' pr-pill-active':''}" data-cat="__all__" onclick="_selToggleCat('__all__')">Todas</span>` +
      cats.map(c=>`<span class="pr-cat-pill${_selSelectedCats.has(c)?' pr-pill-active':''}" data-cat="${escapeHtml(c)}" onclick="_selToggleCat('${escapeAttr(c)}')">${escapeHtml(c)}</span>`).join('');
  }
}

function _selToggleCat(cat){
  if(cat==='__all__'){ _selSelectedCats.clear(); }
  else { _selSelectedCats.has(cat) ? _selSelectedCats.delete(cat) : _selSelectedCats.add(cat); }
  // Actualizar aspecto de las pills en AMBOS toolbars
  ['selCatPills','selTeamCatPills'].forEach(id=>{
    const el = $(id); if(!el) return;
    el.querySelectorAll('.pr-cat-pill').forEach(p=>{
      const c = p.dataset.cat;
      if(c==='__all__') p.classList.toggle('pr-pill-active', _selSelectedCats.size===0);
      else p.classList.toggle('pr-pill-active', _selSelectedCats.has(c));
    });
  });
  renderSeleccion();
}

async function renderSeleccion(){
  const history = _historyForGlobalCat(await _ensureHistory());
  if(!_selFiltersReady){
    _initSelFilters(history);
    _selFiltersReady = true;
  }

  // Mi Equipo mode: use separate candidate pipeline
  if(_convoMode==='myteam'){
    const myTeamCandidates = _buildMyTeamCandidates(history);
    _selPickerAllRiders = myTeamCandidates;
    const totalSlots = _convoTitularCount + 2;
    const baseN = myTeamCandidates.slice(0, totalSlots);
    const currentN = [];
    for(let i=0;i<totalSlots;i++){
      const ov = _selManualOverrides[i];
      if(ov){ const f=myTeamCandidates.find(c=>c.name===ov); currentN.push(f||baseN[i]||null); }
      else currentN.push(baseN[i]||null);
    }
    _selCurrentSlots = currentN;
    _selRenderCards(currentN);
    _selRenderRadar(currentN);
    _selRenderMerits(currentN);
    // ── Fase 2 no-bloqueo: si no hay equipo configurado, mostrar chip ──
    const existingChip = document.getElementById('selNoTeamChip');
    if(existingChip) existingChip.remove();
    if(!myTeam){
      const view = document.getElementById('view-seleccion');
      const chip = document.createElement('div');
      chip.id = 'selNoTeamChip';
      chip.style.cssText = 'background:linear-gradient(135deg,#fef3c7,#fde68a);border:2px solid #f59e0b;color:#78350f;border-radius:12px;padding:14px 18px;font-size:13px;font-weight:700;margin:14px 0;cursor:pointer;display:flex;align-items:center;gap:10px;box-shadow:0 4px 12px rgba(245,158,11,.2);position:sticky;top:8px;z-index:10';
      chip.onclick = ()=>{ document.getElementById('gfMyTeam')?.focus(); };
      chip.innerHTML = '⚙️ <span>Modo <b>Mi Equipo</b> sin equipo configurado · Mostrando candidatos <b>GLOBALES</b> como referencia. <span style="text-decoration:underline">Configura tu equipo</span> en la barra de filtros para personalizar.</span>';
      if(view) view.insertBefore(chip, view.firstChild);
    }
    return;
  }

  const year   = $('selYearFilter')?.value  || '';
  const region = $('selRegionFilter')?.value || '';
  const gender = $('selGenderFilter')?.value || '';
  // Categorías: usar el Set de pills (vacío = todas)
  const selCats = _selSelectedCats;

  const {teamRegion, teamGender} = _prBuildTeamMeta(history);

  // Si se seleccionó VLC pero no hay ningún equipo con datos de región,
  // ignorar el filtro de región para no devolver vacío
  const hasRegionData = Object.keys(teamRegion).length > 0;
  const effectiveRegion = (region && hasRegionData) ? region : '';

  // Filtrar carreras
  const filtered = history.filter(race=>{
    const ry = (_parseSpanishDate(race.raceDate)||'').slice(0,4);
    if(year && ry!==year) return false;
    if(effectiveRegion||gender){
      const ok = (race.riders||[]).some(r=>{
        const t = getCanonicalTeam(r.team||'').trim();
        if(effectiveRegion && teamRegion[t]!==effectiveRegion) return false;
        if(gender && teamGender[t]!==gender) return false;
        return true;
      });
      if(!ok) return false;
    }
    return true;
  });
  filtered.sort((a,b)=>(_parseSpanishDate(a.raceDate)||'').localeCompare(_parseSpanishDate(b.raceDate)||''));
  _selLastHistory = filtered;

  // Acumular stats por ciclista
  const riderMap = {};
  for(const race of filtered){
    const ry = (_parseSpanishDate(race.raceDate)||'').slice(0,4);
    const raceId = race.id||race.raceName;
    for(const r of (race.riders||[])){
      const team = getCanonicalTeam(r.team||'').trim();
      if(!team) continue;
      if(effectiveRegion && teamRegion[team]!==effectiveRegion) continue;
      if(gender && teamGender[team]!==gender) continue;
      const rcat = getRiderCorrectCat(r.name, ry?parseInt(ry):null, r.cat);
      if(selCats.size>0 && !selCats.has(rcat)) continue;
      const nameKey = normalizeRiderName(r.name||'').trim();
      if(!nameKey) continue;
      const mk = nameKey+'|||'+team;
      if(!riderMap[mk]) riderMap[mk]={name:nameKey, displayName:r.name||nameKey, team, cat:rcat, positions:[], raceIds:new Set(), raceHistory:[]};
      riderMap[mk].positions.push(r.pos);
      riderMap[mk].raceIds.add(raceId);
      riderMap[mk].raceHistory.push({raceName:race.raceName, raceDate:race.raceDate, pos:r.pos, time:r.time||'', total:(race.riders||[]).length});
    }
  }

  const candidates = Object.values(riderMap).map(rd=>{
    const n = rd.positions.length;
    if(!n) return null;
    const avgPos  = rd.positions.reduce((s,v)=>s+v,0)/n;
    const bestPos = Math.min(...rd.positions);
    const podiums = rd.positions.filter(p=>p<=3).length;
    const top10   = rd.positions.filter(p=>p<=10).length;
    const last3   = rd.raceHistory.slice(-3);
    const stats   = _computeSelectionStats({positions:rd.positions, avgPos, bestPos, podiums, top10, races:n, raceHistory:rd.raceHistory});
    return {
      name:rd.name, displayName:rd.displayName, team:rd.team, cat:rd.cat,
      avgPos, bestPos, podiums, top10, races:n, last3,
      score: stats.composite,         // menor = mejor (compatibilidad con sort ascendente)
      composite: stats.composite,
      reliability: stats.reliability, // 0-1
      eligible: stats.eligible,
      _stats: stats,
      positions:rd.positions, raceHistory:rd.raceHistory
    };
  }).filter(Boolean);

  // ORDEN ESTRICTO: primero por elegibilidad (cumple suelo 50% o tiene victorias
  // extraordinarias) y luego por composite score (menor = mejor).
  candidates.sort((a,b)=>{
    if(a.eligible!==b.eligible) return a.eligible ? -1 : 1;
    return a.composite - b.composite;
  });
  _selPickerAllRiders = candidates;

  // Aplicar overrides (VLC mode, 4+2). Para auto-selección solo elegibles.
  const totalSlots = _convoTitularCount + 2;
  const eligiblePool = candidates.filter(c=>c.eligible);
  const baseN = eligiblePool.slice(0, totalSlots);
  // Si no llenamos slots con elegibles, dejamos huecos (mejor vacío que erróneo)
  while(baseN.length<totalSlots) baseN.push(null);
  const currentN = [];
  for(let i=0;i<totalSlots;i++){
    const ov = _selManualOverrides[i];
    if(ov){ const f=candidates.find(c=>c.name===ov); currentN.push(f||baseN[i]||null); }
    else currentN.push(baseN[i]||null);
  }
  _selCurrentSlots = currentN;
  _selRenderCards(currentN);
  _selRenderRadar(currentN);
  _selRenderMerits(currentN);
}

/* ══════════════════════════════════════════════════════════
   CONVOCATORIAS — Dual Mode (VLC 4+2 / Mi Equipo 6+2)
══════════════════════════════════════════════════════════ */
function _setConvoMode(mode){
  _convoMode = mode;
  _convoTitularCount = mode==='myteam' ? 6 : 4;
  const totalSlots = _convoTitularCount + 2;
  _selManualOverrides = Array(totalSlots).fill(null);

  // Toggle button styles
  const vlcBtn  = $('convoModeVlcBtn');
  const teamBtn = $('convoModeTeamBtn');
  if(vlcBtn && teamBtn){
    if(mode==='vlc'){
      vlcBtn.style.background  = 'linear-gradient(135deg,#0b2f6b,#1286c7)';
      vlcBtn.style.color       = '#fff';
      teamBtn.style.background = '#f9fafb';
      teamBtn.style.color      = '#374151';
    } else {
      teamBtn.style.background = 'linear-gradient(135deg,#059669,#10b981)';
      teamBtn.style.color      = '#fff';
      vlcBtn.style.background  = '#f9fafb';
      vlcBtn.style.color       = '#374151';
    }
  }

  // Toggle toolbars
  const vlcFilters  = $('selVlcFilters');
  const teamFilters = $('selTeamFilters');
  if(vlcFilters)  vlcFilters.style.display  = mode==='vlc'    ? '' : 'none';
  if(teamFilters) teamFilters.style.display = mode==='myteam' ? '' : 'none';

  // Update labels
  const titLabel = $('selTitularesLabel');
  const supLabel = $('selSuplentesLabel');
  if(titLabel) titLabel.textContent = `${mode==='myteam'?'🟢':'🔵'} ${_convoTitularCount} Titulares`;
  if(supLabel) supLabel.textContent = '⚫ 2 Suplentes';

  _selFiltersReady = false;
  renderSeleccion();
}

/* Build myteam candidates scored by Forma (50%) + AvgPos (30%) + Fiabilidad (20%) */
function _buildMyTeamCandidates(history){
  // Fase 2 no-bloqueo: si no hay equipo configurado, no devolvemos array vacío;
  // delegamos en el pipeline normal (sin filtro de equipo) para que el usuario
  // vea candidatos globales como referencia + chip avisando.
  if(!myTeam){
    // Reutilizamos la lógica del pipeline VLC pero sin filtros de región/género
    // para entregar un top general de candidatos del histórico.
    try{
      const year = $('selTeamYearFilter')?.value || '';
      const selCats = _selSelectedCats;
      const filtered = history.filter(race=>{
        const ry = (_parseSpanishDate(race.raceDate)||'').slice(0,4);
        return !year || ry===year;
      });
      const riderMap = {};
      for(const race of filtered){
        const ry = (_parseSpanishDate(race.raceDate)||'').slice(0,4);
        const raceId = race.id||race.raceName;
        for(const r of (race.riders||[])){
          const rcat = getRiderCorrectCat(r.name, ry?parseInt(ry):null, r.cat);
          if(selCats && selCats.size>0 && !selCats.has(rcat)) continue;
          const nameKey = normalizeRiderName(r.name||'').trim();
          if(!nameKey) continue;
          if(!riderMap[nameKey]) riderMap[nameKey] = {name:nameKey, displayName:r.name||nameKey, team:r.team||'', cat:rcat, positions:[], raceHistory:[], raceIds:new Set()};
          riderMap[nameKey].positions.push(r.pos);
          riderMap[nameKey].raceHistory.push({raceName:race.raceName, raceDate:race.raceDate, pos:r.pos, total:(race.riders||[]).length});
          riderMap[nameKey].raceIds.add(raceId);
        }
      }
      const list = Object.values(riderMap).map(rd=>{
        const n = rd.positions.length;
        const avg = n ? rd.positions.reduce((s,v)=>s+v,0)/n : 999;
        const stats = typeof _computeSelectionStats==='function'
          ? _computeSelectionStats({positions:rd.positions, races:n, avgPos:avg, raceHistory:rd.raceHistory})
          : {composite:avg};
        return {...rd, races:n, avgPos:avg, composite:stats.composite, _iaBase:stats.composite};
      }).sort((a,b)=>a.composite-b.composite).slice(0, 30);
      return list;
    }catch(e){
      console.warn('[Convocatorias] fallback global falló:', e);
      return [];
    }
  }
  const myTeamCanon = getCanonicalTeam(myTeam||'').toLowerCase();
  const year   = $('selTeamYearFilter')?.value   || '';
  const region = $('selTeamRegionFilter')?.value || '';
  const gender = $('selTeamGenderFilter')?.value || '';
  const selCats = _selSelectedCats;

  // Inferir región/género de cada equipo para poder filtrar si el usuario lo pide
  const {teamRegion, teamGender} = _prBuildTeamMeta(history);

  const filtered = history.filter(race=>{
    const ry = (_parseSpanishDate(race.raceDate)||'').slice(0,4);
    return !year || ry===year;
  });
  filtered.sort((a,b)=>(_parseSpanishDate(a.raceDate)||'').localeCompare(_parseSpanishDate(b.raceDate)||''));

  const riderMap = {};
  for(const race of filtered){
    const ry = (_parseSpanishDate(race.raceDate)||'').slice(0,4);
    const raceId = race.id||race.raceName;
    for(const r of (race.riders||[])){
      const team = getCanonicalTeam(r.team||'').trim();
      if(team.toLowerCase()!==myTeamCanon) continue;
      // Filtros opcionales de CCAA y Género aplicados al corredor individual
      if(region && teamRegion[team] && teamRegion[team]!==region) continue;
      if(gender && teamGender[team] && teamGender[team]!==gender) continue;
      const rcat = getRiderCorrectCat(r.name, ry?parseInt(ry):null, r.cat);
      if(selCats.size>0 && !selCats.has(rcat)) continue;
      const nameKey = normalizeRiderName(r.name||'').trim();
      if(!nameKey) continue;
      const mk = nameKey+'|||'+team;
      if(!riderMap[mk]) riderMap[mk]={name:nameKey,displayName:r.name||nameKey,team,cat:rcat,positions:[],raceIds:new Set(),raceHistory:[]};
      riderMap[mk].positions.push(r.pos);
      riderMap[mk].raceIds.add(raceId);
      riderMap[mk].raceHistory.push({raceName:race.raceName,raceDate:race.raceDate,pos:r.pos,time:r.time||'',total:(race.riders||[]).length});
    }
  }

  const candidates = Object.values(riderMap).map(rd=>{
    const n = rd.positions.length; if(!n) return null;
    const avgPos  = rd.positions.reduce((s,v)=>s+v,0)/n;
    const bestPos = Math.min(...rd.positions);
    const podiums = rd.positions.filter(p=>p<=3).length;
    const top10   = rd.positions.filter(p=>p<=10).length;
    const last3   = rd.raceHistory.slice(-3);
    const stats = _computeSelectionStats({positions:rd.positions, avgPos, bestPos, podiums, top10, races:n, raceHistory:rd.raceHistory});
    return {
      name:rd.name, displayName:rd.displayName, team:rd.team, cat:rd.cat,
      avgPos, bestPos, podiums, top10, races:n, last3,
      score: stats.composite,
      composite: stats.composite,
      reliability: stats.reliability,
      eligible: stats.eligible,
      _stats: stats,
      positions:rd.positions, raceHistory:rd.raceHistory
    };
  }).filter(Boolean);

  // En Mi Equipo no se aplica el suelo estricto (somos pocos), pero sí se ordena
  // por composite respetando la elegibilidad como primer criterio.
  candidates.sort((a,b)=>{
    if(a.eligible!==b.eligible) return a.eligible ? -1 : 1;
    return a.composite - b.composite;
  });
  return candidates;
}

// ═══════════════════════════════════════════════════════════════════════════
// FÓRMULA DE SELECCIÓN DE ÉLITE (Convocatorias VLC + Mi Equipo)
// ═══════════════════════════════════════════════════════════════════════════
//
//  FIABILIDAD = % de carreras SIN un mal resultado
//    Umbral malo = max(avgPos + 5, avgPos × 1.5, 15)
//    → Un podio NUNCA es no fiable. Un mal día sí.
//
//  ELEGIBILIDAD (filtro estricto, sin excepciones para Auto/IA):
//    fiabilidad ≥ 50%   O   victorias extraordinarias (≥3 wins ó 1º + ≥3 podios)
//
//  COMPOSITE SCORE (menor = mejor):
//    30% media de posición (calidad base)
//    25% consistencia en Top 10 (% de carreras top10 invertido)
//    20% forma reciente (media últimas 3 carreras)
//    20% fiabilidad invertida (% carreras "no fiables")
//   −10% bonus por podios (resta al penalty total)
//   +volumen: castigo si <3 carreras (poca muestra)
// ═══════════════════════════════════════════════════════════════════════════

// ═════════════════════════════════════════════════════════════════════
// FÓRMULA "PROFESIONAL" — criterios reales de seleccionador nacional
// ═════════════════════════════════════════════════════════════════════
// 1. DESCARTE DE PEORES — quitar peor 20% de carreras (DNF, averías, caídas)
// 2. PERCENTIL — pos/total: un 10º entre 200 vale más que un 10º entre 30
// 3. DECAIMIENTO TEMPORAL — última carrera vale 1.0, hace 60d vale 0.5
// 4. TECHO DE RENDIMIENTO — bonus por top 5% (resultados excepcionales)
// 5. VICTORIAS — bonus grande (un ganador es un ganador)
// 6. CONFIANZA POR VOLUMEN — pocas carreras → score "regresa" a la media
// 7. FIABILIDAD (solo lado malo) — ya no penaliza los días buenos
// ═════════════════════════════════════════════════════════════════════
function _computeSelectionStats(c){
  const positions = c.positions || [];
  const n = c.races || positions.length || 0;
  const avgPos = c.avgPos != null ? c.avgPos : (n ? positions.reduce((s,v)=>s+v,0)/n : 0);
  const bestPos = c.bestPos != null ? c.bestPos : (n ? Math.min(...positions) : 99);
  const podiums = c.podiums != null ? c.podiums : positions.filter(p=>p<=3).length;
  const top10   = c.top10   != null ? c.top10   : positions.filter(p=>p<=10).length;
  const wins    = positions.filter(p=>p===1).length;
  const raceHistory = c.raceHistory || [];

  // ─── PASO 1: DESCARTE DEL PEOR 20% (handles DNF, averías, accidentes) ──
  // Solo si tiene al menos 5 carreras (sino no merece la pena descartar)
  let consideredRaces = raceHistory.length ? raceHistory.slice() : positions.map(p=>({pos:p,raceDate:'',total:0}));
  let droppedCount = 0;
  if(consideredRaces.length >= 5){
    consideredRaces.sort((a,b)=>a.pos-b.pos);
    droppedCount = Math.ceil(consideredRaces.length * 0.20);
    consideredRaces = consideredRaces.slice(0, consideredRaces.length - droppedCount);
  }

  // ─── PASO 2: PERCENTILES (posición relativa al tamaño del campo) ─────
  // Si no tenemos `total`, asumimos campo medio de 100 corredores
  const DEFAULT_FIELD = 100;
  consideredRaces.forEach(r=>{
    r.total = r.total || DEFAULT_FIELD;
    r.percentile = Math.min(1, r.pos / r.total); // 0 = ganador, 1 = último
  });

  // ─── PASO 3: DECAIMIENTO TEMPORAL ────────────────────────────────────
  // Última carrera = 1.0, hace 60 días = 0.5, hace 120 días = 0.25
  const today = new Date();
  const HALF_LIFE_DAYS = 60;
  consideredRaces.forEach(r=>{
    const d = _parseSpanishDate ? _parseSpanishDate(r.raceDate) : null;
    if(d){
      const raceDate = new Date(d);
      const daysAgo = Math.max(0, (today - raceDate) / 86400000);
      r.recencyWeight = Math.pow(0.5, daysAgo / HALF_LIFE_DAYS);
    } else {
      r.recencyWeight = 1; // sin fecha → peso neutro
    }
  });

  // ─── PASO 4: PERCENTIL PONDERADO (calidad real ajustada por contexto) ─
  const totalWeight = consideredRaces.reduce((s,r)=>s+r.recencyWeight, 0);
  const weightedPercentile = totalWeight > 0
    ? consideredRaces.reduce((s,r)=>s+r.percentile*r.recencyWeight, 0) / totalWeight
    : 0.5;
  const qualityScore = weightedPercentile * 100; // 0-100, menor = mejor

  // ─── PASO 5: TECHO DE RENDIMIENTO (resultados excepcionales) ──────────
  // % de carreras en Top 5% del campo (premio fuerte a los "días buenos")
  const ceilingHits = consideredRaces.filter(r=>r.percentile <= 0.05).length;
  const ceilingBonus = -Math.min(ceilingHits * 8, 40); // hasta -40

  // ─── PASO 6: VICTORIAS Y PODIOS ──────────────────────────────────────
  const winBonus    = -Math.min(wins * 12, 50);     // hasta -50 (las wins son oro)
  const podiumBonus = -Math.min(podiums * 4, 30);   // hasta -30

  // ─── PASO 7: CONFIANZA POR VOLUMEN (Bayesian shrinkage) ──────────────
  // n=0: factor 0 (todo es prior); n=20: factor 0.8 (muy confiable)
  const SHRINKAGE_K = 5;
  const confidenceFactor = n / (n + SHRINKAGE_K); // 0-1
  // Si tienes pocas carreras, el score se "tira" hacia 50 (media del campo)
  const adjustedQuality = qualityScore * confidenceFactor + 50 * (1 - confidenceFactor);

  // ─── PASO 8: FORMA RECIENTE (últimas 3 carreras) ─────────────────────
  const last3 = positions.slice(-3);
  const recentAvg = last3.length ? last3.reduce((s,v)=>s+v,0)/last3.length : avgPos;

  // ─── PASO 9: FIABILIDAD (solo lado malo, mantiene la fórmula buena) ──
  const badThreshold = Math.max(avgPos + 5, avgPos * 1.5, 15);
  const reliableRaces = positions.filter(p => p <= badThreshold).length;
  const reliability = n > 0 ? reliableRaces / n : 0;
  const top10Pct = n > 0 ? top10 / n : 0;
  const recentTop10Pct = last3.length ? last3.filter(p=>p<=10).length / last3.length : 0;

  // ─── COMPOSITE FINAL (menor = mejor) ─────────────────────────────────
  // 50% calidad ponderada (percentil + decaimiento + descartar peor 20%)
  // 15% forma reciente (las últimas 3 carreras)
  // 10% consistencia Top 10 (% carreras top 10)
  // 25% bonus: techo + victorias + podios
  // Hard penalty si <3 carreras (muestra mínima)
  const consistencyPenalty = (1 - top10Pct) * 30;            // 0-30
  const recentPenalty      = recentAvg;                       // sin cap
  const volumePenalty      = n < 3 ? (3 - n) * 15 : 0;        // hasta 30

  const composite = (
    adjustedQuality     * 0.50 +
    recentPenalty       * 0.15 +
    consistencyPenalty  * 0.10 +
    ceilingBonus        * 0.10 +
    winBonus            * 0.10 +
    podiumBonus         * 0.05
  ) + volumePenalty;

  // ─── ELEGIBILIDAD ────────────────────────────────────────────────────
  // Suelo: fiabilidad ≥50% Y al menos 3 carreras.
  // Excepción: victorias extraordinarias (3+ wins o 1º + 3+ podios).
  const extraordinaryWins = wins >= 3 || (bestPos === 1 && podiums >= 3);
  const enoughVolume = n >= 3;
  const eligible = (enoughVolume && reliability * 100 >= 50) || extraordinaryWins;

  return {
    composite, reliability, top10Pct, recentAvg, recentTop10Pct,
    eligible, extraordinaryWins, wins, badThreshold, enoughVolume,
    // Nuevos campos para transparencia y debug
    weightedPercentile, qualityScore, adjustedQuality,
    ceilingHits, confidenceFactor, droppedCount
  };
}

// Modo activo de selección: 'auto' | 'ia' | null. Controla el color del botón.
let _selActiveMode = null;

function _selSetActiveMode(mode){
  _selActiveMode = mode;
  // Estilo NARANJA = botón seleccionado (activo); reset = vuelve a su color base
  const ORANGE = 'linear-gradient(135deg,#ea580c,#f97316)';
  const ORANGE_BORDER = '#ea580c';
  // Localizar los 4 botones (Auto y IA en VLC y en Mi Equipo)
  document.querySelectorAll('[onclick="_selAutoPropose()"]').forEach(btn=>{
    if(mode==='auto'){
      btn.style.background = ORANGE;
      btn.style.color      = '#fff';
      btn.style.border     = '1.5px solid '+ORANGE_BORDER;
      btn.style.fontWeight = '700';
    } else {
      btn.style.background = '#fff';
      btn.style.color      = '#374151';
      btn.style.border     = '1.5px solid #d1d5db';
      btn.style.fontWeight = '';
    }
  });
  document.querySelectorAll('[onclick="_selIAPropose()"]').forEach(btn=>{
    if(mode==='ia'){
      btn.style.background = ORANGE;
      btn.style.color      = '#fff';
      btn.style.border     = '1.5px solid '+ORANGE_BORDER;
      btn.style.fontWeight = '700';
    } else {
      // Restaurar color original según el contexto (VLC = azul, Mi Equipo = verde)
      const isMyTeamBtn = btn.textContent.includes('6+2');
      btn.style.background = isMyTeamBtn
        ? 'linear-gradient(135deg,#059669,#10b981)'
        : 'linear-gradient(135deg,#0b2f6b,#1286c7)';
      btn.style.color  = '#fff';
      btn.style.border = '';
      btn.style.fontWeight = '';
    }
  });
}

function _selAutoPropose(){
  _selManualOverrides = Array(_convoTitularCount + 2).fill(null);
  _selSetActiveMode('auto');
  renderSeleccion();
}

