// FIN SIMULADOR
// ═══════════════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════════════
// SIMULADOR DE CARRERAS — Fase 2
// A) Predicción Mi Equipo con intervalo de confianza (Montecarlo)
// B) Head-to-Head con rivales más frecuentes
// C) Análisis por tipo de circuito
// D) Simulación Montecarlo 1000 iteraciones
// ═══════════════════════════════════════════════════════════════════════════

// ── D) MONTECARLO ─────────────────────────────────────────────────────────
// Para un corredor con avgPos y reliability, simula 1000 carreras
// generando posiciones aleatorias dentro de una distribución normal centrada
// en avgPos con sigma derivada de la fiabilidad (a menor fiabilidad, mayor sigma).
// Devuelve {predicted, lower, upper, probTop3, probTop5, probTop10, distribution[20 bins]}
function _simMonteCarlo(rider, iterations){
  iterations = iterations || 1000;
  if(rider.avgPos == null) return null;
  // sigma: con fiabilidad 100% → sigma=2; fiabilidad 0% → sigma=20
  const rel = rider.reliability ?? 30;
  const sigma = Math.max(2, 2 + (100-rel)/100 * 18);
  const positions = [];
  // Generación con Box-Muller
  for(let i=0; i<iterations; i++){
    const u1 = Math.random() || 1e-9;
    const u2 = Math.random();
    const z = Math.sqrt(-2*Math.log(u1)) * Math.cos(2*Math.PI*u2);
    const pos = Math.max(1, Math.round(rider.avgPos + z * sigma));
    positions.push(pos);
  }
  positions.sort((a,b)=>a-b);
  const predicted = Math.round(positions.reduce((s,p)=>s+p,0)/iterations);
  // Percentiles 25 y 75 para el intervalo de confianza del 50%
  const lower = positions[Math.floor(iterations*0.25)];
  const upper = positions[Math.floor(iterations*0.75)];
  // Probabilidades
  const probTop3  = Math.round(positions.filter(p=>p<=3).length/iterations*100);
  const probTop5  = Math.round(positions.filter(p=>p<=5).length/iterations*100);
  const probTop10 = Math.round(positions.filter(p=>p<=10).length/iterations*100);
  // Distribución en 20 bins (cada bin = 5 posiciones)
  const distribution = new Array(20).fill(0);
  positions.forEach(p=>{
    const bin = Math.min(19, Math.floor((p-1)/5));
    distribution[bin]++;
  });
  const maxBin = Math.max(...distribution);
  const distributionNorm = distribution.map(v=>maxBin?v/maxBin:0);
  return { predicted, lower, upper, sigma, probTop3, probTop5, probTop10, distribution, distributionNorm };
}

// ── A) PREDICCIÓN MI EQUIPO ──────────────────────────────────────────────
function _simRenderMyTeamPanel(){
  const panel = document.getElementById('simMyTeamPanel');
  const body = document.getElementById('simMyTeamBody');
  if(!panel || !body) return;
  if(!_simCurrentData || !myTeam){ panel.style.display='none'; return; }
  const {grid} = _simCurrentData;
  const mine = grid.filter(g=>g.isMyTeam);
  if(!mine.length){ panel.style.display='none'; return; }
  panel.style.display = '';
  // Aplicar filtro categoría (sincronizado con simCatSelect)
  const catFilter = document.getElementById('simCatSelect')?.value || '';
  let visible = catFilter ? mine.filter(g=>g.cat===catFilter) : mine;
  // Ordenar de MEJOR a PEOR puesto esperado: primero el que se prevé más alto
  // (predictedPos más bajo). Los corredores sin datos (avgPos null) al final.
  visible = visible.slice().sort((a,b)=>{
    const sa = (a.avgPos == null) ? Infinity : (a.predictedPos ?? a.avgPos ?? Infinity);
    const sb = (b.avgPos == null) ? Infinity : (b.predictedPos ?? b.avgPos ?? Infinity);
    if(sa !== sb) return sa - sb;
    // desempate por nombre alfabético para que sea estable visualmente
    return (a.name||'').localeCompare(b.name||'');
  });
  if(!visible.length){
    body.innerHTML = '<p class="small" style="text-align:center;padding:14px;color:#9ca3af">Ningún corredor de tu equipo en la categoría seleccionada.</p>';
    return;
  }
  body.innerHTML = `<div class="sim-myteam-grid">${visible.map(g=>{
    const isDebut = g.status !== 'known';
    let mcHtml = '';
    if(g.avgPos == null){
      mcHtml = `<div class="sim-mt-pred-block" style="background:#fef3c7"><div style="font-weight:800;color:#92400e;font-size:13px">⚠️ Sin datos suficientes para predicción</div><div style="font-size:11px;color:#78350f;margin-top:3px">Corredor sin historial ni media de equipo disponible.</div></div>`;
    } else {
      const mc = _simMonteCarlo(g, 1000);
      if(!mc){
        mcHtml = '';
      } else {
        const histBars = mc.distributionNorm.map((v,i)=>`<div class="sim-mt-hist-bar" style="height:${Math.max(2,v*100)}%" title="Pos ${i*5+1}-${(i+1)*5}: ${mc.distribution[i]} sim."></div>`).join('');
        mcHtml = `
          <div class="sim-mt-pred-block">
            <div class="sim-mt-pred-pos">${mc.predicted}º <small>esperado</small></div>
            <div class="sim-mt-pred-range">📐 Intervalo de confianza 50%: entre <b>${mc.lower}º</b> y <b>${mc.upper}º</b>${isDebut?' (estimado por equipo)':''}</div>
            <div class="sim-mt-histogram" title="Distribución de 1000 simulaciones (eje X: posiciones 1→100 en bins de 5)">${histBars}</div>
            <div style="display:flex;justify-content:space-between;margin-top:2px"><span class="sim-mt-hist-label">Top</span><span class="sim-mt-hist-label">Resto</span></div>
          </div>
          <div class="sim-mt-prob-row">
            <div class="sim-mt-prob-chip podium"><div class="pc-v">${mc.probTop3}%</div><div class="pc-l">🥇 Podio</div></div>
            <div class="sim-mt-prob-chip top5"><div class="pc-v">${mc.probTop5}%</div><div class="pc-l">🟢 Top 5</div></div>
            <div class="sim-mt-prob-chip top10"><div class="pc-v">${mc.probTop10}%</div><div class="pc-l">🔵 Top 10</div></div>
          </div>`;
      }
    }
    const confDot = `<span class="sim-conf ${g.confidence}" title="Confianza ${g.confidence}"></span>`;
    return `<div class="sim-mt-card ${isDebut?'debut':''}">
      <div class="mt-hdr">
        <div>
          <div class="mt-name">${confDot}${escapeHtml(g.name)}</div>
          <div class="mt-meta">${escapeHtml(g.cat||'')}${g.bib?' · #'+escapeHtml(g.bib):''} · ${g.raceCount||0} carreras previas${isDebut?' · <b style="color:#9a3412">'+(g.status==='team-fb'?'fallback equipo':'debutante')+'</b>':''}</div>
        </div>
      </div>
      ${mcHtml}
    </div>`;
  }).join('')}</div>`;
}

// ═════════════════════════════════════════════════════════════════════════
// BRIEFING PRE-CARRERA · resumen imprimible para explicar a los corredores
// Recoge predicciones, factores aplicados, forma reciente y consejo táctico
// individual de cada corredor del equipo. Pensado para reunirse antes de la
// salida y enseñárselo a los chavales (impresión limpia A4).
// ═════════════════════════════════════════════════════════════════════════

// Convierte una posición esperada en un consejo táctico claro y motivador.
function _simBriefingAdvice(g, mc){
  if(g.avgPos == null){
    return {
      role:'Aprender y disfrutar',
      tag:'#94a3b8',
      tips:[
        'Es tu primera prueba con datos en el sistema, no te obsesiones con el puesto.',
        'Aguanta en grupo el mayor tiempo posible: ahí gastas mucha menos energía.',
        'Toma referencias: cómo se ruedan las curvas, dónde rompe el pelotón, qué corredores parecen fuertes.',
        'Acabar la carrera ya es ganar información para las siguientes.'
      ]
    };
  }
  const pred = mc ? mc.predicted : g.predictedPos;
  const podio = mc ? mc.probTop3 : null;
  const top10 = mc ? mc.probTop10 : null;
  if(pred <= 3 || (podio != null && podio >= 25)){
    return {
      role:'🏆 Candidato a podio',
      tag:'#15803d',
      tips:[
        'Tienes números reales para subir al cajón hoy. Sé tú el que decide la carrera.',
        'No te quedes atrás cuando vayan los favoritos: si alguien se va, tú vas detrás.',
        'Reserva un último cartucho para los 3-5 km finales — no te quemes en ataques largos.',
        'En el sprint, busca rueda buena y abre el esprint a 200-250 m si es llano.'
      ]
    };
  }
  if(pred <= 8 || (top10 != null && top10 >= 50)){
    return {
      role:'🎯 Objetivo Top 10',
      tag:'#0369a1',
      tips:[
        'Vas con números para meterte entre los 10 primeros. No malgastes energía en cazas inútiles.',
        'Cuando se forme la primera selección, mete los codos y métete dentro.',
        'Sigue ataques cortos (≤30 s), deja pasar los kamikazes que se van solos a 30 km de meta.',
        'Llega fresco al último km: es donde se decide tu puesto.'
      ]
    };
  }
  if(pred <= 20 || (top10 != null && top10 >= 20)){
    return {
      role:'🟢 Trabajar para top 15-20',
      tag:'#d97706',
      tips:[
        'Hoy tu carrera es estar siempre con el grupo principal.',
        'Métete delante en los puntos clave (subidas cortas, salidas de curva, zonas con viento).',
        'Si puedes ayudar al líder del equipo, tu puesto sube — y el del equipo también.',
        'Sprint final: no busques a saco el podio, busca ganar 2-3 posiciones de las tuyas.'
      ]
    };
  }
  if(pred <= 40){
    return {
      role:'🧠 Sumar experiencia y apoyar',
      tag:'#7c3aed',
      tips:[
        'Hoy lo que toca es resistir y aprender. Acabar bien colocado en el pelotón es un éxito.',
        'Cuando se rompa el pelotón, intenta agarrar el segundo o tercer grupo, no te quedes solo.',
        'Si el líder pincha o se queda, espéralo y tira tú para devolverlo al pelotón.',
        'Cada km que acabas con el grupo principal es entrenamiento de nivel real.'
      ]
    };
  }
  return {
    role:'🏁 Acabar la carrera con cabeza',
    tag:'#475569',
    tips:[
      'Hoy el objetivo es completar la prueba sin perder tiempo absurdo.',
      'Ahorra energía: ve siempre dentro del grupo, no en los bordes.',
      'Si te descuelgas, busca un grupo de 3-4 corredores y rueda con ellos.',
      'Termina y aprende: cada carrera dura te hace mejor para las próximas.'
    ]
  };
}

// Traduce los factores aplicados (terreno, clima, especialidad, fatiga) en
// una frase corta y entendible para el corredor.
function _simBriefingFactorChips(g){
  const chips = [];
  if(g.terrainReason)   chips.push({icon:'🗺️', txt: g.terrainReason, color: g.terrainFactor < 1 ? '#15803d' : g.terrainFactor > 1 ? '#b91c1c' : '#475569'});
  if(g.climateReason)   chips.push({icon: g.climateIcon || '🌤️', txt: g.climateReason, color: (g.climateFactor||1) < 1 ? '#15803d' : (g.climateFactor||1) > 1 ? '#b91c1c' : '#475569'});
  if(g.specialtyReason) chips.push({icon:'🎯', txt: g.specialtyReason, color:'#0b2f6b'});
  if(g.fatigueReason)   chips.push({icon:'😴', txt: g.fatigueReason, color: '#d97706'});
  // Bloque 1: chip Elo si hay rating con muestra suficiente
  if(g.elo != null && g.eloGames >= 3){
    const eloCol = g.elo >= 1300 ? '#15803d' : g.elo >= 1150 ? '#0b2f6b' : '#b91c1c';
    const rankTxt = g.eloRank ? ` · #${g.eloRank} de la parrilla` : '';
    chips.push({icon:'🧬', txt:`Elo ${g.elo} (${g.eloGames} carreras)${rankTxt}`, color: eloCol});
  }
  // Bloque 1: chip DNF si el corredor tiene tasa relevante (≥15%)
  if(g.dnfRate >= 0.15 && g.dnfRaces >= 3){
    const pct = Math.round(g.dnfRate * 100);
    chips.push({icon:'⚠️', txt:`DNF en ${pct}% de sus carreras (${g.dnfCount}/${g.dnfRaces})`, color:'#b91c1c'});
  }
  return chips;
}

// Inyecta los estilos del briefing (incluye CSS de impresión limpio).
