// ═══════════════════════════════════════════════════════════════════════════
// SIMULADOR DE CARRERAS — Fase 3
// A) Guardar predicción en Supabase (races.notes.prediction)
// B) Comparar predicción vs resultado real (precisión por prueba)
// C) Predicción por equipos (Σ top 3 esperado)
// D) Análisis por localidad
// E) Histórico de precisión del modelo
// ═══════════════════════════════════════════════════════════════════════════

// ── A) GUARDAR PREDICCIÓN EN SUPABASE ────────────────────────────────────
async function _simSavePrediction(silent){
  if(!_simCurrentData){ if(!silent) alert('Selecciona una prueba primero.'); return; }
  if(!_sb){ if(!silent) alert('Supabase no disponible.'); return; }
  const {race, grid, kpis} = _simCurrentData;
  if(!grid || !grid.length){ return; }
  // Construir snapshot ligero (no guardamos toda la grid para evitar bloat)
  const top10 = (()=>{
    const pool = grid.filter(g=>g.avgPos!=null);
    pool.forEach(g=>{ const rel=g.reliability??30; g._s = g.avgPos*(1+(100-rel)/200); });
    pool.sort((a,b)=>a._s-b._s);
    return pool.slice(0,10).map((g,i)=>({rank:i+1, name:g.name, bib:g.bib||'', team:g.team||'', cat:g.cat||'', avgPos:Math.round(g.avgPos*10)/10, reliability:g.reliability, isMyTeam:!!g.isMyTeam}));
  })();
  // Mi equipo Montecarlo (si hay)
  const myTeamPred = grid.filter(g=>g.isMyTeam && g.avgPos!=null).map(g=>{
    const mc = _simMonteCarlo(g, 1000);
    if(!mc) return null;
    return {name:g.name, bib:g.bib||'', cat:g.cat||'', predicted:mc.predicted, lower:mc.lower, upper:mc.upper, probTop3:mc.probTop3, probTop5:mc.probTop5, probTop10:mc.probTop10};
  }).filter(Boolean);
  // Predicción equipos (Σ top 3)
  const teamsPred = _simComputeTeamPredictions(grid).slice(0,10).map((t,i)=>({rank:i+1, team:t.team, sumTop3:Math.round(t.sumTop3*10)/10, best:t.best, isMyTeam:!!t.isMyTeam}));

  const snapshot = {
    savedAt: new Date().toISOString(),
    savedBy: (_rbacUser?.email || ''),
    kpis: {difficulty:kpis.difficulty, predictability:kpis.predictability, coverage:kpis.coverage, totalIns:kpis.totalIns},
    top10,
    myTeamPred,
    teamsPred
  };

  // Leer notes existentes y fusionar
  const {data:current, error:fetchErr} = await _sb.from('races').select('notes').eq('id', race.id).single();
  if(fetchErr){ if(!silent) alert('Error leyendo la prueba: '+fetchErr.message); return; }
  let extra = {};
  try{ extra = JSON.parse(current?.notes||'{}'); }catch(e){}
  extra.prediction = snapshot;
  const {error:updErr} = await _sb.from('races').update({notes: JSON.stringify(extra)}).eq('id', race.id);
  if(updErr){ if(!silent) alert('Error guardando predicción: '+updErr.message); return; }
  // Refrescar cachéd history para que aparezca en futuras vistas
  if(_cachedHistory){
    const h = _cachedHistory.find(x=>x.id===race.id);
    if(h){ h.prediction = snapshot; }
  }
  // Aviso visible junto al Top 10 (tanto al autoguardar como al pulsar el botón)
  const pill = document.getElementById('simTop10SavedHint'); if(pill) pill.style.display='';
  const sb = document.getElementById('simTop10SaveBtn'); if(sb) sb.textContent='💾 Actualizar predicción';
  if(!silent){
    const hint = document.getElementById('simSavedHint');
    if(hint){
      hint.style.display = '';
      hint.innerHTML = `✅ Predicción guardada en Supabase (${snapshot.top10.length} candidatos top 10${myTeamPred.length?' · '+myTeamPred.length+' corredores de tu equipo':''}). Podrás comparar contra el resultado real cuando se dispute la carrera.`;
    }
    if(typeof showToast==='function') showToast('✅ Predicción guardada','ok',2500);
  }
}

// Cargar la predicción guardada desde notes.prediction (parsea _sbLoadHistory ya lo expone vía extra)
function _simGetSavedPrediction(race){
  if(!race) return null;
  return race.prediction || null;
}

// Backtest retroactivo solo para la prueba actualmente seleccionada.
// Reusa _simRetroactiveBacktest filtrando por raceId.
function _simRetroactiveBacktestSingle(){
  const body = document.getElementById('simAccuracyBody');
  if(!body) return;
  if(!_simCurrentData || !_simCurrentData.race){ alert('Selecciona una prueba primero.'); return; }
  const targetId = _simCurrentData.race.id;
  body.innerHTML = '<p class="small" style="text-align:center;padding:18px;color:#0369a1">⏳ Reconstruyendo la predicción para esta prueba con solo el histórico anterior…</p>';
  setTimeout(() => {
    try {
      const { evals, diag } = _simRetroactiveBacktest();
      const e = evals.find(x => x.raceId === targetId);
      if(!e){
        body.innerHTML = `
          <div style="text-align:center;padding:18px">
            <p class="small" style="color:#9ca3af;margin:0 0 10px">No se ha podido evaluar esta prueba retroactivamente.</p>
            <div style="display:inline-block;text-align:left;background:#f8fafc;border:1px solid #e5e7eb;border-radius:8px;padding:10px 14px;font-size:11.5px;color:#374151">
              <b>Desglose global del análisis:</b><br>
              • Histórico total: <b>${diag.totalHist}</b> carreras<br>
              • Candidatas a evaluar: <b>${diag.candidates}</b><br>
              • Con histórico previo suficiente: <b>${diag.histOk}</b><br>
              • Predicción generada: <b>${diag.gridOk}</b><br>
              • Esta prueba evaluable: <b>NO</b>
            </div>
            <p class="small" style="color:#6b7280;margin:10px 0 0">Esta prueba concreta no se ha podido evaluar. Suele pasar si es de las primeras de la temporada (no hay carreras anteriores) o si el matching de nombres falla.</p>
          </div>`;
        return;
      }
      body.innerHTML = `
        <div style="padding:8px 10px;background:#dcfce7;border:1px solid #86efac;border-radius:8px;margin-bottom:12px;font-size:12px;color:#166534">
          ✅ <b>Backtest retroactivo honesto</b> — predicción reconstruida con el histórico que existía justo antes del <b>${escapeHtml(e.raceDate)}</b> (${e.historySize} carreras previas disponibles).
        </div>
        <div class="sim-model-summary">
          <div class="sim-model-card">
            <div class="m-l">🎯 Precisión Top 10</div>
            <div class="m-v">${e.accuracyTop10}%</div>
            <div class="m-s">${e.hitsTop10}/${e.total} aciertos</div>
          </div>
          <div class="sim-model-card">
            <div class="m-l">🥇 Aciertos podio</div>
            <div class="m-v">${e.hitsTop3}/3</div>
            <div class="m-s">de los 3 primeros</div>
          </div>
          <div class="sim-model-card">
            <div class="m-l">📐 Error medio (MAE)</div>
            <div class="m-v">±${e.mae.toFixed(1)}</div>
            <div class="m-s">posiciones</div>
          </div>
        </div>
        <p class="small" style="margin-top:10px;color:#6b7280">Para ver la comparación detallada predicho vs real abre el botón <b>🎯 Predicho vs Real</b> de la cabecera del simulador (usa el predictor actual con TODOS los datos, no el backtest retroactivo, así que los números pueden no coincidir exactamente).</p>`;
    } catch(err){
      body.innerHTML = `<p class="small" style="text-align:center;padding:18px;color:#b91c1c">Error: ${escapeHtml(err.message||String(err))}</p>`;
    }
  }, 50);
}

// Escanea TODAS las pruebas de Supabase y lista cuáles tienen
// notes.prediction guardada. Útil para saber dónde fue a parar una
// predicción que el usuario creía haber guardado en otra carrera.
async function _simListAllSavedPredictions(){
  if(!_sb){ alert('Supabase no disponible.'); return; }
  const body = document.getElementById('simAccuracyBody');
  if(body) body.innerHTML = '<p class="small" style="text-align:center;padding:14px;color:#0369a1">⏳ Escaneando todas las pruebas en Supabase…</p>';
  try {
    const {data, error} = await _sb.from('races').select('id, name, date, notes, race_type').eq('race_type','clasificacion');
    if(error){
      if(body) body.innerHTML = `<p class="small" style="text-align:center;padding:14px;color:#b91c1c">Error: ${escapeHtml(error.message||String(error))}</p>`;
      return;
    }
    const withPred = [];
    (data||[]).forEach(r => {
      try {
        const extra = JSON.parse(r.notes || '{}');
        if(extra && extra.prediction){
          // El nombre/fecha "visibles" suelen vivir DENTRO de notes (raceName,
          // raceDate). Las columnas de la tabla (name, date) son redundantes
          // pero pueden estar vacías. Probamos ambas fuentes.
          withPred.push({
            id: r.id,
            name: extra.raceName || r.name || '(sin nombre)',
            date: extra.raceDate || r.date || '',
            savedAt: extra.prediction.savedAt || '',
            top10n: (extra.prediction.top10||[]).length,
            myTeamN: (extra.prediction.myTeamPred||[]).length
          });
        }
      } catch(e){}
    });
    withPred.sort((a,b)=>(b.savedAt||'').localeCompare(a.savedAt||''));
    if(!body) return;
    if(!withPred.length){
      body.innerHTML = `
        <div style="text-align:center;padding:18px">
          <p style="color:#b91c1c;font-weight:700;margin:0 0 6px">🚫 No se ha encontrado NINGUNA predicción guardada en toda la base de datos.</p>
          <p class="small" style="color:#6b7280;margin:0">Se ha escaneado el campo notes de las ${data?.length||0} pruebas con race_type='clasificacion'. En ninguna existe la clave "prediction".</p>
          <p class="small" style="color:#6b7280;margin:8px 0 0">Esto significa que el botón "💾 Guardar predicción" no llegó a completarse en ningún momento, o el campo notes se ha sobrescrito desde otro proceso.</p>
        </div>`;
      return;
    }
    const currentRaceId = _simCurrentData?.race?.id;
    const rowsHtml = withPred.map(p => {
      const isCurrent = p.id === currentRaceId;
      const savedTxt = p.savedAt ? new Date(p.savedAt).toLocaleString('es-ES') : '(sin fecha)';
      return `<tr style="${isCurrent?'background:#dcfce7':''}">
        <td style="padding:6px 8px;font-weight:700;color:#0b2f6b">${escapeHtml(p.name)}${isCurrent?' <span style="background:#16a34a;color:#fff;font-size:10px;padding:2px 6px;border-radius:4px;margin-left:4px">SELECCIONADA</span>':''}</td>
        <td style="padding:6px 8px;color:#374151">${escapeHtml(p.date)}</td>
        <td style="padding:6px 8px;color:#6b7280;font-size:11px">${escapeHtml(savedTxt)}</td>
        <td style="padding:6px 8px;text-align:center">${p.top10n}</td>
        <td style="padding:6px 8px;text-align:center">${p.myTeamN}</td>
        <td style="padding:6px 8px;font-size:10px;color:#9ca3af;font-family:monospace">${escapeHtml((p.id||'').slice(0,8))}…</td>
      </tr>`;
    }).join('');
    body.innerHTML = `
      <div style="padding:12px">
        <p style="margin:0 0 10px;color:#0b2f6b;font-weight:700">🔎 Encontradas ${withPred.length} predicciones guardadas en Supabase:</p>
        <table style="width:100%;border-collapse:collapse;font-size:12px;background:#fff;border:1px solid #e5e7eb;border-radius:6px;overflow:hidden">
          <thead><tr style="background:#f3f4f6">
            <th style="padding:6px 8px;text-align:left;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Prueba</th>
            <th style="padding:6px 8px;text-align:left;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Fecha</th>
            <th style="padding:6px 8px;text-align:left;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Guardada en</th>
            <th style="padding:6px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Top 10</th>
            <th style="padding:6px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Mi equipo</th>
            <th style="padding:6px 8px;text-align:left;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">ID</th>
          </tr></thead>
          <tbody>${rowsHtml}</tbody>
        </table>
        <p class="small" style="color:#6b7280;margin:10px 0 0">💡 Si la prueba seleccionada ahora no aparece en verde, significa que la predicción se guardó en una OTRA prueba — abre esa otra prueba en el selector del simulador para ver su comparación predicho vs real.</p>
      </div>`;
  } catch(e){
    if(body) body.innerHTML = `<p class="small" style="text-align:center;padding:14px;color:#b91c1c">Error inesperado: ${escapeHtml(e.message||String(e))}</p>`;
  }
}

// Fuerza una consulta directa a Supabase para ESTA prueba — útil cuando
// la predicción se guardó pero la caché aún no la había recargado.
async function _simForceReloadAccuracy(){
  if(!_simCurrentData){ alert('Selecciona una prueba primero.'); return; }
  if(!_sb){ alert('Supabase no disponible.'); return; }
  const race = _simCurrentData.race;
  if(!race || !race.id){ alert('La prueba seleccionada no tiene id.'); return; }
  const body = document.getElementById('simAccuracyBody');
  if(body) body.innerHTML = '<p class="small" style="text-align:center;padding:14px;color:#0369a1">⏳ Consultando Supabase…</p>';
  try {
    const {data, error} = await _sb.from('races').select('id, notes, race_type').eq('id', race.id).single();
    if(error){
      if(body) body.innerHTML = `<p class="small" style="text-align:center;padding:14px;color:#b91c1c">Error consultando Supabase: ${escapeHtml(error.message||String(error))}</p>`;
      return;
    }
    let extra = {};
    try { extra = JSON.parse(data?.notes || '{}'); } catch(e){
      if(body) body.innerHTML = `<p class="small" style="text-align:center;padding:14px;color:#b91c1c">El campo notes de Supabase no es JSON válido: ${escapeHtml(e.message)}</p>`;
      return;
    }
    if(!extra.prediction){
      if(body){
        const keys = Object.keys(extra);
        body.innerHTML = `
          <div style="text-align:center;padding:14px">
            <p class="small" style="color:#9ca3af;margin:0 0 8px">Supabase confirma: <b>esta prueba no tiene predicción guardada</b> en su campo notes.</p>
            <p class="small" style="color:#475569;margin:0">notes contiene las claves: <code>${keys.length? keys.map(k=>escapeHtml(k)).join(', ') : '(vacío)'}</code></p>
            <p class="small" style="color:#6b7280;margin:8px 0 0">race_type = <code>${escapeHtml(data.race_type||'(null)')}</code></p>
            <p class="small" style="color:#6b7280;margin:8px 0 0">Posibles causas:<br>• Guardaste la predicción en OTRA prueba con nombre parecido pero distinto id<br>• El guardado falló silenciosamente sin que te enteraras (revisa la consola)<br>• Borraste el campo notes manualmente en Supabase</p>
          </div>`;
      }
      return;
    }
    // ¡Hay predicción! Refrescamos la caché y re-renderizamos
    race.prediction = extra.prediction;
    if(_cachedHistory){
      const h = _cachedHistory.find(x => x.id === race.id);
      if(h) h.prediction = extra.prediction;
    }
    _simRenderAccuracyPanel();
  } catch(e){
    if(body) body.innerHTML = `<p class="small" style="text-align:center;padding:14px;color:#b91c1c">Error inesperado: ${escapeHtml(e.message||String(e))}</p>`;
  }
}

// ── C) PREDICCIÓN POR EQUIPOS ─────────────────────────────────────────────
// Para cada equipo con ≥3 inscritos con datos, calcular Σ top 3 puestos esperados.
// Devuelve array ordenado asc por sumTop3 (menor = mejor).
function _simComputeTeamPredictions(grid){
  const byTeam = new Map();
  grid.forEach(g=>{
    // Usar predictedPos (fórmula 60/40) si está disponible; sino avgPos
    const score = g.predictedPos ?? g.avgPos;
    if(score==null) return;
    const t = (g.team||'').trim() || '(Sin equipo)';
    if(!byTeam.has(t)) byTeam.set(t, []);
    byTeam.get(t).push({...g, _teamScore: score});
  });
  const out = [];
  const mk = (myTeam||'').toLowerCase();
  byTeam.forEach((list, team)=>{
    list.sort((a,b)=>a._teamScore - b._teamScore);
    if(list.length<3) return; // Sólo equipos con al menos 3 con datos
    const top3 = list.slice(0,3);
    const sumTop3 = top3.reduce((s,g)=>s+g._teamScore,0);
    const best = top3[0]._teamScore;
    // Métricas de probabilidad agregadas (de los top3)
    const _avg = (arr, key) => {
      const vals = arr.map(r=>r[key]).filter(v=>v!=null);
      return vals.length ? vals.reduce((s,v)=>s+v,0)/vals.length : null;
    };
    const avgPodiumProb = _avg(top3, 'probPodiumLogistic');   // % medio podio top3
    const maxPodiumProb = top3.reduce((m,r)=>Math.max(m, r.probPodiumLogistic??0), 0);
    const avgCutRisk    = _avg(top3, 'probCutLogistic');      // % medio riesgo corte top3
    // Suma de Top10 individuales = nº esperado de finishers en Top 10
    const expectedTop10 = top3.reduce((s,r)=>s+((r.probTop10Poisson??0)/100), 0);
    // Probabilidad de que ALGÚN top3 haga podio individual (independencia aproximada)
    // P(alguno podio) = 1 − ∏(1 − P_i)
    const pAnyPodium = 1 - top3.reduce((prod, r)=>prod * (1 - (r.probPodiumLogistic??0)/100), 1);

    out.push({
      team, top3, sumTop3, best, count:list.length,
      isMyTeam: mk && team.toLowerCase()===mk,
      // Enriquecimiento probabilístico
      avgPodiumProb: avgPodiumProb!=null ? Math.round(avgPodiumProb) : null,
      maxPodiumProb: Math.round(maxPodiumProb),
      avgCutRisk:    avgCutRisk!=null    ? Math.round(avgCutRisk)    : null,
      expectedTop10: Math.round(expectedTop10 * 100) / 100,
      anyPodiumProb: Math.round(pAnyPodium * 100)
    });
  });
  out.sort((a,b)=>a.sumTop3-b.sumTop3);
  return out;
}

// ── Diagnóstico: ver carreras históricas de un corredor ───────────────────
// Permite al director verificar si la predicción es realista. Si los puestos
// históricos no cuadran con lo que él sabe del corredor, hay un problema de
// datos o de matching de nombres.
function _simShowRiderHistory(riderName){
  const name = (riderName||'').trim();
  if(!name) return;
  const nk = normalizeForMatching(name);
  const hist = _cachedHistory || [];
  // Recoger TODAS las apariciones del corredor en el histórico
  const apparitions = [];
  hist.forEach(h=>{
    (h.riders||[]).forEach(r=>{
      if(normalizeForMatching(r.name||'')===nk){
        apparitions.push({
          raceName: h.raceName || '(sin nombre)',
          raceDate: h.raceDate || '(sin fecha)',
          localidad: h.localidad || '',
          circuitType: h.circuitType || '',
          pos: r.pos,
          total: (h.riders||[]).length,
          team: r.team || '',
          cat: r.cat || ''
        });
      }
    });
  });
  // Ordenar por fecha desc
  apparitions.sort((a,b)=>{
    const da = _parseSpanishDate(a.raceDate)||'0000-00-00';
    const db = _parseSpanishDate(b.raceDate)||'0000-00-00';
    return db.localeCompare(da);
  });
  // Calcular estadísticas
  const validPos = apparitions.filter(a=>a.pos>0).map(a=>a.pos);
  const avg = validPos.length ? (validPos.reduce((s,p)=>s+p,0)/validPos.length).toFixed(1) : '—';
  const best = validPos.length ? Math.min(...validPos) : '—';
  const worst = validPos.length ? Math.max(...validPos) : '—';
  const dnfs = apparitions.filter(a=>!a.pos || a.pos===0).length;

  // Construir modal
  const overlay = document.createElement('div');
  overlay.id = '_simHistoryModal';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px';
  const rowsHtml = apparitions.length
    ? apparitions.map((a,i)=>{
        const posColor = !a.pos || a.pos===0 ? '#dc2626' : a.pos<=3?'#16a34a':a.pos<=10?'#0369a1':a.pos<=20?'#475569':'#64748b';
        const posLabel = !a.pos || a.pos===0 ? 'DNF/DS' : a.pos+'º';
        return `<tr>
          <td style="text-align:center;color:#94a3b8;font-size:11px">${i+1}</td>
          <td><b>${escapeHtml(a.raceName)}</b><br><small style="color:#64748b">${escapeHtml(a.raceDate)}${a.localidad?' · '+escapeHtml(a.localidad):''}${a.circuitType?' · '+escapeHtml(a.circuitType):''}</small></td>
          <td style="text-align:center;font-weight:800;color:${posColor};font-size:14px">${posLabel}</td>
          <td style="text-align:center;color:#64748b">${a.total||'—'}</td>
          <td><small>${escapeHtml(a.team)}${a.cat?' · '+escapeHtml(a.cat):''}</small></td>
        </tr>`;
      }).join('')
    : '<tr><td colspan="5" style="text-align:center;padding:20px;color:#9ca3af">Sin apariciones en el histórico — debutante absoluto.</td></tr>';

  overlay.innerHTML = `<div style="background:#fff;border-radius:14px;max-width:880px;width:100%;max-height:90vh;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 20px 50px rgba(0,0,0,.3)">
    <div style="padding:16px 20px;border-bottom:2px solid #e2e8f0;display:flex;align-items:center;justify-content:space-between;gap:12px;background:linear-gradient(135deg,#eef2ff,#f0f9ff)">
      <div>
        <div style="font-size:11px;text-transform:uppercase;letter-spacing:.5px;color:#3730a3;font-weight:800">🔍 Diagnóstico de datos</div>
        <h3 style="margin:2px 0 0;color:#0f172a">${escapeHtml(name)}</h3>
      </div>
      <button onclick="document.getElementById('_simHistoryModal').remove()" style="background:#fff;color:#3730a3;border:1.5px solid #c7d2fe;border-radius:8px;padding:7px 14px;cursor:pointer;font-weight:700;font-size:13px">✕ Cerrar</button>
    </div>
    <div style="padding:14px 20px;background:#fafbfc;border-bottom:1px solid #e2e8f0;display:flex;flex-wrap:wrap;gap:18px;font-size:13px">
      <div><b>${apparitions.length}</b> apariciones</div>
      <div><b>${validPos.length}</b> finalizadas</div>
      <div style="color:${dnfs>0?'#dc2626':'#64748b'}"><b>${dnfs}</b> DNF/DS</div>
      <div>Media: <b style="color:#3730a3">${avg}${avg!=='—'?'º':''}</b></div>
      <div>Mejor: <b style="color:#16a34a">${best}${best!=='—'?'º':''}</b></div>
      <div>Peor: <b style="color:#dc2626">${worst}${worst!=='—'?'º':''}</b></div>
    </div>
    <div style="overflow:auto;flex:1">
      <table style="width:100%;border-collapse:collapse;font-size:12.5px">
        <thead style="position:sticky;top:0;background:#f3f6fb;z-index:1">
          <tr>
            <th style="padding:8px 10px;text-align:center;border-bottom:2px solid #e2e8f0">#</th>
            <th style="padding:8px 10px;text-align:left;border-bottom:2px solid #e2e8f0">Carrera</th>
            <th style="padding:8px 10px;text-align:center;border-bottom:2px solid #e2e8f0">Puesto</th>
            <th style="padding:8px 10px;text-align:center;border-bottom:2px solid #e2e8f0">Inscritos</th>
            <th style="padding:8px 10px;text-align:left;border-bottom:2px solid #e2e8f0">Equipo · Cat.</th>
          </tr>
        </thead>
        <tbody>${rowsHtml}</tbody>
      </table>
    </div>
    <div style="padding:10px 20px;background:#fffbeb;border-top:1px solid #fde68a;font-size:11.5px;color:#78350f">
      💡 Si los puestos no cuadran con lo que sabes del corredor, puede haber un <b>problema de matching de nombres</b> (otro corredor con el mismo nombre/apellido se está mezclando) o un <b>error en los datos del histórico</b>. Avísame para revisarlo.
    </div>
  </div>`;
  overlay.onclick = e=>{ if(e.target===overlay) overlay.remove(); };
  document.body.appendChild(overlay);
}

// Toggle plegar/desplegar el cuerpo del panel "Predicción por equipos".
// Persiste el estado en localStorage para que sobreviva a recargas.
const _TEAMS_PANEL_COLLAPSE_KEY = 'tbg.teamsPanelCollapsed.v1';
function _simToggleTeamsPanelCollapse(){
  const body = document.getElementById('simTeamsCollapseBody');
  const btn  = document.getElementById('simTeamsCollapseBtn');
  if(!body || !btn) return;
  const collapsed = body.style.display === 'none';
  body.style.display = collapsed ? '' : 'none';
  btn.textContent    = collapsed ? '▾ Plegar' : '▸ Desplegar';
  btn.title          = collapsed ? 'Plegar el bloque' : 'Desplegar el bloque';
  try { localStorage.setItem(_TEAMS_PANEL_COLLAPSE_KEY, collapsed ? '0' : '1'); } catch(e){}
}
// Aplicar el estado guardado al render inicial
function _simApplyTeamsPanelCollapsedState(){
  try {
    const stored = localStorage.getItem(_TEAMS_PANEL_COLLAPSE_KEY);
    if(stored === '1'){
      const body = document.getElementById('simTeamsCollapseBody');
      const btn  = document.getElementById('simTeamsCollapseBtn');
      if(body) body.style.display = 'none';
      if(btn) { btn.textContent = '▸ Desplegar'; btn.title = 'Desplegar el bloque'; }
    }
  } catch(e){}
}

// ═════════════════════════════════════════════════════════════════════════
// "PREDICHO VS REAL (EQUIPOS)" — modal análogo al individual pero por equipos
// Compara el ranking predicho por Σ top3 con la clasificación real por
// equipos (computada de los riders reales sumando los 3 mejores de cada
// equipo). Botón de impresión incluido.
// ═════════════════════════════════════════════════════════════════════════

// Computa la clasificación real por equipos a partir de los riders reales
// de la carrera (los que tienen pos > 0). Igual fórmula que la predicción:
// suma de los 3 mejores puestos de cada equipo, ascendente.
function _simComputeRealTeamRanking(riders){
  // CLASIFICACIÓN REAL POR EQUIPOS = suma de los 3 MEJORES TIEMPOS de cada equipo
  // (regla oficial). NO por puestos: dos equipos pueden cambiar de orden según el
  // tiempo aunque sus puestos sumen parecido. Si la prueba no tiene tiempos
  // cargados, caemos a la suma de puestos como respaldo.
  const list0 = (riders||[]).filter(r => r && r.pos && r.pos > 0);
  // Tiempo absoluto del ganador (referencia para reconstruir tiempos desde gaps)
  const winner = list0.find(r => (parseInt(r.pos)||0) === 1);
  let winnerSecs = null;
  if(winner){
    winnerSecs = winner.totalSeconds != null ? winner.totalSeconds
               : (typeof timeToSeconds === 'function' ? timeToSeconds(winner.time) : null);
  }
  const riderSecs = (r) => {
    if(r.totalSeconds != null) return r.totalSeconds;
    if(winnerSecs != null && r.gapSeconds != null) return winnerSecs + r.gapSeconds;
    if(r.gapSeconds != null) return r.gapSeconds;               // base relativa (mismo ganador para todos)
    if(typeof timeToSeconds === 'function'){ const s = timeToSeconds(r.time); if(s != null) return s; }
    return null;
  };
  const byTeam = new Map();
  list0.forEach(r => {
    const t = (r.team||'').trim() || '(Sin equipo)';
    if(!byTeam.has(t)) byTeam.set(t, []);
    byTeam.get(t).push({ name: r.name, pos: parseInt(r.pos)||0, cat: r.cat||'', secs: riderSecs(r) });
  });
  // ¿Disponemos de tiempos para ordenar por TIEMPO? Si no, respaldo por puestos.
  const haveTimes = [...byTeam.values()].some(arr => arr.filter(r=>r.secs!=null).length >= 3);
  const out = [];
  const mk = (myTeam||'').toLowerCase();
  byTeam.forEach((arr, team) => {
    if(arr.length < 3) return;
    let top3, sumSecs = null;
    if(haveTimes){
      const withSecs = arr.filter(r => r.secs != null).sort((a,b) => a.secs - b.secs);
      const base = withSecs.length >= 3 ? withSecs : arr.slice().sort((a,b)=>a.pos-b.pos);
      top3 = base.slice(0, 3);
      if(top3.every(r => r.secs != null)) sumSecs = top3.reduce((s,r) => s + r.secs, 0);
    } else {
      top3 = arr.slice().sort((a,b) => a.pos - b.pos).slice(0, 3);
    }
    const sumPos = top3.reduce((s,r) => s + r.pos, 0);
    const byTime = sumSecs != null;
    out.push({
      team, top3, count: arr.length,
      sumByTime: byTime,
      sumSecs,                                  // suma de los 3 mejores tiempos (seg)
      sumTop3: byTime ? sumSecs : sumPos,       // clave de ordenación
      sumPos,                                   // por si se quiere mostrar también
      isMyTeam: mk && team.toLowerCase() === mk
    });
  });
  out.sort((a,b) => a.sumTop3 - b.sumTop3);
  return out;
}

function _simOpenTeamsPredVsReal(){
  try {
    if(!_simCurrentData){ alert('Selecciona una prueba primero.'); return; }
    const { race, grid } = _simCurrentData;
    const realRiders = (race.riders||[]).filter(r => r.pos > 0);
    if(realRiders.length < 9){
      alert('No hay suficientes resultados reales en esta prueba para construir un ranking por equipos. Se necesitan al menos 3 equipos con 3 finishers cada uno (≥9 corredores en meta).');
      return;
    }
    _simInjectPVRStyles();
    const old = document.getElementById('tprvOverlay');
    if(old) old.remove();

    const predTeams = _simComputeTeamPredictions(grid).slice(0, 10);
    const realTeams = _simComputeRealTeamRanking(realRiders).slice(0, 10);
    if(!predTeams.length || !realTeams.length){
      alert('No se ha podido construir uno de los dos rankings (predicho o real). Cada uno necesita al menos 3 equipos con ≥3 corredores.');
      return;
    }

    // Indexar real por equipo para emparejar
    const realByTeam = new Map();
    realTeams.forEach((t, i) => realByTeam.set(t.team.toLowerCase(), { rank: i+1, sumTop3: t.sumTop3 }));
    const predByTeam = new Map();
    predTeams.forEach((t, i) => predByTeam.set(t.team.toLowerCase(), { rank: i+1, sumTop3: t.sumTop3 }));

    // Métricas: aciertos exactos, aciertos en top 5, MAE de posición de equipo
    let exactHits = 0, top5Hits = 0;
    let totalErr = 0, comparedCount = 0;
    predTeams.forEach((p, i) => {
      const realInfo = realByTeam.get(p.team.toLowerCase());
      if(!realInfo) return;
      comparedCount++;
      const predRank = i + 1;
      if(predRank === realInfo.rank) exactHits++;
      if(realInfo.rank <= 5 && predRank <= 5) top5Hits++;
      totalErr += Math.abs(predRank - realInfo.rank);
    });
    const mae = comparedCount ? (totalErr / comparedCount) : null;

    // Render: dos columnas con flechas/iconos comparativos
    const predRowsHtml = predTeams.map((p, i) => {
      const realInfo = realByTeam.get(p.team.toLowerCase());
      const predRank = i + 1;
      let badge;
      if(!realInfo){
        badge = `<span style="background:#fee2e2;color:#991b1b;padding:2px 7px;border-radius:5px;font-size:10.5px;font-weight:700">❌ Fuera del Top 10 real</span>`;
      } else if(realInfo.rank === predRank){
        badge = `<span style="background:#dcfce7;color:#15803d;padding:2px 7px;border-radius:5px;font-size:10.5px;font-weight:700">✓ Exacto · ${realInfo.rank}º real</span>`;
      } else {
        const diff = realInfo.rank - predRank;
        badge = `<span style="background:#fef3c7;color:#92400e;padding:2px 7px;border-radius:5px;font-size:10.5px;font-weight:700">${realInfo.rank}º real (Δ ${diff>0?'+':''}${diff})</span>`;
      }
      const rowBg = realInfo && realInfo.rank===predRank ? '#dcfce7'
                  : !realInfo ? '#fee2e2'
                  : '#fef3c7';
      return `<tr style="background:${rowBg}">
        <td style="padding:6px 8px;text-align:center;font-weight:800;color:#0b2f6b">${predRank}</td>
        <td style="padding:6px 8px"><b>${p.isMyTeam?'⭐ ':''}${escapeHtml(p.team)}</b><div style="font-size:11px;color:#6b7280;margin-top:2px">Σ ${p.sumTop3.toFixed(1)} (puestos previstos) · ${p.top3.map(g=>escapeHtml(g.name.split(',')[0]||g.name)).join(' · ')}</div></td>
        <td style="padding:6px 8px;text-align:right">${badge}</td>
      </tr>`;
    }).join('');

    const realRowsHtml = realTeams.map((t, i) => {
      const predInfo = predByTeam.get(t.team.toLowerCase());
      const realRank = i + 1;
      let badge;
      if(!predInfo){
        badge = `<span style="background:#dbeafe;color:#1e3a8a;padding:2px 7px;border-radius:5px;font-size:10.5px;font-weight:700">🆕 No predicho en Top 10</span>`;
      } else if(predInfo.rank === realRank){
        badge = `<span style="background:#dcfce7;color:#15803d;padding:2px 7px;border-radius:5px;font-size:10.5px;font-weight:700">✓ Predicho ${predInfo.rank}º</span>`;
      } else {
        const diff = predInfo.rank - realRank;
        badge = `<span style="background:#fef3c7;color:#92400e;padding:2px 7px;border-radius:5px;font-size:10.5px;font-weight:700">Predicho ${predInfo.rank}º (Δ ${diff>0?'+':''}${diff})</span>`;
      }
      const rowBg = predInfo && predInfo.rank===realRank ? '#dcfce7'
                  : !predInfo ? '#dbeafe'
                  : '#fef3c7';
      const sumStr = (t.sumByTime && typeof formatSeconds==='function')
        ? `Σ ${formatSeconds(t.sumSecs)} (3 mejores tiempos)`
        : `Σ ${t.sumTop3} (puestos)`;
      return `<tr style="background:${rowBg}">
        <td style="padding:6px 8px;text-align:center;font-weight:800;color:#15803d">${realRank}</td>
        <td style="padding:6px 8px"><b>${t.isMyTeam?'⭐ ':''}${escapeHtml(t.team)}</b><div style="font-size:11px;color:#6b7280;margin-top:2px">${sumStr} · ${t.top3.map(r=>escapeHtml(r.name.split(',')[0]||r.name)).join(' · ')}</div></td>
        <td style="padding:6px 8px;text-align:right">${badge}</td>
      </tr>`;
    }).join('');

    const accColor = (n) => n>=7?'#16a34a':n>=4?'#f59e0b':'#dc2626';
    // Logo de cabecera (mismo patrón que otros modales PVR)
    const pdfLogoSrc = document.querySelector('.brand-logo')?.src || '';

    const overlay = document.createElement('div');
    overlay.id = 'tprvOverlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-start;justify-content:center;padding:20px;overflow:auto';
    overlay.innerHTML = `
      <div class="pvr-modal" style="background:#fff;border-radius:14px;max-width:1100px;width:100%;max-height:94vh;overflow:auto;box-shadow:0 20px 60px rgba(0,0,0,.4)">
        <div class="pvr-hdr" style="position:sticky;top:0;background:#fff;border-bottom:1px solid #e5e7eb;padding:14px 22px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;z-index:2">
          <div style="display:flex;align-items:center;gap:14px">
            ${pdfLogoSrc ? `<img src="${pdfLogoSrc}" alt="MFPP Cycling Specialist" class="pvr-logo">` : ''}
            <div style="min-width:0">
              <h2 style="margin:0;font-size:20px;color:#0b2f6b">🏅 Predicho vs Real (equipos)</h2>
              <div class="small" style="margin-top:2px">${escapeHtml(race.raceName||'')} · ${escapeHtml(race.raceDate||'')}${race.localidad?' · '+escapeHtml(race.localidad):''}</div>
            </div>
          </div>
          <div class="pvr-actions no-print" style="display:flex;gap:8px;flex-wrap:wrap">
            <button class="btn" onclick="_simPrintTeamsPredVsReal()" style="background:#dc2626;color:#fff;border:0;font-weight:800">🖨️ Imprimir / PDF</button>
            <button class="btn light" onclick="_simCloseTeamsPredVsReal()">✕ Cerrar</button>
          </div>
        </div>

        <div class="pvr-kpis" style="padding:14px 22px">
          <div class="pvr-kpi"><div class="pvr-kpi-v" style="color:${accColor(exactHits*2)}">${exactHits}/${Math.min(predTeams.length,realTeams.length)}</div><div class="pvr-kpi-l">Posiciones exactas<br><span class="small">de equipo</span></div></div>
          <div class="pvr-kpi"><div class="pvr-kpi-v" style="color:${accColor(top5Hits*2)}">${top5Hits}/5</div><div class="pvr-kpi-l">Aciertos Top 5<br><span class="small">(equipo en su rango)</span></div></div>
          <div class="pvr-kpi"><div class="pvr-kpi-v" style="color:${mae==null?'#9ca3af':(mae<=1?'#16a34a':mae<=3?'#f59e0b':'#dc2626')}">${mae==null?'—':mae.toFixed(1)}</div><div class="pvr-kpi-l">Error medio<br><span class="small">posiciones de equipo</span></div></div>
          <div class="pvr-kpi"><div class="pvr-kpi-v" style="color:#0b2f6b">${realTeams.length}</div><div class="pvr-kpi-l">Equipos reales<br><span class="small">en clasificación</span></div></div>
        </div>

        <div style="padding:0 22px 6px;font-size:11px;color:#6b7280">
          ⭐ = mi equipo · 🟩 verde = posición exacta · 🟨 amarillo = predicho/real distinto · 🟥 rojo = predicho fuera del Top 10 real · 🟦 azul = real no estaba en el Top 10 predicho
        </div>

        <div class="pvr-table-wrap" style="padding:6px 22px 18px;display:grid;grid-template-columns:1fr 1fr;gap:14px">
          <div>
            <div style="background:#1f6feb;color:#fff;font-weight:800;padding:8px 12px;border-radius:8px 8px 0 0;font-size:13px">🔮 Top 10 Predicho por equipos</div>
            <table style="width:100%;border-collapse:collapse;font-size:12px;background:#fff;border:1px solid #cbd5e1;border-radius:0 0 8px 8px;overflow:hidden">
              <thead><tr style="background:#f1f5f9">
                <th style="padding:5px 8px;width:38px;font-size:10px;color:#475569;text-transform:uppercase">#</th>
                <th style="padding:5px 8px;text-align:left;font-size:10px;color:#475569;text-transform:uppercase">Equipo · Σ top3</th>
                <th style="padding:5px 8px;text-align:right;font-size:10px;color:#475569;text-transform:uppercase">Realidad</th>
              </tr></thead>
              <tbody>${predRowsHtml}</tbody>
            </table>
          </div>
          <div>
            <div style="background:#16a34a;color:#fff;font-weight:800;padding:8px 12px;border-radius:8px 8px 0 0;font-size:13px">🏁 Top 10 Real por equipos</div>
            <table style="width:100%;border-collapse:collapse;font-size:12px;background:#fff;border:1px solid #cbd5e1;border-radius:0 0 8px 8px;overflow:hidden">
              <thead><tr style="background:#f1f5f9">
                <th style="padding:5px 8px;width:38px;font-size:10px;color:#475569;text-transform:uppercase">#</th>
                <th style="padding:5px 8px;text-align:left;font-size:10px;color:#475569;text-transform:uppercase">Equipo · Σ top3</th>
                <th style="padding:5px 8px;text-align:right;font-size:10px;color:#475569;text-transform:uppercase">Predicción</th>
              </tr></thead>
              <tbody>${realRowsHtml}</tbody>
            </table>
          </div>
        </div>
      </div>`;
    document.body.appendChild(overlay);
    document.body.style.overflow = 'hidden';
    overlay.addEventListener('click', (ev) => { if(ev.target === overlay) _simCloseTeamsPredVsReal(); });
  } catch(e){
    console.warn('_simOpenTeamsPredVsReal', e);
    alert('Error al abrir el comparador por equipos: '+(e.message||e));
  }
}
function _simCloseTeamsPredVsReal(){
  const o = document.getElementById('tprvOverlay');
  if(o) o.remove();
  document.body.style.overflow = '';
}
// Restaurar el overflow del body ANTES de imprimir (igual que en el
// briefing): si no, el overflow:hidden que aplicamos al abrir el modal
// puede provocar que el motor de impresión clipe el contenido y la hoja
// salga en blanco.
function _simPrintTeamsPredVsReal(){
  const prev = document.body.style.overflow;
  document.body.style.overflow = '';
  setTimeout(() => {
    window.print();
    setTimeout(() => {
      if(document.getElementById('tprvOverlay')) document.body.style.overflow = prev;
    }, 50);
  }, 10);
}

// ═════════════════════════════════════════════════════════════════════════
// "PREDICHO VS REAL — MI EQUIPO" — modal específico para mostrar cada
// corredor del equipo, su predicción y su resultado real. Imprimible para
// poder enviar a los corredores la comparativa.
// ═════════════════════════════════════════════════════════════════════════

function _simOpenMyTeamPredVsReal(){
  try {
    if(!_simCurrentData){ alert('Selecciona una prueba primero.'); return; }
    if(!myTeam){ alert('No tienes equipo seleccionado. Activa "Mi Equipo" arriba del todo.'); return; }
    const { race, grid } = _simCurrentData;
    const mine = grid.filter(g => g.isMyTeam);
    if(!mine.length){ alert('No hay corredores de tu equipo en esta prueba.'); return; }
    const realRiders = (race.riders||[]).filter(r => r.pos > 0);
    if(!realRiders.length){ alert('Esta prueba no tiene resultados reales cargados todavía.'); return; }
    _simInjectPVRStyles();
    const old = document.getElementById('mtprvOverlay');
    if(old) old.remove();

    // Mapa rápido nombre → posición real
    const realByName = new Map();
    realRiders.forEach(r => {
      const nk = normalizeForMatching(r.name||'');
      if(nk) realByName.set(nk, parseInt(r.pos)||0);
    });
    const totalFinishers = realRiders.length;

    // Para cada corredor del equipo: predicho vs real
    const rows = mine.map(g => {
      const pred = g.predictedPos != null ? Math.round(g.predictedPos) : null;
      const real = realByName.get(normalizeForMatching(g.name||'')) || null;
      const diff = (pred != null && real != null) ? real - pred : null;
      return {
        name: g.name, cat: g.cat || '', bib: g.bib || '',
        pred, real, diff,
        confidence: g.confidence || 'desconocida',
        terrainReason: g.terrainReason || '',
        climateReason: g.climateReason || '',
        elo: g.elo || null
      };
    }).sort((a,b) => {
      // Ordenar por puesto REAL ascendente (con DNFs al final)
      if(a.real == null && b.real == null) return 0;
      if(a.real == null) return 1;
      if(b.real == null) return -1;
      return a.real - b.real;
    });

    // Métricas globales
    let exactHits = 0, within3Hits = 0, within5Hits = 0;
    let totalErr = 0, comparedCount = 0;
    let dnfCount = 0;
    rows.forEach(r => {
      if(r.real == null){ dnfCount++; return; }
      if(r.pred == null) return;
      comparedCount++;
      const d = Math.abs(r.diff);
      if(d === 0) exactHits++;
      if(d <= 3) within3Hits++;
      if(d <= 5) within5Hits++;
      totalErr += d;
    });
    const mae = comparedCount ? totalErr / comparedCount : null;

    const accColor = (n, base) => {
      const pct = base > 0 ? n / base : 0;
      return pct >= 0.7 ? '#16a34a' : pct >= 0.4 ? '#f59e0b' : '#dc2626';
    };
    const pdfLogoSrc = document.querySelector('.brand-logo')?.src || '';

    // Filas de la tabla
    const rowsHtml = rows.map(r => {
      let predTxt, realTxt, diffTxt, rowBg;
      if(r.real == null){
        realTxt = '<span style="color:#b91c1c;font-weight:700">DNF / No terminó</span>';
        predTxt = r.pred != null ? `<b>${r.pred}º</b> esperado` : '—';
        diffTxt = '<span style="color:#b91c1c;font-weight:700">—</span>';
        rowBg = '#fee2e2';
      } else if(r.pred == null){
        realTxt = `<b>${r.real}º</b> real`;
        predTxt = '<span style="color:#6b7280">sin predicción</span>';
        diffTxt = '—';
        rowBg = '#f3f4f6';
      } else {
        const d = r.diff;
        const dAbs = Math.abs(d);
        predTxt = `<b>${r.pred}º</b>`;
        realTxt = `<b>${r.real}º</b>`;
        if(d === 0){
          diffTxt = '<span style="background:#dcfce7;color:#15803d;padding:2px 9px;border-radius:6px;font-weight:800;font-size:11px">✓ EXACTO</span>';
          rowBg = '#dcfce7';
        } else if(d < 0){
          diffTxt = `<span style="background:#dbeafe;color:#1e3a8a;padding:2px 9px;border-radius:6px;font-weight:800;font-size:11px">⬆️ ${dAbs} puestos MEJOR</span>`;
          rowBg = '#dbeafe';
        } else {
          diffTxt = `<span style="background:#fef3c7;color:#92400e;padding:2px 9px;border-radius:6px;font-weight:800;font-size:11px">⬇️ ${dAbs} puestos peor</span>`;
          rowBg = dAbs <= 5 ? '#fef3c7' : '#fed7aa';
        }
      }
      const extraInfo = [];
      if(r.terrainReason) extraInfo.push('🗺️ ' + escapeHtml(r.terrainReason));
      if(r.climateReason) extraInfo.push('🌤️ ' + escapeHtml(r.climateReason));
      if(r.elo != null) extraInfo.push('🧬 Elo ' + r.elo);
      return `<tr style="background:${rowBg}">
        <td style="padding:8px 10px"><b>${escapeHtml(r.name)}</b><div style="font-size:11px;color:#475569;margin-top:2px">${escapeHtml(r.cat)}${r.bib?' · #'+escapeHtml(r.bib):''}${extraInfo.length?' · '+extraInfo.join(' · '):''}</div></td>
        <td style="padding:8px 10px;text-align:center;font-size:14px">${predTxt}</td>
        <td style="padding:8px 10px;text-align:center;font-size:14px">${realTxt}</td>
        <td style="padding:8px 10px;text-align:center">${diffTxt}</td>
      </tr>`;
    }).join('');

    // Mensaje motivacional según resultados globales
    let mainMessage = '';
    if(comparedCount === 0){
      mainMessage = 'No hay corredores con predicción Y resultado real para evaluar.';
    } else if(mae != null && mae <= 3){
      mainMessage = `📍 <b>Predicción casi clavada</b>: error medio de solo ±${mae.toFixed(1)} puestos. El equipo ha rendido tal y como se esperaba.`;
    } else if(mae != null && mae <= 7){
      mainMessage = `🎯 <b>Predicción razonable</b>: error medio de ±${mae.toFixed(1)} puestos. Variaciones esperadas; algún corredor rindió por encima o por debajo del pronóstico.`;
    } else {
      mainMessage = `📊 <b>Carrera con sorpresas</b>: error medio de ±${mae.toFixed(1)} puestos. Varios corredores se alejaron bastante del pronóstico — pueden ser señales de mejora o de mal día.`;
    }

    const overlay = document.createElement('div');
    overlay.id = 'mtprvOverlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:flex-start;justify-content:center;padding:20px;overflow:auto';
    overlay.innerHTML = `
      <div class="pvr-modal" style="background:#fff;border-radius:14px;max-width:980px;width:100%;max-height:94vh;overflow:auto;box-shadow:0 20px 60px rgba(0,0,0,.4)">
        <div class="pvr-hdr" style="position:sticky;top:0;background:#fff;border-bottom:1px solid #e5e7eb;padding:14px 22px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;z-index:2">
          <div style="display:flex;align-items:center;gap:14px">
            ${pdfLogoSrc ? `<img src="${pdfLogoSrc}" alt="MFPP Cycling Specialist" class="pvr-logo">` : ''}
            <div style="min-width:0">
              <h2 style="margin:0;font-size:20px;color:#0b2f6b">🎯 Predicho vs Real · ${escapeHtml(myTeam)}</h2>
              <div class="small" style="margin-top:2px">${escapeHtml(race.raceName||'')} · ${escapeHtml(race.raceDate||'')}${race.localidad?' · '+escapeHtml(race.localidad):''}</div>
            </div>
          </div>
          <div class="pvr-actions no-print" style="display:flex;gap:8px;flex-wrap:wrap">
            <button class="btn" onclick="_simPrintMyTeamPredVsReal()" style="background:#dc2626;color:#fff;border:0;font-weight:800">🖨️ Imprimir / PDF</button>
            <button class="btn light" onclick="_simCloseMyTeamPredVsReal()">✕ Cerrar</button>
          </div>
        </div>

        <div class="pvr-kpis" style="padding:14px 22px">
          <div class="pvr-kpi"><div class="pvr-kpi-v" style="color:${accColor(exactHits, comparedCount)}">${exactHits}/${comparedCount}</div><div class="pvr-kpi-l">Puestos<br><span class="small">exactos</span></div></div>
          <div class="pvr-kpi"><div class="pvr-kpi-v" style="color:${accColor(within3Hits, comparedCount)}">${within3Hits}/${comparedCount}</div><div class="pvr-kpi-l">Predichos<br><span class="small">dentro de ±3 puestos</span></div></div>
          <div class="pvr-kpi"><div class="pvr-kpi-v" style="color:${accColor(within5Hits, comparedCount)}">${within5Hits}/${comparedCount}</div><div class="pvr-kpi-l">Predichos<br><span class="small">dentro de ±5 puestos</span></div></div>
          <div class="pvr-kpi"><div class="pvr-kpi-v" style="color:${mae==null?'#9ca3af':(mae<=3?'#16a34a':mae<=7?'#f59e0b':'#dc2626')}">${mae==null?'—':'±'+mae.toFixed(1)}</div><div class="pvr-kpi-l">Error medio<br><span class="small">posiciones</span></div></div>
        </div>

        <div style="padding:0 22px 6px;font-size:13px;color:#0b2f6b;background:#f0f9ff;border-bottom:1px solid #e0f2fe;margin:0 0 6px">
          <div style="padding:10px 0">${mainMessage}${dnfCount?' · <b style="color:#b91c1c">'+dnfCount+' DNF</b>':''}</div>
        </div>

        <div style="padding:0 22px 6px;font-size:11px;color:#6b7280">
          🟩 verde = puesto exacto · 🟦 azul = MEJOR que la predicción · 🟨 amarillo = peor pero dentro del rango · 🟧 naranja = bastante peor · 🟥 rojo = DNF
        </div>

        <div class="pvr-table-wrap" style="padding:6px 22px 18px">
          <table style="width:100%;border-collapse:collapse;font-size:13px;background:#fff;border:1px solid #cbd5e1;border-radius:8px;overflow:hidden">
            <thead><tr style="background:#1e3a8a;color:#fff">
              <th style="padding:8px 10px;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.5px">Corredor</th>
              <th style="padding:8px 10px;text-align:center;font-size:11px;text-transform:uppercase;letter-spacing:.5px;width:120px">🔮 Predicho</th>
              <th style="padding:8px 10px;text-align:center;font-size:11px;text-transform:uppercase;letter-spacing:.5px;width:120px">🏁 Real</th>
              <th style="padding:8px 10px;text-align:center;font-size:11px;text-transform:uppercase;letter-spacing:.5px;width:200px">Diferencia</th>
            </tr></thead>
            <tbody>${rowsHtml}</tbody>
          </table>
        </div>

        <div style="padding:0 22px 18px;font-size:11px;color:#475569">
          <b>Cómo leer la diferencia:</b> ⬆️ azul = el corredor rindió MEJOR de lo previsto (puesto menor) · ⬇️ amarillo = rindió peor pero dentro de rango razonable (≤5 puestos) · ⬇️ naranja = bastante peor de lo esperado · ✓ EXACTO = clavado al puesto previsto.
        </div>
      </div>`;
    document.body.appendChild(overlay);
    document.body.style.overflow = 'hidden';
    overlay.addEventListener('click', (ev) => { if(ev.target === overlay) _simCloseMyTeamPredVsReal(); });
  } catch(e){
    console.warn('_simOpenMyTeamPredVsReal', e);
    alert('Error al abrir el comparador de Mi Equipo: '+(e.message||e));
  }
}
function _simCloseMyTeamPredVsReal(){
  const o = document.getElementById('mtprvOverlay');
  if(o) o.remove();
  document.body.style.overflow = '';
}
function _simPrintMyTeamPredVsReal(){
  const prev = document.body.style.overflow;
  document.body.style.overflow = '';
  setTimeout(() => {
    window.print();
    setTimeout(() => {
      if(document.getElementById('mtprvOverlay')) document.body.style.overflow = prev;
    }, 50);
  }, 10);
}

function _simRenderTeamsPanel(){
  const panel = document.getElementById('simTeamsPanel');
  const body = document.getElementById('simTeamsBody');
  if(!panel || !body) return;
  if(!_simCurrentData){ panel.style.display='none'; return; }
  const {grid, race} = _simCurrentData;
  const _title    = document.getElementById('simTeamsTitle');
  const _predBtn  = document.getElementById('simTeamsPredVsRealBtn');
  const _reportBtn= document.getElementById('simTeamsReportBtn');
  const teams = _simComputeTeamPredictions(grid);
  // Clasificación REAL por equipos (suma de los 3 mejores TIEMPOS), si ya hay
  // resultados. Sirve de respaldo cuando NO hay predicción fiable por equipos.
  const realRiders = (race && Array.isArray(race.riders)) ? race.riders.filter(r=>r && r.pos>0) : [];
  const realTeams  = (typeof _simComputeRealTeamRanking==='function') ? _simComputeRealTeamRanking(realRiders) : [];
  const hasPred = teams.length >= 2;
  const hasReal = realTeams.length >= 2;
  if(!hasPred && !hasReal){ panel.style.display='none'; return; }
  panel.style.display = '';

  // ── CASO B: sin predicción fiable pero CON resultados → mostramos la
  // clasificación REAL por equipos, avisando de que la predicción no está
  // disponible (p.ej. una CRI sin otras CRI previas de la categoría).
  if(!hasPred){
    if(_title) _title.textContent = '🏁 Clasificación real por equipos';
    if(_predBtn)   _predBtn.style.display   = 'none';
    if(_reportBtn) _reportBtn.style.display = 'none';
    const note = `<div style="background:#fffbeb;border:1.5px solid #fcd34d;border-radius:10px;padding:10px 13px;margin-bottom:12px;font-size:12.5px;color:#92400e;line-height:1.5">
      ⚠️ <b>Predicción por equipos no disponible:</b> no hay histórico suficiente/compatible para predecir (p.ej. una <b>CRI</b> sin otras CRI previas de la categoría, o categoría sin pruebas anteriores). Mostramos la <b>clasificación REAL por equipos</b> = suma de los <b>3 mejores tiempos</b> de cada equipo.
    </div>`;
    const rt = realTeams.slice(0,10);
    body.innerHTML = note + `<div class="sim-teams-grid">${rt.map((t,i)=>{
      const rank=i+1;
      let cls = rank===1?'gold':rank===2?'silver':rank===3?'bronze':'';
      if(t.isMyTeam) cls='mine';
      const sumStr = (t.sumByTime && typeof formatSeconds==='function') ? formatSeconds(t.sumSecs) : String(t.sumTop3);
      const ridersHtml = (t.top3||[]).map(g=>{
        const ts = (g.secs!=null && typeof formatSeconds==='function') ? formatSeconds(g.secs) : '';
        return `<div><b>${escapeHtml(g.name)}</b> <span style="color:#15803d;font-weight:700">${g.pos}º</span>${ts?` · <span style="color:#6b7280">${ts}</span>`:''}</div>`;
      }).join('');
      return `<div class="sim-team-card ${cls}">
        <div class="sim-team-card-hdr">
          <span class="sim-team-rank">${rank}º</span>
          <span class="sim-team-name">${t.isMyTeam?'🔵 ':''}${escapeHtml(t.team)}</span>
          <span class="sim-team-sum">Σ ${sumStr}</span>
        </div>
        <div class="sim-team-riders">${ridersHtml}</div>
        <div style="font-size:11px;color:#6b7280;margin-top:6px">${t.sumByTime?'Suma de los 3 mejores tiempos':'Suma de puestos (sin tiempos cargados)'}</div>
      </div>`;
    }).join('')}</div>`;
    _simApplyTeamsPanelCollapsedState();
    return;
  }

  // ── CASO A: hay predicción por equipos (comportamiento normal) ──
  if(_title) _title.textContent = '🏅 Predicción por equipos · Top 3 esperado';
  if(_predBtn)   _predBtn.style.display   = hasReal ? '' : 'none';
  if(_reportBtn) _reportBtn.style.display = '';
  // Top 10 equipos
  const top = teams.slice(0,10);
  body.innerHTML = `<div class="sim-teams-grid">${top.map((t,i)=>{
    const rank = i+1;
    let cls = '';
    if(rank===1) cls = 'gold';
    else if(rank===2) cls = 'silver';
    else if(rank===3) cls = 'bronze';
    if(t.isMyTeam) cls = 'mine';
    const ridersHtml = t.top3.map(g=>{
      const score = g._teamScore ?? g.predictedPos ?? g.avgPos;
      const trend = g.trend==='up'?'⬆️':g.trend==='down'?'⬇️':'';
      // Si la predicción excede el pelotón, mostrar con "+"
      const totIns = _simCurrentData?.inscritos?.length || 60;
      const exceeds = g.predExceedsGrid || (score != null && score > totIns);
      const scoreStr = score==null ? '—'
                     : exceeds ? totIns+'+º'
                     : score.toFixed(1)+'º';
      return `<div>${g.isMyTeam?'🔵 ':''}<b class="sim-rider-clickable" data-rider="${escapeHtml(g.name)}" onclick="_simShowRiderHistory(this.dataset.rider)" title="Click para ver carreras históricas">${escapeHtml(g.name)}</b> <span style="color:#7c3aed;font-weight:700" title="${exceeds?'Predicción real: '+Math.round(score)+'º (excede el pelotón)':'Posición predicha'}">${scoreStr}</span> ${trend}</div>`;
    }).join('');
    // Indicador de "amenaza" colectiva
    const podColor = t.anyPodiumProb>=50?'#15803d':t.anyPodiumProb>=25?'#d97706':'#94a3b8';
    const riskColor = t.avgCutRisk>50?'#b91c1c':t.avgCutRisk>25?'#d97706':'#94a3b8';
    return `<div class="sim-team-card ${cls}">
      <div class="sim-team-card-hdr">
        <span class="sim-team-rank">${rank}º</span>
        <span class="sim-team-name">${t.isMyTeam?'🔵 ':''}${escapeHtml(t.team)}</span>
        <span class="sim-team-sum">Σ ${t.sumTop3.toFixed(1)}</span>
      </div>
      <div class="sim-team-riders">${ridersHtml}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:6px;display:flex;flex-wrap:wrap;gap:8px;align-items:center">
        <span>Mejor: ${t.best.toFixed(1)}º</span>
        <span>·</span>
        <span title="Suma de probabilidades Top10 individuales">🎯 ${t.expectedTop10!=null?t.expectedTop10.toFixed(1):'—'} esperados Top10</span>
        <span>·</span>
        <span style="color:${podColor};font-weight:700" title="Prob. de que algún top3 haga podio">🥇 ${t.anyPodiumProb??'—'}%</span>
        ${t.avgCutRisk>25?`<span>·</span><span style="color:${riskColor};font-weight:700" title="Riesgo medio de corte top3">🚨 ${t.avgCutRisk}%</span>`:''}
      </div>
    </div>`;
  }).join('')}</div>
  <p class="small" style="margin-top:10px;color:#6b7280">Ranking por Σ top3 (menor = mejor). 🎯 = nº esperado de Top10 (Bernoulli). 🥇 = prob. de podio individual del top3 (logística). 🚨 = riesgo medio de corte.</p>`;
  // Bloque movido + colapsable: aplicar el estado guardado en localStorage
  _simApplyTeamsPanelCollapsedState();
}

// ── D) ANÁLISIS POR LOCALIDAD ─────────────────────────────────────────────
function _simRenderLocalityPanel(){
  const panel = document.getElementById('simLocalityPanel');
  const body = document.getElementById('simLocalityBody');
  if(!panel || !body) return;
  if(!_simCurrentData){ panel.style.display='none'; return; }
  const {race, grid} = _simCurrentData;
  const locality = (race.localidad||'').trim();
  if(!locality){ panel.style.display='none'; return; }
  // Normalizar localidad para matching (case-insensitive)
  const locNorm = locality.toLowerCase();
  const hist = (_cachedHistory||[]).filter(h => h.id!==race.id && (h.riders||[]).length>=3 && (h.localidad||'').toLowerCase().trim()===locNorm);
  if(!hist.length){ panel.style.display='none'; return; }
  // Para cada inscrito con histórico, calcular media en esa localidad
  const rows = grid.filter(g=>g.hasHistory).map(g=>{
    const nk = normalizeForMatching(g.name||'');
    const positions = [];
    hist.forEach(h=>{
      const r = (h.riders||[]).find(x=>normalizeForMatching(x.name)===nk);
      if(r && r.pos) positions.push(r.pos);
    });
    if(!positions.length) return null;
    const avgInLoc = positions.reduce((s,p)=>s+p,0)/positions.length;
    const delta = avgInLoc - g.avgPos;
    return {
      name: g.name, team: g.team, cat: g.cat, isMyTeam: g.isMyTeam,
      avgGlobal: g.avgPos, avgInLoc, races: positions.length, delta
    };
  }).filter(Boolean).sort((a,b)=>a.avgInLoc-b.avgInLoc);
  if(!rows.length){ panel.style.display='none'; return; }
  // Resumen
  const mineRows = rows.filter(r=>r.isMyTeam);
  let mineSummary = '';
  if(mineRows.length){
    const avg = mineRows.reduce((s,r)=>s+r.avgInLoc,0)/mineRows.length;
    const avgGl = mineRows.reduce((s,r)=>s+r.avgGlobal,0)/mineRows.length;
    const dlt = avg - avgGl;
    const dltCls = Math.abs(dlt)<1?'equal':dlt<0?'better':'worse';
    const dltLbl = Math.abs(dlt)<1?'≈':(dlt<0?'▲ '+Math.abs(dlt).toFixed(1):'▼ '+dlt.toFixed(1));
    mineSummary = `🔵 <b>Tu equipo en ${escapeHtml(locality)}</b>: media ${avg.toFixed(1)}º vs ${avgGl.toFixed(1)}º global · <span class="sim-circ-delta ${dltCls}">${dltLbl}</span>`;
  }
  panel.style.display = '';
  body.innerHTML = `
    <div class="sim-circ-summary" style="background:linear-gradient(135deg,#dbeafe,#bfdbfe);border-color:#93c5fd">
      <span>📍 <b>${hist.length} pruebas previas</b> en <b>${escapeHtml(locality)}</b> · <b>${rows.length} inscritos</b> con datos en esta localidad</span>
      ${mineSummary?'<span style="margin-left:auto">'+mineSummary+'</span>':''}
    </div>
    <div class="table-wrap" style="max-height:380px;overflow:auto">
      <table class="sim-circ-table">
        <thead><tr>
          <th>#</th><th>Corredor</th><th>Equipo</th><th style="text-align:center">Media en ${escapeHtml(locality)}</th><th style="text-align:center">Media global</th><th style="text-align:center">Δ</th><th style="text-align:center">Carrs.</th>
        </tr></thead>
        <tbody>${rows.map((r,i)=>{
          const dlt = r.delta;
          const dltCls = Math.abs(dlt)<1?'equal':dlt<0?'better':'worse';
          const dltLbl = Math.abs(dlt)<1?'≈':(dlt<0?'▲ '+Math.abs(dlt).toFixed(1):'▼ '+dlt.toFixed(1));
          return `<tr class="${r.isMyTeam?'sim-my-team':''}">
            <td style="text-align:center;font-weight:700">${i+1}</td>
            <td>${r.isMyTeam?'🔵 ':''}<b>${escapeHtml(r.name)}</b></td>
            <td>${escapeHtml(r.team||'')}</td>
            <td style="text-align:center;font-weight:800;color:#0c4a6e">${r.avgInLoc.toFixed(1)}º</td>
            <td style="text-align:center;color:#6b7280">${r.avgGlobal.toFixed(1)}º</td>
            <td style="text-align:center"><span class="sim-circ-delta ${dltCls}">${dltLbl}</span></td>
            <td style="text-align:center;color:#6b7280">${r.races}</td>
          </tr>`;
        }).join('')}</tbody>
      </table>
    </div>`;
}

// ── B) COMPARAR PREDICCIÓN VS RESULTADO ──────────────────────────────────
function _simRenderAccuracyPanel(){
  const panel = document.getElementById('simAccuracyPanel');
  const body = document.getElementById('simAccuracyBody');
  const savePanel = document.getElementById('simSavePanel');
  if(!panel || !body) return;
  if(!_simCurrentData){ panel.style.display='none'; if(savePanel) savePanel.style.display='none'; return; }
  const {race} = _simCurrentData;
  const ridersN = (race.riders||[]).length;
  const isPre = ridersN < 3;
  const saved = _simGetSavedPrediction(race);

  // Si carrera no disputada: mostrar panel de "guardar"
  if(isPre){
    panel.style.display = 'none';
    if(savePanel){
      savePanel.style.display = '';
      const hint = document.getElementById('simSavedHint');
      if(saved){
        if(hint){
          hint.style.display = '';
          hint.innerHTML = `📌 Ya hay una predicción guardada de ${new Date(saved.savedAt).toLocaleString('es-ES')}. Pulsa de nuevo para sobreescribir.`;
        }
      } else {
        if(hint) hint.style.display = 'none';
      }
    }
    return;
  }
  // Si está disputada: ocultar panel de guardar, mostrar precisión si hay predicción guardada
  if(savePanel) savePanel.style.display = 'none';
  if(!saved){
    panel.style.display = '';
    const raceId = race.id || '(sin id)';
    const raceName = race.raceName || '(sin nombre)';
    body.innerHTML = `
      <div style="text-align:center;padding:14px">
        <p class="small" style="color:#9ca3af;margin:0 0 10px">No se ha encontrado predicción guardada para esta prueba en la caché local.</p>
        <div style="font-size:11.5px;color:#475569;background:#f8fafc;border:1px solid #e5e7eb;border-radius:8px;padding:8px 12px;margin:0 auto 10px;max-width:520px;text-align:left">
          <b>Prueba seleccionada:</b> ${escapeHtml(raceName)}<br>
          <b>ID:</b> <code style="font-size:10.5px">${escapeHtml(raceId)}</code>
        </div>
        <div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
          <button class="btn" onclick="_simForceReloadAccuracy()" style="background:#0369a1;color:#fff;font-weight:800;font-size:12px;padding:6px 14px">🔄 Forzar recarga desde Supabase</button>
          <button class="btn" onclick="_simListAllSavedPredictions()" style="background:#7c3aed;color:#fff;font-weight:800;font-size:12px;padding:6px 14px">🔎 Buscar TODAS mis predicciones guardadas</button>
          <button class="btn" onclick="_simRetroactiveBacktestSingle()" style="background:#16a34a;color:#fff;font-weight:800;font-size:12px;padding:6px 14px" title="Predice esta prueba como si no la conociéramos y compara con el resultado real">🔁 Backtest retroactivo de esta prueba</button>
        </div>
        <p class="small" style="color:#6b7280;margin:10px 0 0">El <b>backtest retroactivo</b> reconstruye la predicción usando solo el histórico anterior a la fecha de esta carrera — no necesita que hayas guardado nada en su momento.</p>
      </div>`;
    return;
  }
  panel.style.display = '';
  // Comparar: para cada predicho top 10, ver dónde quedó realmente
  const riders = race.riders || [];
  const ridersByName = new Map();
  riders.forEach(r=>{ ridersByName.set(normalizeForMatching(r.name||''), r); });
  const compareRows = (saved.top10||[]).map(p=>{
    const real = ridersByName.get(normalizeForMatching(p.name||''));
    return {
      ...p,
      realPos: real ? real.pos : null,
      diff: real ? real.pos - p.rank : null  // diff positivo = peor de lo predicho
    };
  });
  // Métricas:
  // - Hits Top 10: cuántos predichos top 10 quedaron en top 10 real
  // - Hits Top 3: cuántos predichos top 3 quedaron en top 3 real
  // - Diferencia media absoluta (MAE)
  const inReal = compareRows.filter(r=>r.realPos!=null);
  const hitsTop10 = compareRows.filter(r=>r.realPos!=null && r.realPos<=10).length;
  const hitsTop3 = compareRows.slice(0,3).filter(r=>r.realPos!=null && r.realPos<=3).length;
  const mae = inReal.length ? Math.round(inReal.reduce((s,r)=>s+Math.abs(r.diff),0)/inReal.length*10)/10 : null;
  // Accuracy global: hitsTop10/10 si los 10 predichos están en clasificación
  const accuracyTop10 = compareRows.length ? Math.round(hitsTop10/compareRows.length*100) : 0;
  const accClass = accuracyTop10>=70?'good':accuracyTop10>=40?'ok':'bad';

  // Mi equipo: comparar predicción Montecarlo vs realidad
  const myAccRows = (saved.myTeamPred||[]).map(p=>{
    const real = ridersByName.get(normalizeForMatching(p.name||''));
    if(!real) return {...p, realPos:null, inRange:false, diff:null};
    const inRange = real.pos>=p.lower && real.pos<=p.upper;
    return {...p, realPos:real.pos, inRange, diff:real.pos-p.predicted};
  });
  const myHits = myAccRows.filter(r=>r.realPos!=null && r.inRange).length;
  const myWithReal = myAccRows.filter(r=>r.realPos!=null).length;

  const summaryHtml = `
    <div class="sim-acc-summary">
      <div class="sim-acc-card ${accClass}">
        <div class="acc-v">${accuracyTop10}%</div>
        <div class="acc-l">🎯 Aciertos Top 10</div>
        <div class="acc-s">${hitsTop10} de ${compareRows.length} predichos</div>
      </div>
      <div class="sim-acc-card ${hitsTop3===3?'good':hitsTop3>=2?'ok':'bad'}">
        <div class="acc-v">${hitsTop3}/3</div>
        <div class="acc-l">🥇 Podio acertado</div>
        <div class="acc-s">predichos en top 3 real</div>
      </div>
      ${mae!=null?`<div class="sim-acc-card ${mae<=3?'good':mae<=7?'ok':'bad'}">
        <div class="acc-v">±${mae}</div>
        <div class="acc-l">📐 Error medio (MAE)</div>
        <div class="acc-s">posiciones de diferencia</div>
      </div>`:''}
      ${myWithReal?`<div class="sim-acc-card ${myHits===myWithReal?'good':myHits>0?'ok':'bad'}">
        <div class="acc-v">${myHits}/${myWithReal}</div>
        <div class="acc-l">🔵 Mi equipo</div>
        <div class="acc-s">dentro del rango 50%</div>
      </div>`:''}
    </div>`;

  const tableHtml = `
    <h3 style="font-size:14px;margin:8px 0;color:#0b2f6b">📊 Top 10 predicho vs realidad</h3>
    <div class="table-wrap" style="max-height:360px;overflow:auto">
      <table class="sim-acc-table">
        <thead><tr><th>Pred.</th><th>Corredor</th><th>Equipo</th><th style="text-align:center">Pos. real</th><th style="text-align:center">Diferencia</th></tr></thead>
        <tbody>${compareRows.map(r=>{
          let diffHtml = '<span class="small" style="color:#9ca3af">— No acabó</span>';
          if(r.diff!=null){
            const abs = Math.abs(r.diff);
            const cls = abs<=3?'perfect':abs<=8?'close':'far';
            const sign = r.diff>0?'+':'';
            diffHtml = `<span class="sim-diff-badge ${cls}">${sign}${r.diff}</span>`;
          }
          return `<tr class="${r.isMyTeam?'sim-my-team':''}">
            <td><b>${r.rank}º</b></td>
            <td>${r.isMyTeam?'🔵 ':''}<b>${escapeHtml(r.name||'')}</b></td>
            <td>${escapeHtml(r.team||'')}</td>
            <td style="text-align:center;font-weight:800;color:#1d4ed8">${r.realPos!=null?r.realPos+'º':'DNF'}</td>
            <td style="text-align:center">${diffHtml}</td>
          </tr>`;
        }).join('')}</tbody>
      </table>
    </div>
    <p class="small" style="margin-top:6px;color:#6b7280">Predicción guardada el ${new Date(saved.savedAt).toLocaleString('es-ES')}.</p>`;

  body.innerHTML = summaryHtml + tableHtml;
}

// ── E) HISTÓRICO PRECISIÓN DEL MODELO ────────────────────────────────────
function _simToggleModelAccuracy(){
  const panel = document.getElementById('simModelAccPanel');
  if(!panel){ alert('Panel de precisión no disponible en esta vista.'); return; }
  const open = panel.style.display !== 'none';
  panel.style.display = open ? 'none' : '';
  if(!open){
    _simRenderModelAccuracy();
    // Hacer scroll suave para que el usuario vea el panel recién abierto
    try { panel.scrollIntoView({behavior:'smooth', block:'start'}); } catch(e){ panel.scrollIntoView(); }
  }
}

// Backtest retroactivo HONESTO: para cada carrera del histórico, le decimos
// al simulador "haz como si no conocieras esta carrera ni nada posterior" y
// generamos la predicción que el modelo habría hecho en su día. Después la
// comparamos contra el resultado real.
//
// Implementación: hot-swap temporal de _cachedHistory por una versión
// filtrada solo con carreras de fecha ESTRICTAMENTE anterior, luego restauramos.
function _simRetroactiveBacktest(){
  const hist = (typeof _cachedHistory !== 'undefined' && Array.isArray(_cachedHistory)) ? _cachedHistory : [];
  if(!hist.length) return { evals:[] };

  // Guardar estado del simulador
  const prevRaceId = _simSelectedRaceId;
  const prevData   = _simCurrentData;
  const origHist   = _cachedHistory;

  // Carreras válidas: disputadas (≥3 finishers) con fecha. Si no hay
  // inscritos guardados (común en histórico antiguo), usamos los propios
  // corredores que terminaron como lista a predecir.
  const candidates = hist.filter(h =>
       Array.isArray(h.riders) && h.riders.filter(r=>r.pos>0).length >= 3
    && h.raceDate
  );
  const diag = { totalHist: hist.length, candidates: candidates.length, dateOk:0, histOk:0, gridOk:0, comparable:0 };

  const evals = [];
  candidates.forEach(race => {
    try {
      const raceIso = _parseSpanishDate(race.raceDate);
      if(!raceIso) return;
      diag.dateOk++;
      // Histórico restringido: la prueba objetivo (para que el simulador
      // pueda encontrarla y predecirla) + SOLO carreras con fecha
      // estrictamente anterior. El simulador ya filtra internamente la
      // prueba actual para no usarla como entrenamiento de sí misma.
      const previousRaces = hist.filter(h => {
        if(h.id === race.id) return false;
        const iso = _parseSpanishDate(h.raceDate);
        return iso && iso < raceIso;
      });
      if(previousRaces.length < 2) return; // necesitamos al menos 2 carreras previas
      diag.histOk++;
      const restricted = [race, ...previousRaces];

      // Si la carrera no tiene inscritos guardados, sintetizamos uno temporal
      // con los corredores que terminaron (sabemos al menos quién participó).
      const needsSyntheticInscritos = !Array.isArray(race.inscritos) || race.inscritos.length < 3;
      let restored = null;
      if(needsSyntheticInscritos){
        restored = race.inscritos;
        race.inscritos = (race.riders||[]).filter(r=>r.pos>0).map(r=>({
          name: r.name, bib: r.bib||'', team: r.team||'', cat: r.cat||''
        }));
      }

      _cachedHistory = restricted;
      try { _simBuildData(race.id); }
      finally {
        if(needsSyntheticInscritos) race.inscritos = restored;
      }
      if(!_simCurrentData || !Array.isArray(_simCurrentData.grid)) return;
      diag.gridOk++;
      const grid = _simCurrentData.grid;

      // Top 10 predicho: orden por puesto esperado ascendente
      const predRanked = grid.filter(g => g.predictedPos != null)
        .sort((a,b)=>a.predictedPos - b.predictedPos)
        .slice(0, 10)
        .map((g,i) => ({ rank: i+1, name: g.name, isMyTeam: !!g.isMyTeam }));
      if(!predRanked.length) return;

      const realByName = new Map();
      (race.riders||[]).forEach(r => {
        if(r && r.pos > 0 && r.name) realByName.set(normalizeForMatching(r.name), parseInt(r.pos)||0);
      });
      const compare = predRanked.map(p => {
        const real = realByName.get(normalizeForMatching(p.name));
        return real ? { predRank: p.rank, realPos: real, diff: real - p.rank } : null;
      }).filter(Boolean);
      if(!compare.length) return;

      const hitsTop10 = compare.filter(c => c.realPos <= 10).length;
      const hitsTop3  = predRanked.slice(0,3).reduce((s,p) => s + ((realByName.get(normalizeForMatching(p.name))||999) <= 3 ? 1 : 0), 0);
      const mae = compare.reduce((s,c)=>s+Math.abs(c.diff),0) / compare.length;

      evals.push({
        raceId: race.id,
        raceName: race.raceName || '(sin nombre)',
        raceDate: race.raceDate || '',
        localidad: race.localidad || '',
        total: predRanked.length,
        hitsTop10,
        hitsTop3,
        mae,
        accuracyTop10: Math.round(hitsTop10 / predRanked.length * 100),
        historySize: previousRaces.length
      });
    } catch(e){
      console.warn('[retrobacktest]', race.raceName, e);
    }
  });

  // Restaurar histórico y estado del simulador
  _cachedHistory = origHist;
  try {
    if(prevRaceId) _simBuildData(prevRaceId);
    else _simCurrentData = prevData;
  } catch(e){ _simCurrentData = prevData; }

  return { evals, diag };
}

function _simRenderModelAccuracy(){
  const body = document.getElementById('simModelAccBody');
  if(!body) return;
  const hist = _cachedHistory || [];
  // Pruebas con predicción guardada Y resultado real (camino clásico)
  const withBoth = hist.filter(h => h.prediction && Array.isArray(h.riders) && h.riders.length>=3);

  // Si no hay ninguna predicción guardada, lanzamos el backtest retroactivo
  // automáticamente y enseñamos esos números.
  if(!withBoth.length){
    body.innerHTML = `
      <div style="text-align:center;padding:14px;background:#fef3c7;border:1px solid #fde68a;border-radius:8px;margin-bottom:14px">
        <p style="margin:0;color:#92400e;font-weight:700">ℹ️ No hay predicciones guardadas (botón 💾 nunca ejecutado), pero podemos evaluar el modelo igualmente.</p>
        <p class="small" style="margin:6px 0 10px;color:#78350f">Vamos a hacer un <b>backtest retroactivo honesto</b>: para cada carrera ya disputada, predecimos como si no conociéramos esa carrera ni nada posterior, y comparamos con el resultado real.</p>
        <button class="btn" onclick="_simRunRetroactiveBacktest()" style="background:#0369a1;color:#fff;font-weight:800;padding:8px 16px">🔁 Ejecutar backtest retroactivo</button>
      </div>`;
    return;
  }
  // Calcular precisión por prueba
  const evals = withBoth.map(h=>{
    const ridersByName = new Map();
    (h.riders||[]).forEach(r=>{ ridersByName.set(normalizeForMatching(r.name||''), r); });
    const top10 = h.prediction.top10 || [];
    const compare = top10.map(p=>{
      const real = ridersByName.get(normalizeForMatching(p.name||''));
      return real ? {predRank:p.rank, realPos:real.pos, diff:real.pos-p.rank} : null;
    }).filter(Boolean);
    const hitsTop10 = compare.filter(c=>c.realPos<=10).length;
    const hitsTop3 = top10.slice(0,3).map(p=>{
      const real = ridersByName.get(normalizeForMatching(p.name||''));
      return real && real.pos<=3 ? 1 : 0;
    }).reduce((s,v)=>s+v, 0);
    const mae = compare.length ? compare.reduce((s,c)=>s+Math.abs(c.diff),0)/compare.length : null;
    return {
      raceId:h.id, raceName:h.raceName, raceDate:h.raceDate, localidad:h.localidad||'',
      total: top10.length, hitsTop10, hitsTop3, mae, accuracyTop10: top10.length? Math.round(hitsTop10/top10.length*100):0
    };
  });
  // Ordenar por fecha desc
  evals.sort((a,b)=>{
    const da=_parseSpanishDate(a.raceDate)||'0000-00-00';
    const db=_parseSpanishDate(b.raceDate)||'0000-00-00';
    return db.localeCompare(da);
  });
  // Métricas globales
  const totalEvals = evals.length;
  const avgAccTop10 = Math.round(evals.reduce((s,e)=>s+e.accuracyTop10,0)/totalEvals);
  const totalHitsPodium = evals.reduce((s,e)=>s+e.hitsTop3,0);
  const totalPodiumPossible = totalEvals * 3;
  const podiumPct = Math.round(totalHitsPodium/totalPodiumPossible*100);
  const maes = evals.filter(e=>e.mae!=null).map(e=>e.mae);
  const avgMae = maes.length ? Math.round(maes.reduce((s,v)=>s+v,0)/maes.length*10)/10 : null;
  body.innerHTML = `
    <div class="sim-model-summary">
      <div class="sim-model-card">
        <div class="m-l">🎯 Precisión Top 10 (media)</div>
        <div class="m-v">${avgAccTop10}%</div>
        <div class="m-s">en ${totalEvals} predicciones</div>
      </div>
      <div class="sim-model-card">
        <div class="m-l">🥇 Aciertos podio</div>
        <div class="m-v">${totalHitsPodium}/${totalPodiumPossible}</div>
        <div class="m-s">${podiumPct}% del total</div>
      </div>
      ${avgMae!=null?`<div class="sim-model-card">
        <div class="m-l">📐 Error medio (MAE)</div>
        <div class="m-v">±${avgMae}</div>
        <div class="m-s">posiciones</div>
      </div>`:''}
    </div>
    <div class="table-wrap" style="max-height:380px;overflow:auto">
      <table class="sim-acc-table">
        <thead><tr><th>Fecha</th><th>Prueba</th><th>Localidad</th><th style="text-align:center">Top 10</th><th style="text-align:center">Podio</th><th style="text-align:center">MAE</th></tr></thead>
        <tbody>${evals.map(e=>{
          const accCls = e.accuracyTop10>=70?'good':e.accuracyTop10>=40?'ok':'bad';
          return `<tr>
            <td style="color:#475569;white-space:nowrap">${escapeHtml(e.raceDate||'—')}</td>
            <td><b>${escapeHtml(e.raceName||'')}</b></td>
            <td>${escapeHtml(e.localidad||'—')}</td>
            <td style="text-align:center"><span class="sim-diff-badge ${e.accuracyTop10>=70?'perfect':e.accuracyTop10>=40?'close':'far'}">${e.accuracyTop10}% (${e.hitsTop10}/${e.total})</span></td>
            <td style="text-align:center;font-weight:800;color:${e.hitsTop3===3?'#16a34a':e.hitsTop3>=2?'#f59e0b':'#dc2626'}">${e.hitsTop3}/3</td>
            <td style="text-align:center;color:#475569">${e.mae!=null?'±'+e.mae.toFixed(1):'—'}</td>
          </tr>`;
        }).join('')}</tbody>
      </table>
    </div>`;
}

// Dispara el backtest retroactivo y pinta los resultados en el panel.
function _simRunRetroactiveBacktest(){
  const body = document.getElementById('simModelAccBody');
  if(!body) return;
  body.innerHTML = '<p class="small" style="text-align:center;padding:20px;color:#0369a1">⏳ Ejecutando backtest retroactivo… (esto puede tardar unos segundos según el tamaño del histórico)</p>';
  // Damos un tick al navegador para que repinte el mensaje antes del cálculo
  setTimeout(() => {
    try {
      const { evals, diag } = _simRetroactiveBacktest();
      if(!evals.length){
        body.innerHTML = `
          <div style="text-align:center;padding:18px">
            <p class="small" style="color:#9ca3af;margin:0 0 10px">No se ha podido evaluar ninguna prueba retroactivamente.</p>
            <div style="display:inline-block;text-align:left;background:#f8fafc;border:1px solid #e5e7eb;border-radius:8px;padding:10px 14px;font-size:11.5px;color:#374151">
              <b>Desglose del análisis:</b><br>
              • Histórico total: <b>${diag.totalHist}</b> carreras<br>
              • Con resultados suficientes (≥3 finishers) y fecha: <b>${diag.candidates}</b><br>
              • Con fecha parseable: <b>${diag.dateOk}</b><br>
              • Con suficientes carreras anteriores: <b>${diag.histOk}</b><br>
              • Predicción generada con éxito: <b>${diag.gridOk}</b><br>
              • Comparables con el resultado real: <b>0</b>
            </div>
            <p class="small" style="color:#6b7280;margin:10px 0 0">Si <b>histOk &gt; 0</b> pero <b>gridOk = 0</b>, el simulador no encuentra histórico de los corredores aunque haya carreras previas (problema típico: nombres de corredores que no coinciden entre carreras).</p>
            <p class="small" style="color:#6b7280;margin:6px 0 0">Si <b>gridOk &gt; 0</b> pero comparables = 0, las predicciones no casan con los nombres de los corredores reales de cada carrera.</p>
          </div>`;
        return;
      }
      evals.sort((a,b)=>{
        const da = _parseSpanishDate(a.raceDate)||'0000-00-00';
        const db = _parseSpanishDate(b.raceDate)||'0000-00-00';
        return db.localeCompare(da);
      });
      const totalEvals = evals.length;
      const avgAccTop10 = Math.round(evals.reduce((s,e)=>s+e.accuracyTop10,0)/totalEvals);
      const totalHitsPodium = evals.reduce((s,e)=>s+e.hitsTop3,0);
      const totalPodiumPossible = totalEvals * 3;
      const podiumPct = Math.round(totalHitsPodium/totalPodiumPossible*100);
      const maes = evals.filter(e=>e.mae!=null).map(e=>e.mae);
      const avgMae = maes.length ? Math.round(maes.reduce((s,v)=>s+v,0)/maes.length*10)/10 : null;
      body.innerHTML = `
        <div style="padding:8px 10px;background:#dbeafe;border:1px solid #93c5fd;border-radius:8px;margin-bottom:12px;font-size:12px;color:#1e3a8a">
          ✅ <b>Backtest retroactivo honesto</b> sobre ${totalEvals} carreras del histórico. Cada predicción se generó usando SOLO el histórico anterior a la fecha de la carrera (no contamos datos del futuro). Útil para saber cómo de bien predice el modelo SIN haber guardado nada en su día.
        </div>
        <div class="sim-model-summary">
          <div class="sim-model-card">
            <div class="m-l">🎯 Precisión Top 10 (media)</div>
            <div class="m-v">${avgAccTop10}%</div>
            <div class="m-s">en ${totalEvals} pruebas</div>
          </div>
          <div class="sim-model-card">
            <div class="m-l">🥇 Aciertos podio</div>
            <div class="m-v">${totalHitsPodium}/${totalPodiumPossible}</div>
            <div class="m-s">${podiumPct}% del total</div>
          </div>
          ${avgMae!=null?`<div class="sim-model-card">
            <div class="m-l">📐 Error medio (MAE)</div>
            <div class="m-v">±${avgMae}</div>
            <div class="m-s">posiciones</div>
          </div>`:''}
        </div>
        <div class="table-wrap" style="max-height:380px;overflow:auto">
          <table class="sim-acc-table">
            <thead><tr><th>Fecha</th><th>Prueba</th><th>Localidad</th><th style="text-align:center">Hist.usado</th><th style="text-align:center">Top 10</th><th style="text-align:center">Podio</th><th style="text-align:center">MAE</th></tr></thead>
            <tbody>${evals.map(e=>{
              const accCls = e.accuracyTop10>=70?'good':e.accuracyTop10>=40?'ok':'bad';
              return `<tr>
                <td style="color:#475569;white-space:nowrap">${escapeHtml(e.raceDate||'—')}</td>
                <td><b>${escapeHtml(e.raceName||'')}</b></td>
                <td>${escapeHtml(e.localidad||'—')}</td>
                <td style="text-align:center;color:#6b7280;font-size:11px">${e.historySize} carreras</td>
                <td style="text-align:center"><span class="sim-diff-badge ${e.accuracyTop10>=70?'perfect':e.accuracyTop10>=40?'close':'far'}">${e.accuracyTop10}% (${e.hitsTop10}/${e.total})</span></td>
                <td style="text-align:center;font-weight:800;color:${e.hitsTop3===3?'#16a34a':e.hitsTop3>=2?'#f59e0b':'#dc2626'}">${e.hitsTop3}/3</td>
                <td style="text-align:center;color:#475569">±${e.mae.toFixed(1)}</td>
              </tr>`;
            }).join('')}</tbody>
          </table>
        </div>
        <p class="small" style="margin-top:10px;color:#6b7280">💡 La columna <b>Hist.usado</b> muestra cuántas carreras anteriores tenía disponibles el modelo para predecir esa carrera. Carreras tempranas en la temporada tendrán menos histórico y por tanto menor precisión esperada.</p>`;
    } catch(e){
      body.innerHTML = `<p class="small" style="text-align:center;padding:18px;color:#b91c1c">Error en el backtest: ${escapeHtml(e.message||String(e))}</p>`;
      console.warn('_simRunRetroactiveBacktest', e);
    }
  }, 50);
}

// ═══════════════════════════════════════════════════════════════════════════
// OPTIMIZADOR DEL PESO ELO
// Ejecuta el backtest retroactivo con varios pesos del blend Elo y devuelve
// cuál minimiza el MAE global. Permite aplicarlo automáticamente.
// ═══════════════════════════════════════════════════════════════════════════

function _simRunEloWeightOptimization(){
  const body = document.getElementById('simModelAccBody');
  if(!body) return;
  const weights = [0, 0.10, 0.20, 0.30, 0.40, 0.50];
  body.innerHTML = `
    <div style="text-align:center;padding:18px">
      <p style="color:#0369a1;font-weight:700;margin:0 0 8px">⏳ Optimizando peso del rating Elo…</p>
      <p class="small" style="color:#6b7280;margin:0">Probando ${weights.length} pesos diferentes contra todas tus carreras. Puede tardar 20-40 segundos.</p>
      <div id="eloOptProgress" style="margin-top:12px;font-size:13px;color:#0b2f6b;font-weight:700"></div>
    </div>`;

  // Guardar estado actual del simulador para restaurarlo al final
  const prevSelectedRaceId = _simSelectedRaceId;
  const prevData = _simCurrentData;
  const prevOverride = _eloBlendOverride;

  // Ejecutar las pruebas SECUENCIALMENTE con setTimeout encadenado para no
  // bloquear el navegador y poder actualizar el indicador de progreso.
  const results = [];
  let idx = 0;
  const progressEl = () => document.getElementById('eloOptProgress');

  const runNext = () => {
    if(idx >= weights.length){
      // Restaurar estado y mostrar resultados
      _eloBlendOverride = prevOverride;
      try { if(prevSelectedRaceId) _simBuildData(prevSelectedRaceId); else _simCurrentData = prevData; } catch(e){ _simCurrentData = prevData; }
      _renderEloOptimizationResults(results);
      return;
    }
    const w = weights[idx];
    if(progressEl()) progressEl().textContent = `Probando peso ${(w*100).toFixed(0)}% del Elo… (${idx+1}/${weights.length})`;
    setTimeout(() => {
      try {
        _eloBlendOverride = w;
        const { evals } = _simRetroactiveBacktest();
        if(evals.length){
          const avgAccTop10 = evals.reduce((s,e)=>s+e.accuracyTop10,0)/evals.length;
          const hitsPodium  = evals.reduce((s,e)=>s+e.hitsTop3,0);
          const possible    = evals.length * 3;
          const podiumPct   = hitsPodium / possible * 100;
          const maes        = evals.filter(e=>e.mae!=null).map(e=>e.mae);
          const avgMae      = maes.reduce((s,v)=>s+v,0)/maes.length;
          results.push({
            weight: w, races: evals.length,
            avgAccTop10, podiumPct, avgMae,
            hitsPodium, possiblePodium: possible
          });
        }
      } catch(e){ console.warn('[elo-opt]', w, e); }
      idx++;
      runNext();
    }, 30);
  };
  runNext();
}

function _renderEloOptimizationResults(results){
  const body = document.getElementById('simModelAccBody');
  if(!body) return;
  if(!results.length){
    body.innerHTML = '<p class="small" style="text-align:center;padding:18px;color:#b91c1c">No se ha podido completar la optimización.</p>';
    return;
  }
  // Mejor peso = menor MAE (criterio principal). Empate → mayor precisión Top 10.
  results.sort((a,b)=> a.avgMae - b.avgMae || b.avgAccTop10 - a.avgAccTop10);
  const best = results[0];
  // Reordenar por peso ASC para la tabla
  const tableRows = results.slice().sort((a,b)=>a.weight - b.weight);
  const baselineMae = results.find(r => r.weight === 0)?.avgMae;
  const baselineAcc = results.find(r => r.weight === 0)?.avgAccTop10;

  const rowsHtml = tableRows.map(r => {
    const isBest = r.weight === best.weight;
    const deltaMae = baselineMae != null ? r.avgMae - baselineMae : 0;
    const deltaAcc = baselineAcc != null ? r.avgAccTop10 - baselineAcc : 0;
    const dMaeColor = deltaMae < -0.3 ? '#15803d' : deltaMae > 0.3 ? '#b91c1c' : '#6b7280';
    const dAccColor = deltaAcc > 1 ? '#15803d' : deltaAcc < -1 ? '#b91c1c' : '#6b7280';
    return `<tr style="${isBest?'background:#dcfce7;font-weight:700':''}">
      <td style="padding:6px 8px;text-align:center;font-weight:800;color:${isBest?'#15803d':'#0b2f6b'}">${(r.weight*100).toFixed(0)}%${isBest?' 🏆':''}</td>
      <td style="padding:6px 8px;text-align:center">${r.races}</td>
      <td style="padding:6px 8px;text-align:center">${r.avgAccTop10.toFixed(0)}%</td>
      ${r.weight !== 0 ? `<td style="padding:6px 8px;text-align:center;color:${dAccColor}">${deltaAcc>=0?'+':''}${deltaAcc.toFixed(1)}%</td>` : '<td style="padding:6px 8px;text-align:center;color:#9ca3af">baseline</td>'}
      <td style="padding:6px 8px;text-align:center">${r.podiumPct.toFixed(0)}% (${r.hitsPodium}/${r.possiblePodium})</td>
      <td style="padding:6px 8px;text-align:center;font-weight:800">±${r.avgMae.toFixed(1)}</td>
      ${r.weight !== 0 ? `<td style="padding:6px 8px;text-align:center;color:${dMaeColor};font-weight:700">${deltaMae>=0?'+':''}${deltaMae.toFixed(2)}</td>` : '<td style="padding:6px 8px;text-align:center;color:#9ca3af">baseline</td>'}
    </tr>`;
  }).join('');

  const bestImprovement = best.weight === 0
    ? null
    : { mae: baselineMae - best.avgMae, acc: best.avgAccTop10 - baselineAcc };

  // ── AUTOMÁTICO: la app aplica sola la mejor opción. El director no tiene que
  // entender MAE ni "peso Elo": se le explica el resultado en lenguaje claro. ──
  try{ _simApplyEloWeight(best.weight, true); }catch(_){}

  const maeMej = bestImprovement ? Math.abs(bestImprovement.mae) : 0;
  const accMej = bestImprovement ? bestImprovement.acc : 0;
  const verdictHtml = best.weight === 0
    ? `<div style="background:#fef3c7;border:1px solid #fde68a;color:#92400e;padding:14px 16px;border-radius:10px;font-size:14px;line-height:1.5">
        🟡 <b>De momento NO conviene usar el aprendizaje.</b> Con las carreras que hay ahora, el simulador acierta igual o mejor sin él, así que <b>lo he dejado desactivado</b> automáticamente.<br>
        <span style="font-size:12.5px;color:#a16207">No tienes que hacer nada. Cuando cargues más carreras, vuelve a pulsar "🧪 Optimizar aprendizaje" y, si entonces mejora, lo activaré solo.</span>
      </div>`
    : `<div style="background:#dcfce7;border:1px solid #86efac;color:#166534;padding:14px 16px;border-radius:10px;font-size:14px;line-height:1.5">
        ✅ <b>Listo. He activado el aprendizaje automáticamente</b> porque mejora la predicción: ahora acierta de media <b>${maeMej.toFixed(1)} puesto(s) mejor</b>${accMej>0?` y mete <b>${accMej.toFixed(0)}% más</b> de corredores en el Top 10`:''}.<br>
        <span style="font-size:12.5px;color:#15803d">No tienes que hacer nada más: todas las predicciones a partir de ahora ya lo usan.</span>
      </div>`;

  const undoBtn = best.weight === 0
    ? ''
    : `<button class="btn light" onclick="_simApplyEloWeight(0)" style="font-weight:700">Prefiero no usarlo (volver a como estaba)</button>`;

  body.innerHTML = `
    ${verdictHtml}
    <div style="text-align:center;margin-top:14px;display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
      ${undoBtn}
      <button class="btn light" onclick="_simRunRetroactiveBacktest()" style="font-weight:700">↻ Ver backtest normal</button>
    </div>
    <details style="margin-top:14px">
      <summary style="cursor:pointer;font-weight:700;color:#6b7280;font-size:12.5px">🔍 Ver el detalle técnico (para curiosos)</summary>
      <table class="sim-acc-table" style="margin-top:10px;width:100%">
        <thead><tr>
          <th>Peso aprendizaje</th>
          <th style="text-align:center">Carreras</th>
          <th style="text-align:center">Precisión Top 10</th>
          <th style="text-align:center">Δ vs sin aprendizaje</th>
          <th style="text-align:center">Aciertos podio</th>
          <th style="text-align:center">Error medio (puestos)</th>
          <th style="text-align:center">Δ error</th>
        </tr></thead>
        <tbody>${rowsHtml}</tbody>
      </table>
      <p class="small" style="margin-top:8px;color:#94a3b8">El "error medio" es cuántos puestos se equivoca de media la predicción (menos = mejor). El "peso" es cuánto influye el nivel aprendido (Elo). La app elige y aplica sola el que menos se equivoca.</p>
    </details>`;
}

function _simApplyEloWeight(w, silent){
  _saveEloBlendWeight(w);
  _saveEloBlendEnabled(w > 0);
  if(!silent){
    if(w > 0 && typeof showToast==='function') showToast('✅ Aprendizaje activado en las predicciones','ok',3000);
    else if(typeof showToast==='function') showToast('↺ Aprendizaje desactivado','info',3000);
    // Si se desactiva manualmente, refrescar el panel para reflejarlo
    if(w===0){ const b=document.getElementById('simModelAccBody'); if(b) b.innerHTML='<div style="background:#fef3c7;border:1px solid #fde68a;color:#92400e;padding:14px 16px;border-radius:10px;font-size:14px">↺ Aprendizaje <b>desactivado</b>. Vuelves a la predicción de siempre. Puedes reactivarlo con "🧪 Optimizar aprendizaje".</div>'; }
  }
  // Recalcular la prueba activa
  if(typeof _simSelectedRaceId !== 'undefined' && _simSelectedRaceId){
    try { _simBuildData(_simSelectedRaceId); _simRenderCurrent(); } catch(e){}
  }
  if(typeof _simRefreshEloBlendBtnLabel === 'function') _simRefreshEloBlendBtnLabel();
  // Re-mostrar el backtest normal
  _simRunRetroactiveBacktest();
}

// Asegurar que _sbLoadHistory expone prediction desde notes
const _origSbLoadHistory_F3 = (typeof _sbLoadHistory==='function') ? _sbLoadHistory : null;
if(_origSbLoadHistory_F3){
  window._sbLoadHistory = async function(){
    const list = await _origSbLoadHistory_F3();
    // Cargar prediction desde notes en cada race (need second pass)
    if(!_sb || !list || !list.length) return list;
    const {data} = await _sb.from('races').select('id, notes').eq('race_type','clasificacion');
    if(data){
      const notesMap = new Map();
      data.forEach(r=>{ try{ notesMap.set(r.id, JSON.parse(r.notes||'{}')); }catch(e){} });
      list.forEach(h=>{
        const extra = notesMap.get(h.id);
        if(extra && extra.prediction) h.prediction = extra.prediction;
      });
    }
    return list;
  };
}

