// ═══════════════════════════════════════════════════════════════════════════
// SIMULADOR FASE 3b — PRONÓSTICO COLECTIVO + OPTIMIZADOR DE ALINEACIÓN
// ═══════════════════════════════════════════════════════════════════════════

// Estado global del optimizador (null = todos titulares)
let _simLineupActive = null;

// ── Utilidades de cálculo ─────────────────────────────────────────────────

// Calcula el score (Σ top3) con la alineación activa
function _simComputeLineupScore(myRiders, activeSet){
  const pool = (activeSet
    ? myRiders.filter(r=>activeSet.has(r.name))
    : myRiders.slice()
  ).filter(r=>(r.predictedPos??r.avgPos)!=null)
   .map(r=>({...r, _ls: r.predictedPos??r.avgPos}));
  pool.sort((a,b)=>a._ls - b._ls);
  const top3 = pool.slice(0,3);
  const sumTop3 = top3.reduce((s,r)=>s+r._ls, 0);
  const avgReliability = top3.length
    ? top3.reduce((s,r)=>s+(r.reliability??50),0)/top3.length : 0;
  return { pool, top3, sumTop3, avgReliability, hasEnough: top3.length>=3 };
}

// Probabilidad de podio colectivo a partir del ranking estimado
// Curva exponencial: P(rank=k) ≈ 0.85 · exp(-0.45·(k-1)) · ajusteFiab
// Justificación: la prob. de podio decae rápido con la posición esperada,
// pero un equipo predicho 1º con baja fiabilidad NO debería ser 88% seguro.
function _simPodiumProbability(rank, totalTeams, avgReliability){
  if(rank == null || totalTeams < 3) return null;
  // Decae exponencialmente con el ranking (más rápido si hay menos equipos)
  const decay = Math.max(0.35, 0.55 - 0.02 * totalTeams); // más equipos = decae más lento
  const base  = 0.85 * Math.exp(-decay * (rank - 1));
  // Ajuste por fiabilidad: corredores fiables → la predicción se cumple más
  // rel=100% → factor 1.00 · rel=50% → factor 0.75 · rel=0% → factor 0.50
  const relFactor = 0.5 + 0.5 * ((avgReliability||50)/100);
  return Math.min(95, Math.max(1, Math.round(base * relFactor * 100)));
}

// Detecta el rival directo (equipo más cercano por encima en el ranking)
function _simGetDirectRival(myRank, teams){
  const rivals = teams.filter(t=>!t.isMyTeam);
  if(!rivals.length) return null;
  // El de menor diferencia de Σ respecto al mío (inmediatamente encima)
  const justAbove = teams[myRank - 2]; // rank 1 → index 0
  if(justAbove && !justAbove.isMyTeam) return justAbove;
  return rivals[0];
}

// Genera alertas contextuales para el equipo
function _simTeamContextAlerts(grid, teams, myRank){
  const alerts = [];
  // Rivales con corredores en racha
  teams.filter(t=>!t.isMyTeam).slice(0, myRank + 2).forEach(t=>{
    const upCount = (t.top3||[]).filter(r=>r.trend==='up').length;
    if(upCount >= 2){
      alerts.push({type:'danger',icon:'⚠️',
        title:'Aviso IA',
        msg:`La predicción puede quedar corta: ${t.team} inscribe ${upCount} corredores en racha ascendente que podrían subir posiciones`});
    }
  });
  // Mis top3 con baja fiabilidad
  const myData = teams.find(t=>t.isMyTeam);
  if(myData){
    const unstable = (myData.top3||[]).filter(r=>(r.reliability??100)<50);
    if(unstable.length){
      alerts.push({type:'warning',icon:'⚠️',
        title:'Titulares inestables',
        msg:`${unstable.map(r=>(r.name||'').split(/[,\s]/)[0]).join(', ')} tienen fiabilidad <50%. Considera usar el optimizador para evaluar un cambio.`});
    }
    // Mis top3 en racha positiva
    const racing = (myData.top3||[]).filter(r=>r.trend==='up').length;
    if(racing >= 2){
      alerts.push({type:'info',icon:'🔥',
        title:'Equipo en buena forma',
        msg:`${racing} de tus 3 mejores corredores llevan racha positiva. La probabilidad de podio puede ser mayor de lo indicado.`});
    }
  }
  return alerts;
}

// ── Panel de pronóstico colectivo ─────────────────────────────────────────
function _simRenderTeamSummaryPanel(){
  const panel = document.getElementById('simTeamSummaryPanel');
  const body  = document.getElementById('simTeamSummaryBody');
  if(!panel||!body) return;
  if(!_simCurrentData||!myTeam){ panel.style.display='none'; return; }
  const {grid} = _simCurrentData;
  const myRiders = grid.filter(g=>g.isMyTeam);
  if(!myRiders.length){ panel.style.display='none'; return; }

  const teams    = _simComputeTeamPredictions(grid);
  const myData   = teams.find(t=>t.isMyTeam);
  if(!myData){ panel.style.display='none'; return; }

  const myRank     = teams.findIndex(t=>t.isMyTeam) + 1;
  const totalTeams = teams.length;
  const avgRel     = myData.top3.reduce((s,r)=>s+(r.reliability??50),0)/Math.max(1,myData.top3.length);
  const podiumProb = _simPodiumProbability(myRank, totalTeams, avgRel);
  const rival      = _simGetDirectRival(myRank, teams);
  const alerts     = _simTeamContextAlerts(grid, teams, myRank);

  panel.style.display='';
  const rc = myRank<=3?'#16a34a':myRank<=6?'#f59e0b':'#dc2626';
  const pc = podiumProb>=60?'#16a34a':podiumProb>=35?'#f59e0b':'#dc2626';
  const rivalDiff = rival ? rival.sumTop3 - myData.sumTop3 : null;

  body.innerHTML = `
    <div class="sim-team-summary-kpis">
      <div class="sim-ts-kpi" style="background:linear-gradient(135deg,${rc}12,${rc}06);border-color:${rc}30">
        <div class="sim-ts-kpi-icon">🏆</div>
        <div class="sim-ts-kpi-val" style="color:${rc}">${myRank}º <span style="font-size:15px;font-weight:600;color:#64748b">de ${totalTeams}</span></div>
        <div class="sim-ts-kpi-lbl">Posición estimada del equipo</div>
        <div class="sim-ts-kpi-sub">Suma top3: ${myData.sumTop3.toFixed(1)} pts · Fiab. media: ${Math.round(avgRel)}%</div>
      </div>
      <div class="sim-ts-kpi" style="background:linear-gradient(135deg,${pc}12,${pc}06);border-color:${pc}30">
        <div class="sim-ts-kpi-icon">🥇</div>
        <div class="sim-ts-kpi-val" style="color:${pc}">${podiumProb}%</div>
        <div class="sim-ts-kpi-lbl">Probabilidad de podio colectivo</div>
        <div class="sim-ts-kpi-sub">P(alguno del top3 hace podio individual): ${myData.anyPodiumProb??'—'}%</div>
      </div>
      <div class="sim-ts-kpi" style="background:linear-gradient(135deg,#0ea5e912,#0ea5e906);border-color:#0ea5e930">
        <div class="sim-ts-kpi-icon">🎯</div>
        <div class="sim-ts-kpi-val" style="color:#0369a1">${myData.expectedTop10!=null?myData.expectedTop10.toFixed(1):'—'}</div>
        <div class="sim-ts-kpi-lbl">Finishers esperados en Top 10</div>
        <div class="sim-ts-kpi-sub">Suma de probabilidades individuales (Bernoulli)</div>
      </div>
      <div class="sim-ts-kpi" style="background:linear-gradient(135deg,#dc262612,#dc262606);border-color:#dc262630">
        <div class="sim-ts-kpi-icon">⚔️</div>
        <div class="sim-ts-kpi-val" style="font-size:17px;color:#dc2626;font-weight:800">${rival?escapeHtml((rival.team||'').slice(0,22)):'—'}</div>
        <div class="sim-ts-kpi-lbl">Rival directo más peligroso</div>
        <div class="sim-ts-kpi-sub">${(() => {
          if(!rival || rivalDiff==null) return 'Sin rival detectado';
          const absDiff = Math.abs(rivalDiff).toFixed(1);
          // sumTop3 es la suma de puestos del top3 — menor = mejor posición
          // rivalDiff = rival.sumTop3 - myData.sumTop3
          //   <0 → el rival tiene menor suma → está POR DELANTE → nos llevan ventaja
          //   >0 → el rival tiene mayor suma → está POR DETRÁS → vamos por delante
          if(rivalDiff < -0.05) return `🔴 Nos llevan <b>${absDiff} pts</b> · Hay que recuperar`;
          if(rivalDiff >  0.05) return `🟢 Les llevamos <b>${absDiff} pts</b> · A defender la ventaja`;
          return `⚖️ Empate técnico — Σ idéntica`;
        })()}</div>
      </div>
    </div>
    ${alerts.length?`<div class="sim-team-alerts">
      ${alerts.map(a=>`<div class="sim-team-alert ${a.type}">${a.icon} <b>${escapeHtml(a.title)}:</b> ${escapeHtml(a.msg)}</div>`).join('')}
    </div>`:''}
  `;
}

// ── Optimizador de alineación ─────────────────────────────────────────────
function _simRenderLineupOptimizer(){
  const panel = document.getElementById('simLineupPanel');
  const body  = document.getElementById('simLineupBody');
  if(!panel||!body) return;
  if(!_simCurrentData||!myTeam){ panel.style.display='none'; return; }
  const {grid} = _simCurrentData;
  const myRiders = grid.filter(g=>g.isMyTeam);
  if(myRiders.length<2){ panel.style.display='none'; return; }
  panel.style.display='';
  // Inicializar estado si es primera vez o se cambió de prueba
  if(_simLineupActive===null){
    _simLineupActive = new Set(myRiders.map(r=>r.name));
  }
  _simLineupRedraw(body, myRiders, grid);
}

function _simLineupRedraw(body, myRiders, grid){
  const activeSet = _simLineupActive || new Set(myRiders.map(r=>r.name));
  const score = _simComputeLineupScore(myRiders, activeSet);
  // Ranking de mi equipo con el score actual
  const allTeams = _simComputeTeamPredictions(grid);
  const rivals   = allTeams.filter(t=>!t.isMyTeam);
  const myRank   = score.hasEnough
    ? rivals.filter(t=>t.sumTop3 < score.sumTop3).length + 1
    : null;
  const total    = rivals.length + 1;
  const podProb  = (myRank!=null) ? _simPodiumProbability(myRank, total, score.avgReliability) : null;

  const rc = myRank==null?'#94a3b8':myRank<=3?'#16a34a':myRank<=6?'#f59e0b':'#dc2626';
  const pc = podProb==null?'#94a3b8':podProb>=60?'#16a34a':podProb>=35?'#f59e0b':'#dc2626';

  // Ordenar: activos primero, luego por score
  const sorted = myRiders.slice().sort((a,b)=>{
    const aA=activeSet.has(a.name), bA=activeSet.has(b.name);
    if(aA&&!bA) return -1; if(!aA&&bA) return 1;
    return ((a.predictedPos??a.avgPos)??99) - ((b.predictedPos??b.avgPos)??99);
  });

  let html = `
    <div class="sim-lineup-score-bar">
      <div class="sim-ls-metric">
        <span class="sim-ls-val" style="color:${rc}">${myRank!=null?myRank+'º':'—'}</span>
        <span class="sim-ls-lbl">Posición equipo ${myRank!=null?'(de '+total+')':''}</span>
      </div>
      <div class="sim-ls-sep"></div>
      <div class="sim-ls-metric">
        <span class="sim-ls-val" style="color:#7c3aed">${score.hasEnough?'Σ '+score.sumTop3.toFixed(1):'—'}</span>
        <span class="sim-ls-lbl">Suma top3</span>
      </div>
      <div class="sim-ls-sep"></div>
      <div class="sim-ls-metric">
        <span class="sim-ls-val" style="color:${pc}">${podProb!=null?podProb+'%':'—'}</span>
        <span class="sim-ls-lbl">Prob. podio equipo</span>
      </div>
      <div class="sim-ls-sep"></div>
      <div class="sim-ls-metric">
        <span class="sim-ls-val" style="color:#475569">${score.top3.length}/3</span>
        <span class="sim-ls-lbl">Titulares en top3</span>
      </div>
    </div>
    ${!score.hasEnough?'<div class="sim-team-alert warning" style="margin-bottom:10px">⚠️ <b>Mínimo 3 titulares con datos</b> para calcular el score de equipo. Reactiva corredores.</div>':''}
    <div class="sim-lineup-hint">👆 Pulsa <b style="color:#991b1b">❌ Quitar</b> a la derecha de un corredor para dejarlo en la <b>suplencia</b> (deja de contar para el score del equipo). Cuando esté suplente, el botón cambiará a <b style="color:#065f46">✅ Poner</b> para reactivarlo. La <b>Σ top3</b> de los titulares activos se recalcula al instante.</div>
    <div class="sim-lineup-list">`;

  sorted.forEach(r=>{
    const isActive = activeSet.has(r.name);
    const inTop3   = score.top3.some(t=>t.name===r.name);
    const score_ = r.predictedPos ?? r.avgPos;
    const rangeStr = (r.predLower!=null&&r.predUpper!=null)
      ? `${r.predLower}º–${r.predUpper}º`
      : (score_!=null ? Math.round(score_)+'º' : 'Sin datos');
    const relC = r.reliability==null?'#9ca3af':r.reliability>=75?'#16a34a':r.reliability>=50?'#f59e0b':'#dc2626';
    const tIcon = r.trend==='up'?'⬆️':r.trend==='down'?'⬇️':r.recentForm?.length>=2?'➡️':'';
    const role  = !isActive?'suplente':inTop3?'top3':'titular';
    const roleLabel = !isActive?'SUPLENTE':inTop3?'TOP3 ✓':'TITULAR';

    html += `<div class="sim-lineup-row ${isActive?'active':'inactive'}">
      <div class="sim-lineup-rider-info">
        <div class="sim-lr-name"><span class="sim-rider-clickable" data-rider="${escapeHtml(r.name)}" onclick="_simShowRiderHistory(this.dataset.rider)" title="Click para ver carreras históricas">${escapeHtml(r.name)}</span> ${tIcon}</div>
        <div class="sim-lr-meta">
          ${escapeHtml(r.cat||'—')} ·
          Pos. IA: <b style="color:#7c3aed">${rangeStr}</b> ·
          Fiab: <b style="color:${relC}">${r.reliability!=null?r.reliability+'%':'—'}</b>
          ${r.raceCount?` · ${r.raceCount} carr.`:''}
        </div>
      </div>
      <div class="sim-lineup-role-badge ${role}">${roleLabel}</div>
      <button class="sim-lineup-toggle-btn ${isActive?'btn-quitar':'btn-poner'}"
        data-rider="${escapeHtml(r.name)}"
        onclick="_simLineupToggle(this.dataset.rider)">
        ${isActive?'❌ Quitar':'✅ Poner'}
      </button>
    </div>`;
  });

  html += `</div>
    <button class="btn light" style="margin-top:12px;font-size:12px;padding:7px 14px"
      onclick="_simLineupReset()">🔄 Resetear (todos titulares)</button>`;
  body.innerHTML = html;
}

function _simLineupToggle(name){
  if(!_simCurrentData) return;
  const {grid} = _simCurrentData;
  const myRiders = grid.filter(g=>g.isMyTeam);
  if(!_simLineupActive) _simLineupActive = new Set(myRiders.map(r=>r.name));
  // Guardar el hint actual antes de cambiar
  if(_simLineupActive.has(name)){
    // Comprobar que quedan ≥3 activos con datos
    const afterRemove = myRiders.filter(r=>
      _simLineupActive.has(r.name) && r.name!==name && (r.predictedPos??r.avgPos)!=null
    );
    if(afterRemove.length < 3){
      const body = document.getElementById('simLineupBody');
      if(body){
        const hint = body.querySelector('.sim-lineup-hint');
        if(hint){
          const prev = hint.innerHTML;
          hint.style.color='#dc2626';
          hint.textContent='⚠️ Necesitas al menos 3 titulares con datos para calcular el score del equipo.';
          setTimeout(()=>{ if(hint){ hint.style.color=''; hint.innerHTML=prev; } }, 2200);
        }
      }
      return;
    }
    _simLineupActive.delete(name);
  } else {
    _simLineupActive.add(name);
  }
  // Redibujado instantáneo
  const body = document.getElementById('simLineupBody');
  if(body) _simLineupRedraw(body, myRiders, grid);
  // Actualizar también el panel de resumen colectivo
  try{ _simRenderTeamSummaryPanel(); }catch(e){}
}

function _simLineupReset(){
  if(!_simCurrentData) return;
  const {grid} = _simCurrentData;
  const myRiders = grid.filter(g=>g.isMyTeam);
  _simLineupActive = new Set(myRiders.map(r=>r.name));
  const body = document.getElementById('simLineupBody');
  if(body) _simLineupRedraw(body, myRiders, grid);
  try{ _simRenderTeamSummaryPanel(); }catch(e){}
}

// ── HOOK: integrar Fase 3b en _simRenderCurrent ───────────────────────────
const _origSimRenderCurrent_F3b = (typeof _simRenderCurrent==='function') ? _simRenderCurrent : null;
if(_origSimRenderCurrent_F3b){
  window._simRenderCurrent = function(){
    // Resetear lineup al cambiar de carrera
    _simLineupActive = null;
    _origSimRenderCurrent_F3b();
    try{ _simRenderTeamSummaryPanel(); }catch(e){ console.warn('[sim][teamSummary]',e); }
    try{ _simRenderLineupOptimizer(); }catch(e){ console.warn('[sim][lineup]',e); }
  };
}

// Ocultar paneles Fase 3b cuando estado vacío
const _origSimShowEmpty_F3b = (typeof _simShowEmpty==='function') ? _simShowEmpty : null;
if(_origSimShowEmpty_F3b){
  window._simShowEmpty = function(customMsg){
    _origSimShowEmpty_F3b(customMsg);
    ['simTeamSummaryPanel','simLineupPanel'].forEach(id=>{
      const el = document.getElementById(id); if(el) el.style.display='none';
    });
  };
}
// ═══════════════════════════════════════════════════════════════════════════
// FIN SIMULADOR FASE 3b
// ═══════════════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════════════
// SIMULADOR FASE 4b — HOJA DE RUTA TÁCTICA (BRIEFING)
// ═══════════════════════════════════════════════════════════════════════════

// Genera el objeto de briefing estructurado a partir de los datos actuales
function _simBuildBriefing(){
  if(!_simCurrentData) return null;
  const {race, grid, kpis} = _simCurrentData;
  const esc = s => escapeHtml(String(s||''));

  // ── Bloque 1: Objetivo colectivo ─────────────────────────────────────────
  const teams    = _simComputeTeamPredictions(grid);
  const myData   = teams.find(t=>t.isMyTeam);
  const myRank   = myData ? teams.findIndex(t=>t.isMyTeam) + 1 : null;
  const totalT   = teams.length;
  const myRiders = grid.filter(g=>g.isMyTeam);

  // Alineación activa (respeta el optimizador)
  const activeSet = _simLineupActive && _simLineupActive.size
    ? _simLineupActive
    : new Set(myRiders.map(r=>r.name));
  const lineupScore = _simComputeLineupScore(myRiders, activeSet);
  const podiumProb  = lineupScore.hasEnough && myRank!=null
    ? _simPodiumProbability(myRank, totalT, lineupScore.avgReliability) : null;

  // Objetivo textual
  const goalText = (() => {
    if(!myRank) return 'Consolidar presencia y sumar experiencia';
    if(myRank===1) return 'Pelear por la victoria colectiva';
    if(myRank<=3)  return 'Luchar por el podio por equipos';
    if(myRank<=6)  return 'Alcanzar el Top ' + myRank + ' por equipos';
    return 'Sumar puntos y colocar a nuestros hombres en el top ' + Math.min(myRank+2, 15);
  })();

  // Líder estimado (mejor predictedPos de los titulares activos)
  const leaderPool = myRiders
    .filter(r=>activeSet.has(r.name) && (r.predictedPos??r.avgPos)!=null)
    .sort((a,b)=>((a.predictedPos??a.avgPos)||99)-((b.predictedPos??b.avgPos)||99));
  const leader = leaderPool[0] || null;

  const obj = {
    goalText, myRank, totalT, podiumProb,
    leader: leader ? {
      name: leader.name,
      range: (leader.predLower!=null&&leader.predUpper!=null)
        ? `${leader.predLower}º–${leader.predUpper}º`
        : (leader.predictedPos!=null ? Math.round(leader.predictedPos)+'º' : null),
      trend: leader.trend,
      probTop10: leader.probTop10Poisson,
      probPodium: leader.probPodiumLogistic,
      probCut: leader.probCutLogistic
    } : null,
    top3Riders: lineupScore.top3.map(r=>({
      name:r.name, score:(r.predictedPos??r.avgPos)?.toFixed(1), trend:r.trend,
      probTop10: r.probTop10Poisson, probPodium: r.probPodiumLogistic, probCut: r.probCutLogistic
    })),
    // Métricas agregadas del equipo
    teamExpectedTop10: myData ? myData.expectedTop10 : null,
    teamAnyPodium:     myData ? myData.anyPodiumProb : null,
    teamAvgCutRisk:    myData ? myData.avgCutRisk : null
  };

  // ── Bloque 2: Scouting — rivales más peligrosos por amenaza real ─────────
  // Score de amenaza compuesto: posición + tendencia + prob. podio individual
  const rivals = grid
    .filter(g => !g.isMyTeam && g.hasHistory && (g.predictedPos??g.avgPos)!=null)
    .map(g=>({
      name:g.name, team:g.team, cat:g.cat,
      score: g.predictedPos??g.avgPos,
      trend:g.trend, rel:g.reliability,
      probTop10: g.probTop10Poisson, probPodium: g.probPodiumLogistic, probCut: g.probCutLogistic,
      range:(g.predLower!=null&&g.predUpper!=null)?`${g.predLower}º–${g.predUpper}º`:null,
      // Score amenaza: mayor prob. podio + tendencia ascendente = más peligroso
      _threat: (g.probPodiumLogistic||0) + (g.trend==='up'?15:g.trend==='down'?-10:0) - (g.predictedPos||50)*0.5
    }));
  // Ordenar por amenaza descendente (los más peligrosos primero)
  rivals.sort((a,b)=>b._threat - a._threat);
  const scouting = rivals.slice(0,5);

  // ── Bloque 3: Consejo táctico ─────────────────────────────────────────────
  const circuitType = (race.circuitType||'').toLowerCase();
  const circuitProf = _simCircuitToProfile(race.circuitType||'');
  const circuitMeta = _SIM_PROFILE_META[circuitProf] || {};
  const advice = _simGenerateTacticAdvice({race, kpis, myRank, totalT, lineupScore, scouting, circuitProf, circuitMeta, leaderPool});

  return { race, kpis, obj, scouting, advice, circuitMeta, now: new Date().toLocaleString('es-ES') };
}

function _simGenerateTacticAdvice({race, kpis, myRank, totalT, lineupScore, scouting, circuitProf, circuitMeta, leaderPool}){
  const lines = [];
  const pred = kpis.predictability;
  const diff = kpis.difficulty;
  const cov  = kpis.coverage;
  const upRivals = scouting.filter(r=>r.trend==='up').length;

  // Sobre la predictibilidad y cobertura
  if(pred < 35 || cov < 50){
    lines.push(`La predictibilidad de la prueba es ${pred<35?'baja':'limitada'} (${pred}%) debido a la ${cov<50?'escasa cobertura histórica de la parrilla':'alta variabilidad de resultados'}. Se recomienda una táctica flexible y atenta a los cortes en los primeros kilómetros.`);
  } else if(pred >= 70){
    lines.push(`La prueba tiene alta predictibilidad (${pred}%), lo que indica una parrilla estable y conocida. Nuestro modelo es fiable en este contexto.`);
  }

  // Sobre la dificultad
  if(diff >= 60){
    lines.push(`La competencia es exigente: ${kpis.strongRivals} corredores con posición media inferior a 15. Prioriza proteger a nuestros líderes en los momentos de mayor exigencia.`);
  } else if(diff < 30){
    lines.push(`La parrilla es relativamente asequible. Buena oportunidad para que nuestros corredores adopten un rol más ofensivo.`);
  }

  // Sobre el tipo de circuito
  if(circuitProf && circuitMeta.label){
    lines.push(`Circuito de tipo ${circuitMeta.label}${race.circuitType?' ("'+race.circuitType+'")'||'':''}: ${circuitMeta.desc}. Asegúrate de que nuestros ${circuitMeta.label.toLowerCase()}s estén en posición en los momentos decisivos.`);
  }

  // Sobre la fiabilidad del equipo
  const unreliable = leaderPool.filter(r=>(r.reliability??100)<50);
  if(unreliable.length){
    lines.push(`Atención: ${unreliable.map(r=>(r.name||'').split(/[,\s]/)[0]).join(' y ')} presentan fiabilidad inferior al 50%. No expongas a estos corredores innecesariamente en la primera parte de carrera.`);
  }

  // Sobre rivales en racha
  if(upRivals>=2){
    const names = scouting.filter(r=>r.trend==='up').slice(0,2).map(r=>(r.name||'').split(/[,\s]/)[0]).join(' y ');
    lines.push(`${names} llevan racha ascendente y pueden superar su posición media esperada. Marcaje prioritario en las fases decisivas.`);
  }

  // Cierre constructivo
  if(myRank && myRank<=3 && lineupScore.hasEnough){
    lines.push(`Con la alineación actual nuestro equipo se sitúa ${myRank}º de ${totalT} en la clasificación por escuadras. Mantén el plan y protege esa posición.`);
  } else if(myRank && myRank>3 && lineupScore.hasEnough){
    lines.push(`Una mejora de 2-3 posiciones en nuestros corredores de apoyo podría hacer subir al equipo del ${myRank}º al podio colectivo. Busca el máximo rendimiento de todos los titulares.`);
  }

  return lines.join(' ');
}

// ── Render del panel ──────────────────────────────────────────────────────
function _simOpenBriefPanel(){
  const panel = document.getElementById('simBriefPanel');
  if(!panel) return;
  if(!_simCurrentData){ showToast('Selecciona una prueba primero', 'warn'); return; }
  const brief = _simBuildBriefing();
  if(!brief) return;
  _simDrawBriefPanel(brief);
  panel.style.display = '';
  panel.scrollIntoView({behavior:'smooth', block:'start'});
}

function _simDrawBriefPanel(brief){
  const body = document.getElementById('simBriefBody');
  if(!body) return;
  const esc = s => escapeHtml(String(s||''));
  const {obj, scouting, advice, circuitMeta, kpis, race, now} = brief;
  const trendI = t => t==='up'?'⬆️':t==='down'?'⬇️':t==='stable'?'➡️':'';

  // Helper para chips de probabilidad compactos
  const chip = (val, type) => {
    if(val==null) return '';
    let c, bg, icon='';
    if(type==='top10'){ c=val>=70?'#15803d':val>=40?'#92400e':'#475569'; bg=val>=70?'#dcfce7':val>=40?'#fef3c7':'#f1f5f9'; }
    else if(type==='podium'){ c=val>=60?'#15803d':val>=30?'#92400e':'#475569'; bg=val>=60?'#dcfce7':val>=30?'#fef3c7':'#f1f5f9'; if(val>=60) icon=' 🥇'; }
    else /* risk */ { c=val>50?'#991b1b':val>25?'#92400e':'#475569'; bg=val>50?'#fee2e2':val>25?'#fef3c7':'#f1f5f9'; if(val>50) icon=' ⚠️'; }
    return `<span style="background:${bg};color:${c};padding:1px 6px;border-radius:4px;font-weight:800;font-size:11px">${val}%${icon}</span>`;
  };

  // ── Bloque 1: Objetivo ──────────────────────────────────────────────────
  const block1 = `<div class="sim-brief-block sim-brief-obj">
    <div class="sim-brief-block-title">🎯 Bloque 1 · Resumen de objetivos</div>
    <div class="sim-brief-obj-goal">Objetivo colectivo: ${esc(obj.goalText)}</div>
    ${obj.leader ? `<div class="sim-brief-obj-leader">
      <span>👑 Líder estimado:</span>
      <b>${esc(obj.leader.name)}</b>
      ${obj.leader.range?`<span style="color:#7c3aed;font-weight:700">${esc(obj.leader.range)}</span>`:''}
      ${trendI(obj.leader.trend)}
      <span style="margin-left:6px;display:inline-flex;gap:5px;align-items:center;flex-wrap:wrap">
        ${obj.leader.probTop10!=null?`🎯 ${chip(obj.leader.probTop10,'top10')}`:''}
        ${obj.leader.probPodium!=null?`🥇 ${chip(obj.leader.probPodium,'podium')}`:''}
        ${obj.leader.probCut!=null && obj.leader.probCut>25?`🚨 ${chip(obj.leader.probCut,'risk')}`:''}
      </span>
    </div>` : ''}
    ${obj.podiumProb!=null ? `<div style="margin-top:10px;display:flex;gap:14px;flex-wrap:wrap">
      <span style="font-size:12px;color:#475569">Pos. equipo estimada: <b style="color:#0b2f6b">${obj.myRank}º de ${obj.totalT}</b></span>
      <span style="font-size:12px;color:#475569">Prob. podio colectivo: <b style="color:${obj.podiumProb>=60?'#16a34a':obj.podiumProb>=35?'#d97706':'#dc2626'}">${obj.podiumProb}%</b></span>
      ${obj.teamExpectedTop10!=null?`<span style="font-size:12px;color:#475569">🎯 Esperados Top10: <b style="color:#0369a1">${obj.teamExpectedTop10.toFixed(1)}</b></span>`:''}
      ${obj.teamAnyPodium!=null?`<span style="font-size:12px;color:#475569">🥇 Algún top3 podio: <b>${obj.teamAnyPodium}%</b></span>`:''}
    </div>` : ''}
    ${obj.top3Riders.length ? `<div style="margin-top:10px;font-size:12px;color:#475569">Top 3 titulares activos: ${obj.top3Riders.map(r=>`<b>${esc(r.name.split(/[,\s]/)[0])}</b> (${r.score||'—'}º) ${trendI(r.trend)}`).join(' · ')}</div>` : ''}
  </div>`;

  // ── Bloque 2: Scouting ──────────────────────────────────────────────────
  const scoutRows = scouting.map((r,i)=>`<div class="sim-brief-scout-row">
    <div class="sim-brief-scout-rank">${i+1}</div>
    <div class="sim-brief-scout-info">
      <div class="sim-brief-scout-name">${esc(r.name)}</div>
      <div class="sim-brief-scout-meta">${esc(r.team||'—')}${r.cat?' · '+esc(r.cat):''} · Pos. IA: <b>${r.range||Math.round(r.score)+'º'}</b> · Fiab: ${r.rel!=null?r.rel+'%':'—'}
        ${r.probPodium!=null?'<br>'+chip(r.probTop10,'top10')+' '+chip(r.probPodium,'podium')+(r.probCut>25?' '+chip(r.probCut,'risk'):''):''}
      </div>
    </div>
    <div class="sim-brief-scout-trend">${trendI(r.trend)}</div>
  </div>`).join('');
  const block2 = `<div class="sim-brief-block sim-brief-scout">
    <div class="sim-brief-block-title">🔭 Bloque 2 · Radar de vigilancia rival (Scouting)</div>
    <div class="sim-brief-scout-list">${scoutRows||'<p style="color:#9ca3af;font-size:12px">Sin rivales con suficiente historial detectados</p>'}</div>
  </div>`;

  // ── Bloque 3: Consejo táctico ────────────────────────────────────────────
  const block3 = `<div class="sim-brief-block sim-brief-advice">
    <div class="sim-brief-block-title">🧠 Bloque 3 · Consejo táctico de la IA</div>
    <div class="sim-brief-advice-text">${esc(advice)}</div>
  </div>`;

  // Cabecera
  const header = `<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:14px;flex-wrap:wrap">
    <div>
      <div style="font-size:11px;text-transform:uppercase;letter-spacing:.5px;color:#7c3aed;font-weight:800;margin-bottom:2px">Hoja de Ruta · Generada ${esc(now)}</div>
      <div style="font-size:15px;font-weight:900;color:#0f172a">${esc(race.raceName||'')}</div>
      <div style="font-size:12px;color:#64748b">${esc(race.raceDate||'')}${race.localidad?' · 📍'+esc(race.localidad):''}${circuitMeta.icon?' · '+circuitMeta.icon+' '+esc(circuitMeta.label||''):''}</div>
    </div>
    <div style="font-size:11px;color:#94a3b8;text-align:right">Predictibilidad: <b>${kpis.predictability}%</b><br>Cobertura: <b>${kpis.coverage}%</b><br>Inscritos: <b>${kpis.totalIns}</b></div>
  </div>`;

  body.innerHTML = header + block1 + block2 + block3;
}

