const _origParseText = (typeof parseText === 'function') ? parseText : null;
if(_origParseText){
  window.parseText = function(text){
    const ret = _origParseText(text);
    // Tras parsear, mostrar alertas de consistencia (con delay para que renderAll acabe)
    setTimeout(()=>{
      try{ _cargaRenderConsistencyAlerts(); }catch(e){ console.warn('[carga] consistency',e); }
    }, 300);
    return ret;
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// MENÚ CARGA Y RESUMEN · Opción B (3 mejoras del Tier MEDIO)
// 6. Validación rica inscritos vs histórico (detección de typos)
// 7. Previsualización en el modal del histórico
// 8. Detección de duplicados al guardar con contexto
// ═══════════════════════════════════════════════════════════════════════════

// ─── 6. VALIDACIÓN RICA INSCRITOS vs HISTÓRICO ────────────────────────────
// Levenshtein distance simple para detectar typos
function _cargaLevenshtein(a, b){
  if(!a || !b) return Math.max((a||'').length, (b||'').length);
  if(a === b) return 0;
  const m = a.length, n = b.length;
  if(Math.abs(m - n) > 4) return 99; // optimización: si difieren mucho en longitud, no son typo
  const dp = Array.from({length: m+1}, () => new Array(n+1));
  for(let i = 0; i <= m; i++) dp[i][0] = i;
  for(let j = 0; j <= n; j++) dp[0][j] = j;
  for(let i = 1; i <= m; i++){
    for(let j = 1; j <= n; j++){
      const cost = a[i-1] === b[j-1] ? 0 : 1;
      dp[i][j] = Math.min(dp[i-1][j] + 1, dp[i][j-1] + 1, dp[i-1][j-1] + cost);
    }
  }
  return dp[m][n];
}

// Para un inscrito sin match exacto, buscar el nombre del histórico más parecido
function _cargaFindSimilarRider(insName, allHistRiderNames){
  const nk = (insName||'').toLowerCase().trim();
  if(!nk || !allHistRiderNames.length) return null;
  let bestMatch = null, bestDist = 99;
  // Solo buscar entre nombres cuya longitud está cerca (±3)
  const targetLen = nk.length;
  for(const histName of allHistRiderNames){
    const hk = histName.toLowerCase().trim();
    if(Math.abs(hk.length - targetLen) > 3) continue;
    if(hk === nk) return null; // ya tiene match exacto, no es typo
    const dist = _cargaLevenshtein(nk, hk);
    if(dist < bestDist && dist <= 3){ // umbral típico de typo
      bestDist = dist;
      bestMatch = histName;
    }
  }
  return bestMatch ? {name: bestMatch, distance: bestDist} : null;
}

// Análisis completo de inscritos
async function _cargaAnalyzeInscritosVsHistory(insArr){
  if(!Array.isArray(insArr) || !insArr.length) return null;
  // ── Garantizar que el histórico está cargado ────────────────────────────
  if(!Array.isArray(_cachedHistory) || !_cachedHistory.length){
    try{
      if(typeof _sbLoadHistory === 'function'){
        _cachedHistory = await _sbLoadHistory();
      }
    }catch(e){ console.warn('analyze: no se pudo cargar histórico', e); }
  }
  const hist = Array.isArray(_cachedHistory) ? _cachedHistory : [];
  const allRiderNames = new Set();
  hist.forEach(h => {
    (h.riders||[]).forEach(r => { if(r.name) allRiderNames.add(r.name); });
    (h.inscritos||[]).forEach(i => { if(i.name) allRiderNames.add(i.name); });
  });
  const allRiderNamesArr = [...allRiderNames];

  // ── Generador de variantes de clave ─────────────────────────────────────
  // Algunas listas (típico de FCCV) pegan el nombre como
  // "Apellido1, Apellido2 Nombre". El normalizador estándar coge sólo la
  // PRIMERA palabra tras la coma, que en ese formato es el SEGUNDO APELLIDO
  // en vez del nombre, y entonces no casa con el histórico "Apellido1, Nombre".
  // Por eso devolvemos varias variantes y matcheamos contra cualquiera.
  const stripDiacritics = (s) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
  const variantsOf = (rawName) => {
    if(!rawName) return [];
    const s = String(rawName).trim();
    const out = new Set();
    // 1) Forma estándar (la que ya usa el resto de la app)
    try{
      if(typeof normalizeForMatching === 'function') out.add(normalizeForMatching(s));
    }catch(e){}
    // 2) Si hay coma, generar la variante "Apellido1, ÚLTIMA-palabra-tras-coma"
    //    Esto cubre el caso "Apellido1, Apellido2 Nombre" → "Apellido1, Nombre"
    const m = s.match(/^([^,]+),\s*(.+)$/);
    if(m){
      const ap = stripDiacritics((m[1].trim().split(/\s+/)[0])||'');
      const restWords = m[2].trim().split(/\s+/).filter(Boolean);
      if(restWords.length){
        const first = stripDiacritics(restWords[0]);
        const last  = stripDiacritics(restWords[restWords.length-1]);
        if(ap) out.add(ap+', '+first);
        if(ap && last !== first) out.add(ap+', '+last);
      }
    } else {
      // 3) Sin coma: input como "Apellido1 Apellido2 Nombre" o "Nombre Apellido1 Apellido2".
      //    Probamos ambas interpretaciones para no perder coincidencias.
      const ws = s.split(/\s+/).filter(Boolean);
      if(ws.length>=2){
        const w0=stripDiacritics(ws[0]), wL=stripDiacritics(ws[ws.length-1]);
        // "Apellido NOMBRE": surname=w0, name=wL
        out.add(w0+', '+wL);
        // "Nombre Apellido1 [Apellido2]": surname=w1, name=w0
        if(ws.length>=2) out.add(stripDiacritics(ws[1])+', '+w0);
      } else if(ws.length===1){
        out.add(stripDiacritics(ws[0]));
      }
    }
    return [...out].filter(Boolean);
  };

  // Set global: todas las variantes de todos los nombres del histórico.
  const normSet = new Set();
  allRiderNamesArr.forEach(n => variantsOf(n).forEach(v => normSet.add(v)));

  const enriched = [], newRiders = [], possibleTypos = [];
  insArr.forEach(ins => {
    const insVariants = variantsOf(ins.name);
    const matched = insVariants.some(v => normSet.has(v));
    if(matched){
      enriched.push(ins);
    } else {
      const similar = _cargaFindSimilarRider(ins.name, allRiderNamesArr);
      if(similar){
        possibleTypos.push({...ins, suggestion: similar.name, distance: similar.distance});
      } else {
        newRiders.push(ins);
      }
    }
  });
  return {
    total: insArr.length,
    enriched, newRiders, possibleTypos,
    enrichedN: enriched.length,
    newN: newRiders.length,
    typoN: possibleTypos.length
  };
}

// Render del informe enriquecido (sustituye el alert plano)
async function _cargaShowInscritosReportRich(insArr, source){
  const a = await _cargaAnalyzeInscritosVsHistory(insArr);
  if(!a){
    if(typeof showToast === 'function') showToast('No se pudo analizar inscritos','warn');
    return;
  }
  // Construir contenido del modal
  const overlay = document.createElement('div');
  overlay.id = '_cargaInscritosReportModal';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px';
  overlay.onclick = e => { if(e.target===overlay) overlay.remove(); };

  const typosHtml = a.typoN > 0 ? `
    <div style="margin-top:14px;padding:12px;background:#fef3c7;border:1.5px solid #fde68a;border-radius:10px">
      <div style="font-weight:800;color:#92400e;margin-bottom:8px">⚠️ Posibles typos detectados (${a.typoN})</div>
      <div style="font-size:11.5px;color:#78350f;margin-bottom:8px">Estos nombres del listado de inscritos se parecen mucho a otros del histórico — podrían ser el mismo corredor con un nombre escrito ligeramente distinto:</div>
      <div style="max-height:200px;overflow-y:auto">
        ${a.possibleTypos.map(t => `<div style="padding:6px 0;border-bottom:1px dashed #fcd34d;font-size:12.5px;display:flex;justify-content:space-between;align-items:center;gap:10px">
          <div><b style="color:#78350f">${escapeHtml(t.name)}</b> ${t.bib?`<span style="color:#a16207">(#${escapeHtml(t.bib)})</span>`:''}</div>
          <div style="text-align:right">
            <span style="font-size:11px;color:#a16207">≈ Histórico:</span><br>
            <b style="color:#15803d">${escapeHtml(t.suggestion)}</b>
            <span style="font-size:10px;color:#9ca3af">(${t.distance} car. dif.)</span>
          </div>
        </div>`).join('')}
      </div>
    </div>` : '';

  const newHtml = a.newN > 0 ? `
    <div style="margin-top:14px;padding:12px;background:#dbeafe;border:1.5px solid #93c5fd;border-radius:10px">
      <div style="font-weight:800;color:#1e40af;margin-bottom:8px">🆕 Corredores SIN histórico previo (${a.newN})</div>
      <div style="font-size:11.5px;color:#1e3a8a;margin-bottom:8px">Estos corredores no aparecen en ninguna carrera previa de la app. Pueden ser:<br>· Debutantes reales (primera carrera)<br>· Corredores nuevos en la categoría<br>· Nombres mal escritos (revisa la lista pegada)</div>
      <div style="max-height:200px;overflow-y:auto;font-size:12px;color:#1e3a8a">
        ${a.newRiders.slice(0,30).map(n => `<div style="padding:3px 0">• <b>${escapeHtml(n.name)}</b> ${n.team?` <span style="color:#64748b">· ${escapeHtml(n.team)}</span>`:''}</div>`).join('')}
        ${a.newN > 30 ? `<div style="margin-top:6px;color:#64748b;font-size:11px">… y ${a.newN - 30} más</div>` : ''}
      </div>
    </div>` : '';

  overlay.innerHTML = `<div style="background:#fff;border-radius:14px;max-width:680px;width:100%;max-height:90vh;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 20px 50px rgba(0,0,0,.3)">
    <div style="padding:16px 22px;background:linear-gradient(135deg,#0b2f6b,#1286c7);color:#fff">
      <div style="font-size:11px;text-transform:uppercase;letter-spacing:.5px;opacity:.85">📋 Análisis de inscritos</div>
      <h3 style="margin:2px 0 0">${a.total} corredores cargados desde ${escapeHtml(source)}</h3>
    </div>
    <div style="padding:18px 22px;overflow-y:auto;flex:1">
      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:6px">
        <div style="padding:10px;background:#dcfce7;border:1.5px solid #86efac;border-radius:10px;text-align:center">
          <div style="font-size:11px;font-weight:800;color:#15803d;text-transform:uppercase">✅ En histórico</div>
          <div style="font-size:26px;font-weight:900;color:#15803d">${a.enrichedN}</div>
          <div style="font-size:11px;color:#15803d">${Math.round(a.enrichedN/a.total*100)}% del total</div>
        </div>
        <div style="padding:10px;background:#fef3c7;border:1.5px solid #fde68a;border-radius:10px;text-align:center">
          <div style="font-size:11px;font-weight:800;color:#92400e;text-transform:uppercase">⚠️ Posibles typos</div>
          <div style="font-size:26px;font-weight:900;color:#92400e">${a.typoN}</div>
          <div style="font-size:11px;color:#92400e">parecidos a histórico</div>
        </div>
        <div style="padding:10px;background:#dbeafe;border:1.5px solid #93c5fd;border-radius:10px;text-align:center">
          <div style="font-size:11px;font-weight:800;color:#1e40af;text-transform:uppercase">🆕 Sin histórico</div>
          <div style="font-size:26px;font-weight:900;color:#1e40af">${a.newN}</div>
          <div style="font-size:11px;color:#1e40af">debutantes o nuevos</div>
        </div>
      </div>
      ${typosHtml}
      ${newHtml}
      <p style="font-size:11px;color:#6b7280;margin-top:14px;line-height:1.5">💡 <b>Los typos no se corrigen automáticamente.</b> Si quieres unificar nombres, edita manualmente la lista pegada antes de procesar. El simulador usa <code>normalizeForMatching</code> para hacer match parcial, así que pequeñas diferencias (acentos, etc.) pueden funcionar igualmente.</p>
    </div>
    <div style="padding:12px 22px;background:#f9fafb;border-top:1px solid #e5e7eb;display:flex;justify-content:flex-end;gap:8px">
      <button onclick="document.getElementById('_cargaInscritosReportModal').remove()" style="background:#0b2f6b;color:#fff;border:0;border-radius:8px;padding:8px 18px;font-weight:800;cursor:pointer">✅ Entendido</button>
    </div>
  </div>`;
  document.body.appendChild(overlay);
}

// Sustitución del alert plano: hook en _showInscritosEnrichmentReport
const _origShowInscritosEnrichmentReport = (typeof _showInscritosEnrichmentReport === 'function') ? _showInscritosEnrichmentReport : null;
if(_origShowInscritosEnrichmentReport){
  window._showInscritosEnrichmentReport = function(arr, source){
    // En vez del alert, usar el modal rico
    try{ _cargaShowInscritosReportRich(arr, source); }
    catch(e){
      console.warn('[carga] enrichment report error', e);
      _origShowInscritosEnrichmentReport(arr, source); // fallback al alert clásico
    }
  };
}

// ─── 7. PREVISUALIZACIÓN EN EL MODAL DEL HISTÓRICO ────────────────────────
// Añade un botón 👁 a cada entrada del modal del histórico que muestra
// un panel inline con: top 5 podio, nº inscritos, mejor de mi equipo
function _cargaShowHistoryPreview(raceId, btnEl){
  const hist = _cachedHistory || [];
  const race = hist.find(h => h.id === raceId);
  if(!race){
    if(typeof showToast === 'function') showToast('Carrera no encontrada','warn');
    return;
  }
  // Buscar el contenedor padre (.hist-entry)
  const entry = btnEl.closest('.hist-entry');
  if(!entry) return;
  // Si ya hay preview abierto, cerrarlo
  const existing = entry.nextElementSibling;
  if(existing && existing.classList.contains('hist-preview-inline')){
    existing.remove();
    btnEl.textContent = '👁 Preview';
    return;
  }
  // Quitar otros previews abiertos
  document.querySelectorAll('.hist-preview-inline').forEach(el => el.remove());
  document.querySelectorAll('[data-preview-btn="1"]').forEach(el => el.textContent = '👁 Preview');

  // Construir preview
  const top5 = (race.riders||[]).slice(0, 5);
  const myTeamKey = (typeof myTeam !== 'undefined' && myTeam) ? myTeam.toLowerCase().trim() : '';
  const myRiders = myTeamKey ? (race.riders||[]).filter(r => (r.team||'').toLowerCase().trim() === myTeamKey).sort((a,b)=>a.pos-b.pos) : [];
  const totalRiders = (race.riders||[]).length;
  const inscritosN = Array.isArray(race.inscritos) ? race.inscritos.length : 0;

  const preview = document.createElement('div');
  preview.className = 'hist-preview-inline';
  preview.style.cssText = 'background:#f8fafc;border:1.5px solid #cbd5e1;border-radius:10px;padding:12px 14px;margin:4px 0 8px 24px';
  preview.innerHTML = `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;font-size:12px">
      <div>
        <div style="font-weight:800;color:#0b2f6b;margin-bottom:6px;text-transform:uppercase;font-size:10.5px;letter-spacing:.4px">🏆 Top 5</div>
        ${top5.length ? top5.map(r => {
          const medal = r.pos===1?'🥇':r.pos===2?'🥈':r.pos===3?'🥉':' ';
          return `<div style="padding:2px 0">${medal} <b>${r.pos}º</b> ${escapeHtml(r.name||'')} <span style="color:#6b7280;font-size:11px">${escapeHtml((r.team||'').slice(0,22))}</span></div>`;
        }).join('') : '<div style="color:#9ca3af">Sin clasificados</div>'}
      </div>
      <div>
        <div style="font-weight:800;color:#0b2f6b;margin-bottom:6px;text-transform:uppercase;font-size:10.5px;letter-spacing:.4px">📊 Resumen</div>
        <div style="padding:2px 0">📋 <b>${totalRiders}</b> clasificados${inscritosN ? ' (de ' + inscritosN + ' inscritos)' : ''}</div>
        ${race.localidad ? `<div style="padding:2px 0">📍 ${escapeHtml(race.localidad)}</div>` : ''}
        ${race.circuitType ? `<div style="padding:2px 0">🛣️ ${escapeHtml(race.circuitType)}</div>` : ''}
        ${race.km ? `<div style="padding:2px 0">📏 ${escapeHtml(_fmtKm(race.km))}</div>` : ''}
        ${myTeamKey ? `<div style="margin-top:6px;padding-top:6px;border-top:1px solid #e2e8f0">
          <div style="font-weight:800;color:#1d4ed8;font-size:10.5px;text-transform:uppercase;letter-spacing:.4px;margin-bottom:3px">🔵 Mi equipo</div>
          ${myRiders.length
            ? myRiders.slice(0,3).map(r => `<div style="padding:1px 0">${r.pos}º · ${escapeHtml((r.name||'').split(',')[0])}</div>`).join('') + (myRiders.length > 3 ? `<div style="color:#6b7280;font-size:11px">+ ${myRiders.length - 3} más</div>` : '')
            : '<div style="color:#9ca3af;font-size:11px">Sin corredores de mi equipo</div>'
          }
        </div>` : ''}
      </div>
    </div>`;
  entry.parentNode.insertBefore(preview, entry.nextSibling);
  btnEl.textContent = '👁 Cerrar';
}

// Hook en openHistoryModal para añadir botón de preview a cada entrada
const _origOpenHistoryModal = (typeof openHistoryModal === 'function') ? openHistoryModal : null;
if(_origOpenHistoryModal){
  window.openHistoryModal = async function(){
    await _origOpenHistoryModal();
    // Tras renderizar el modal, añadir botones de preview a cada .hist-entry
    try{
      const entries = document.querySelectorAll('#histModalBody .hist-entry');
      entries.forEach(entry => {
        // Sacar el raceId del onclick existente
        const onclickStr = entry.getAttribute('onclick') || '';
        const m = onclickStr.match(/loadHistoryEntry\(['"]([^'"]+)['"]\)/);
        if(!m) return;
        const raceId = m[1];
        // Si ya hay botón preview, no añadir otro
        if(entry.querySelector('[data-preview-btn]')) return;
        const btn = document.createElement('button');
        btn.textContent = '👁 Preview';
        btn.setAttribute('data-preview-btn', '1');
        btn.style.cssText = 'background:#eef2ff;color:#3730a3;border:0;border-radius:6px;padding:6px 10px;font-size:12px;font-weight:700;cursor:pointer;margin-right:4px';
        btn.onclick = (ev) => { ev.stopPropagation(); _cargaShowHistoryPreview(raceId, btn); };
        // Insertar antes del botón "▶ Cargar"
        const actions = entry.querySelector('div:last-child');
        if(actions && actions.firstChild){
          actions.insertBefore(btn, actions.firstChild);
        }
      });
    }catch(e){ console.warn('[carga] history preview hook',e); }
  };
}

// ─── 8. DUPLICADOS YA EXISTÍA — solo añadimos toast informativo ───────────
// (La detección de duplicados ya estaba implementada en saveHistory →
//  _mostrarDialogoDuplicado. No la duplicamos aquí.)
// Lo que mejoramos: mostrar un toast al detectar duplicado para que el
// director vea claro que se ha disparado el diálogo (no es un freeze).

// ════════════════════════════════════════════════════════════════════════
// EQUIPOS — Opción B (Tier ALTO + MEDIO)
//   1. "Solo mi equipo" highlight + scroll
//   2. "Δ" diferencia A vs B en tabla de comparativa
//   3. Botón "Simular con estos equipos"
//   4. Tendencia ▲/▼ por equipo en ranking
//   5. Historial enfrentamientos directos A vs B
//   6. Columna "Media prueba" en comparativa
// ════════════════════════════════════════════════════════════════════════

// ── Inyección de controles UI (toolbar) sobre la sección de ranking ──
function _eqB_injectToolbar(){
  try{
    const sec = document.querySelector('.team-ranking-full .section-title');
    if(!sec || sec.querySelector('#eqB_myTeamBtn')) return;
    // Buscar el contenedor de controles de la derecha (el que ya tiene "Por tiempos / Por puntos / Informe completo")
    const exportBtn = sec.querySelector('button[onclick*="_exportTeamRanking"]');
    const rightBox = exportBtn ? exportBtn.parentElement : null;
    if(!rightBox) return;
    const btn = document.createElement('button');
    btn.id = 'eqB_myTeamBtn';
    btn.className = 'btn light';
    btn.style.cssText = 'font-size:12px;padding:6px 12px';
    btn.title = 'Resaltar y enfocar mi equipo';
    btn.innerHTML = '🎯 Solo mi equipo';
    btn.onclick = _eqB_focusMyTeam;
    rightBox.appendChild(btn);
    // Status (solo aparece cuando hay mensaje, no rompe el layout)
    const status = document.createElement('span');
    status.id = 'eqB_myTeamStatus';
    status.style.cssText = 'font-size:11px;color:#6b7280;align-self:center;margin-left:6px';
    rightBox.appendChild(status);
  }catch(e){}
}

function _eqB_getMyTeam(){
  try{
    return (typeof getPersistentTeam==='function' && getPersistentTeam()) ||
           (localStorage.getItem('myPersistentTeam')||'').trim() ||
           '';
  }catch(e){ return ''; }
}

function _eqB_focusMyTeam(){
  const mt = _eqB_getMyTeam();
  const status = document.getElementById('eqB_myTeamStatus');
  if(!mt){
    if(status) status.textContent = '⚠️ Define primero "Mi equipo" en Carga y Resumen';
    return;
  }
  const canon = (typeof getCanonicalTeam==='function') ? getCanonicalTeam(mt) : mt;
  const rows = document.querySelectorAll('#teamTimeRanking [data-team-row]');
  let found = null;
  rows.forEach(r=>{
    const t = r.getAttribute('data-team-row')||'';
    const tCanon = (typeof getCanonicalTeam==='function') ? getCanonicalTeam(t) : t;
    if(tCanon.toLowerCase() === canon.toLowerCase()){
      r.classList.add('highlight-team');
      r.style.outline = '3px solid #fbbf24';
      r.style.background = '#fffbeb';
      found = r;
    } else {
      r.style.opacity = '0.45';
    }
  });
  if(found){
    found.scrollIntoView({behavior:'smooth', block:'center'});
    if(status) status.innerHTML = `✅ Resaltando <b>${mt}</b> · <button class="btn light" style="font-size:10px;padding:2px 6px" onclick="_eqB_clearMyTeamFocus()">Quitar</button>`;
  } else {
    if(status) status.textContent = `⚠️ "${mt}" no tiene 3 clasificados en esta categoría`;
  }
}

function _eqB_clearMyTeamFocus(){
  const rows = document.querySelectorAll('#teamTimeRanking [data-team-row]');
  rows.forEach(r=>{
    r.style.opacity = '';
    r.style.outline = '';
    r.style.background = '';
    if(!r.classList.contains('highlight-team-orig')) r.classList.remove('highlight-team');
  });
  const status = document.getElementById('eqB_myTeamStatus');
  if(status) status.textContent = '';
}

// ── Tendencia ▲/▼ por equipo basado en historial ──
function _eqB_computeTeamTrend(team){
  try{
    if(!Array.isArray(_cachedHistory) || !_cachedHistory.length) return null;
    if(!team) return null;
    const tCanon = (typeof getCanonicalTeam==='function') ? getCanonicalTeam(team).toLowerCase() : team.toLowerCase();
    // Posición media del equipo en cada carrera histórica (orden cronológico inverso)
    const hist = _cachedHistory.slice().sort((a,b)=>{
      const da=(typeof _parseSpanishDate==='function'? _parseSpanishDate(a.raceDate):'')||'';
      const db=(typeof _parseSpanishDate==='function'? _parseSpanishDate(b.raceDate):'')||'';
      return db.localeCompare(da);
    });
    const avgsRecent = [];
    for(const race of hist){
      if(avgsRecent.length>=3) break;
      const rs = (race.riders||[]).filter(r=>{
        const rt = r.team || '';
        const rtC = (typeof getCanonicalTeam==='function') ? getCanonicalTeam(rt).toLowerCase() : rt.toLowerCase();
        return rtC === tCanon;
      });
      if(rs.length>=2){
        const avg = rs.reduce((s,r)=>s+(parseInt(r.pos)||0),0)/rs.length;
        avgsRecent.push(avg);
      }
    }
    if(avgsRecent.length<2) return null;
    const histAvg = avgsRecent.reduce((s,v)=>s+v,0)/avgsRecent.length;
    // Posición media actual del equipo en la prueba mostrada
    const currentRs = (typeof riders!=='undefined'?riders:[]).filter(r=>{
      const rt = r.team || '';
      const rtC = (typeof getCanonicalTeam==='function') ? getCanonicalTeam(rt).toLowerCase() : rt.toLowerCase();
      return rtC === tCanon;
    });
    if(!currentRs.length) return null;
    const currentAvg = currentRs.reduce((s,r)=>s+r.pos,0)/currentRs.length;
    const delta = currentAvg - histAvg;  // negativo = ha mejorado (posiciones más bajas)
    return { delta, histAvg, currentAvg, n: avgsRecent.length };
  }catch(e){ return null; }
}

function _eqB_trendBadge(team){
  const t = _eqB_computeTeamTrend(team);
  if(!t) return '';
  const d = t.delta;
  if(Math.abs(d) < 1.5) return `<span title="Estable vs media de últimas ${t.n} carreras (${t.histAvg.toFixed(1)})" style="font-size:10px;color:#6b7280;font-weight:700">▬ estable</span>`;
  if(d < 0) return `<span title="Mejora ${Math.abs(d).toFixed(1)} posiciones vs media histórica (${t.histAvg.toFixed(1)})" style="font-size:10px;color:#059669;font-weight:800">▲ +${Math.abs(d).toFixed(1)}</span>`;
  return `<span title="Empeora ${d.toFixed(1)} posiciones vs media histórica (${t.histAvg.toFixed(1)})" style="font-size:10px;color:#dc2626;font-weight:800">▼ -${d.toFixed(1)}</span>`;
}

function _eqB_postRanking(){
  _eqB_injectToolbar();
  // Añadir badge de tendencia a cada fila
  const rows = document.querySelectorAll('#teamTimeRanking [data-team-row]');
  rows.forEach(row=>{
    if(row.querySelector('.eqB-trend')) return;
    const team = row.getAttribute('data-team-row')||'';
    const badge = _eqB_trendBadge(team);
    if(!badge) return;
    const statsBox = row.querySelector('.team-ranking-stats');
    if(statsBox){
      const span = document.createElement('span');
      span.className = 'team-ranking-stat eqB-trend';
      span.innerHTML = badge;
      statsBox.appendChild(span);
    }
  });
}

// ── Media de la prueba (baseline para comparativa) ──
function _eqB_pruebaBaseline(){
  try{
    if(!Array.isArray(riders) || !riders.length) return null;
    const valid = riders.filter(r=>r.pos);
    const avgPos = valid.reduce((s,r)=>s+r.pos,0)/valid.length;
    const gaps = valid.map(r=>r.gapSeconds).filter(v=>v!=null);
    const avgGap = gaps.length ? gaps.reduce((s,v)=>s+v,0)/gaps.length : null;
    // media de clasificados por equipo
    const byTeam = {};
    valid.forEach(r=>{ if(r.team){ (byTeam[r.team]=byTeam[r.team]||[]).push(r); } });
    const counts = Object.values(byTeam).map(arr=>arr.length);
    const avgCount = counts.length ? counts.reduce((s,v)=>s+v,0)/counts.length : 0;
    return { avgPos, avgGap, avgCount, nTeams: counts.length };
  }catch(e){ return null; }
}

// ── Historial de enfrentamientos directos A vs B ──
function _eqB_h2hAB(teamA, teamB){
  try{
    if(!Array.isArray(_cachedHistory) || !_cachedHistory.length) return [];
    const tA = (typeof getCanonicalTeam==='function') ? getCanonicalTeam(teamA).toLowerCase() : teamA.toLowerCase();
    const tB = (typeof getCanonicalTeam==='function') ? getCanonicalTeam(teamB).toLowerCase() : teamB.toLowerCase();
    const out = [];
    const hist = _cachedHistory.slice().sort((a,b)=>{
      const da=(typeof _parseSpanishDate==='function'? _parseSpanishDate(a.raceDate):'')||'';
      const db=(typeof _parseSpanishDate==='function'? _parseSpanishDate(b.raceDate):'')||'';
      return db.localeCompare(da);
    });
    for(const race of hist){
      if(out.length>=5) break;
      const rsA = (race.riders||[]).filter(r=>{
        const rt=r.team||''; const c=(typeof getCanonicalTeam==='function')?getCanonicalTeam(rt).toLowerCase():rt.toLowerCase();
        return c===tA;
      });
      const rsB = (race.riders||[]).filter(r=>{
        const rt=r.team||''; const c=(typeof getCanonicalTeam==='function')?getCanonicalTeam(rt).toLowerCase():rt.toLowerCase();
        return c===tB;
      });
      if(rsA.length>=2 && rsB.length>=2){
        const bestA = Math.min(...rsA.map(r=>parseInt(r.pos)||999));
        const bestB = Math.min(...rsB.map(r=>parseInt(r.pos)||999));
        const avgA = rsA.reduce((s,r)=>s+(parseInt(r.pos)||0),0)/rsA.length;
        const avgB = rsB.reduce((s,r)=>s+(parseInt(r.pos)||0),0)/rsB.length;
        out.push({ raceName: race.raceName||race.name||'?', raceDate: race.raceDate||'', bestA, bestB, avgA, avgB });
      }
    }
    return out;
  }catch(e){ return []; }
}

function _eqB_postCompare(A, B){
  if(!A || !B) return;

  // 1. Añadir columna "Δ" y "Media prueba" a la tabla de comparativa
  const summary = document.getElementById('teamCompareSummary');
  if(summary){
    const baseline = _eqB_pruebaBaseline();
    const rowsTpl = [
      { label:'Clasificados',     a:A.count, b:B.count, lower:false, base: baseline?baseline.avgCount.toFixed(1):'—', fmt:v=>v },
      { label:'Mejor puesto',     a:A.best,  b:B.best,  lower:true,  base:'—', fmt:v=>v },
      { label:'Posición media',   a:A.avg,   b:B.avg,   lower:true,  base: baseline?baseline.avgPos.toFixed(1):'—', fmt:v=>(typeof v==='number'?v.toFixed(1):v) },
      { label:'Top 10',           a:A.top10, b:B.top10, lower:false, base:'—', fmt:v=>v },
      { label:'Top 20',           a:A.top20, b:B.top20, lower:false, base:'—', fmt:v=>v },
      { label:'Consistencia (σ)', a:A.stdDev,b:B.stdDev,lower:true,  base:'—', fmt:v=>(typeof v==='number'?v.toFixed(1):v) },
      { label:'Gap medio',        a:A.avgGap,b:B.avgGap,lower:true,  base: baseline&&baseline.avgGap!=null?(typeof formatSeconds==='function'?formatSeconds(baseline.avgGap):baseline.avgGap.toFixed(0)):'—',
                                  fmt:v=>v==null?'—':(typeof formatSeconds==='function'?formatSeconds(v):String(v)) }
    ];
    const tableHtml = `
      <div style="margin-top:12px;border-top:1px solid #e5e7eb;padding-top:10px">
        <div style="font-weight:800;font-size:12px;color:#0b2f6b;margin-bottom:6px">
          📊 Detalle con Δ y baseline de la prueba
        </div>
        <table style="width:100%;border-collapse:collapse;font-size:12px">
          <thead><tr style="background:#f9fafb">
            <th style="padding:4px 6px;text-align:left;font-size:10px;text-transform:uppercase;color:#6b7280">Métrica</th>
            <th style="padding:4px 6px;text-align:center;font-size:10px;color:#1f6feb">A</th>
            <th style="padding:4px 6px;text-align:center;font-size:10px;color:#12b76a">B</th>
            <th style="padding:4px 6px;text-align:center;font-size:10px;color:#7c3aed">Δ (A−B)</th>
            <th style="padding:4px 6px;text-align:center;font-size:10px;color:#6b7280">Media prueba</th>
          </tr></thead>
          <tbody>
            ${rowsTpl.map(r=>{
              const aVal = (r.a==null)?null:Number(r.a);
              const bVal = (r.b==null)?null:Number(r.b);
              let dTxt='—', dColor='#6b7280';
              if(aVal!=null && bVal!=null && !isNaN(aVal) && !isNaN(bVal)){
                const d = aVal - bVal;
                if(Math.abs(d)<0.05){ dTxt='0'; dColor='#6b7280'; }
                else {
                  const sign = d>0?'+':'';
                  const aBetter = r.lower ? (d<0) : (d>0);
                  dTxt = sign + (Number.isInteger(d)?d:d.toFixed(1));
                  dColor = aBetter ? '#1f6feb' : '#12b76a';
                }
              }
              return `<tr>
                <td style="padding:4px 6px;color:#374151">${r.label}</td>
                <td style="padding:4px 6px;text-align:center;font-weight:700;color:#1f6feb">${r.fmt(r.a)}</td>
                <td style="padding:4px 6px;text-align:center;font-weight:700;color:#12b76a">${r.fmt(r.b)}</td>
                <td style="padding:4px 6px;text-align:center;font-weight:800;color:${dColor}">${dTxt}</td>
                <td style="padding:4px 6px;text-align:center;color:#6b7280">${r.base}</td>
              </tr>`;
            }).join('')}
          </tbody>
        </table>
        <div style="font-size:10px;color:#9ca3af;margin-top:4px">Δ&nbsp;positivo en métricas donde "mayor es mejor" favorece a A; en métricas donde "menor es mejor" (posición, σ, gap) Δ&nbsp;negativo favorece a A. El color verde/azul indica qué equipo gana esa métrica.</div>
      </div>`;

    // H2H histórico
    const h2h = _eqB_h2hAB(A.team, B.team);
    let h2hHtml = '';
    if(h2h.length){
      const winsA = h2h.filter(x=>x.avgA < x.avgB).length;
      const winsB = h2h.filter(x=>x.avgB < x.avgA).length;
      h2hHtml = `
        <div style="margin-top:14px;border-top:1px solid #e5e7eb;padding-top:10px">
          <div style="font-weight:800;font-size:12px;color:#0b2f6b;margin-bottom:6px">
            ⚔️ Últimos enfrentamientos directos (${h2h.length})
            <span style="font-weight:700;color:#1f6feb;margin-left:8px">A ${winsA}</span>
            <span style="color:#9ca3af">·</span>
            <span style="font-weight:700;color:#12b76a">${winsB} B</span>
          </div>
          <table style="width:100%;border-collapse:collapse;font-size:11px">
            <thead><tr style="background:#f9fafb">
              <th style="padding:3px 5px;text-align:left;color:#6b7280;font-size:10px">Carrera</th>
              <th style="padding:3px 5px;text-align:center;color:#1f6feb;font-size:10px">A mejor</th>
              <th style="padding:3px 5px;text-align:center;color:#1f6feb;font-size:10px">A media</th>
              <th style="padding:3px 5px;text-align:center;color:#12b76a;font-size:10px">B mejor</th>
              <th style="padding:3px 5px;text-align:center;color:#12b76a;font-size:10px">B media</th>
              <th style="padding:3px 5px;text-align:center;color:#374151;font-size:10px">Gana</th>
            </tr></thead>
            <tbody>
              ${h2h.map(x=>{
                const winner = x.avgA < x.avgB ? 'A' : (x.avgB < x.avgA ? 'B' : '=');
                const wColor = winner==='A'?'#1f6feb':(winner==='B'?'#12b76a':'#6b7280');
                return `<tr>
                  <td style="padding:3px 5px;color:#374151">${escapeHtml(x.raceName)} <span style="color:#9ca3af">· ${escapeHtml(x.raceDate||'')}</span></td>
                  <td style="padding:3px 5px;text-align:center">${x.bestA}º</td>
                  <td style="padding:3px 5px;text-align:center">${x.avgA.toFixed(1)}</td>
                  <td style="padding:3px 5px;text-align:center">${x.bestB}º</td>
                  <td style="padding:3px 5px;text-align:center">${x.avgB.toFixed(1)}</td>
                  <td style="padding:3px 5px;text-align:center;font-weight:800;color:${wColor}">${winner}</td>
                </tr>`;
              }).join('')}
            </tbody>
          </table>
          <div style="font-size:10px;color:#9ca3af;margin-top:4px">Solo se cuentan carreras donde ambos equipos tenían ≥ 2 corredores. "Gana" = equipo con menor posición media.</div>
        </div>`;
    } else {
      h2hHtml = `<div style="margin-top:14px;padding:8px;background:#f9fafb;border-radius:6px;font-size:11px;color:#6b7280;text-align:center">⚔️ No hay enfrentamientos directos previos en el histórico</div>`;
    }

    // Botón simular
    const simBtn = `
      <div style="margin-top:14px;text-align:center">
        <button class="btn primary" style="font-size:12px;padding:8px 14px" onclick='_eqB_simulateAB(${JSON.stringify(A.team)}, ${JSON.stringify(B.team)})'>
          🎲 Simular próxima carrera con ${escapeHtml(A.team)} vs ${escapeHtml(B.team)}
        </button>
      </div>`;

    // Sólo añadir si no existe ya
    if(!summary.querySelector('[data-eqb-extra]')){
      const extra = document.createElement('div');
      extra.setAttribute('data-eqb-extra','1');
      extra.innerHTML = tableHtml + h2hHtml + simBtn;
      summary.appendChild(extra);
    } else {
      const extra = summary.querySelector('[data-eqb-extra]');
      extra.innerHTML = tableHtml + h2hHtml + simBtn;
    }
  }
}

// ── Lanzar simulador con equipos preseleccionados ──
function _eqB_simulateAB(teamA, teamB){
  try{
    sessionStorage.setItem('_eqB_simRivalTeams', JSON.stringify({a:teamA, b:teamB, ts:Date.now()}));
    if(typeof showView==='function'){
      showView('view-simulador');
      setTimeout(()=>{
        try{
          const banner = document.createElement('div');
          banner.id = 'eqB_simBanner';
          banner.style.cssText = 'position:fixed;top:16px;left:50%;transform:translateX(-50%);background:#fef3c7;border:2px solid #f59e0b;border-radius:10px;padding:10px 16px;font-size:13px;font-weight:700;color:#92400e;z-index:9999;box-shadow:0 6px 20px rgba(0,0,0,0.15)';
          banner.innerHTML = `🎲 Foco sugerido para simulación: <span style="color:#1f6feb">${escapeHtml(teamA)}</span> vs <span style="color:#12b76a">${escapeHtml(teamB)}</span> &nbsp; <button onclick="this.parentNode.remove()" style="background:none;border:0;cursor:pointer;font-size:14px">✕</button>`;
          const old = document.getElementById('eqB_simBanner'); if(old) old.remove();
          document.body.appendChild(banner);
          setTimeout(()=>{ const b=document.getElementById('eqB_simBanner'); if(b) b.remove(); }, 12000);
        }catch(e){}
      }, 250);
    }
  }catch(e){ console.warn('_eqB_simulateAB', e); }
}

// Auto-inyectar la toolbar al abrir la vista (por si la primera carga no llamó al ranking)
document.addEventListener('DOMContentLoaded', ()=>{
  setTimeout(_eqB_injectToolbar, 500);
});

// ════════════════════════════════════════════════════════════════════════
// TOP 10 — Opción B (Tier ALTO + MEDIO)
//   1. Badges de forma (🔥 racha, 📈 sube, 🌱 debutante) en cada fila
//   2. Botón "📊 Comparar todos en Comparativa" (primeros 6)
//   3. Botón "🎲 Simular próxima carrera con este Top 10"
//   4. Tooltip H2H en hover de fila (últimas coincidencias con otros del top10)
//   5. Toggle "▼ Mostrar Top 20"
//   6. "💎 Sorpresa" detectada en el comentario del director
// ════════════════════════════════════════════════════════════════════════

let _t10B_expandedTo20 = false;

function _t10B_riderHistory(name){
  try{
    if(!Array.isArray(_cachedHistory) || !_cachedHistory.length) return [];
    const nk = (typeof normalizeForMatching==='function') ? normalizeForMatching(name) : (name||'').toLowerCase().trim();
    const out = [];
    for(const race of _cachedHistory){
      const r = (race.riders||[]).find(x=>{
        const xk = (typeof normalizeForMatching==='function') ? normalizeForMatching(x.name||'') : (x.name||'').toLowerCase().trim();
        return xk === nk;
      });
      if(r && r.pos){
        out.push({
          raceName: race.raceName||race.name||'?',
          raceDate: race.raceDate||'',
          pos: parseInt(r.pos)||0,
          sortKey: (typeof _parseSpanishDate==='function' && _parseSpanishDate(race.raceDate))||(race.raceDate||'')
        });
      }
    }
    out.sort((a,b)=>String(b.sortKey).localeCompare(String(a.sortKey)));
    return out;
  }catch(e){ return []; }
}

function _t10B_formBadge(rider){
  const hist = _t10B_riderHistory(rider.name);
  if(!hist.length) return '<span class="t10b-badge" style="background:#dbeafe;color:#1e40af" title="Sin historial previo (al menos en el año en caché)">🌱 Nuevo</span>';
  if(hist.length < 3) return `<span class="t10b-badge" style="background:#fef3c7;color:#92400e" title="Solo ${hist.length} carrera(s) en histórico">🌱 Debutante</span>`;
  const recent3 = hist.slice(0,3).map(h=>h.pos);
  const avgRecent = recent3.reduce((s,v)=>s+v,0)/recent3.length;
  const all = hist.map(h=>h.pos);
  const avgAll = all.reduce((s,v)=>s+v,0)/all.length;
  const currentPos = rider.pos;
  // Racha: las últimas dos posiciones han mejorado consecutivamente
  if(recent3.length>=2 && recent3[0] < recent3[1] - 0 && recent3[1] < (recent3[2]||999)){
    // mejora monótona reciente
    return `<span class="t10b-badge" style="background:#fee2e2;color:#b91c1c" title="Mejorando en las últimas carreras: ${recent3.join('→')}">🔥 En racha</span>`;
  }
  // Sube mucho respecto a su media global
  if(currentPos < avgAll - 5){
    const delta = Math.round(avgAll - currentPos);
    return `<span class="t10b-badge" style="background:#dcfce7;color:#166534" title="Esta posición (${currentPos}º) supera a su media histórica (${avgAll.toFixed(1)}º)">📈 +${delta}</span>`;
  }
  // Mantiene nivel
  if(Math.abs(currentPos - avgAll) <= 2){
    return `<span class="t10b-badge" style="background:#e0e7ff;color:#3730a3" title="Posición acorde a su media histórica (${avgAll.toFixed(1)}º)">▬ Regular</span>`;
  }
  return '';
}

function _t10B_styleInject(){
  if(document.getElementById('t10B-styles')) return;
  const st = document.createElement('style');
  st.id = 't10B-styles';
  st.textContent = `
    .t10b-badge{display:inline-block;font-size:10px;font-weight:800;padding:2px 7px;border-radius:10px;margin-left:6px;letter-spacing:.2px;cursor:help}
    .t10b-actions{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 4px}
    .t10b-actions button{font-size:12px;padding:7px 12px}
    .t10b-h2h-tip{position:absolute;background:#0b2f6b;color:#fff;padding:8px 10px;border-radius:8px;font-size:11px;line-height:1.45;max-width:280px;z-index:9999;box-shadow:0 6px 16px rgba(0,0,0,.25);pointer-events:none}
    .t10b-h2h-tip .t10b-h2h-title{font-weight:800;border-bottom:1px solid rgba(255,255,255,.25);padding-bottom:3px;margin-bottom:4px;color:#fbbf24}
    .top10-table tbody tr{cursor:default}
  `;
  document.head.appendChild(st);
}

function _t10B_addBadgesToTable(top){
  const table = document.querySelector('#top10 .top10-table tbody');
  if(!table) return;
  const rows = table.querySelectorAll('tr');
  rows.forEach((tr, i)=>{
    if(!top[i]) return;
    const nameCell = tr.querySelector('.t-name');
    if(nameCell && !nameCell.querySelector('.t10b-badge')){
      const badge = _t10B_formBadge(top[i]);
      if(badge) nameCell.insertAdjacentHTML('beforeend', ' '+badge);
    }
    // Marcar fila con data para H2H
    tr.setAttribute('data-t10b-rider', top[i].name);
    tr.setAttribute('data-t10b-idx', String(i));
  });
}

// ── H2H tooltip en hover ──
let _t10B_tipEl = null;
function _t10B_hideTip(){ if(_t10B_tipEl){ _t10B_tipEl.remove(); _t10B_tipEl=null; } }
function _t10B_showH2HTip(tr, rider, top){
  _t10B_hideTip();
  const others = top.filter(r=>r.name !== rider.name);
  const ridersHist = _t10B_riderHistory(rider.name);
  // Para cada otro, buscar carreras en común (en el cache)
  const matches = [];
  for(const other of others){
    let foundPos = null, foundOtherPos = null, foundDate = '', foundName = '';
    for(const h of ridersHist){
      const race = _cachedHistory.find(rc => (rc.raceName||rc.name)===h.raceName && rc.raceDate===h.raceDate);
      if(!race) continue;
      const otherR = (race.riders||[]).find(x=>{
        const xk = (typeof normalizeForMatching==='function') ? normalizeForMatching(x.name||'') : (x.name||'').toLowerCase();
        const ok = (typeof normalizeForMatching==='function') ? normalizeForMatching(other.name||'') : (other.name||'').toLowerCase();
        return xk === ok;
      });
      if(otherR && otherR.pos){
        foundPos = h.pos;
        foundOtherPos = parseInt(otherR.pos)||0;
        foundDate = race.raceDate||'';
        foundName = race.raceName||race.name||'?';
        break; // la más reciente
      }
    }
    if(foundPos!=null){
      matches.push({ other: other.name, myPos: foundPos, otherPos: foundOtherPos, race: foundName, date: foundDate, win: foundPos < foundOtherPos });
    }
  }
  const tip = document.createElement('div');
  tip.className = 't10b-h2h-tip';
  let html = `<div class="t10b-h2h-title">${escapeHtml(rider.name)} · Histórico vs Top 10</div>`;
  if(!matches.length){
    html += `Sin coincidencias previas en el histórico cargado.`;
  } else {
    const wins = matches.filter(m=>m.win).length;
    html += `<div style="margin-bottom:3px;font-size:10px;opacity:.85">${wins} victorias en ${matches.length} duelos directos</div>`;
    html += matches.slice(0,5).map(m=>{
      const ic = m.win ? '✅' : '❌';
      return `${ic} <b>${m.myPos}º</b> vs ${m.otherPos}º — ${escapeHtml(m.other)} <span style="opacity:.6">(${escapeHtml(m.date||'')})</span>`;
    }).join('<br>');
  }
  tip.innerHTML = html;
  document.body.appendChild(tip);
  const rect = tr.getBoundingClientRect();
  let top_ = rect.top + window.scrollY + rect.height + 6;
  let left = rect.left + window.scrollX + 20;
  // ajustar si se sale
  const tipRect = tip.getBoundingClientRect();
  if(left + tipRect.width > window.innerWidth - 10) left = window.innerWidth - tipRect.width - 10;
  if(top_ + tipRect.height > window.scrollY + window.innerHeight - 10){
    top_ = rect.top + window.scrollY - tipRect.height - 6;
  }
  tip.style.top = top_+'px';
  tip.style.left = left+'px';
  _t10B_tipEl = tip;
}

function _t10B_attachH2HHover(top){
  const table = document.querySelector('#top10 .top10-table tbody');
  if(!table) return;
  const rows = table.querySelectorAll('tr');
  rows.forEach((tr, i)=>{
    if(tr._t10b_hooked) return;
    tr._t10b_hooked = true;
    tr.addEventListener('mouseenter', ()=>{
      const idx = parseInt(tr.getAttribute('data-t10b-idx'));
      if(top[idx]) _t10B_showH2HTip(tr, top[idx], top);
    });
    tr.addEventListener('mouseleave', _t10B_hideTip);
  });
  window.addEventListener('scroll', _t10B_hideTip, {passive:true});
}

// ── Sorpresa: corredor con media histórica >20 que está en el top 10 ──
function _t10B_findSorpresas(top){
  const out = [];
  for(const r of top){
    const hist = _t10B_riderHistory(r.name);
    if(hist.length < 3) continue;
    const avg = hist.reduce((s,h)=>s+h.pos,0)/hist.length;
    if(avg > 20 && r.pos <= 10){
      out.push({ name: r.name, pos: r.pos, avg });
    }
  }
  return out;
}

function _t10B_addSorpresaToCommentary(top){
  const commentEl = document.getElementById('top10Commentary');
  if(!commentEl) return;
  if(commentEl.querySelector('[data-t10b-sorpresa]')) return;
  const sorp = _t10B_findSorpresas(top);
  if(!sorp.length) return;
  const html = `<div data-t10b-sorpresa style="margin-top:8px;padding:6px 10px;background:#fef3c7;border-left:3px solid #f59e0b;border-radius:4px;font-size:12px">
    💎 <b>Sorpresa${sorp.length>1?'s':''} del día:</b> ${sorp.map(s=>`<b>${escapeHtml(s.name)}</b> (${s.pos}º; media histórica ${s.avg.toFixed(1)}º)`).join(', ')}.
  </div>`;
  commentEl.insertAdjacentHTML('beforeend', html);
}

// ── Botones de acción ──
function _t10B_injectActionButtons(top, base){
  const sect = document.querySelector('#view-top10 .top10-panel .section-title');
  if(!sect) return;
  if(sect.querySelector('#t10B_actionsRow')) {
    // ya existe — solo actualizar visibilidad del toggle
    const tBtn = sect.querySelector('#t10B_toggle20');
    if(tBtn) tBtn.textContent = _t10B_expandedTo20 ? '▲ Solo Top 10' : '▼ Mostrar Top 20';
    return;
  }
  const row = document.createElement('div');
  row.id = 't10B_actionsRow';
  row.className = 't10b-actions';
  row.style.width = '100%';
  row.innerHTML = `
    <button class="btn light" onclick="_t10B_goCompare()" title="Lleva los primeros 6 al menú Comparativo">📊 Comparar (6)</button>
    <button class="btn light" onclick="_t10B_goSimulator()" title="Abre el Simulador con los del Top 10 como rivales clave">🎲 Simular próxima</button>
    <button class="btn light" id="t10B_toggle20" onclick="_t10B_toggle20()">${_t10B_expandedTo20?'▲ Solo Top 10':'▼ Mostrar Top 20'}</button>
  `;
  sect.appendChild(row);
}

function _t10B_toggle20(){
  _t10B_expandedTo20 = !_t10B_expandedTo20;
  // Mostrar/ocultar filas extra
  const base = (typeof getTeamRankingFilteredRiders==='function') ? getTeamRankingFilteredRiders() : [];
  const sorted = base.slice().sort((a,b)=>a.pos-b.pos);
  const tbody = document.querySelector('#top10 .top10-table tbody');
  if(!tbody) return;
  // Quitar filas extra previas
  tbody.querySelectorAll('tr.t10b-extra').forEach(tr=>tr.remove());
  const btn = document.getElementById('t10B_toggle20');
  if(_t10B_expandedTo20){
    const extra = sorted.slice(10,20);
    if(!extra.length){
      if(btn) btn.textContent = '▼ No hay más corredores';
      _t10B_expandedTo20 = false;
      return;
    }
    extra.forEach((r,i)=>{
      let timeDisplay;
      if(r.totalSeconds && typeof formatSeconds==='function'){
        timeDisplay = formatSeconds(r.totalSeconds);
        if(r.gapSeconds) timeDisplay += `<span style="font-size:11px;color:#667085;display:block">+${formatSeconds(r.gapSeconds)}</span>`;
      } else if(r.gapSeconds!=null && typeof formatSeconds==='function'){
        timeDisplay = '+'+formatSeconds(r.gapSeconds);
      } else {
        timeDisplay = escapeHtml(r.time||'—');
      }
      const tr = document.createElement('tr');
      tr.className = 't10b-extra';
      tr.style.background = '#fafbfc';
      tr.style.opacity = '0.85';
      tr.innerHTML = `<td><b>${r.pos}</b></td>
        <td class="t-name">${escapeHtml(r.name)}</td>
        <td class="t-time">${timeDisplay}</td>
        <td><span class="pill"><span class="cat-dot" style="background:${typeof getColorForCategory==='function'?getColorForCategory(r.cat):'#999'}"></span>${escapeHtml(r.cat||'')}</span></td>
        <td>${escapeHtml(r.region||'—')}</td>
        <td class="t-team">${escapeHtml(r.team||'')}</td>
        <td><button onclick="analyzeRiderByKey('${escapeAttr(getRiderKey(r))}');showView('view-analisis')" style="background:none;border:none;cursor:pointer;font-size:15px;opacity:.55" title="Análisis individual">👤</button></td>`;
      tbody.appendChild(tr);
    });
    if(btn) btn.textContent = '▲ Solo Top 10';
  } else {
    if(btn) btn.textContent = '▼ Mostrar Top 20';
  }
}

function _t10B_goCompare(){
  try{
    const base = (typeof getTeamRankingFilteredRiders==='function') ? getTeamRankingFilteredRiders() : [];
    const top6 = base.slice().sort((a,b)=>a.pos-b.pos).slice(0,6);
    if(top6.length<2){ alert('No hay suficientes corredores en el Top para comparar.'); return; }
    selectedCompare = top6.slice(0,3); // por si Comparativa simple lee este array
    if(typeof comparativoRiders !== 'undefined' && Array.isArray(comparativoRiders)){
      for(let i=0;i<comparativoRiders.length;i++) comparativoRiders[i] = top6[i] || null;
    }
    window._suppressAutoFill = true;
    if(typeof showView==='function') showView('view-comparativo');
    setTimeout(()=>{
      if(typeof renderComparativo==='function') renderComparativo();
      window._suppressAutoFill = false;
    }, 100);
  }catch(e){ console.warn('_t10B_goCompare', e); }
}

function _t10B_goSimulator(){
  try{
    const base = (typeof getTeamRankingFilteredRiders==='function') ? getTeamRankingFilteredRiders() : [];
    const top10 = base.slice().sort((a,b)=>a.pos-b.pos).slice(0,10);
    sessionStorage.setItem('_t10B_simKey', JSON.stringify({ names: top10.map(r=>r.name), ts: Date.now() }));
    if(typeof showView==='function'){
      showView('view-simulador');
      setTimeout(()=>{
        try{
          const banner = document.createElement('div');
          banner.id = 't10B_simBanner';
          banner.style.cssText = 'position:fixed;top:16px;left:50%;transform:translateX(-50%);background:#fef3c7;border:2px solid #f59e0b;border-radius:10px;padding:10px 16px;font-size:13px;font-weight:700;color:#92400e;z-index:9999;box-shadow:0 6px 20px rgba(0,0,0,0.15);max-width:90vw';
          banner.innerHTML = `🎲 Rivales clave a vigilar (del Top 10 actual): <b>${top10.slice(0,5).map(r=>escapeHtml(r.name)).join(', ')}${top10.length>5?'…':''}</b> &nbsp; <button onclick="this.parentNode.remove()" style="background:none;border:0;cursor:pointer;font-size:14px">✕</button>`;
          const old = document.getElementById('t10B_simBanner'); if(old) old.remove();
          document.body.appendChild(banner);
          setTimeout(()=>{ const b=document.getElementById('t10B_simBanner'); if(b) b.remove(); }, 14000);
        }catch(e){}
      }, 250);
    }
  }catch(e){ console.warn('_t10B_goSimulator', e); }
}

function _t10B_postRender(top, base){
  _t10B_styleInject();
  _t10B_injectActionButtons(top, base);
  _t10B_addBadgesToTable(top);
  _t10B_attachH2HHover(top);
  _t10B_addSorpresaToCommentary(top);
  // Restaurar estado del toggle
  if(_t10B_expandedTo20){
    _t10B_expandedTo20 = false;
    _t10B_toggle20();
  }
}

// ════════════════════════════════════════════════════════════════════════
// SIMULADOR — Predicho vs Real
//   Modal que compara el Top 10 predicho por el simulador con el Top 10
//   real de la prueba ya disputada. Incluye:
//     - Tabla lado a lado con resaltado de aciertos
//     - Estadísticas: aciertos en presencia, aciertos exactos, error medio
//     - Botón Imprimir/PDF (window.print con CSS de impresión inyectado)
// ════════════════════════════════════════════════════════════════════════

function _simOpenPredVsReal(){
  try{
    if(!_simCurrentData){ alert('Selecciona una prueba primero.'); return; }
    const { race, grid } = _simCurrentData;
    const actualRiders = (race.riders||[]).slice().filter(r=>r.pos).sort((a,b)=>(parseInt(a.pos)||999)-(parseInt(b.pos)||999));
    if(actualRiders.length < 3){
      alert('Esta prueba aún no tiene clasificación final cargada.');
      return;
    }
    // Predicho: MISMA fuente que el panel "Top 10 esperado" para que coincidan
    // exactamente (incluye corredores de respaldo y respeta el filtro de cat).
    const predRanked = _simPredictedPool(grid, _simActiveCatFilter());
    const top10Pred = predRanked.slice(0, 10);
    const top10Real = actualRiders.slice(0, 10);

    const nkey = (s) => (typeof normalizeForMatching==='function')
      ? normalizeForMatching(s||'')
      : (s||'').toLowerCase().trim();
    const realByName = new Map();
    actualRiders.forEach(r => realByName.set(nkey(r.name), { pos: parseInt(r.pos)||0, team: r.team||'', cat: r.cat||'' }));
    const predByName = new Map();
    predRanked.forEach((g, i) => predByName.set(nkey(g.name), { predPos: i+1, team: g.team||'', isMyTeam: !!g.isMyTeam }));

    // Estadísticas
    let hitsPresence = 0;          // del predicho top 10, cuántos están en el real top 10
    let hitsExact = 0;             // misma posición exacta
    let positionErrors = [];       // diferencia absoluta para los que están en ambos
    top10Pred.forEach((g, i) => {
      const real = realByName.get(nkey(g.name));
      if(real){
        if(real.pos <= 10) hitsPresence++;
        if(real.pos === (i+1)) hitsExact++;
        positionErrors.push(Math.abs(real.pos - (i+1)));
      }
    });
    const avgErr = positionErrors.length ? (positionErrors.reduce((s,v)=>s+v,0)/positionErrors.length) : null;

    // Construir filas pareadas
    const rowsHtml = [];
    for(let i=0;i<10;i++){
      const p = top10Pred[i];
      const r = top10Real[i];
      let pName='—', pTeam='—', pCat='', pHit='', pExtra='', pMyTeam='', pUncertainty='';
      if(p){
        pName = p.name; pTeam = p.team||''; pCat = p.cat||'';
        const realOfP = realByName.get(nkey(p.name));
        if(realOfP){
          if(realOfP.pos === (i+1)){ pHit='exact'; pExtra=`<span class="pvr-tag pvr-tag-ok">✅ Exacto · ${realOfP.pos}º real</span>`; }
          else if(realOfP.pos <= 10){ pHit='top10';  pExtra=`<span class="pvr-tag pvr-tag-near">🎯 Entró ${realOfP.pos}º (Δ ${Math.abs(realOfP.pos-(i+1))})</span>`; }
          else { pHit='out'; pExtra=`<span class="pvr-tag pvr-tag-miss">⚠️ Acabó ${realOfP.pos}º</span>`; }
        } else {
          pHit='nf'; pExtra=`<span class="pvr-tag pvr-tag-bad">❌ No clasificó / DNF</span>`;
        }
        if(p.isMyTeam) pMyTeam=' <span style="color:#1f6feb;font-weight:800">★</span>';
        if(p.predLower!=null && p.predUpper!=null && p.predLower!==p.predUpper){
          pUncertainty = `<span class="pvr-rng">(${p.predLower}–${p.predUpper})</span>`;
        }
      }
      let rName='—', rTeam='—', rCat='', rHit='', rExtra='';
      if(r){
        rName = r.name; rTeam = r.team||''; rCat = r.cat||'';
        const predOfR = predByName.get(nkey(r.name));
        if(predOfR){
          if(predOfR.predPos === (i+1)){ rHit='exact'; rExtra=`<span class="pvr-tag pvr-tag-ok">✅ Predicho ${predOfR.predPos}º</span>`; }
          else if(predOfR.predPos <= 10){ rHit='top10'; rExtra=`<span class="pvr-tag pvr-tag-near">🎯 Predicho ${predOfR.predPos}º (Δ ${Math.abs(predOfR.predPos-(i+1))})</span>`; }
          else { rHit='out'; rExtra=`<span class="pvr-tag pvr-tag-miss">😮 Sorpresa · predicho ${predOfR.predPos}º</span>`; }
        } else {
          rHit='nf'; rExtra=`<span class="pvr-tag pvr-tag-bad">💎 Sin predicción (debutante / sin histórico)</span>`;
        }
      }
      const bgL = pHit==='exact' ? '#dcfce7' : (pHit==='top10' ? '#fef9c3' : (pHit==='out'||pHit==='nf' ? '#fee2e2' : '#f9fafb'));
      const bgR = rHit==='exact' ? '#dcfce7' : (rHit==='top10' ? '#fef9c3' : (rHit==='out'||rHit==='nf' ? '#fee2e2' : '#f9fafb'));
      rowsHtml.push(`
        <tr>
          <td class="pvr-pos">${i+1}</td>
          <td style="background:${bgL}">
            <div class="pvr-name">${escapeHtml(pName)}${pMyTeam} ${pUncertainty}</div>
            <div class="pvr-meta">${escapeHtml(pTeam)}${pCat?' · '+escapeHtml(pCat):''}</div>
            <div class="pvr-extra">${pExtra}</div>
          </td>
          <td class="pvr-pos">${i+1}</td>
          <td style="background:${bgR}">
            <div class="pvr-name">${escapeHtml(rName)}</div>
            <div class="pvr-meta">${escapeHtml(rTeam)}${rCat?' · '+escapeHtml(rCat):''}</div>
            <div class="pvr-extra">${rExtra}</div>
          </td>
        </tr>`);
    }

    // KPIs cabecera
    const pct = (n) => Math.round((n/10)*100);
    const accColor = (n) => n>=7?'#16a34a':n>=4?'#f59e0b':'#dc2626';
    const summaryHtml = `
      <div class="pvr-kpis">
        <div class="pvr-kpi"><div class="pvr-kpi-v" style="color:${accColor(hitsPresence)}">${hitsPresence}/10</div><div class="pvr-kpi-l">Aciertos en Top&nbsp;10<br><span class="small">(${pct(hitsPresence)}%)</span></div></div>
        <div class="pvr-kpi"><div class="pvr-kpi-v" style="color:${accColor(hitsExact*2)}">${hitsExact}/10</div><div class="pvr-kpi-l">Aciertos exactos<br><span class="small">(${pct(hitsExact)}%)</span></div></div>
        <div class="pvr-kpi"><div class="pvr-kpi-v" style="color:${avgErr==null?'#9ca3af':(avgErr<=2?'#16a34a':avgErr<=5?'#f59e0b':'#dc2626')}">${avgErr==null?'—':avgErr.toFixed(1)}</div><div class="pvr-kpi-l">Error medio<br><span class="small">posiciones</span></div></div>
        <div class="pvr-kpi"><div class="pvr-kpi-v" style="color:#0b2f6b">${top10Real.length}</div><div class="pvr-kpi-l">Reales en cabeza<br><span class="small">cargados</span></div></div>
      </div>`;

    // ── FASE 5.5: Validación del factor de terreno ──────────────────────
    // Para cada corredor con terrainFactor != 1.00, comparamos:
    //   - Pos. predicha SIN factor (predictedPosBaseTerrain)
    //   - Pos. predicha CON factor (predictedPos)
    //   - Pos. real (de race.riders)
    // y vemos si el factor ayudó a aproximar la realidad o no.
    const terrainLabels2 = { llana:'🟢 Llana', rompepiernas:'🟡 Rompepiernas', media_montana:'🟠 Media montaña', montanosa:'🔴 Montañosa', desconocido:'⚪ Sin datos' };
    let terrainCalibHtml = '';
    const terrainAdjusted = grid.filter(g => g.terrainFactor && g.terrainFactor !== 1 && g.predictedPos != null && g.predictedPosBaseTerrain != null);
    const tInfo = _simCurrentData && _simCurrentData.terrain;
    if(terrainAdjusted.length && tInfo){
      const realByName = new Map();
      actualRiders.forEach(r => realByName.set(nkey(r.name), parseInt(r.pos)||0));
      // Por cada corredor afectado, calcular errores con/sin factor
      const rows = [];
      let improved = 0, worsened = 0, same = 0;
      let sumErrWith = 0, sumErrWithout = 0, cnt = 0;
      terrainAdjusted.forEach(g => {
        const real = realByName.get(nkey(g.name));
        if(!real) return;
        const errWith    = Math.abs(g.predictedPos - real);
        const errWithout = Math.abs(g.predictedPosBaseTerrain - real);
        sumErrWith += errWith; sumErrWithout += errWithout; cnt++;
        let verdict, vColor, vIcon;
        if(errWith < errWithout - 0.5){ verdict='Mejoró'; vColor='#15803d'; vIcon='✓'; improved++; }
        else if(errWith > errWithout + 0.5){ verdict='Empeoró'; vColor='#b91c1c'; vIcon='✗'; worsened++; }
        else { verdict='Sin cambio relevante'; vColor='#6b7280'; vIcon='='; same++; }
        rows.push(`<tr>
          <td style="padding:4px 8px;font-weight:700;color:#0b2f6b">${escapeHtml(g.name)}</td>
          <td style="padding:4px 8px;text-align:center;color:#374151">${g.predictedPosBaseTerrain}º</td>
          <td style="padding:4px 8px;text-align:center;color:#7c3aed;font-weight:700">${Math.round(g.predictedPos)}º</td>
          <td style="padding:4px 8px;text-align:center;color:#0b2f6b;font-weight:800">${real}º</td>
          <td style="padding:4px 8px;text-align:center;color:#6b7280">${errWithout.toFixed(1)}</td>
          <td style="padding:4px 8px;text-align:center;color:#7c3aed">${errWith.toFixed(1)}</td>
          <td style="padding:4px 8px;text-align:center;color:${vColor};font-weight:800">${vIcon} ${verdict}</td>
        </tr>`);
      });
      if(rows.length){
        const maeWith    = sumErrWith / cnt;
        const maeWithout = sumErrWithout / cnt;
        const delta      = maeWithout - maeWith;
        const verdictGlobal = delta > 0.3
          ? { txt:'El factor de terreno MEJORÓ la predicción media', color:'#15803d', icon:'✅' }
          : delta < -0.3
          ? { txt:'El factor de terreno EMPEORÓ la predicción media', color:'#b91c1c', icon:'❌' }
          : { txt:'El factor de terreno tuvo un efecto neutro', color:'#6b7280', icon:'➖' };
        terrainCalibHtml = `
          <div class="no-print" style="padding:14px 20px;border-top:1px solid #e5e7eb;background:#f8fafc">
            <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:8px">
              <div style="font-weight:800;color:#0b2f6b;font-size:14px">🗺️ Validación del factor de terreno · ${terrainLabels2[tInfo.terrain_type]||tInfo.terrain_type}</div>
              <span style="background:${verdictGlobal.color}20;color:${verdictGlobal.color};font-size:11px;font-weight:800;padding:2px 9px;border-radius:6px">${verdictGlobal.icon} ${verdictGlobal.txt}</span>
            </div>
            <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;margin-bottom:10px">
              <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:8px;text-align:center"><div style="font-size:18px;font-weight:900;color:#0b2f6b">${cnt}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">Corredores afectados</div></div>
              <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:8px;text-align:center"><div style="font-size:18px;font-weight:900;color:#15803d">${improved}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">Mejoraron</div></div>
              <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:8px;text-align:center"><div style="font-size:18px;font-weight:900;color:#b91c1c">${worsened}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">Empeoraron</div></div>
              <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:8px;text-align:center"><div style="font-size:18px;font-weight:900;color:#6b7280">${same}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">Sin cambio</div></div>
              <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:8px;text-align:center"><div style="font-size:18px;font-weight:900;color:#374151">${maeWithout.toFixed(1)}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">Error medio sin factor</div></div>
              <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:8px;text-align:center"><div style="font-size:18px;font-weight:900;color:#7c3aed">${maeWith.toFixed(1)}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">Error medio con factor</div></div>
              <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:8px;text-align:center"><div style="font-size:18px;font-weight:900;color:${delta>0?'#15803d':delta<0?'#b91c1c':'#6b7280'}">${delta>=0?'−':'+'}${Math.abs(delta).toFixed(1)}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">Δ Error medio</div></div>
            </div>
            <details style="margin-top:6px">
              <summary style="cursor:pointer;font-weight:700;color:#374151;font-size:12px">Ver detalle por corredor (${cnt})</summary>
              <table style="width:100%;border-collapse:collapse;font-size:12px;margin-top:8px;background:#fff">
                <thead><tr style="background:#f3f4f6">
                  <th style="padding:5px 8px;text-align:left;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Corredor</th>
                  <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Sin factor</th>
                  <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Con factor</th>
                  <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Real</th>
                  <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Err. sin</th>
                  <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Err. con</th>
                  <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Veredicto</th>
                </tr></thead>
                <tbody>${rows.join('')}</tbody>
              </table>
            </details>
            <div style="font-size:10.5px;color:#6b7280;margin-top:6px;line-height:1.5">
              <b>Cómo leer esto:</b> "Sin factor" = predicción que habría salido sin tener en cuenta el terreno · "Con factor" = la que sale ahora · "Real" = la posición que ocurrió en la carrera · Δ&nbsp;Error medio positivo (verde) significa que el factor afina la predicción.<br>
              Si tras 5-6 pruebas con terreno conocido el Δ es sistemáticamente negativo, podemos ajustar los umbrales del factor.
            </div>
          </div>`;
      }
    }

    const meta = `
      <div class="pvr-race-meta">
        <b>${escapeHtml(race.raceName||'')}</b>
        ${race.raceDate?` · 📅 ${escapeHtml(race.raceDate)}`:''}
        ${race.localidad?` · 📍 ${escapeHtml(race.localidad)}`:''}
        ${race.circuitType?` · 🛣️ ${escapeHtml(race.circuitType)}`:''}
      </div>`;

    // Inyectar overlay si no existe
    let overlay = document.getElementById('pvrModalOverlay');
    if(!overlay){
      overlay = document.createElement('div');
      overlay.id = 'pvrModalOverlay';
      overlay.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.6);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px';
      overlay.addEventListener('click', (e)=>{ if(e.target===overlay) _simClosePredVsReal(); });
      document.body.appendChild(overlay);
    }
    const _pdfLogoSrc = document.querySelector('.brand-logo')?.src || '';
    overlay.innerHTML = `
      <div id="pvrModalBox" style="background:#fff;border-radius:14px;max-width:1100px;width:100%;max-height:92vh;overflow:auto;box-shadow:0 20px 60px rgba(0,0,0,.4)">
        <div class="pvr-header">
          <div style="display:flex;align-items:center;gap:14px;flex:1;min-width:0">
            ${_pdfLogoSrc ? `<img src="${_pdfLogoSrc}" alt="MFPP Cycling Specialist" class="pvr-logo">` : ''}
            <div style="min-width:0">
              <h2 style="margin:0;font-size:20px;color:#0b2f6b">🎯 Predicho vs Real</h2>
              ${meta}
            </div>
          </div>
          <div class="pvr-actions no-print">
            <button class="btn" onclick="_simPrintPredVsReal()" style="background:#dc2626;color:#fff;font-weight:800">🖨️ Imprimir / PDF</button>
            <button class="btn light" onclick="_simClosePredVsReal()">✕ Cerrar</button>
          </div>
        </div>
        ${summaryHtml}
        ${terrainCalibHtml}
        <div style="padding:0 20px 4px;font-size:11px;color:#6b7280">
          ★ = ciclista de mi equipo · 🟩 verde = posición exacta · 🟨 amarillo = entró en Top 10 (otra pos.) · 🟥 rojo = fuera del Top 10 o sin predicción
        </div>
        <div class="pvr-table-wrap">
          <table class="pvr-table">
            <thead>
              <tr>
                <th colspan="2" style="background:#1f6feb;color:#fff">🔮 Top 10 Predicho (Simulador)</th>
                <th colspan="2" style="background:#16a34a;color:#fff">🏁 Top 10 Real (Clasificación)</th>
              </tr>
              <tr>
                <th style="width:38px">#</th><th>Ciclista · Equipo</th>
                <th style="width:38px">#</th><th>Ciclista · Equipo</th>
              </tr>
            </thead>
            <tbody>${rowsHtml.join('')}</tbody>
          </table>
        </div>
        <div class="pvr-footer">
          <div style="font-size:11px;color:#6b7280;text-align:center">
            Informe generado por <b>Dashboard Director · MFPP Cycling Specialist</b> · ${new Date().toLocaleString('es-ES')}
          </div>
        </div>
      </div>`;

    _simInjectPVRStyles();
    document.body.style.overflow = 'hidden';
  }catch(e){
    console.warn('_simOpenPredVsReal', e);
    alert('Error al abrir el comparador: '+(e.message||e));
  }
}

function _simClosePredVsReal(){
  const overlay = document.getElementById('pvrModalOverlay');
  if(overlay) overlay.remove();
  document.body.style.overflow = '';
}

function _simPrintPredVsReal(){
  // window.print con CSS de impresión que oculta todo excepto el modal
  window.print();
}

// ═════════════════════════════════════════════════════════════════════════
// FASE 6 — CALIBRACIÓN GLOBAL DEL FACTOR DE TERRENO
// ─────────────────────────────────────────────────────────────────────────
// Recorre TODO el histórico de carreras con terrain_type conocido y resul-
// tados reales. Para cada corredor afectado por el factor de terreno
// (terrainFactor != 1.00) compara error con/sin factor.
// Agrega por tipo de terreno y por bucket de factor (0.93, 0.97, 1.03,
// 1.08) y sugiere ajustes si el factor está sistemáticamente desviado.
// ═════════════════════════════════════════════════════════════════════════

function _simComputeTerrainCalibration(){
  const hist = (typeof _cachedHistory !== 'undefined' && Array.isArray(_cachedHistory)) ? _cachedHistory : [];
  if(!hist.length) return { byTerrain:{}, totalRaces:0, totalRiders:0, racesProcessed:[] };

  // Guardamos estado actual del simulador para restaurarlo al final
  const prevRaceId = _simSelectedRaceId;
  const prevData   = _simCurrentData;

  const candidates = hist.filter(h => {
    const tt = h.route && h.route.terrain_type;
    if(!tt || tt === 'desconocido') return false;
    if(!Array.isArray(h.riders) || !h.riders.some(r => r.pos > 0)) return false;
    if(!Array.isArray(h.inscritos) || h.inscritos.length < 5) return false;
    return true;
  });

  const byTerrain = {};
  const racesProcessed = [];
  let totalRaces = 0, totalRiders = 0;

  candidates.forEach(race => {
    try {
      _simBuildData(race.id);
      if(!_simCurrentData || !Array.isArray(_simCurrentData.grid)) return;
      const { grid } = _simCurrentData;
      const tt = (race.route && race.route.terrain_type) || 'desconocido';

      const realByName = new Map();
      (race.riders||[]).forEach(r => {
        const nk = normalizeForMatching(r.name||'');
        if(nk && r.pos > 0) realByName.set(nk, parseInt(r.pos)||0);
      });

      let raceAffected = 0, raceErrWith = 0, raceErrWithout = 0;

      grid.forEach(g => {
        if(!g.terrainFactor || g.terrainFactor === 1) return;
        if(g.predictedPos == null || g.predictedPosBaseTerrain == null) return;
        const real = realByName.get(normalizeForMatching(g.name||''));
        if(!real) return;
        const errWith    = Math.abs(g.predictedPos - real);
        const errWithout = Math.abs(g.predictedPosBaseTerrain - real);

        if(!byTerrain[tt]) byTerrain[tt] = {
          terrain: tt, races: 0, riders: 0,
          sumErrWith: 0, sumErrWithout: 0,
          improved: 0, worsened: 0, same: 0,
          byBucket: {}
        };
        const T = byTerrain[tt];
        T.riders++;
        T.sumErrWith    += errWith;
        T.sumErrWithout += errWithout;
        if(errWith < errWithout - 0.5)      T.improved++;
        else if(errWith > errWithout + 0.5) T.worsened++;
        else                                 T.same++;

        // Agrupamos por bucket CONCEPTUAL (strong_low / mild_low / mild_high /
        // strong_high), no por el valor numérico, para que el autoajuste pueda
        // iterar coherentemente aunque los factores ya estén calibrados.
        const bKey = g.terrainBucket || _bucketKeyFromFactor(g.terrainFactor);
        if(!T.byBucket[bKey]) T.byBucket[bKey] = {
          bucketKey: bKey,
          factor: g.terrainFactor,   // factor APLICADO actualmente (puede no ser el default)
          defaultFactor: _TERRAIN_FACTOR_DEFAULTS[bKey],
          riders: 0,
          sumErrWith: 0, sumErrWithout: 0,
          sumRealOverBase: 0
        };
        const B = T.byBucket[bKey];
        B.riders++;
        B.sumErrWith    += errWith;
        B.sumErrWithout += errWithout;
        // ratio real/base: indica qué multiplicador "ideal" habría dejado la
        // predicción base sobre la real. Si la media de ratios ≠ factor
        // actual → señal de calibración.
        if(g.predictedPosBaseTerrain > 0){
          B.sumRealOverBase += (real / g.predictedPosBaseTerrain);
        }

        raceAffected++;
        raceErrWith    += errWith;
        raceErrWithout += errWithout;
      });

      if(raceAffected){
        byTerrain[tt].races++;
        totalRaces++;
        totalRiders += raceAffected;
        racesProcessed.push({
          id: race.id,
          name: race.raceName || race.name || '(sin nombre)',
          date: race.raceDate || '',
          terrain: tt,
          ridersAffected: raceAffected,
          maeWith:    raceErrWith / raceAffected,
          maeWithout: raceErrWithout / raceAffected
        });
      }
    } catch(e){
      console.warn('[fase6] error procesando', race.raceName, e);
    }
  });

  // Restaurar estado anterior del simulador
  try {
    if(prevRaceId){
      _simBuildData(prevRaceId);
    } else {
      _simCurrentData = prevData;
    }
  } catch(e){
    _simCurrentData = prevData;
  }

  return { byTerrain, totalRaces, totalRiders, racesProcessed };
}

// ─── Aplica los factores sugeridos a la tabla persistente y devuelve el
//     log de cambios para mostrar al usuario.
function _simApplyTerrainAutoCalibration(){
  const res = _simComputeTerrainCalibration();
  const current = _loadTerrainFactorsTable();
  const updated = JSON.parse(JSON.stringify(current||{}));
  const changes = [];
  Object.keys(res.byTerrain).forEach(tt => {
    const T = res.byTerrain[tt];
    if(!updated[tt]) updated[tt] = {};
    Object.values(T.byBucket).forEach(B => {
      const sug = _simSuggestTerrainFactor(B);
      if(!sug) return; // muestra insuficiente
      const bKey = B.bucketKey;
      if(!bKey) return;
      const prev = (updated[tt][bKey] != null) ? updated[tt][bKey] : _TERRAIN_FACTOR_DEFAULTS[bKey];
      const next = sug.suggested;
      if(Math.abs(next - prev) < 0.005) return; // sin cambio relevante
      updated[tt][bKey] = next;
      changes.push({ terrain: tt, bucket: bKey, from: prev, to: next, n: B.riders });
    });
  });
  _saveTerrainFactorsTable(updated);
  return { changes, totalRaces: res.totalRaces, totalRiders: res.totalRiders };
}

// Devuelve un factor SUGERIDO para un bucket, mezclando 50/50 el observado
// con el actual para no sobreajustar con muestras pequeñas.
function _simSuggestTerrainFactor(bucket){
  if(!bucket || bucket.riders < 5) return null; // muestra insuficiente
  const observed = bucket.sumRealOverBase / bucket.riders;
  // Clamp para evitar sugerencias absurdas con outliers
  const obsClamped = Math.max(0.80, Math.min(1.25, observed));
  const suggested  = +(0.5 * bucket.factor + 0.5 * obsClamped).toFixed(3);
  const delta      = suggested - bucket.factor;
  let verdict;
  if(Math.abs(delta) < 0.015) verdict = { txt: 'OK, mantener', color: '#15803d', icon: '✓' };
  else if(delta > 0)          verdict = { txt: `Subir a ${suggested.toFixed(2)}`, color: '#b91c1c', icon: '↑' };
  else                        verdict = { txt: `Bajar a ${suggested.toFixed(2)}`, color: '#2563eb', icon: '↓' };
  return { observed, suggested, delta, verdict };
}

function _simOpenTerrainCalibration(){
  try{
    _simInjectPVRStyles();
    // Cerrar overlay anterior si existe
    const old = document.getElementById('tcalOverlay');
    if(old) old.remove();

    const res = _simComputeTerrainCalibration();
    if(!res.totalRaces){
      alert('Aún no hay suficientes carreras con terreno conocido + resultados reales para calibrar.\n\nNecesitas al menos 1 carrera con GPX/FIT subido y clasificación cargada en la que el factor de terreno haya modificado alguna predicción.');
      return;
    }

    const labels = { llana:'🟢 Llana', rompepiernas:'🟡 Rompepiernas', media_montana:'🟠 Media montaña', montanosa:'🔴 Montañosa' };
    const ttKeys = Object.keys(res.byTerrain).sort();

    // Resumen agregado por terreno
    const terrainRows = ttKeys.map(tt => {
      const T = res.byTerrain[tt];
      const mW  = T.sumErrWith    / T.riders;
      const mWo = T.sumErrWithout / T.riders;
      const delta = mWo - mW; // positivo = el factor ayuda
      const dCol = delta > 0.3 ? '#15803d' : delta < -0.3 ? '#b91c1c' : '#6b7280';
      const dTxt = (delta >= 0 ? '−' : '+') + Math.abs(delta).toFixed(2);

      // Filas por bucket (strong_low, mild_low, mild_high, strong_high)
      const bucketLabels = { strong_low:'Especialista', mild_low:'Cómodo', mild_high:'No es lo suyo', strong_high:'Sufre' };
      const bucketRows = Object.values(T.byBucket)
        .sort((a,b)=>a.factor-b.factor)
        .map(B => {
          const sug = _simSuggestTerrainFactor(B);
          const appliedTxt = (B.factor !== B.defaultFactor)
            ? `<span style="font-weight:800;color:#0d9488">${B.factor.toFixed(2)}</span><span style="font-size:10px;color:#6b7280">&nbsp;(def ${B.defaultFactor.toFixed(2)})</span>`
            : `<span style="font-weight:800;color:#0b2f6b">${B.factor.toFixed(2)}</span>`;
          if(!sug){
            return `<tr>
              <td style="padding:4px 8px;text-align:center">${appliedTxt}</td>
              <td style="padding:4px 8px;text-align:center;color:#374151;font-size:11px">${bucketLabels[B.bucketKey]||B.bucketKey}</td>
              <td style="padding:4px 8px;text-align:center;color:#374151">${B.riders}</td>
              <td style="padding:4px 8px;text-align:center;color:#6b7280" colspan="3">— muestra insuficiente (mín. 5) —</td>
            </tr>`;
          }
          return `<tr>
            <td style="padding:4px 8px;text-align:center">${appliedTxt}</td>
            <td style="padding:4px 8px;text-align:center;color:#374151;font-size:11px">${bucketLabels[B.bucketKey]||B.bucketKey}</td>
            <td style="padding:4px 8px;text-align:center;color:#374151">${B.riders}</td>
            <td style="padding:4px 8px;text-align:center;color:#7c3aed;font-weight:700">${sug.observed.toFixed(3)}</td>
            <td style="padding:4px 8px;text-align:center;color:#0b2f6b;font-weight:800">${sug.suggested.toFixed(2)}</td>
            <td style="padding:4px 8px;text-align:center;color:${sug.verdict.color};font-weight:800">${sug.verdict.icon} ${sug.verdict.txt}</td>
          </tr>`;
        }).join('');

      return `
        <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:12px;margin-bottom:10px">
          <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:8px">
            <div style="font-weight:800;color:#0b2f6b;font-size:15px">${labels[tt]||tt}</div>
            <span style="background:#f3f4f6;color:#374151;font-size:11px;font-weight:700;padding:2px 9px;border-radius:6px">${T.races} carreras · ${T.riders} corredores</span>
            <span style="background:${dCol}20;color:${dCol};font-size:11px;font-weight:800;padding:2px 9px;border-radius:6px">Δ MAE = ${dTxt}</span>
            <span style="background:#15803d20;color:#15803d;font-size:11px;font-weight:700;padding:2px 8px;border-radius:6px">✓ ${T.improved}</span>
            <span style="background:#b91c1c20;color:#b91c1c;font-size:11px;font-weight:700;padding:2px 8px;border-radius:6px">✗ ${T.worsened}</span>
            <span style="background:#6b728020;color:#6b7280;font-size:11px;font-weight:700;padding:2px 8px;border-radius:6px">= ${T.same}</span>
          </div>
          <table style="width:100%;border-collapse:collapse;font-size:12px;background:#fafbfc;border-radius:6px;overflow:hidden">
            <thead><tr style="background:#f3f4f6">
              <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Factor aplicado</th>
              <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Bucket</th>
              <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">N</th>
              <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Ratio real/base obs.</th>
              <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Sugerido (50/50)</th>
              <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Veredicto</th>
            </tr></thead>
            <tbody>${bucketRows || '<tr><td colspan="6" style="padding:6px;text-align:center;color:#6b7280">—</td></tr>'}</tbody>
          </table>
        </div>`;
    }).join('');

    // Lista de carreras procesadas (colapsable)
    const raceRows = res.racesProcessed
      .slice()
      .sort((a,b)=>(b.maeWithout - b.maeWith) - (a.maeWithout - a.maeWith))
      .map(r => {
        const delta = r.maeWithout - r.maeWith;
        const dCol = delta > 0.3 ? '#15803d' : delta < -0.3 ? '#b91c1c' : '#6b7280';
        const dTxt = (delta >= 0 ? '−' : '+') + Math.abs(delta).toFixed(2);
        return `<tr>
          <td style="padding:4px 8px;color:#0b2f6b;font-weight:700">${escapeHtml(r.name)}</td>
          <td style="padding:4px 8px;text-align:center;color:#6b7280;font-size:11px">${escapeHtml(r.date||'')}</td>
          <td style="padding:4px 8px;text-align:center;color:#374151">${labels[r.terrain]||r.terrain}</td>
          <td style="padding:4px 8px;text-align:center;color:#374151">${r.ridersAffected}</td>
          <td style="padding:4px 8px;text-align:center;color:#374151">${r.maeWithout.toFixed(2)}</td>
          <td style="padding:4px 8px;text-align:center;color:#7c3aed">${r.maeWith.toFixed(2)}</td>
          <td style="padding:4px 8px;text-align:center;color:${dCol};font-weight:800">${dTxt}</td>
        </tr>`;
      }).join('');

    // KPI agregado global
    let globalMaeWith = 0, globalMaeWithout = 0;
    ttKeys.forEach(tt => {
      globalMaeWith    += res.byTerrain[tt].sumErrWith;
      globalMaeWithout += res.byTerrain[tt].sumErrWithout;
    });
    const gW  = globalMaeWith    / res.totalRiders;
    const gWo = globalMaeWithout / res.totalRiders;
    const gD  = gWo - gW;
    const gCol = gD > 0.3 ? '#15803d' : gD < -0.3 ? '#b91c1c' : '#6b7280';

    const overlay = document.createElement('div');
    overlay.id = 'tcalOverlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px;overflow:auto';
    overlay.innerHTML = `
      <div style="background:#fff;border-radius:14px;max-width:1100px;width:100%;max-height:94vh;overflow:auto;box-shadow:0 20px 60px rgba(0,0,0,.4)">
        <div style="position:sticky;top:0;background:#fff;border-bottom:1px solid #e5e7eb;padding:14px 20px;display:flex;justify-content:space-between;align-items:center;z-index:2">
          <div>
            <h2 style="margin:0;font-size:20px;color:#0b2f6b">📊 Calibración global del factor de terreno</h2>
            <div style="font-size:11.5px;color:#6b7280;margin-top:2px">Agrega TODAS las carreras del histórico con terreno conocido y resultados reales</div>
          </div>
          <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
            <button class="btn" onclick="_simRunTerrainAutoCalibration()" style="background:#0d9488;color:#fff;border:0;font-weight:800" title="Aplica los factores sugeridos a la tabla del simulador. Persiste en este dispositivo.">🤖 Aplicar autoajuste</button>
            <button class="btn light" onclick="_simResetTerrainFactors()" style="background:#fff;color:#374151;border:1px solid #d1d5db;font-weight:700" title="Vuelve a los factores por defecto 0.93 / 0.97 / 1.03 / 1.08">↺ Restablecer defaults</button>
            <button class="btn light" onclick="document.getElementById('tcalOverlay').remove()">✕ Cerrar</button>
          </div>
        </div>
        <div style="padding:18px 20px">
          <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:18px">
            <div style="background:#f8fafc;border:1px solid #e5e7eb;border-radius:10px;padding:10px;text-align:center"><div style="font-size:22px;font-weight:900;color:#0b2f6b">${res.totalRaces}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">Carreras analizadas</div></div>
            <div style="background:#f8fafc;border:1px solid #e5e7eb;border-radius:10px;padding:10px;text-align:center"><div style="font-size:22px;font-weight:900;color:#0b2f6b">${res.totalRiders}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">Corredores afectados</div></div>
            <div style="background:#f8fafc;border:1px solid #e5e7eb;border-radius:10px;padding:10px;text-align:center"><div style="font-size:22px;font-weight:900;color:#374151">${gWo.toFixed(2)}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">MAE sin factor</div></div>
            <div style="background:#f8fafc;border:1px solid #e5e7eb;border-radius:10px;padding:10px;text-align:center"><div style="font-size:22px;font-weight:900;color:#7c3aed">${gW.toFixed(2)}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">MAE con factor</div></div>
            <div style="background:#f8fafc;border:1px solid #e5e7eb;border-radius:10px;padding:10px;text-align:center"><div style="font-size:22px;font-weight:900;color:${gCol}">${(gD>=0?'−':'+') + Math.abs(gD).toFixed(2)}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">Δ MAE global</div></div>
          </div>

          <h3 style="margin:0 0 8px;font-size:14px;color:#0b2f6b">📈 Por tipo de terreno · sugerencias de calibración</h3>
          ${terrainRows || '<div style="color:#6b7280;font-size:12px">Sin datos por terreno.</div>'}

          <details style="margin-top:14px">
            <summary style="cursor:pointer;font-weight:700;color:#0b2f6b;font-size:13px">📋 Ver detalle de las ${res.racesProcessed.length} carreras analizadas</summary>
            <table style="width:100%;border-collapse:collapse;font-size:12px;margin-top:10px;background:#fff;border:1px solid #e5e7eb;border-radius:6px;overflow:hidden">
              <thead><tr style="background:#f3f4f6">
                <th style="padding:6px 8px;text-align:left;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Carrera</th>
                <th style="padding:6px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Fecha</th>
                <th style="padding:6px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Terreno</th>
                <th style="padding:6px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">N</th>
                <th style="padding:6px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">MAE sin</th>
                <th style="padding:6px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">MAE con</th>
                <th style="padding:6px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Δ MAE</th>
              </tr></thead>
              <tbody>${raceRows}</tbody>
            </table>
          </details>

          <details class="sim-help" style="margin-top:14px">
            <summary>❓ ¿Cómo funciona este panel y qué tengo que hacer?</summary>
            <div class="sim-help-body">

              <h4>🎯 ¿Para qué sirve este panel?</h4>
              <p>El simulador predice en qué puesto va a acabar cada corredor en la próxima carrera. Una de las cosas que tiene en cuenta es el <b>tipo de terreno</b> (llana, rompepiernas, media montaña, montañosa): un corredor que va bien en montaña debe tener mejor predicción cuando la carrera es de montaña, y viceversa.</p>
              <p>Para hacer eso, el modelo aplica unos <b>multiplicadores</b> ("factores de terreno"). Por defecto vienen valores genéricos del ciclismo amateur (0.93 / 0.97 / 1.03 / 1.08), pero <b>cada equipo y cada zona son distintos</b>. Este panel sirve para que el sistema <b>afine esos multiplicadores a TUS corredores</b> mirando lo que ya ha pasado en las carreras que has cargado.</p>

              <h4>📊 Las 5 cifras grandes de arriba</h4>
              <ul>
                <li><b>Carreras analizadas</b>: carreras de tu histórico con GPX subido + resultados reales cargados.</li>
                <li><b>Corredores afectados</b>: corredores donde el factor de terreno ha modificado su predicción (los que no, no cuentan).</li>
                <li><b>MAE sin factor</b>: error medio en puestos si NO usáramos el factor de terreno. <i>(MAE = "Mean Absolute Error" — el promedio de cuánto se desvía la predicción de la realidad. Más bajo es mejor.)</i></li>
                <li><b>MAE con factor</b>: error medio aplicando el factor de terreno.</li>
                <li><b style="color:#15803d">Δ MAE global</b> (verde): la mejora. Si pone <b>−2.24</b> significa que el factor de terreno está afinando la predicción en 2.24 puestos de media. Cuanto más negativo (más verde), mejor.</li>
              </ul>

              <h4>🟢🟡🟠🔴 Los bloques por tipo de terreno</h4>
              <p>Cada bloque muestra cómo se está comportando el factor en ese tipo específico de carrera.</p>
              <ul>
                <li><b>Δ MAE</b> del bloque: mejora propia de ese terreno. Verde = bueno, rojo = el factor empeora la predicción ahí.</li>
                <li><b>✓ verde / ✗ rojo / = gris</b>: cuántos corredores mejoraron / empeoraron / quedaron igual con el factor de terreno.</li>
              </ul>

              <h4>📋 La tabla por bucket (las 4 columnas centrales)</h4>
              <p>El modelo clasifica a cada corredor en uno de 4 "buckets" según cómo se le da ese terreno:</p>
              <ul>
                <li><b>Especialista</b>: claramente le va bien (multiplica su puesto por ~0.93).</li>
                <li><b>Cómodo</b>: ligeramente mejor que su media (×0.97).</li>
                <li><b>No es lo suyo</b>: peor de lo normal (×1.03).</li>
                <li><b>Sufre</b>: claramente peor (×1.08).</li>
              </ul>
              <p>Columnas:</p>
              <ul>
                <li><b>Factor aplicado</b>: el valor que el simulador está usando AHORA. Si pone <code>0.89 (def 0.97)</code> significa que el autoajuste lo bajó de 0.97 a 0.89.</li>
                <li><b>N</b>: cuántos corredores caen en ese bucket en tu histórico.</li>
                <li><b>Ratio real/base observado</b>: dato técnico. Si los corredores con factor 1.08 acabaron en promedio 1.15× peor que la predicción base, la realidad sugiere un factor más fuerte.</li>
                <li><b>Sugerido (50/50)</b>: el valor nuevo que el sistema propone. Hace una mezcla 50/50 entre el actual y el observado para no sobreajustar.</li>
                <li><b>Veredicto</b>: ✓ OK mantener · ↑ subir · ↓ bajar.</li>
              </ul>

              <h4>🤖 ¿Cuándo pulsar "Aplicar autoajuste"?</h4>
              <ol>
                <li><b>Después de cargar una carrera nueva</b> con GPX + resultados → abre el panel y mira si aparecen sugerencias rojas/azules. Si sí, pulsa el botón.</li>
                <li>Si ves <b>casi todo "✓ OK mantener"</b> (verde) → no hace falta tocar nada, el modelo ya está afinado a tu pelotón.</li>
                <li>Si aplicas autoajuste y siguen quedando sugerencias → vuelve a pulsar. Cada pulsación lleva los factores la mitad del camino al óptimo (es deliberadamente conservador). En 2-4 pulsaciones converge.</li>
              </ol>

              <h4>↺ ¿Y "Restablecer defaults"?</h4>
              <p>Vuelve a los valores genéricos originales (0.93 / 0.97 / 1.03 / 1.08). Solo úsalo si crees que algo se ha desajustado por una carrera rara o si quieres empezar la calibración de cero.</p>

              <h4>🛡️ Salvaguardas automáticas (no tienes que preocuparte)</h4>
              <ul>
                <li>Mínimo <b>5 corredores</b> por bucket antes de tocar nada — evita ajustes con muestras pequeñas.</li>
                <li>Los valores se acotan entre <b>0.80 y 1.25</b> — nunca harán una predicción absurda.</li>
                <li>Mezcla <b>50/50</b> entre actual y observado — si una carrera trae números raros, no destroza la calibración.</li>
                <li>Los ajustes se guardan en tu <b>navegador</b>. Si cambias de dispositivo empieza desde defaults y vuelves a pulsar autoajuste un par de veces.</li>
              </ul>

              <h4>📈 Resumen en una frase</h4>
              <p><b>Abre este panel cuando cargues una carrera nueva, mira el Δ MAE global, si ves sugerencias pulsa "Aplicar autoajuste" hasta que casi todo esté en verde "OK mantener", y olvídate.</b> El sistema seguirá aprendiendo solo de tus datos.</p>

            </div>
          </details>
        </div>
      </div>`;
    document.body.appendChild(overlay);

  }catch(e){
    console.warn('_simOpenTerrainCalibration', e);
    alert('Error al calcular la calibración: '+(e.message||e));
  }
}

// Aplica el autoajuste y muestra un alert con el resumen de cambios.
// Después relanza el modal y recalcula la prueba actual si la había.
function _simRunTerrainAutoCalibration(){
  try{
    const { changes, totalRaces, totalRiders } = _simApplyTerrainAutoCalibration();
    const labels = { llana:'🟢 Llana', rompepiernas:'🟡 Rompepiernas', media_montana:'🟠 Media montaña', montanosa:'🔴 Montañosa' };
    const bLabels = { strong_low:'Especialista', mild_low:'Cómodo', mild_high:'No es lo suyo', strong_high:'Sufre' };
    if(!changes.length){
      alert(`✅ Autoajuste ejecutado sobre ${totalRaces} carreras y ${totalRiders} corredores.\n\nNo hay cambios relevantes: los factores actuales ya están bien ajustados a los datos.`);
    } else {
      const lines = changes.map(c => `  • ${labels[c.terrain]||c.terrain} · ${bLabels[c.bucket]||c.bucket} (n=${c.n}): ${c.from.toFixed(3)} → ${c.to.toFixed(3)}`);
      alert(`🤖 Autoajuste aplicado sobre ${totalRaces} carreras y ${totalRiders} corredores.\n\n${changes.length} factor(es) actualizado(s):\n\n${lines.join('\n')}\n\nSe aplicarán en todas las predicciones futuras. Persistido en este dispositivo.`);
    }
    // Recalcular la prueba activa si la había, para que el usuario vea el efecto.
    if(typeof _simSelectedRaceId !== 'undefined' && _simSelectedRaceId){
      try { _simBuildData(_simSelectedRaceId); _simRenderCurrent(); } catch(e){}
    }
    // Recargar el modal con los nuevos valores
    _simOpenTerrainCalibration();
  }catch(e){
    console.warn('_simRunTerrainAutoCalibration', e);
    alert('Error al aplicar el autoajuste: '+(e.message||e));
  }
}

// Restablece la tabla persistida y vuelve a los defaults 0.93/0.97/1.03/1.08
function _simResetTerrainFactors(){
  if(!confirm('¿Volver a los factores por defecto (0.93 / 0.97 / 1.03 / 1.08)?\n\nSe perderá todo el autoajuste calibrado a tu histórico.')) return;
  _resetTerrainFactorsTable();
  if(typeof _simSelectedRaceId !== 'undefined' && _simSelectedRaceId){
    try { _simBuildData(_simSelectedRaceId); _simRenderCurrent(); } catch(e){}
  }
  _simOpenTerrainCalibration();
}

// ═════════════════════════════════════════════════════════════════════════
// FASE 7 — CALIBRACIÓN GLOBAL DEL FACTOR CLIMÁTICO
// Estructura análoga a la del terreno pero con 4 condiciones detectables
// (calor / frío / viento / lluvia) en lugar de tipos de terreno.
// ═════════════════════════════════════════════════════════════════════════

function _simComputeClimateCalibration(){
  const hist = (typeof _cachedHistory !== 'undefined' && Array.isArray(_cachedHistory)) ? _cachedHistory : [];
  if(!hist.length) return { byCondition:{}, totalRaces:0, totalRiders:0, racesProcessed:[] };

  const prevRaceId = _simSelectedRaceId;
  const prevData   = _simCurrentData;

  const candidates = hist.filter(h => {
    const w = h.weather || (h._extraNotes && h._extraNotes.weather);
    if(!w) return false;
    if(!_detectClimateConditions(w).length) return false;
    if(!Array.isArray(h.riders) || !h.riders.some(r => r.pos > 0)) return false;
    if(!Array.isArray(h.inscritos) || h.inscritos.length < 5) return false;
    return true;
  });

  const byCondition = {};
  const racesProcessed = [];
  let totalRaces = 0, totalRiders = 0;

  candidates.forEach(race => {
    try {
      _simBuildData(race.id);
      if(!_simCurrentData || !Array.isArray(_simCurrentData.grid)) return;
      const grid = _simCurrentData.grid;
      const realByName = new Map();
      (race.riders||[]).forEach(r => {
        const nk = normalizeForMatching(r.name||'');
        if(nk && r.pos > 0) realByName.set(nk, parseInt(r.pos)||0);
      });

      let raceAffected = 0, raceErrWith = 0, raceErrWithout = 0;

      grid.forEach(g => {
        if(!g.climateBuckets || !g.climateBuckets.length) return;
        if(g.predictedPos == null || g.predictedPosBaseClimate == null) return;
        const real = realByName.get(normalizeForMatching(g.name||''));
        if(!real) return;
        const errWith    = Math.abs(g.predictedPos - real);
        const errWithout = Math.abs(g.predictedPosBaseClimate - real);
        raceAffected++;
        raceErrWith += errWith;
        raceErrWithout += errWithout;

        // Repartir errores por CADA (condición, bucket) activada por el corredor
        g.climateBuckets.forEach(({condition, bucketKey, factor}) => {
          if(!byCondition[condition]) byCondition[condition] = {
            condition,
            racesSet: new Set(),
            riders: 0,
            sumErrWith: 0, sumErrWithout: 0,
            improved: 0, worsened: 0, same: 0,
            byBucket: {}
          };
          const C = byCondition[condition];
          C.racesSet.add(race.id);
          C.riders++;
          C.sumErrWith    += errWith;
          C.sumErrWithout += errWithout;
          if(errWith < errWithout - 0.5)      C.improved++;
          else if(errWith > errWithout + 0.5) C.worsened++;
          else                                 C.same++;
          if(!C.byBucket[bucketKey]) C.byBucket[bucketKey] = {
            bucketKey,
            factor,
            defaultFactor: _CLIMATE_FACTOR_DEFAULTS[bucketKey],
            riders: 0,
            sumErrWith: 0, sumErrWithout: 0,
            sumRealOverBase: 0
          };
          const B = C.byBucket[bucketKey];
          B.riders++;
          B.sumErrWith    += errWith;
          B.sumErrWithout += errWithout;
          if(g.predictedPosBaseClimate > 0){
            B.sumRealOverBase += (real / g.predictedPosBaseClimate);
          }
        });
      });

      if(raceAffected){
        totalRaces++;
        totalRiders += raceAffected;
        racesProcessed.push({
          id: race.id,
          name: race.raceName || race.name || '(sin nombre)',
          date: race.raceDate || '',
          ridersAffected: raceAffected,
          maeWith:    raceErrWith    / raceAffected,
          maeWithout: raceErrWithout / raceAffected
        });
      }
    } catch(e){
      console.warn('[fase7] error procesando', race.raceName, e);
    }
  });

  // Sustituir Set por número
  Object.values(byCondition).forEach(C => { C.races = C.racesSet.size; delete C.racesSet; });

  // Restaurar estado del simulador
  try {
    if(prevRaceId) _simBuildData(prevRaceId);
    else _simCurrentData = prevData;
  } catch(e){ _simCurrentData = prevData; }

  return { byCondition, totalRaces, totalRiders, racesProcessed };
}

function _simApplyClimateAutoCalibration(){
  const res = _simComputeClimateCalibration();
  const current = _loadClimateFactorsTable();
  const updated = JSON.parse(JSON.stringify(current||{}));
  const changes = [];
  Object.keys(res.byCondition).forEach(cond => {
    const C = res.byCondition[cond];
    if(!updated[cond]) updated[cond] = {};
    Object.values(C.byBucket).forEach(B => {
      const sug = _simSuggestTerrainFactor(B); // misma fórmula 50/50, mismas salvaguardas
      if(!sug) return;
      const bKey = B.bucketKey;
      if(!bKey) return;
      const prev = (updated[cond][bKey] != null) ? updated[cond][bKey] : _CLIMATE_FACTOR_DEFAULTS[bKey];
      const next = sug.suggested;
      if(Math.abs(next - prev) < 0.005) return;
      updated[cond][bKey] = next;
      changes.push({ condition: cond, bucket: bKey, from: prev, to: next, n: B.riders });
    });
  });
  _saveClimateFactorsTable(updated);
  return { changes, totalRaces: res.totalRaces, totalRiders: res.totalRiders };
}

function _simOpenClimateCalibration(){
  try {
    _simInjectPVRStyles();
    const old = document.getElementById('ccalOverlay');
    if(old) old.remove();

    const res = _simComputeClimateCalibration();
    if(!res.totalRaces){
      alert('Aún no hay suficientes carreras con clima registrado + resultados reales para calibrar el factor climático.\n\nAsegúrate de:\n  • Tener clima guardado en alguna carrera disputada (Open-Meteo Archive vía "Cargar clima histórico")\n  • Tener resultados reales y al menos 5 inscritos en esa carrera\n  • Que la carrera tenga calor (≥24°C), frío (≤12°C), viento (≥15 km/h) o lluvia (≥40%)');
      return;
    }

    const condLabels = { hot:'☀️ Calor', cold:'🥶 Frío', windy:'💨 Viento', rainy:'🌧️ Lluvia' };
    const bucketLabels = { strong_low:'Va muy bien', mild_low:'Cómodo', mild_high:'Le cuesta', strong_high:'Sufre' };
    const condKeys = Object.keys(res.byCondition).sort();

    const condRows = condKeys.map(cond => {
      const C = res.byCondition[cond];
      const mW  = C.sumErrWith    / C.riders;
      const mWo = C.sumErrWithout / C.riders;
      const delta = mWo - mW;
      const dCol = delta > 0.3 ? '#15803d' : delta < -0.3 ? '#b91c1c' : '#6b7280';
      const dTxt = (delta >= 0 ? '−' : '+') + Math.abs(delta).toFixed(2);

      const bucketRows = Object.values(C.byBucket)
        .sort((a,b)=>a.factor-b.factor)
        .map(B => {
          const sug = _simSuggestTerrainFactor(B);
          const appliedTxt = (B.factor !== B.defaultFactor)
            ? `<span style="font-weight:800;color:#0d9488">${B.factor.toFixed(2)}</span><span style="font-size:10px;color:#6b7280">&nbsp;(def ${B.defaultFactor.toFixed(2)})</span>`
            : `<span style="font-weight:800;color:#0b2f6b">${B.factor.toFixed(2)}</span>`;
          if(!sug){
            return `<tr>
              <td style="padding:4px 8px;text-align:center">${appliedTxt}</td>
              <td style="padding:4px 8px;text-align:center;color:#374151;font-size:11px">${bucketLabels[B.bucketKey]||B.bucketKey}</td>
              <td style="padding:4px 8px;text-align:center;color:#374151">${B.riders}</td>
              <td style="padding:4px 8px;text-align:center;color:#6b7280" colspan="3">— muestra insuficiente (mín. 5) —</td>
            </tr>`;
          }
          return `<tr>
            <td style="padding:4px 8px;text-align:center">${appliedTxt}</td>
            <td style="padding:4px 8px;text-align:center;color:#374151;font-size:11px">${bucketLabels[B.bucketKey]||B.bucketKey}</td>
            <td style="padding:4px 8px;text-align:center;color:#374151">${B.riders}</td>
            <td style="padding:4px 8px;text-align:center;color:#7c3aed;font-weight:700">${sug.observed.toFixed(3)}</td>
            <td style="padding:4px 8px;text-align:center;color:#0b2f6b;font-weight:800">${sug.suggested.toFixed(2)}</td>
            <td style="padding:4px 8px;text-align:center;color:${sug.verdict.color};font-weight:800">${sug.verdict.icon} ${sug.verdict.txt}</td>
          </tr>`;
        }).join('');

      return `
        <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:12px;margin-bottom:10px">
          <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:8px">
            <div style="font-weight:800;color:#0b2f6b;font-size:15px">${condLabels[cond]||cond}</div>
            <span style="background:#f3f4f6;color:#374151;font-size:11px;font-weight:700;padding:2px 9px;border-radius:6px">${C.races} carreras · ${C.riders} corredores</span>
            <span style="background:${dCol}20;color:${dCol};font-size:11px;font-weight:800;padding:2px 9px;border-radius:6px">Δ MAE = ${dTxt}</span>
            <span style="background:#15803d20;color:#15803d;font-size:11px;font-weight:700;padding:2px 8px;border-radius:6px">✓ ${C.improved}</span>
            <span style="background:#b91c1c20;color:#b91c1c;font-size:11px;font-weight:700;padding:2px 8px;border-radius:6px">✗ ${C.worsened}</span>
            <span style="background:#6b728020;color:#6b7280;font-size:11px;font-weight:700;padding:2px 8px;border-radius:6px">= ${C.same}</span>
          </div>
          <table style="width:100%;border-collapse:collapse;font-size:12px;background:#fafbfc;border-radius:6px;overflow:hidden">
            <thead><tr style="background:#f3f4f6">
              <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Factor aplicado</th>
              <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Bucket</th>
              <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">N</th>
              <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Ratio real/base obs.</th>
              <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Sugerido (50/50)</th>
              <th style="padding:5px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Veredicto</th>
            </tr></thead>
            <tbody>${bucketRows || '<tr><td colspan="6" style="padding:6px;text-align:center;color:#6b7280">—</td></tr>'}</tbody>
          </table>
        </div>`;
    }).join('');

    const raceRows = res.racesProcessed
      .slice()
      .sort((a,b)=>(b.maeWithout - b.maeWith) - (a.maeWithout - a.maeWith))
      .map(r => {
        const delta = r.maeWithout - r.maeWith;
        const dCol = delta > 0.3 ? '#15803d' : delta < -0.3 ? '#b91c1c' : '#6b7280';
        const dTxt = (delta >= 0 ? '−' : '+') + Math.abs(delta).toFixed(2);
        return `<tr>
          <td style="padding:4px 8px;color:#0b2f6b;font-weight:700">${escapeHtml(r.name)}</td>
          <td style="padding:4px 8px;text-align:center;color:#6b7280;font-size:11px">${escapeHtml(r.date||'')}</td>
          <td style="padding:4px 8px;text-align:center;color:#374151">${r.ridersAffected}</td>
          <td style="padding:4px 8px;text-align:center;color:#374151">${r.maeWithout.toFixed(2)}</td>
          <td style="padding:4px 8px;text-align:center;color:#7c3aed">${r.maeWith.toFixed(2)}</td>
          <td style="padding:4px 8px;text-align:center;color:${dCol};font-weight:800">${dTxt}</td>
        </tr>`;
      }).join('');

    let globalMaeWith = 0, globalMaeWithout = 0;
    condKeys.forEach(c => {
      globalMaeWith    += res.byCondition[c].sumErrWith;
      globalMaeWithout += res.byCondition[c].sumErrWithout;
    });
    const totalContribs = condKeys.reduce((s,c)=>s+res.byCondition[c].riders, 0) || 1;
    const gW  = globalMaeWith    / totalContribs;
    const gWo = globalMaeWithout / totalContribs;
    const gD  = gWo - gW;
    const gCol = gD > 0.3 ? '#15803d' : gD < -0.3 ? '#b91c1c' : '#6b7280';

    const overlay = document.createElement('div');
    overlay.id = 'ccalOverlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px;overflow:auto';
    overlay.innerHTML = `
      <div style="background:#fff;border-radius:14px;max-width:1100px;width:100%;max-height:94vh;overflow:auto;box-shadow:0 20px 60px rgba(0,0,0,.4)">
        <div style="position:sticky;top:0;background:#fff;border-bottom:1px solid #e5e7eb;padding:14px 20px;display:flex;justify-content:space-between;align-items:center;z-index:2;flex-wrap:wrap;gap:10px">
          <div>
            <h2 style="margin:0;font-size:20px;color:#0b2f6b">🌦️ Calibración global del factor climático</h2>
            <div style="font-size:11.5px;color:#6b7280;margin-top:2px">Agrega TODAS las carreras del histórico con clima registrado y resultados reales</div>
          </div>
          <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
            <button class="btn" onclick="_simRunClimateAutoCalibration()" style="background:#0284c7;color:#fff;border:0;font-weight:800" title="Aplica los factores climáticos sugeridos. Persiste en este dispositivo.">🤖 Aplicar autoajuste</button>
            <button class="btn light" onclick="_simResetClimateFactors()" style="background:#fff;color:#374151;border:1px solid #d1d5db;font-weight:700" title="Vuelve a los factores climáticos por defecto">↺ Restablecer defaults</button>
            <button class="btn light" onclick="document.getElementById('ccalOverlay').remove()">✕ Cerrar</button>
          </div>
        </div>
        <div style="padding:18px 20px">
          <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:18px">
            <div style="background:#f8fafc;border:1px solid #e5e7eb;border-radius:10px;padding:10px;text-align:center"><div style="font-size:22px;font-weight:900;color:#0b2f6b">${res.totalRaces}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">Carreras analizadas</div></div>
            <div style="background:#f8fafc;border:1px solid #e5e7eb;border-radius:10px;padding:10px;text-align:center"><div style="font-size:22px;font-weight:900;color:#0b2f6b">${res.totalRiders}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">Corredores afectados</div></div>
            <div style="background:#f8fafc;border:1px solid #e5e7eb;border-radius:10px;padding:10px;text-align:center"><div style="font-size:22px;font-weight:900;color:#374151">${gWo.toFixed(2)}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">MAE sin factor</div></div>
            <div style="background:#f8fafc;border:1px solid #e5e7eb;border-radius:10px;padding:10px;text-align:center"><div style="font-size:22px;font-weight:900;color:#7c3aed">${gW.toFixed(2)}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">MAE con factor</div></div>
            <div style="background:#f8fafc;border:1px solid #e5e7eb;border-radius:10px;padding:10px;text-align:center"><div style="font-size:22px;font-weight:900;color:${gCol}">${(gD>=0?'−':'+') + Math.abs(gD).toFixed(2)}</div><div style="font-size:10px;color:#6b7280;text-transform:uppercase;font-weight:700;letter-spacing:.3px">Δ MAE global</div></div>
          </div>

          <h3 style="margin:0 0 8px;font-size:14px;color:#0b2f6b">🌤️ Por condición climática · sugerencias de calibración</h3>
          ${condRows || '<div style="color:#6b7280;font-size:12px">Sin datos por condición.</div>'}

          <details style="margin-top:14px">
            <summary style="cursor:pointer;font-weight:700;color:#0b2f6b;font-size:13px">📋 Ver detalle de las ${res.racesProcessed.length} carreras analizadas</summary>
            <table style="width:100%;border-collapse:collapse;font-size:12px;margin-top:10px;background:#fff;border:1px solid #e5e7eb;border-radius:6px;overflow:hidden">
              <thead><tr style="background:#f3f4f6">
                <th style="padding:6px 8px;text-align:left;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Carrera</th>
                <th style="padding:6px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Fecha</th>
                <th style="padding:6px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">N</th>
                <th style="padding:6px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">MAE sin</th>
                <th style="padding:6px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">MAE con</th>
                <th style="padding:6px 8px;text-align:center;font-size:10px;color:#6b7280;text-transform:uppercase;letter-spacing:.3px">Δ MAE</th>
              </tr></thead>
              <tbody>${raceRows}</tbody>
            </table>
          </details>

          <details class="sim-help" style="margin-top:14px">
            <summary>❓ ¿Cómo funciona este panel y qué tengo que hacer?</summary>
            <div class="sim-help-body">
              <h4>🎯 ¿Para qué sirve?</h4>
              <p>Igual que con el terreno, este panel afina los multiplicadores que el simulador aplica cuando la carrera del día tiene <b>calor, frío, viento o lluvia</b>. Detecta qué corredores rinden mejor o peor en cada condición a partir de tu histórico y los multiplica adecuadamente.</p>

              <h4>🌡️ Las 4 condiciones detectables</h4>
              <ul>
                <li>☀️ <b>Calor</b>: temperatura ≥ 24 °C</li>
                <li>🥶 <b>Frío</b>: temperatura ≤ 12 °C</li>
                <li>💨 <b>Viento</b>: viento ≥ 15 km/h</li>
                <li>🌧️ <b>Lluvia</b>: probabilidad ≥ 40 %</li>
              </ul>
              <p>Una misma carrera puede activar varias a la vez (p.ej. calor + viento). Los factores se multiplican y se acotan entre 0.80 y 1.25 para que el ajuste nunca sea absurdo.</p>

              <h4>📊 Los 4 buckets de comportamiento del corredor</h4>
              <ul>
                <li><b>Va muy bien</b>: rinde claramente mejor en esa condición (×0.93).</li>
                <li><b>Cómodo</b>: rinde algo mejor (×0.97).</li>
                <li><b>Le cuesta</b>: rinde algo peor (×1.03).</li>
                <li><b>Sufre</b>: rinde claramente peor (×1.08).</li>
              </ul>

              <h4>🤖 ¿Cuándo pulsar "Aplicar autoajuste"?</h4>
              <ol>
                <li>Cuando cargues una carrera nueva con clima conocido + resultados reales.</li>
                <li>Si ves muchas flechas rojas/azules → pulsa el botón (2-3 veces si hace falta) hasta que la mayoría diga "✓ OK mantener".</li>
                <li>Cuanta más carrera con clima disputes, más se afinan los factores a tu pelotón.</li>
              </ol>

              <h4>🛡️ Salvaguardas (no te preocupes)</h4>
              <ul>
                <li>Mínimo <b>5 corredores</b> por bucket antes de ajustar.</li>
                <li>Mezcla <b>50/50</b> entre actual y observado → no sobreajusta con muestras pequeñas.</li>
                <li>Clamp <b>0.80–1.25</b> en el factor total — nada de predicciones absurdas.</li>
              </ul>

              <h4>📈 Resumen</h4>
              <p><b>Abre cuando dispute una carrera con clima cargado, pulsa "Aplicar autoajuste" hasta ver casi todo verde "OK mantener", y olvídate.</b></p>
            </div>
          </details>
        </div>
      </div>`;
    document.body.appendChild(overlay);
  } catch(e){
    console.warn('_simOpenClimateCalibration', e);
    alert('Error al calcular la calibración climática: '+(e.message||e));
  }
}

function _simRunClimateAutoCalibration(){
  try {
    const { changes, totalRaces, totalRiders } = _simApplyClimateAutoCalibration();
    const cLabels = { hot:'☀️ Calor', cold:'🥶 Frío', windy:'💨 Viento', rainy:'🌧️ Lluvia' };
    const bLabels = { strong_low:'Va muy bien', mild_low:'Cómodo', mild_high:'Le cuesta', strong_high:'Sufre' };
    if(!changes.length){
      alert(`✅ Autoajuste climático ejecutado sobre ${totalRaces} carreras y ${totalRiders} corredores.\n\nNo hay cambios relevantes: los factores actuales ya están bien ajustados a los datos.`);
    } else {
      const lines = changes.map(c => `  • ${cLabels[c.condition]||c.condition} · ${bLabels[c.bucket]||c.bucket} (n=${c.n}): ${c.from.toFixed(3)} → ${c.to.toFixed(3)}`);
      alert(`🤖 Autoajuste climático aplicado sobre ${totalRaces} carreras y ${totalRiders} corredores.\n\n${changes.length} factor(es) actualizado(s):\n\n${lines.join('\n')}\n\nSe aplicarán en todas las predicciones futuras. Persistido en este dispositivo.`);
    }
    if(typeof _simSelectedRaceId !== 'undefined' && _simSelectedRaceId){
      try { _simBuildData(_simSelectedRaceId); _simRenderCurrent(); } catch(e){}
    }
    _simOpenClimateCalibration();
  } catch(e){
    console.warn('_simRunClimateAutoCalibration', e);
    alert('Error al aplicar el autoajuste climático: '+(e.message||e));
  }
}

function _simResetClimateFactors(){
  if(!confirm('¿Volver a los factores climáticos por defecto (0.93 / 0.97 / 1.03 / 1.08)?\n\nSe perderá todo el autoajuste calibrado a tu histórico.')) return;
  _resetClimateFactorsTable();
  if(typeof _simSelectedRaceId !== 'undefined' && _simSelectedRaceId){
    try { _simBuildData(_simSelectedRaceId); _simRenderCurrent(); } catch(e){}
  }
  _simOpenClimateCalibration();
}

