// ════════════════════════════════════════════════════════════════════════
// GESTOR DE LOCALIDADES
//   Permite renombrar una localidad mal escrita en TODAS las pruebas del
//   histórico, o simplemente ocultarla de las sugerencias del datalist
//   sin tocar los datos guardados (lista de ignoradas en localStorage).
// ════════════════════════════════════════════════════════════════════════

function _cargaGetIgnoredLocs(){
  try{ return new Set(JSON.parse(localStorage.getItem('_cargaIgnoredLocs')||'[]')); }
  catch(e){ return new Set(); }
}
function _cargaSetIgnoredLocs(set){
  localStorage.setItem('_cargaIgnoredLocs', JSON.stringify([...set]));
}

// Wrap del builder original para filtrar las ignoradas
(function(){
  const _orig = (typeof _cargaPopulateLocalidadDatalist === 'function') ? _cargaPopulateLocalidadDatalist : null;
  if(!_orig) return;
  window._cargaPopulateLocalidadDatalist = function(){
    const inp = document.getElementById('raceLocalidad');
    if(!inp) return;
    let dl = document.getElementById('cargaLocalidadList');
    if(!dl){
      dl = document.createElement('datalist');
      dl.id = 'cargaLocalidadList';
      document.body.appendChild(dl);
      inp.setAttribute('list', 'cargaLocalidadList');
    }
    const hist = Array.isArray(_cachedHistory) ? _cachedHistory : [];
    const ignored = _cargaGetIgnoredLocs();
    const locs = new Set();
    hist.forEach(h => {
      const v = (h.localidad||'').trim();
      if(v && !ignored.has(v.toLowerCase())) locs.add(v);
    });
    dl.innerHTML = [...locs].sort().map(l => `<option value="${escapeAttr(l)}">`).join('');
  };
})();

async function _cargaOpenLocalidadManager(){
  // Asegurar histórico cargado
  if(!Array.isArray(_cachedHistory) || !_cachedHistory.length){
    if(typeof _sbLoadHistory==='function') _cachedHistory = await _sbLoadHistory();
  }
  const hist = Array.isArray(_cachedHistory) ? _cachedHistory : [];
  // Mapear localidad → [{id, name}]
  const map = new Map();
  hist.forEach(h=>{
    const v = (h.localidad||'').trim();
    if(!v) return;
    if(!map.has(v)) map.set(v, []);
    map.get(v).push({ id: h.id, name: h.raceName||'' });
  });
  const ignored = _cargaGetIgnoredLocs();
  const items = [...map.entries()].sort((a,b)=>a[0].localeCompare(b[0],'es'));

  let overlay = document.getElementById('_locMgrOverlay');
  if(!overlay){
    overlay = document.createElement('div');
    overlay.id = '_locMgrOverlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:10002;display:flex;align-items:center;justify-content:center;padding:20px';
    overlay.addEventListener('click',(e)=>{ if(e.target===overlay) _cargaCloseLocalidadManager(); });
    document.body.appendChild(overlay);
  }

  if(!items.length){
    overlay.innerHTML = `<div style="background:#fff;border-radius:12px;max-width:520px;padding:24px;text-align:center">
      <div style="font-size:15px;color:#374151">No hay localidades guardadas en el histórico todavía.</div>
      <button class="btn light" style="margin-top:14px" onclick="_cargaCloseLocalidadManager()">Cerrar</button>
    </div>`;
    return;
  }

  const rows = items.map(([loc, races])=>{
    const isIgnored = ignored.has(loc.toLowerCase());
    const racesTooltip = races.slice(0,5).map(r=>r.name).join('\n');
    return `<tr data-loc-row="${escapeAttr(loc)}">
      <td style="padding:6px 8px;vertical-align:top;width:32px;color:#9ca3af;font-size:11px;text-align:right">${races.length}</td>
      <td style="padding:6px 8px;vertical-align:top">
        <div style="font-weight:700;color:#0b2f6b;font-size:13px">${escapeHtml(loc)}</div>
        <div title="${escapeAttr(racesTooltip)}" style="font-size:10.5px;color:#6b7280;margin-top:1px">
          en ${races.length} prueba${races.length!==1?'s':''}${isIgnored?' · <span style="color:#dc2626;font-weight:700">oculta en sugerencias</span>':''}
        </div>
      </td>
      <td style="padding:6px 8px;vertical-align:top;white-space:nowrap">
        <button class="btn light" style="font-size:11px;padding:4px 8px" onclick="_cargaRenameLocalidad(this.getAttribute('data-loc'))" data-loc="${escapeAttr(loc)}">✏️ Renombrar</button>
        <button class="btn light" style="font-size:11px;padding:4px 8px;${isIgnored?'background:#fef2f2;color:#991b1b':''}" onclick="_cargaToggleIgnoreLoc(this.getAttribute('data-loc'))" data-loc="${escapeAttr(loc)}">${isIgnored?'↩️ Mostrar':'🚫 Ocultar'}</button>
      </td>
    </tr>`;
  }).join('');

  overlay.innerHTML = `
    <div style="background:#fff;border-radius:14px;max-width:720px;width:100%;max-height:85vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.4)">
      <div style="padding:14px 18px;border-bottom:1px solid #e5e7eb;display:flex;justify-content:space-between;align-items:flex-start;gap:10px">
        <div>
          <div style="font-weight:800;font-size:16px;color:#0b2f6b">🧹 Gestionar localidades</div>
          <div style="font-size:11.5px;color:#6b7280;margin-top:3px">
            <b>Renombrar</b>: cambia el texto en TODAS las pruebas que la tengan (corrige errores de escritura).<br>
            <b>Ocultar</b>: la quita de las sugerencias del autocompletado sin tocar los datos guardados.
          </div>
        </div>
        <button class="btn light" onclick="_cargaCloseLocalidadManager()" style="font-size:12px;padding:5px 10px">✕</button>
      </div>
      <div style="flex:1;overflow:auto;padding:6px 8px">
        <table style="width:100%;border-collapse:collapse;font-size:12.5px">
          <thead><tr style="background:#f9fafb">
            <th style="padding:6px 8px;text-align:right;color:#6b7280;font-size:10px;text-transform:uppercase;letter-spacing:.3px">#</th>
            <th style="padding:6px 8px;text-align:left;color:#6b7280;font-size:10px;text-transform:uppercase;letter-spacing:.3px">Localidad</th>
            <th style="padding:6px 8px;text-align:right;color:#6b7280;font-size:10px;text-transform:uppercase;letter-spacing:.3px">Acciones</th>
          </tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </div>
      <div style="padding:10px 14px;border-top:1px solid #e5e7eb;background:#f9fafb;font-size:11px;color:#6b7280;text-align:center">
        Total: ${items.length} localidad${items.length!==1?'es':''} distintas · ${ignored.size} oculta${ignored.size!==1?'s':''}
      </div>
    </div>`;
}

function _cargaCloseLocalidadManager(){
  const ov = document.getElementById('_locMgrOverlay');
  if(ov) ov.remove();
}

function _cargaToggleIgnoreLoc(loc){
  const ignored = _cargaGetIgnoredLocs();
  const k = (loc||'').toLowerCase();
  if(ignored.has(k)) ignored.delete(k); else ignored.add(k);
  _cargaSetIgnoredLocs(ignored);
  // Refrescar datalist y modal
  if(typeof _cargaPopulateLocalidadDatalist==='function') _cargaPopulateLocalidadDatalist();
  _cargaOpenLocalidadManager();
}

async function _cargaRenameLocalidad(oldName){
  const nv = prompt(`Renombrar localidad "${oldName}" a:\n\n(El cambio se aplicará a TODAS las pruebas que la tengan en el histórico)`, oldName);
  if(nv == null) return;
  const newName = nv.trim();
  if(!newName){ alert('El nuevo nombre no puede estar vacío. Si quieres quitarla, usa "Ocultar".'); return; }
  if(newName === oldName){ return; }
  if(!_sb){ alert('Supabase no disponible.'); return; }
  const hist = Array.isArray(_cachedHistory) ? _cachedHistory : [];
  const affected = hist.filter(h => (h.localidad||'').trim() === oldName);
  if(!affected.length){ alert('No se encontraron pruebas con esa localidad.'); return; }
  if(!confirm(`Se renombrará "${oldName}" → "${newName}" en ${affected.length} prueba${affected.length!==1?'s':''} del histórico.\n\n¿Continuar?`)) return;
  // Para cada prueba afectada, leer notes, actualizar y guardar
  let ok = 0, fail = 0;
  for(const h of affected){
    try{
      const {data, error} = await _sb.from('races').select('notes').eq('id', h.id).single();
      if(error || !data){ fail++; continue; }
      let extra = {};
      try{ extra = JSON.parse(data.notes||'{}'); }catch(e){}
      extra.localidad = newName;
      const {error:e2} = await _sb.from('races').update({notes: JSON.stringify(extra)}).eq('id', h.id);
      if(e2){ fail++; } else { ok++; }
    }catch(e){ fail++; }
  }
  // Quitar la antigua de ignoradas si estaba
  const ignored = _cargaGetIgnoredLocs();
  if(ignored.has(oldName.toLowerCase())){ ignored.delete(oldName.toLowerCase()); _cargaSetIgnoredLocs(ignored); }
  // Refrescar caché y vistas
  _cachedHistory = null;
  if(typeof _sbLoadHistory==='function') _cachedHistory = await _sbLoadHistory();
  if(typeof _cargaPopulateLocalidadDatalist==='function') _cargaPopulateLocalidadDatalist();
  // Si el campo del formulario muestra la antigua, actualízalo también
  const inp = document.getElementById('raceLocalidad');
  if(inp && inp.value.trim() === oldName) inp.value = newName;
  alert(`✅ Renombradas ${ok} prueba${ok!==1?'s':''}.${fail?` ❌ Errores: ${fail}.`:''}`);
  _cargaOpenLocalidadManager();
}

// ════════════════════════════════════════════════════════════════════════
// SIMULADOR — Informe del Top 10 esperado (compartir / PDF / PNG)
//   Modal independiente con el Top 10 predicho por la IA en formato
//   imprimible y limpio, para enviar al jefe de equipo o segundo
//   director. Reutiliza la marca MFPP y el patrón de impresión de los
//   otros modales (Pred vs Real, DNFs).
// ════════════════════════════════════════════════════════════════════════

function _simOpenTop10Report(){
  try{
    if(!_simCurrentData){ alert('Selecciona una prueba primero.'); return; }
    const { race, grid, kpis } = _simCurrentData;
    const catSelEl = document.getElementById('simCatSelect');
    const catFilter = catSelEl ? (catSelEl.value||'') : '';
    // Construir el Top 10 igual que la vista (predictedPos asc, filtrado por cat si procede)
    const pool = grid.filter(g => g.predictedPos != null && (!catFilter || g.cat === catFilter));
    pool.sort((a,b)=>{
      const ap = a.predictedPosRaw!=null?a.predictedPosRaw:a.predictedPos;
      const bp = b.predictedPosRaw!=null?b.predictedPosRaw:b.predictedPos;
      return ap - bp;
    });
    const top10 = pool.slice(0,10);
    if(!top10.length){ alert('No hay predicciones disponibles para mostrar.'); return; }

    const _pdfLogoSrc = document.querySelector('.brand-logo')?.src || '';
    const ridersWithHist = top10.filter(g => g.hasHistory).length;
    const avgRelTop10 = (()=>{
      const rels = top10.map(g => (typeof g.reliability === 'number') ? g.reliability : null).filter(v => v != null);
      return rels.length ? Math.round(rels.reduce((s,v)=>s+v,0)/rels.length) : null;
    })();
    const myInTop10 = top10.filter(g => g.isMyTeam).length;

    const rowsHtml = top10.map((g, i) => {
      const pos = i+1;
      const bib = g.bib ? '#'+g.bib : '—';
      const team = g.team || '—';
      const cat = g.cat || '';
      const avg = (typeof g.avgPos === 'number') ? g.avgPos.toFixed(1)+'º' : '—';
      const best = (typeof g.bestPos === 'number') ? g.bestPos+'º' : (typeof g.best === 'number' ? g.best+'º' : '—');
      const rel = (typeof g.reliability === 'number') ? g.reliability+'%' : '—';
      const carrs = (typeof g.nRaces === 'number') ? g.nRaces : (typeof g.races === 'number' ? g.races : '—');
      const rngLo = (g.predLower!=null) ? g.predLower : null;
      const rngHi = (g.predUpper!=null) ? g.predUpper : null;
      const rng = (rngLo!=null && rngHi!=null && rngLo!==rngHi) ? `${rngLo}º–${rngHi}º` : (g.predictedPos!=null?g.predictedPos+'º':'—');
      const myTeamTag = g.isMyTeam ? ' <span style="color:#1f6feb;font-weight:800">★</span>' : '';
      // Color de fila: top 3 destacado
      const bgRow = i < 3 ? '#fef9c3' : (i % 2 === 0 ? '#ffffff' : '#f9fafb');
      return `<tr style="background:${bgRow}">
        <td class="st10-pos">${pos}º</td>
        <td>
          <div class="st10-name">${escapeHtml(g.name)}${myTeamTag}</div>
          <div class="st10-meta">${escapeHtml(team)}${cat?' · '+escapeHtml(cat):''} · ${escapeHtml(bib)}</div>
        </td>
        <td class="st10-num"><b>${rng}</b><br><span class="st10-small">rango IA</span></td>
        <td class="st10-num">${avg}<br><span class="st10-small">media</span></td>
        <td class="st10-num">${best}<br><span class="st10-small">mejor</span></td>
        <td class="st10-num">${rel}<br><span class="st10-small">fiab.</span></td>
        <td class="st10-num">${carrs}<br><span class="st10-small">carrs.</span></td>
      </tr>`;
    }).join('');

    const meta = `
      <div class="st10-race-meta">
        <b>${escapeHtml(race.raceName||'')}</b>
        ${race.raceDate?` · 📅 ${escapeHtml(race.raceDate)}`:''}
        ${race.localidad?` · 📍 ${escapeHtml(race.localidad)}`:''}
        ${race.circuitType?` · 🛣️ ${escapeHtml(race.circuitType)}`:''}
        ${catFilter?` · 🏷️ Categoría <b>${escapeHtml(catFilter)}</b>`:''}
      </div>`;

    let overlay = document.getElementById('simTop10Overlay');
    if(!overlay){
      overlay = document.createElement('div');
      overlay.id = 'simTop10Overlay';
      overlay.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.6);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px';
      overlay.addEventListener('click',(e)=>{ if(e.target===overlay) _simCloseTop10Report(); });
      document.body.appendChild(overlay);
    }
    overlay.innerHTML = `
      <div id="simTop10Box">
        <div class="st10-header">
          <div style="display:flex;align-items:center;gap:14px;flex:1;min-width:0">
            ${_pdfLogoSrc?`<img src="${_pdfLogoSrc}" alt="MFPP Cycling Specialist" class="st10-logo">`:''}
            <div style="min-width:0">
              <h2 class="st10-title">🏆 Top 10 esperado · Predicción IA</h2>
              ${meta}
            </div>
          </div>
          <div class="st10-actions no-print">
            <button class="btn" onclick="window.print()" style="background:#dc2626;color:#fff;font-weight:800">🖨️ Imprimir / PDF</button>
            <button class="btn light" onclick="_simCloseTop10Report()">✕</button>
          </div>
        </div>
        <div class="st10-kpis">
          <div class="st10-kpi"><div class="st10-kpi-v" style="color:#0b2f6b">${top10.length}</div><div class="st10-kpi-l">Predicciones</div></div>
          <div class="st10-kpi"><div class="st10-kpi-v" style="color:#16a34a">${ridersWithHist}</div><div class="st10-kpi-l">Con histórico</div></div>
          ${avgRelTop10!=null?`<div class="st10-kpi"><div class="st10-kpi-v" style="color:#7c3aed">${avgRelTop10}%</div><div class="st10-kpi-l">Fiabilidad media</div></div>`:''}
          <div class="st10-kpi"><div class="st10-kpi-v" style="color:#1f6feb">${myInTop10}</div><div class="st10-kpi-l">Mi equipo (★)</div></div>
        </div>
        <div style="padding:0 0 6px;font-size:11px;color:#6b7280;text-align:center">
          Ordenado por <b>Pos. IA ascendente</b> (mejor predicción primero) · ★ = corredor de mi equipo
        </div>
        <div class="st10-table-wrap">
          <table class="st10-table">
            <thead>
              <tr>
                <th style="width:48px">Pos.</th>
                <th>Ciclista · Equipo · Dorsal</th>
                <th style="width:90px;text-align:center">Rango IA</th>
                <th style="width:72px;text-align:center">Media</th>
                <th style="width:68px;text-align:center">Mejor</th>
                <th style="width:68px;text-align:center">Fiab.</th>
                <th style="width:68px;text-align:center">Carrs.</th>
              </tr>
            </thead>
            <tbody>${rowsHtml}</tbody>
          </table>
        </div>
        <div class="st10-footer">
          <div><b>Pos. IA</b> = (0.60 × media últimas 3) + (0.40 × media histórica) × factor cadete × penalización por fiabilidad</div>
          <div style="margin-top:8px">Informe generado por <b>Dashboard Director · MFPP Cycling Specialist</b> · ${new Date().toLocaleString('es-ES')}</div>
        </div>
      </div>`;

    _simInjectTop10Styles();
    document.body.style.overflow = 'hidden';
  }catch(e){
    console.warn('_simOpenTop10Report', e);
    alert('Error al abrir el informe: '+(e.message||e));
  }
}

function _simCloseTop10Report(){
  const ov = document.getElementById('simTop10Overlay');
  if(ov) ov.remove();
  document.body.style.overflow = '';
}

