// ── Init de la pestaña Generar ──
function _fccvInitGenerar(){
  _fccvPopulatePruebas();
  _fccvPopulateStaff();
  _fccvSetCat(_fccvSelCat);
  _fccvRenderSelected();
}

// Extender el toggle de tabs (ya definido) para inicializar Generar al entrar
(function _wrapShowTab(){
  const _orig = (typeof _fccvShowTab === 'function') ? _fccvShowTab : null;
  if(!_orig) return;
  window._fccvShowTab = function(tab){
    _orig.apply(this, arguments);
    if(tab === 'generar') setTimeout(_fccvInitGenerar, 30);
  };
})();

// ── Selector de prueba: pruebas planificadas + últimas clasificaciones ──
async function _fccvPopulatePruebas(){
  const sel = document.getElementById('fccvGenPruebaSelect');
  if(!sel) return;
  let opts = '<option value="">— Cargar desde calendario / histórico —</option>';
  // Planificadas
  try{
    if(_sb){
      const {data} = await _sb.from('races').select('id, name, date, notes').eq('race_type','planificada').order('date');
      (data||[]).forEach(r => {
        let extra = {};
        try{ extra = JSON.parse(r.notes||'{}'); }catch(e){}
        const dt = extra.raceDate || (formatDateDisplay(r.date)) || r.date;
        opts += `<option value="planif:${r.id}">📅 ${escapeHtml(dt||'?')} · ${escapeHtml(r.name||'')}</option>`;
      });
    }
  }catch(e){ console.warn('fccvPopulatePruebas planificadas', e); }
  // Históricas (últimas 25)
  try{
    const hist = (Array.isArray(_cachedHistory) && _cachedHistory.length) ? _cachedHistory : (typeof _sbLoadHistory==='function' ? await _sbLoadHistory() : []);
    if(Array.isArray(_cachedHistory) === false || !_cachedHistory.length) _cachedHistory = hist;
    const sorted = hist.slice().sort((a,b)=>{
      const da = _parseSpanishDate(a.raceDate)||'0000-00-00';
      const db = _parseSpanishDate(b.raceDate)||'0000-00-00';
      return db.localeCompare(da);
    }).slice(0,25);
    if(sorted.length){
      opts += '<optgroup label="── Histórico (últimas 25) ──">';
      sorted.forEach(h => {
        opts += `<option value="hist:${h.id}">🏁 ${escapeHtml(h.raceDate||'?')} · ${escapeHtml(h.raceName||'')}</option>`;
      });
      opts += '</optgroup>';
    }
  }catch(e){ console.warn('fccvPopulatePruebas histórico', e); }
  sel.innerHTML = opts;
}

async function _fccvOnPickPrueba(){
  const sel = document.getElementById('fccvGenPruebaSelect');
  const val = sel ? sel.value : '';
  if(!val) return;
  const [kind, id] = val.split(':');
  let extra = {}, name = '', dateStr = '';
  if(kind === 'planif'){
    if(!_sb) return;
    const {data} = await _sb.from('races').select('name, date, notes').eq('id', id).single();
    if(!data) return;
    name = data.name || '';
    dateStr = data.date || '';
    try{ extra = JSON.parse(data.notes||'{}'); }catch(e){}
  } else if(kind === 'hist'){
    const h = (_cachedHistory||[]).find(x => x.id === id);
    if(!h) return;
    name = h.raceName || '';
    dateStr = h.raceDate || '';
    extra = { localidad: h.localidad, circuitType: h.circuitType, hora_inicio: h.hora_inicio, km: h.km };
  }
  document.getElementById('fccvPRname').value     = name || '';
  document.getElementById('fccvPRfecha').value    = extra.raceDate || (formatDateDisplay(_parseSpanishDate(dateStr))) || dateStr || '';
  document.getElementById('fccvPRhora').value     = extra.hora_inicio || '';
  document.getElementById('fccvPRlugar').value    = extra.localidad || '';
  document.getElementById('fccvPRmodalidad').value= extra.modality || extra.modalidad || '';
  document.getElementById('fccvPRclase').value    = extra.circuitType || '';
  // categoria desde la prueba si la trae, si no inferida de filtros globales
  const inferCat = (typeof _globalFilters !== 'undefined' && _globalFilters && _globalFilters.cat) || '';
  document.getElementById('fccvPRcategoria').value= extra.categoria || extra.cat || inferCat || '';
}

function _fccvClearPrueba(){
  ['fccvPRname','fccvPRfecha','fccvPRhora','fccvPRlugar','fccvPRmodalidad','fccvPRclase','fccvPRcategoria'].forEach(id=>{
    const el = document.getElementById(id); if(el) el.value = '';
  });
  const sel = document.getElementById('fccvGenPruebaSelect'); if(sel) sel.value = '';
}

// ── Staff dropdowns ──
function _fccvPopulateStaff(){
  const all = _fccvGetLicencias();
  const staff = all.filter(l => l.tipo === 'staff').sort((a,b)=>{
    const ka = ((a.apellidos||'')+' '+(a.nombre||'')).toLowerCase();
    const kb = ((b.apellidos||'')+' '+(b.nombre||'')).toLowerCase();
    return ka.localeCompare(kb,'es');
  });
  const fillSelect = (id, isOptional) => {
    const el = document.getElementById(id);
    if(!el) return;
    const placeholder = isOptional ? '— Ninguno —' : '— Selecciona —';
    let html = `<option value="">${placeholder}</option>`;
    staff.forEach(l => {
      const role = (l.catLicencia||'').replace(/^[A-Z]+\s*/,'') || 'Staff';
      const label = `${l.apellidos||''}, ${l.nombre||''} — ${l.catLicencia||'Staff'}`;
      html += `<option value="${escapeAttr(l.dni)}">${escapeHtml(label)}</option>`;
    });
    el.innerHTML = html;
  };
  fillSelect('fccvStaffDir', false);
  fillSelect('fccvStaffAux1', true);
  fillSelect('fccvStaffAux2', true);
}

// ── Selección de ciclistas ──
function _fccvSetCat(cat){
  _fccvSelCat = cat;
  const btnC = document.getElementById('fccvCatBtnCad');
  const btnJ = document.getElementById('fccvCatBtnJuv');
  if(btnC) btnC.classList.toggle('active', cat==='cadete');
  if(btnJ) btnJ.classList.toggle('active', cat==='juvenil');
  const lbl = document.getElementById('fccvAvailLabel');
  if(lbl) lbl.textContent = `Disponibles · ${cat==='cadete'?'Cadetes':'Juveniles'}`;
  _fccvRenderAvail();
}

function _fccvRenderAvail(){
  const wrap = document.getElementById('fccvAvailList');
  const cntEl = document.getElementById('fccvAvailCount');
  if(!wrap) return;
  const q = (document.getElementById('fccvAvailSearch')?.value||'').toLowerCase().trim();
  const all = _fccvGetLicencias();
  const filtered = all
    .filter(l => l.tipo === _fccvSelCat)
    .filter(l => {
      if(!q) return true;
      const blob = [l.apellidos, l.nombre, l.dni, l.uciId, l.equipo, l.catLicencia].join(' ').toLowerCase();
      return blob.includes(q);
    })
    .sort((a,b)=>{
      const ka = ((a.apellidos||'')+' '+(a.nombre||'')).toLowerCase();
      const kb = ((b.apellidos||'')+' '+(b.nombre||'')).toLowerCase();
      return ka.localeCompare(kb,'es');
    });
  if(cntEl) cntEl.textContent = `${filtered.length} corredor${filtered.length===1?'':'es'}`;
  if(!filtered.length){
    wrap.innerHTML = `<div style="padding:18px;text-align:center;color:#9ca3af;font-size:12px">${all.filter(l=>l.tipo===_fccvSelCat).length===0?'No hay '+_fccvSelCat+'s importados aún.':'Sin resultados con ese filtro.'}</div>`;
    return;
  }
  const selSet = new Set([..._fccvSel.titulares, ..._fccvSel.reservas]);
  wrap.innerHTML = filtered.map(l => {
    const isSel = selSet.has(l.dni);
    return `<div class="fccv-avail-row ${isSel?'fccv-already':''}">
      <div class="fccv-avail-name"><b>${escapeHtml(l.apellidos||'')}, ${escapeHtml(l.nombre||'')}</b>
        <span style="color:#9ca3af;font-size:10.5px"> · ${escapeHtml(l.equipo||'(sin equipo)')}</span>
      </div>
      ${isSel
        ? '<span style="font-size:10px;color:#0ea5e9;font-weight:800">YA SELECCIONADO</span>'
        : `<button class="fccv-mini-btn fccv-btn-tit" onclick="_fccvAdd('titular','${escapeAttr(l.dni)}')">T+</button>
           <button class="fccv-mini-btn fccv-btn-res" onclick="_fccvAdd('reserva','${escapeAttr(l.dni)}')">R+</button>`}
    </div>`;
  }).join('');
}

function _fccvAdd(slot, dni){
  if(!dni) return;
  if(_fccvSel.titulares.includes(dni) || _fccvSel.reservas.includes(dni)) return;
  // Sin bloqueo: el "cupo" es solo informativo. El director sabe mejor que
  // nadie cuántos puede llevar a cada prueba (algunas no tienen límite,
  // el CRI no tiene reservas, etc.). Si supera el cupo se ve en rojo en
  // el panel de seleccionados pero NO se le impide añadir más.
  if(slot === 'titular'){
    _fccvSel.titulares.push(dni);
  } else {
    _fccvSel.reservas.push(dni);
  }
  _fccvRenderAvail();
  _fccvRenderSelected();
}

// Presets de cupo: ajustan rápido los inputs para los casos típicos.
function _fccvPresetCRI(){
  const t = document.getElementById('fccvMaxT'); if(t) t.value = 18;
  const r = document.getElementById('fccvMaxR'); if(r) r.value = 0;
  _fccvRenderSelected();
  if(typeof showToast==='function') showToast('🛣️ Modo CRI · cupo 18 + 0. Mete todos los ciclistas como TITULARES en el orden de salida.','ok',4000);
}
function _fccvPresetBoletin(){
  const t = document.getElementById('fccvMaxT'); if(t) t.value = 8;
  const r = document.getElementById('fccvMaxR'); if(r) r.value = 4;
  _fccvRenderSelected();
  if(typeof showToast==='function') showToast('📋 Modo Boletín · cupo 8 titulares + 4 reservas (formato FCCV estándar).','ok',3500);
}

function _fccvRemoveSel(dni){
  _fccvSel.titulares = _fccvSel.titulares.filter(d => d !== dni);
  _fccvSel.reservas = _fccvSel.reservas.filter(d => d !== dni);
  _fccvRenderAvail();
  _fccvRenderSelected();
}

function _fccvMove(slot, dni, direction){
  const arr = slot==='titular' ? _fccvSel.titulares : _fccvSel.reservas;
  const i = arr.indexOf(dni);
  if(i < 0) return;
  const j = direction==='up' ? i-1 : i+1;
  if(j < 0 || j >= arr.length) return;
  [arr[i], arr[j]] = [arr[j], arr[i]];
  _fccvRenderSelected();
}

function _fccvClearSel(){
  _fccvSel = { titulares: [], reservas: [] };
  _fccvRenderAvail();
  _fccvRenderSelected();
}

function _fccvRenderSelected(){
  const wrap = document.getElementById('fccvSelList');
  const hdr = document.getElementById('fccvSelHeader');
  if(!wrap) return;
  const maxT = parseInt(document.getElementById('fccvMaxT')?.value)||8;
  const maxR = parseInt(document.getElementById('fccvMaxR')?.value)||4;
  if(hdr){
    // Color: rojo si sobra (más de los del cupo), verde si llega justo,
    // azul si va por debajo del cupo, gris si vacío. El cupo es solo
    // referencia — el director puede meter los que quiera.
    const colorFor = (n, max) => {
      if(n === 0) return '#9ca3af';
      if(max > 0 && n > max) return '#dc2626';   // ojo, supera el cupo
      if(max > 0 && n === max) return '#15803d'; // cupo completo justo
      return '#1d4ed8';
    };
    const tColor = colorFor(_fccvSel.titulares.length, maxT);
    const rColor = colorFor(_fccvSel.reservas.length, maxR);
    hdr.innerHTML = `Seleccionados · <span style="color:${tColor}">${_fccvSel.titulares.length}/${maxT} titulares</span> · <span style="color:${rColor}">${_fccvSel.reservas.length}/${maxR} reservas</span>`;
  }
  const all = _fccvGetLicencias();
  const byDni = new Map(all.map(l => [l.dni, l]));
  const renderSlot = (dnis, slotName) => {
    return dnis.map((dni, i) => {
      const l = byDni.get(dni);
      if(!l) return `<div class="fccv-sel-row" style="background:#fee2e2"><span class="fccv-sel-num">${i+1}</span><span class="fccv-sel-name">?? ${escapeHtml(dni)} (eliminado)</span><button class="fccv-sel-rm" onclick="_fccvRemoveSel('${escapeAttr(dni)}')">×</button></div>`;
      return `<div class="fccv-sel-row">
        <span class="fccv-sel-num">${i+1}</span>
        <div style="flex:1;min-width:0">
          <div class="fccv-sel-name">${escapeHtml(l.apellidos||'')}, ${escapeHtml(l.nombre||'')}</div>
          <div class="fccv-sel-meta">${escapeHtml(l.equipo||'')}${l.catLicencia?' · '+escapeHtml(l.catLicencia):''}${l.uciId?' · UCI '+escapeHtml(l.uciId):''}</div>
        </div>
        <button class="fccv-mini-btn fccv-btn-tit" title="Subir" onclick="_fccvMove('${slotName}','${escapeAttr(dni)}','up')" style="padding:2px 5px">↑</button>
        <button class="fccv-mini-btn fccv-btn-tit" title="Bajar" onclick="_fccvMove('${slotName}','${escapeAttr(dni)}','down')" style="padding:2px 5px">↓</button>
        <button class="fccv-sel-rm" onclick="_fccvRemoveSel('${escapeAttr(dni)}')">×</button>
      </div>`;
    }).join('');
  };
  let html = '';
  html += `<div class="fccv-sect-title">🟢 Titulares (${_fccvSel.titulares.length}/${maxT})</div>`;
  html += _fccvSel.titulares.length ? renderSlot(_fccvSel.titulares, 'titular') : '<div style="font-size:11px;color:#9ca3af;padding:4px 6px">Pulsa T+ en la columna izquierda para añadir titulares.</div>';
  html += `<div class="fccv-sect-title" style="color:#92400e;margin-top:14px">🟡 Reservas (${_fccvSel.reservas.length}/${maxR})</div>`;
  html += _fccvSel.reservas.length ? renderSlot(_fccvSel.reservas, 'reserva') : '<div style="font-size:11px;color:#9ca3af;padding:4px 6px">Pulsa R+ en la columna izquierda para añadir reservas.</div>';
  wrap.innerHTML = html;
}

// ── Generación PDF ──
function _fccvDniToLic(dni){ return _fccvGetLicencias().find(l => l.dni === dni); }

function _fccvFullName(lic){
  return `${(lic.apellidos||'').trim()}, ${(lic.nombre||'').trim()}`.replace(/^, $/,'(sin nombre)');
}

// Resuelve la categoría ESPECÍFICA (CAD-1, CAD-2, JUN-1, JUN-2…) de un
// ciclista. La columna "Cat. Licencia" del Excel suele decir solo "CADETE"
// o "JUVENIL" en genérico, pero en el Boletín hace falta la versión con
// dígito porque los premios se reparten por años (cadete-1 vs cadete-2).
// Buscamos al ciclista en el histórico de la app (race_results) y nos
// quedamos con la categoría con dígito MÁS FRECUENTE del año en curso.
// Si no hay datos suficientes, devolvemos la genérica del Excel.
function _fccvResolveSpecificCat(lic){
  if(!lic) return '';
  const generic = (lic.catLicencia||'').trim();
  try{
    const hist = (typeof _cachedHistory!=='undefined' && Array.isArray(_cachedHistory)) ? _cachedHistory : [];
    if(!hist.length) return generic;
    // Clave de matching: apellido + nombre (normalizado, sin tildes, primer apellido).
    const key = (typeof normalizeForMatching==='function')
      ? normalizeForMatching(`${lic.apellidos||''}, ${lic.nombre||''}`)
      : `${(lic.apellidos||'').toLowerCase()}, ${(lic.nombre||'').toLowerCase()}`;
    if(!key) return generic;
    // Recorremos riders e inscritos de cada carrera. Priorizamos riders
    // (clasificación oficial) porque traen la categoría más fiable.
    const cats = new Map(); // catEspecífica → contador
    const ingest = (r) => {
      const nk = (typeof normalizeForMatching==='function') ? normalizeForMatching(r.name||'') : (r.name||'').toLowerCase();
      if(nk !== key) return;
      const c = (r.cat||'').trim();
      if(!c) return;
      // Solo nos interesan las que tienen dígito (las específicas)
      if(!/\d/.test(c)) return;
      cats.set(c, (cats.get(c)||0)+1);
    };
    for(const race of hist){
      (race.riders||[]).forEach(ingest);
      (race.inscritos||[]).forEach(ingest);
    }
    if(!cats.size) return generic;
    // Devolver la más frecuente
    const sorted = [...cats.entries()].sort((a,b)=>b[1]-a[1]);
    return sorted[0][0];
  }catch(e){
    console.warn('_fccvResolveSpecificCat', e);
    return generic;
  }
}

function _fccvSetField(form, fieldName, value){
  if(value == null || value === '') return;
  try{
    const f = form.getTextField(fieldName);
    f.setText(String(value));
  }catch(e){ console.warn('Campo no encontrado:', fieldName); }
}

async function _fccvLoadTemplate(url){
  const resp = await fetch(url);
  if(!resp.ok) throw new Error('No se pudo cargar la plantilla: '+url+' ('+resp.status+')');
  return await resp.arrayBuffer();
}

function _fccvSanitizeFileName(s){
  return String(s||'').replace(/[\\\/:*?"<>|]/g,'_').replace(/\s+/g,'_').slice(0,80) || 'documento';
}

function _fccvDownloadPdf(bytes, filename){
  const blob = new Blob([bytes], { type:'application/pdf' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click();
  setTimeout(()=>{ document.body.removeChild(a); URL.revokeObjectURL(url); }, 200);
}

// Marca un campo con borde rojo y mensaje. ids puede ser string o array.
function _fccvFlagFields(ids){
  // Limpiar marcas previas
  document.querySelectorAll('.fccv-error-field').forEach(el=>{
    el.classList.remove('fccv-error-field');
    el.style.boxShadow = '';
    el.style.borderColor = '';
  });
  if(!ids || !ids.length) return;
  const arr = Array.isArray(ids) ? ids : [ids];
  let firstEl = null;
  arr.forEach(id => {
    const el = document.getElementById(id);
    if(!el) return;
    el.classList.add('fccv-error-field');
    el.style.boxShadow = '0 0 0 3px rgba(220,38,38,.25)';
    el.style.borderColor = '#dc2626';
    if(!firstEl) firstEl = el;
  });
  if(firstEl){
    firstEl.scrollIntoView({behavior:'smooth', block:'center'});
    setTimeout(()=>{ try{ firstEl.focus(); }catch(e){} }, 350);
  }
}

// Devuelve { errors:[texto…], fields:[ids…] } con todos los campos obligatorios
// que faltan. Si hay errores, además los muestra con alerta visible Y los
// resalta con borde rojo en el formulario, haciendo scroll al primero.
function _fccvValidateBasics(opts){
  const reqAutoriz = !opts || opts.doc !== 'boletin';
  // (los dos PDFs comparten los mismos campos obligatorios; mantengo el flag
  //  por si en el futuro alguno tiene requerimientos distintos)
  const errors = [];
  const missingFields = [];
  const add = (msg, id) => { errors.push(msg); if(id) missingFields.push(id); };

  // Firmante (común a ambos documentos)
  const firm = _fccvGetFirmante();
  if(!firm.nombre)    { add('Falta el NOMBRE del firmante (ve a "Licencias y firmante")', null); }
  if(!firm.cargo)     { add('Falta el CARGO del firmante (Presidenta/Presidente…)', null); }
  if(!firm.equipo)    { add('Falta el EQUIPO del firmante', null); }
  if(!firm.localidad) { add('Falta la LOCALIDAD del firmante', null); }
  if(reqAutoriz){
    if(!firm.telefono) { add('Falta el TELÉFONO del firmante (necesario para la Autorización)', null); }
    if(!firm.email)    { add('Falta el EMAIL del firmante (necesario para la Autorización)', null); }
  }

  // Datos de la prueba
  if(!document.getElementById('fccvPRname')?.value.trim())     add('Falta el NOMBRE de la prueba', 'fccvPRname');
  if(!document.getElementById('fccvPRfecha')?.value.trim())    add('Falta la FECHA de la prueba', 'fccvPRfecha');
  if(reqAutoriz && !document.getElementById('fccvPRlugar')?.value.trim()) add('Falta el LUGAR/Localidad de la prueba', 'fccvPRlugar');
  // Modalidad y Clase NO son obligatorias. A veces hay que mandar la
  // inscripción sin tener todavía el reglamento publicado. Quedan en
  // blanco en el PDF y el director las rellena a mano más tarde si
  // hace falta.
  if(!document.getElementById('fccvPRcategoria')?.value.trim()) add('Falta la CATEGORÍA (Cadete, Juvenil…)', 'fccvPRcategoria');

  // Staff
  if(!document.getElementById('fccvStaffDir')?.value) add('Falta el DIRECTOR DEPORTIVO', 'fccvStaffDir');

  // Ciclistas
  if(!_fccvSel.titulares.length) add('No hay ningún ciclista TITULAR seleccionado', 'fccvAvailList');

  return { errors, fields: missingFields };
}

// Muestra los errores de validación: alerta + borde rojo + scroll.
function _fccvShowValidationErrors(result, docLabel){
  const { errors, fields } = result;
  if(!errors.length) return false;
  _fccvFlagFields(fields);
  const list = errors.map(e => '  • ' + e).join('\n');
  alert(`No se puede generar ${docLabel || 'el documento'}.\n\nFalta rellenar:\n\n${list}\n\nLos campos vacíos en rojo en el formulario son los que faltan.\nLos datos del firmante se rellenan en la pestaña "🪪 Licencias y firmante".`);
  _fccvGenStatus(`❌ Faltan ${errors.length} campo${errors.length===1?'':'s'} por rellenar (mira la alerta)`, false);
  return true;
}

function _fccvGenStatus(msg, ok){
  const st = document.getElementById('fccvGenStatus');
  if(st) st.innerHTML = `<span style="color:${ok?'#15803d':'#b42318'};font-weight:700">${msg}</span>`;
}

async function _fccvGenerarBoletin(){
  if(typeof PDFLib === 'undefined'){ alert('La librería PDF aún no está cargada. Recarga la página (Ctrl/Cmd+Shift+R).'); return; }
  const v = _fccvValidateBasics({doc:'boletin'});
  if(_fccvShowValidationErrors(v, 'el Boletín de inscripción')) return;
  if(_fccvSel.titulares.length > 8 || _fccvSel.reservas.length > 4){
    const ok = confirm(`El Boletín FCCV solo tiene 8 plazas de titular y 4 de reserva.\n\nTienes seleccionados ${_fccvSel.titulares.length} titulares y ${_fccvSel.reservas.length} reservas.\n\nSe rellenarán solo los 8 primeros titulares y las 4 primeras reservas.\nEl resto se quedarán fuera de este documento.\n\n¿Continuar?`);
    if(!ok) return;
  }
  _fccvFlagFields(null); // limpiar bordes rojos previos si los hubiera
  _fccvGenStatus('⏳ Generando Boletín…', true);
  try{
    const buf = await _fccvLoadTemplate(FCCV_TPL_BOLETIN);
    const pdf = await PDFLib.PDFDocument.load(buf);
    const form = pdf.getForm();
    const firm = _fccvGetFirmante();

    // Cabecera
    _fccvSetField(form, 'del equipo deportivo', firm.equipo||'');
    _fccvSetField(form, 'Nombre',    document.getElementById('fccvPRname').value);
    _fccvSetField(form, 'Clase',     document.getElementById('fccvPRclase').value);
    _fccvSetField(form, 'Categoría', document.getElementById('fccvPRcategoria').value);
    _fccvSetField(form, 'Fecha',     document.getElementById('fccvPRfecha').value);

    // Titulares (hasta 8 plazas con sufijo numérico simple)
    _fccvSel.titulares.slice(0,8).forEach((dni,i)=>{
      const lic = _fccvDniToLic(dni); if(!lic) return;
      const n = i+1;
      _fccvSetField(form, `NOMBRE DEL CORREDOR${n}`, _fccvFullName(lic));
      _fccvSetField(form, `LICENCIA${n}`,            lic.dni);
      _fccvSetField(form, `UCI ID${n}`,              lic.uciId);
      _fccvSetField(form, `CATEGORÍA${n}`,           _fccvResolveSpecificCat(lic));
    });

    // Reservas (mapeo irregular del PDF original):
    // R1 → name='1', lic='RESERVA1',   uci='UCI ID5RES', cat='CATEGORÍA5RES'
    // R2 → name='2', lic='LICENCIA6RES', uci='UCI ID6RES', cat='CATEGORÍA6RES'
    // R3 → name='3', lic='LICENCIA7RES', uci='UCI ID7RES', cat='CATEGORÍA7RES'
    // R4 → name='4', lic='LICENCIA8RES', uci='UCI ID8RES', cat='CATEGORÍA8RES'
    const RES_MAP = [
      { name:'1', lic:'RESERVA1',    uci:'UCI ID5RES', cat:'CATEGORÍA5RES' },
      { name:'2', lic:'LICENCIA6RES', uci:'UCI ID6RES', cat:'CATEGORÍA6RES' },
      { name:'3', lic:'LICENCIA7RES', uci:'UCI ID7RES', cat:'CATEGORÍA7RES' },
      { name:'4', lic:'LICENCIA8RES', uci:'UCI ID8RES', cat:'CATEGORÍA8RES' }
    ];
    _fccvSel.reservas.slice(0,4).forEach((dni,i)=>{
      const lic = _fccvDniToLic(dni); if(!lic) return;
      const m = RES_MAP[i]; if(!m) return;
      _fccvSetField(form, m.name, _fccvFullName(lic));
      _fccvSetField(form, m.lic,  lic.dni);
      _fccvSetField(form, m.uci,  lic.uciId);
      _fccvSetField(form, m.cat,  _fccvResolveSpecificCat(lic));
    });

    // Directores (hasta 2):
    // D1 → name='1_2', lic='DD1',          uci='UCI ID5RDD', cat='CATEGORÍA5RDD'
    // D2 → name='2_2', lic='LICENCIA6RDD',  uci='UCI ID6RDD', cat='CATEGORÍA6RDD'
    const DD_MAP = [
      { name:'1_2', lic:'DD1',            uci:'UCI ID5RDD', cat:'CATEGORÍA5RDD' },
      { name:'2_2', lic:'LICENCIA6RDD',   uci:'UCI ID6RDD', cat:'CATEGORÍA6RDD' }
    ];
    const dirDni = document.getElementById('fccvStaffDir').value;
    const aux1Dni = document.getElementById('fccvStaffAux1').value;
    const dirs = [dirDni, aux1Dni].filter(Boolean).slice(0,2);
    dirs.forEach((dni,i)=>{
      const lic = _fccvDniToLic(dni); if(!lic) return;
      const m = DD_MAP[i]; if(!m) return;
      _fccvSetField(form, m.name, _fccvFullName(lic));
      _fccvSetField(form, m.lic,  lic.dni);
      _fccvSetField(form, m.uci,  lic.uciId);
      _fccvSetField(form, m.cat,  lic.catLicencia);
    });

    // Pie del Boletín — firmante
    _fccvSetField(form, 'Don',           firm.nombre||'');
    _fccvSetField(form, 'en calidad de', firm.cargo||'');
    const lugarFechaBoletin = [firm.localidad||'', new Date().toLocaleDateString('es-ES')].filter(Boolean).join(', ');
    _fccvSetField(form, 'Lugar y fecha', lugarFechaBoletin);

    try{ form.updateFieldAppearances(); }catch(e){}
    // Si el usuario pidió documento final no editable, aplanamos el formulario:
    // los campos pasan a ser texto fijo del documento (no se pueden editar y
    // los iconos de "campo editable" del visor desaparecen).
    if(document.getElementById('fccvFlatten')?.checked){
      try{ form.flatten(); }catch(e){ console.warn('flatten falló', e); }
    }
    const bytes = await pdf.save();
    const dateTag = _fccvSanitizeFileName(document.getElementById('fccvPRfecha').value);
    const nameTag = _fccvSanitizeFileName(document.getElementById('fccvPRname').value);
    _fccvDownloadPdf(bytes, `Boletin_${dateTag}_${nameTag}.pdf`);
    _fccvGenStatus('✅ Boletín generado y descargado', true);
  }catch(e){
    console.warn('_fccvGenerarBoletin', e);
    _fccvGenStatus('❌ Error: '+(e.message||e), false);
  }
}

async function _fccvGenerarAutorizacion(){
  if(typeof PDFLib === 'undefined'){ alert('La librería PDF aún no está cargada. Recarga la página (Ctrl/Cmd+Shift+R).'); return; }
  const v = _fccvValidateBasics({doc:'autorizacion'});
  if(_fccvShowValidationErrors(v, 'la Autorización de desplazamiento')) return;
  const totalAuth = _fccvSel.titulares.length + _fccvSel.reservas.length;
  if(totalAuth > 15){
    const ok = confirm(`La Autorización FCCV tiene 15 plazas de ciclistas.\n\nTienes ${totalAuth} seleccionados (${_fccvSel.titulares.length} titulares + ${_fccvSel.reservas.length} reservas).\n\nSe rellenarán solo los 15 primeros (titulares antes que reservas).\nEl resto se quedarán fuera de este documento.\n\n¿Continuar?`);
    if(!ok) return;
  }
  _fccvFlagFields(null);
  _fccvGenStatus('⏳ Generando Autorización…', true);
  try{
    const buf = await _fccvLoadTemplate(FCCV_TPL_AUTORIZ);
    const pdf = await PDFLib.PDFDocument.load(buf);
    const form = pdf.getForm();
    const firm = _fccvGetFirmante();

    // Datos prueba
    _fccvSetField(form, 'Nombre de l a Prueba', document.getElementById('fccvPRname').value);
    _fccvSetField(form, 'Lugar',                document.getElementById('fccvPRlugar').value);
    _fccvSetField(form, 'Modal i dad',          document.getElementById('fccvPRmodalidad').value);
    _fccvSetField(form, 'Clase',                document.getElementById('fccvPRclase').value);
    _fccvSetField(form, 'Categorías',           document.getElementById('fccvPRcategoria').value);
    _fccvSetField(form, 'Fechas',               document.getElementById('fccvPRfecha').value);
    _fccvSetField(form, 'Hora',                 document.getElementById('fccvPRhora').value);

    // Equipo del club (mismo que firmante)
    _fccvSetField(form, 'EquipoC l ub', firm.equipo||'');

    // Director y auxiliares
    const dirLic = _fccvDniToLic(document.getElementById('fccvStaffDir').value);
    if(dirLic){
      _fccvSetField(form, 'D i rector Deport i vo', _fccvFullName(dirLic));
      _fccvSetField(form, 'Licenc i a',             dirLic.dni);
    }
    const aux1 = _fccvDniToLic(document.getElementById('fccvStaffAux1').value);
    if(aux1){
      _fccvSetField(form, 'Personal aux i l i ar', _fccvFullName(aux1));
      _fccvSetField(form, 'Licenc i a_2',          aux1.dni);
    }
    const aux2 = _fccvDniToLic(document.getElementById('fccvStaffAux2').value);
    if(aux2){
      _fccvSetField(form, 'Personal aux i l i ar_2', _fccvFullName(aux2));
      _fccvSetField(form, 'Licenc i a_3',            aux2.dni);
    }

    // Corredores (15 plazas, TODOS los que viajan = titulares + reservas)
    // La nueva versión de la plantilla añade una columna Dorsal a la
    // izquierda; el dorsal lo resolvemos desde el histórico igual que en
    // el CRI. Si el ciclista no tiene dorsal en histórico, queda en blanco.
    const todos = [..._fccvSel.titulares, ..._fccvSel.reservas].slice(0,15);
    todos.forEach((dni, i)=>{
      const lic = _fccvDniToLic(dni); if(!lic) return;
      const row = i+1;
      _fccvSetField(form, `Dorsal ${row}`,                  _fccvResolveBib(lic));
      _fccvSetField(form, `Nombre y Apel l i dosRow${row}`, _fccvFullName(lic));
      _fccvSetField(form, `Licenc i aRow${row}`,            lic.dni);
      _fccvSetField(form, `Código UCIRow${row}`,            lic.uciId);
    });

    // Firmante
    _fccvSetField(form, 'Nombre del que firma',   firm.nombre||'');
    _fccvSetField(form, 'F i rmado',              firm.cargo||'');
    _fccvSetField(form, 'Telefono del que firma', firm.telefono||'');
    _fccvSetField(form, 'e-mail del que firma',   firm.email||'');
    const lugarFechaAut = [firm.localidad||'', new Date().toLocaleDateString('es-ES')].filter(Boolean).join(', ');
    _fccvSetField(form, 'Lugar y FEcha',          lugarFechaAut);

    try{ form.updateFieldAppearances(); }catch(e){}
    // Si el usuario pidió documento final no editable, aplanamos el formulario:
    // los campos pasan a ser texto fijo del documento (no se pueden editar y
    // los iconos de "campo editable" del visor desaparecen).
    if(document.getElementById('fccvFlatten')?.checked){
      try{ form.flatten(); }catch(e){ console.warn('flatten falló', e); }
    }
    const bytes = await pdf.save();
    const dateTag = _fccvSanitizeFileName(document.getElementById('fccvPRfecha').value);
    const nameTag = _fccvSanitizeFileName(document.getElementById('fccvPRname').value);
    _fccvDownloadPdf(bytes, `Autorizacion_${dateTag}_${nameTag}.pdf`);
    _fccvGenStatus('✅ Autorización generada y descargada', true);
  }catch(e){
    console.warn('_fccvGenerarAutorizacion', e);
    _fccvGenStatus('❌ Error: '+(e.message||e), false);
  }
}

async function _fccvGenerarAmbos(){
  await _fccvGenerarBoletin();
  await new Promise(r => setTimeout(r, 350));
  await _fccvGenerarAutorizacion();
  _fccvGenStatus('✅ Los dos documentos se han generado y descargado', true);
}

// ════════════════════════════════════════════════════════════════════════
// MÓDULO FCCV — Inscripción Contrarreloj por equipos (CRI)
//   Tercer documento, independiente del Boletín y la Autorización.
//   18 plazas, datos: prueba, equipo, categoría, matrículas coches
//   seguidores, director, ciclistas con dorsal+nombre+licencia.
// ════════════════════════════════════════════════════════════════════════

const FCCV_TPL_CRI = 'assets/templates/cri-fccv.pdf';

// (los helpers _isCVRace / _CV_LOCS están definidos arriba, antes de
//  _postProcessInscritos, porque también los usa el enriquecimiento al
//  pegar inscritos. Aquí solo reutilizamos.)

// Resuelve el dorsal OFICIAL de la Comunidad Valenciana del ciclista.
// IMPORTANTE: en CV cada ciclista tiene un dorsal anual fijo que se usa
// en TODAS las pruebas autonómicas. Cuando viajan fuera (p.ej. Villarrobledo)
// el organizador asigna un dorsal temporal distinto que NO debemos usar
// para los documentos federativos. Por eso filtramos a carreras CV y
// elegimos el dorsal más reciente y más frecuente dentro de ellas.
function _fccvResolveBib(lic){
  if(!lic) return '';
  try{
    const hist = (typeof _cachedHistory!=='undefined' && Array.isArray(_cachedHistory)) ? _cachedHistory : [];
    if(!hist.length) return '';
    const key = (typeof normalizeForMatching==='function')
      ? normalizeForMatching(`${lic.apellidos||''}, ${lic.nombre||''}`)
      : `${(lic.apellidos||'').toLowerCase()}, ${(lic.nombre||'').toLowerCase()}`;
    if(!key) return '';

    // Recolectar todos los dorsales del ciclista, anotando:
    //   cv      : true | false | null (CCAA de la carrera)
    //   source  : 'riders' (clasificación oficial) | 'inscritos' (puede estar
    //             contaminado por enriquecimientos antiguos no-CV)
    //   date    : ISO de la carrera
    const found = []; // [{bib, date, cv, source}]
    const collect = (r, race, source) => {
      if(!r || !r.bib) return;
      const nk = (typeof normalizeForMatching==='function') ? normalizeForMatching(r.name||'') : (r.name||'').toLowerCase();
      if(nk !== key) return;
      const iso = (typeof _parseSpanishDate==='function' ? _parseSpanishDate(race.raceDate||'') : '') || '';
      found.push({ bib: String(r.bib), date: iso, cv: _isCVRace(race), source });
    };
    for(const race of hist){
      (race.riders||[]).forEach(r => collect(r, race, 'riders'));
      (race.inscritos||[]).forEach(r => collect(r, race, 'inscritos'));
    }
    if(!found.length) return '';

    // Helper: moda de bibs (más frecuente, desempate por fecha más reciente).
    const modeBib = (arr) => {
      if(!arr.length) return '';
      const counts = new Map();
      const dates  = new Map();
      arr.forEach(f => {
        counts.set(f.bib, (counts.get(f.bib)||0)+1);
        const prev = dates.get(f.bib)||'';
        if(f.date > prev) dates.set(f.bib, f.date);
      });
      const sorted = [...counts.entries()].sort((a,b)=>{
        if(b[1] !== a[1]) return b[1]-a[1];
        return (dates.get(b[0])||'').localeCompare(dates.get(a[0])||'');
      });
      return sorted[0][0];
    };

    // 1) Carreras CV confirmadas. Damos prioridad MUY ALTA a los riders
    //    (clasificación oficial) sobre los inscritos, porque los inscritos
    //    pueden estar contaminados por enriquecimientos antiguos pre-CCAA
    //    que metieron dorsales no-CV en pruebas CV.
    const cvRiders    = found.filter(f => f.cv === true  && f.source === 'riders');
    const cvInscritos = found.filter(f => f.cv === true  && f.source === 'inscritos');
    if(cvRiders.length) return modeBib(cvRiders);
    if(cvInscritos.length) return modeBib(cvInscritos);

    // 2) Sin carreras CV identificadas pero hay inciertas (CCAA sin marcar).
    //    Aquí también priorizamos riders sobre inscritos por la misma razón.
    const uncRiders    = found.filter(f => f.cv === null && f.source === 'riders');
    const uncInscritos = found.filter(f => f.cv === null && f.source === 'inscritos');
    if(uncRiders.length){
      uncRiders.sort((a,b)=>b.date.localeCompare(a.date));
      return uncRiders[0].bib;
    }
    if(uncInscritos.length){
      uncInscritos.sort((a,b)=>b.date.localeCompare(a.date));
      return uncInscritos[0].bib;
    }
    // 3) Solo hay dorsales de carreras NO-CV: blanco (el director lo escribe).
    return '';
  }catch(e){
    console.warn('_fccvResolveBib', e);
    return '';
  }
}

// Validación específica para CRI: requiere algunos campos diferentes del
// Boletín/Autorización (no se necesita email/teléfono del firmante).
function _fccvValidateCRI(){
  const errors = [];
  const missingFields = [];
  const add = (msg, id) => { errors.push(msg); if(id) missingFields.push(id); };

  const firm = _fccvGetFirmante();
  if(!firm.nombre)    add('Falta el NOMBRE del firmante (ve a "Licencias y firmante")', null);
  if(!firm.equipo)    add('Falta el EQUIPO del firmante', null);

  if(!document.getElementById('fccvPRname')?.value.trim())      add('Falta el NOMBRE de la prueba', 'fccvPRname');
  if(!document.getElementById('fccvPRfecha')?.value.trim())     add('Falta la FECHA de la prueba', 'fccvPRfecha');
  if(!document.getElementById('fccvPRlugar')?.value.trim())     add('Falta el LUGAR/Localidad de la prueba', 'fccvPRlugar');
  if(!document.getElementById('fccvPRcategoria')?.value.trim()) add('Falta la CATEGORÍA (Cadete, Juvenil…)', 'fccvPRcategoria');

  if(!document.getElementById('fccvStaffDir')?.value) add('Falta el DIRECTOR DEPORTIVO', 'fccvStaffDir');

  if(!_fccvSel.titulares.length) add('No hay ningún ciclista TITULAR seleccionado', 'fccvAvailList');

  return { errors, fields: missingFields };
}

function _fccvSplitFecha(s){
  if(!s) return { dia:'', mes:'', anio:'' };
  let m = String(s).match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})$/);
  if(m){
    let [_,d,mo,y] = m;
    if(y.length===2) y = (parseInt(y)>30?'19':'20')+y;
    return { dia:String(parseInt(d)), mes:String(parseInt(mo)), anio:y };
  }
  m = String(s).match(/^(\d{4})[\/\-\.](\d{1,2})[\/\-\.](\d{1,2})/);
  if(m){
    return { dia:String(parseInt(m[3])), mes:String(parseInt(m[2])), anio:m[1] };
  }
  return { dia:'', mes:'', anio:'' };
}

async function _fccvGenerarCRI(){
  if(typeof PDFLib === 'undefined'){ alert('La librería PDF aún no está cargada. Recarga la página (Ctrl/Cmd+Shift+R).'); return; }
  const v = _fccvValidateCRI();
  if(_fccvShowValidationErrors(v, 'la Inscripción CRI')) return;
  const totalCRI = _fccvSel.titulares.length + _fccvSel.reservas.length;
  if(totalCRI > 18){
    const ok = confirm(`El CRI tiene 18 plazas.\n\nTienes ${totalCRI} seleccionados.\n\nSe rellenarán solo los 18 primeros (titulares antes que reservas) en el orden de la lista.\nEl resto se quedarán fuera de este documento.\n\n¿Continuar?`);
    if(!ok) return;
  }
  _fccvFlagFields(null);
  _fccvGenStatus('⏳ Generando Inscripción CRI…', true);
  try{
    const buf = await _fccvLoadTemplate(FCCV_TPL_CRI);
    const pdf = await PDFLib.PDFDocument.load(buf);
    const form = pdf.getForm();
    const firm = _fccvGetFirmante();

    _fccvSetField(form, 'Nombre de la Prueba', document.getElementById('fccvPRname').value);
    // Los campos Localidad / Día / Mes / Año del PDF están en la zona de
    // FIRMA al pie, no son la fecha de la prueba sino "donde y cuándo se
    // firma el documento". Usamos la localidad del firmante (Castellón) y
    // la fecha del día en que se genera el informe — lo que la FCCV
    // espera ver cuando recibe el documento.
    const today = new Date();
    _fccvSetField(form, 'Localidad', firm.localidad||'');
    _fccvSetField(form, 'Día',       String(today.getDate()));
    _fccvSetField(form, 'Mes',       String(today.getMonth()+1));
    _fccvSetField(form, 'Año',       String(today.getFullYear()));
    _fccvSetField(form, 'Equipo/Club',          firm.equipo||'');
    _fccvSetField(form, 'Categoría del equipo', document.getElementById('fccvPRcategoria').value);
    // Matrículas: la plantilla tiene 3 cuadritos separados. Si el director
    // pone "1234-ABC, 5678-DEF, 9012-GHI" en el firmante, ponemos una
    // matrícula por cuadrito (1ª, 2ª, 3ª). Si pone solo una o dos, los
    // huecos sobrantes quedan vacíos.
    const matriculas = (firm.matriculas||'').split(/[,;]/).map(s=>s.trim()).filter(Boolean);
    if(matriculas[0]) _fccvSetField(form, 'Matrículas Coches Seguidoras Campeonato', matriculas[0]);
    if(matriculas[1]) _fccvSetField(form, 'Matrícula 2', matriculas[1]);
    if(matriculas[2]) _fccvSetField(form, 'Matrícula 3', matriculas[2]);

    const dirLic = _fccvDniToLic(document.getElementById('fccvStaffDir').value);
    if(dirLic){
      _fccvSetField(form, 'Nombre director deportivo', _fccvFullName(dirLic));
    }

    const todos = [..._fccvSel.titulares, ..._fccvSel.reservas].slice(0,18);
    todos.forEach((dni, i)=>{
      const lic = _fccvDniToLic(dni); if(!lic) return;
      const row = i+1;
      _fccvSetField(form, `Nombre y apellidos ${row}`, _fccvFullName(lic));
      _fccvSetField(form, `Nº LICENCIA ${row}`,        lic.dni);
      _fccvSetField(form, `Dorsal ${row}`,             _fccvResolveBib(lic));
    });

    _fccvSetField(form, 'Nombre Firma', firm.nombre||'');

    try{ form.updateFieldAppearances(); }catch(e){}
    if(document.getElementById('fccvFlatten')?.checked){
      try{ form.flatten(); }catch(e){ console.warn('flatten falló', e); }
    }
    const bytes = await pdf.save();
    const dateTag = _fccvSanitizeFileName(document.getElementById('fccvPRfecha').value);
    const nameTag = _fccvSanitizeFileName(document.getElementById('fccvPRname').value);
    _fccvDownloadPdf(bytes, `CRI_${dateTag}_${nameTag}.pdf`);
    _fccvGenStatus('✅ Inscripción CRI generada · revisa los dorsales (se prerellenan desde el histórico cuando hay datos)', true);
  }catch(e){
    console.warn('_fccvGenerarCRI', e);
    _fccvGenStatus('❌ Error: '+(e.message||e), false);
  }
}

// ── Chip "es CV / no es CV" debajo del campo Localidad de Carga y Resumen ──
// Avisa al director del contexto detectado por la heurística para que sepa
// si el enriquecimiento de dorsales vendrá del histórico CV o no.
function _cargaUpdateCVHint(){
  const el = document.getElementById('raceCVHint');
  if(!el) return;
  const ccaaSel = (document.getElementById('raceCCAA')?.value || '').trim();
  const cv = _isCurrentRaceCV();
  // Si hay marcador manual, lo decimos para que se vea que es decisión del director.
  const sourceTag = ccaaSel
    ? `<span style="color:#1d4ed8;font-weight:800"> · marcador manual</span>`
    : '<span style="color:#9ca3af;font-weight:600"> · auto-detectado</span>';
  if(cv === true){
    el.innerHTML = '<span style="color:#15803d">🟢 Prueba CV · los dorsales se rellenarán con el dorsal oficial CV del año</span>'+sourceTag;
  } else if(cv === false){
    el.innerHTML = '<span style="color:#9a3412">🟠 Prueba FUERA de la Comunitat Valenciana · los dorsales NO se rellenarán del histórico CV</span>'+sourceTag;
  } else {
    el.innerHTML = '<span style="color:#9ca3af">⚪ Sin marcador manual ni detección clara · se usará el comportamiento clásico. Marca la CCAA en el desplegable para evitar mezclas.</span>';
  }
}

// También actualizamos al cambiar el NOMBRE de la prueba (a veces lo
// nombramos "Comunitat Valenciana ..." y eso es señal suficiente).
(function(){
  const inp = document.getElementById('raceName');
  if(inp) inp.addEventListener('input', () => { try{ _cargaUpdateCVHint(); }catch(e){} });
  const sel = document.getElementById('raceCCAA');
  if(sel) sel.addEventListener('change', () => { try{ _cargaUpdateCVHint(); }catch(e){} });
  // Refrescar al cargar la app
  document.addEventListener('DOMContentLoaded', () => setTimeout(_cargaUpdateCVHint, 300));
})();

// ════════════════════════════════════════════════════════════════════════
// Gestor CCAA · Etiquetar pruebas guardadas en bloque
//   Carga todas las pruebas race_type=clasificacion del histórico y permite
//   asignarles una CCAA manual (extra.ccaa). Sirve para corregir el problema
//   de mezclas de dorsales sin tener que re-cargar prueba a prueba.
// ════════════════════════════════════════════════════════════════════════

const _CCAA_OPTS = ['Comunitat Valenciana','Castilla-La Mancha','Murcia','Cataluña','Aragón','Andalucía','Madrid','Castilla y León','Islas Baleares','País Vasco','Navarra','La Rioja','Galicia','Asturias','Cantabria','Extremadura','Canarias','Ceuta','Melilla'];

async function _ccaaOpenManager(){
  // Asegurar histórico
  if(!Array.isArray(_cachedHistory) || !_cachedHistory.length){
    if(typeof _sbLoadHistory === 'function') _cachedHistory = await _sbLoadHistory();
  }
  const hist = (Array.isArray(_cachedHistory) ? _cachedHistory : []).slice().sort((a,b)=>{
    const da = _parseSpanishDate(a.raceDate)||'0000-00-00';
    const db = _parseSpanishDate(b.raceDate)||'0000-00-00';
    return db.localeCompare(da);
  });

  let overlay = document.getElementById('_ccaaMgrOverlay');
  if(!overlay){
    overlay = document.createElement('div');
    overlay.id = '_ccaaMgrOverlay';
    overlay.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.6);z-index:10001;display:flex;align-items:center;justify-content:center;padding:20px';
    overlay.addEventListener('click', e => { if(e.target===overlay) _ccaaCloseManager(); });
    document.body.appendChild(overlay);
  }

  if(!hist.length){
    overlay.innerHTML = `<div style="background:#fff;border-radius:12px;padding:24px;text-align:center;max-width:480px">
      <div style="font-size:14px;color:#374151">No hay pruebas guardadas todavía.</div>
      <button class="btn light" style="margin-top:12px" onclick="_ccaaCloseManager()">Cerrar</button>
    </div>`;
    return;
  }

  const rows = hist.map(h => {
    const sel = h.ccaa || '';
    const guess = _isCVRace({localidad:h.localidad, raceName:h.raceName, riders:h.riders});
    const guessLbl = guess === true ? '🟢 sugerida CV' : (guess === false ? '🟠 sugerida fuera CV' : '⚪ incierta');
    const stateBadge = sel
      ? `<span style="background:#dbeafe;color:#1e3a8a;border:1px solid #93c5fd;border-radius:6px;padding:1px 7px;font-size:10px;font-weight:800">${escapeHtml(sel)}</span>`
      : `<span style="background:#f3f4f6;color:#6b7280;border:1px solid #d1d5db;border-radius:6px;padding:1px 7px;font-size:10px;font-weight:700">SIN ASIGNAR</span>`;
    const opts = '<option value="">— Sin asignar —</option>' + _CCAA_OPTS.map(c => `<option value="${escapeAttr(c)}" ${c===sel?'selected':''}>${escapeHtml(c)}</option>`).join('');
    return `<tr data-race-id="${escapeAttr(h.id)}">
      <td style="padding:6px 8px;font-size:12px;color:#475569">${escapeHtml(h.raceDate||'—')}</td>
      <td style="padding:6px 8px;font-size:12px"><b>${escapeHtml(h.raceName||'(sin nombre)')}</b><div style="font-size:10.5px;color:#6b7280">${escapeHtml(h.localidad||'(sin localidad)')} · ${guessLbl}</div></td>
      <td style="padding:6px 8px;text-align:center">${stateBadge}</td>
      <td style="padding:6px 8px">
        <select onchange="_ccaaSaveRow('${escapeAttr(h.id)}', this.value, this)" style="padding:4px 8px;border:1.5px solid #d0d5dd;border-radius:6px;font-size:12px;width:100%;max-width:200px">
          ${opts}
        </select>
      </td>
    </tr>`;
  }).join('');

  overlay.innerHTML = `
    <div style="background:#fff;border-radius:14px;max-width:920px;width:100%;max-height:88vh;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.4)">
      <div style="padding:14px 18px;border-bottom:1px solid #e5e7eb;display:flex;justify-content:space-between;align-items:flex-start;gap:10px">
        <div>
          <div style="font-weight:800;font-size:16px;color:#0b2f6b">🗂 Etiquetar CCAA de pruebas guardadas</div>
          <div style="font-size:11.5px;color:#6b7280;margin-top:3px">
            Marca la CCAA donde se celebró cada prueba. La CCAA <b>manual</b> tiene prioridad sobre la auto-detección, y se usa para decidir qué dorsales son CV (oficiales del año) y cuáles son temporales del organizador.<br>
            Cambios se guardan al instante en Supabase.
          </div>
        </div>
        <button class="btn light" onclick="_ccaaCloseManager()" style="font-size:12px;padding:5px 10px">✕</button>
      </div>
      <div style="padding:10px 14px;border-bottom:1px solid #e5e7eb;background:#f9fafb;display:flex;gap:8px;flex-wrap:wrap;align-items:center">
        <button class="btn" onclick="_ccaaBulkApplyGuess()" style="background:#1f6feb;color:#fff;font-weight:800;font-size:12px;padding:6px 12px">⚡ Aplicar sugerencia a las SIN ASIGNAR</button>
        <span style="font-size:11px;color:#6b7280">Pone la CCAA "Comunitat Valenciana" cuando la sugerencia es 🟢, deja sin tocar las 🟠 y ⚪.</span>
        <button class="btn" onclick="_ccaaCleanContaminatedBibs()" style="background:#b91c1c;color:#fff;font-weight:800;font-size:12px;padding:6px 12px;margin-left:auto">🧹 Limpiar dorsales contaminados</button>
        <span style="font-size:11px;color:#9a3412">Vacía los dorsales de los INSCRITOS en pruebas CV que no aparecen en sus clasificaciones (suelen ser enriquecimientos antiguos no-CV).</span>
      </div>
      <div style="flex:1;overflow:auto">
        <table style="width:100%;border-collapse:collapse;font-size:12px">
          <thead style="position:sticky;top:0;background:#f3f4f6;z-index:1">
            <tr>
              <th style="padding:7px 8px;text-align:left;font-size:10px;text-transform:uppercase;color:#6b7280">Fecha</th>
              <th style="padding:7px 8px;text-align:left;font-size:10px;text-transform:uppercase;color:#6b7280">Prueba · Localidad · sugerencia</th>
              <th style="padding:7px 8px;text-align:center;font-size:10px;text-transform:uppercase;color:#6b7280">Estado</th>
              <th style="padding:7px 8px;text-align:left;font-size:10px;text-transform:uppercase;color:#6b7280">CCAA manual</th>
            </tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>
      </div>
      <div id="_ccaaMgrStatus" style="padding:8px 14px;background:#f9fafb;border-top:1px solid #e5e7eb;font-size:11.5px;color:#374151;min-height:30px"></div>
    </div>`;
}

function _ccaaCloseManager(){
  const ov = document.getElementById('_ccaaMgrOverlay');
  if(ov) ov.remove();
}

async function _ccaaSaveRow(raceId, newCCAA, selectEl){
  if(!_sb){ alert('Supabase no disponible.'); return; }
  const status = document.getElementById('_ccaaMgrStatus');
  if(status) status.textContent = '⏳ Guardando…';
  try{
    const { data, error } = await _sb.from('races').select('notes').eq('id', raceId).single();
    if(error || !data){ throw new Error(error?.message || 'No se pudo leer la prueba'); }
    let extra = {};
    try{ extra = JSON.parse(data.notes||'{}'); }catch(e){}
    extra.ccaa = newCCAA || '';
    const { error: upErr } = await _sb.from('races').update({notes: JSON.stringify(extra)}).eq('id', raceId);
    if(upErr) throw new Error(upErr.message);
    // Refrescar en cache
    if(Array.isArray(_cachedHistory)){
      const h = _cachedHistory.find(x => x.id === raceId);
      if(h) h.ccaa = newCCAA || '';
    }
    // Invalidar el índice anual para que se reconstruya en el próximo lookup
    if(typeof _yearRiderIdxKey!=='undefined'){ _yearRiderIdxKey=null; _yearRiderIdxCache=null; }
    // Actualizar badge "estado" en la fila
    const row = selectEl.closest('tr');
    if(row){
      const stateCell = row.querySelectorAll('td')[2];
      if(stateCell){
        if(newCCAA){
          stateCell.innerHTML = `<span style="background:#dbeafe;color:#1e3a8a;border:1px solid #93c5fd;border-radius:6px;padding:1px 7px;font-size:10px;font-weight:800">${escapeHtml(newCCAA)}</span>`;
        } else {
          stateCell.innerHTML = `<span style="background:#f3f4f6;color:#6b7280;border:1px solid #d1d5db;border-radius:6px;padding:1px 7px;font-size:10px;font-weight:700">SIN ASIGNAR</span>`;
        }
      }
    }
    if(status) status.innerHTML = `✅ Guardado · ${newCCAA?escapeHtml(newCCAA):'sin asignar'}`;
  }catch(e){
    console.warn('_ccaaSaveRow', e);
    if(status) status.innerHTML = `❌ Error: ${escapeHtml(e.message||String(e))}`;
  }
}

// Limpia los dorsales contaminados en inscritos de carreras CV. La idea:
// los inscritos CV pueden haber sido enriquecidos en versiones antiguas
// con dorsales de carreras NO-CV (Villarrobledo, etc.) cuando no había
// distinción CCAA. Esos dorsales "contaminan" la moda CV y devuelven
// dorsales temporales que no son los oficiales del año.
//
// Estrategia: para cada carrera CV con inscritos:
//   - Si tiene clasificación (riders), conservamos solo dorsales de
//     inscritos que también aparezcan en riders (mismo nombre+bib).
//   - Si NO tiene clasificación (solo pre-inscripción), vaciamos todos
//     los dorsales para forzar a que el director los reintroduzca
//     pegando una startlist limpia.
async function _ccaaCleanContaminatedBibs(){
  if(!_sb){ alert('Supabase no disponible.'); return; }
  const hist = Array.isArray(_cachedHistory) ? _cachedHistory : [];
  // Pruebas CV confirmadas (manual o por marcador heurístico fiable)
  const cvRaces = hist.filter(h => _isCVRace(h) === true && Array.isArray(h.inscritos) && h.inscritos.length>0);
  if(!cvRaces.length){
    alert('No hay pruebas CV con inscritos para limpiar.');
    return;
  }
  // Calcular plan de limpieza
  const plan = []; // [{race, cleaned: [{name, oldBib}]}]
  const nkey = (s) => (typeof normalizeForMatching==='function')?normalizeForMatching(s||''):(s||'').toLowerCase();
  cvRaces.forEach(race => {
    const riders = race.riders || [];
    const ridersByName = new Map();
    riders.forEach(r => {
      if(r.bib) ridersByName.set(nkey(r.name||''), String(r.bib));
    });
    const hasRiders = riders.length >= 3;
    const newIns = race.inscritos.map(ins => {
      const insBib = String(ins.bib||'');
      if(!insBib) return ins;
      if(hasRiders){
        const officialBib = ridersByName.get(nkey(ins.name||''));
        // Si la clasificación oficial tiene su dorsal, conservamos solo si
        // coincide. Si no aparece en clasificación, mantenemos (puede ser
        // un inscrito que abandonó).
        if(officialBib && officialBib !== insBib){
          return { ...ins, bib: '' };
        }
        return ins;
      }
      // Sin clasificación oficial: vaciamos para forzar re-pegado limpio.
      return { ...ins, bib: '' };
    });
    const cleanedCount = race.inscritos.filter((ins, i) => ins.bib && !newIns[i].bib).length;
    if(cleanedCount > 0){
      plan.push({ race, newIns, cleanedCount });
    }
  });
  if(!plan.length){
    alert('No se encontraron dorsales contaminados en las pruebas CV.');
    return;
  }
  const total = plan.reduce((s,p)=>s+p.cleanedCount,0);
  if(!confirm(`Voy a vaciar ${total} dorsal(es) sospechoso(s) en ${plan.length} prueba(s) CV.\n\nQuedarán en blanco para que los inscritos no sigan inyectando dorsales no-CV en la resolución automática. La clasificación oficial (riders) NO se toca.\n\n¿Continuar?`)) return;
  const status = document.getElementById('_ccaaMgrStatus');
  if(status) status.textContent = '⏳ Limpiando…';
  let ok = 0, fail = 0;
  for(const p of plan){
    try{
      const { data, error } = await _sb.from('races').select('notes').eq('id', p.race.id).single();
      if(error || !data){ fail++; continue; }
      let extra = {};
      try{ extra = JSON.parse(data.notes||'{}'); }catch(e){}
      extra.inscritos = p.newIns;
      const { error: upErr } = await _sb.from('races').update({notes: JSON.stringify(extra)}).eq('id', p.race.id);
      if(upErr){ fail++; continue; }
      p.race.inscritos = p.newIns;
      ok++;
    }catch(e){ fail++; }
  }
  if(typeof _yearRiderIdxKey!=='undefined'){ _yearRiderIdxKey=null; _yearRiderIdxCache=null; }
  if(status) status.innerHTML = `🧹 ${total} dorsales vaciados en ${ok} prueba(s)${fail?` · ❌ ${fail} fallos`:''}. Vuelve a generar los PDFs para ver el efecto.`;
}

async function _ccaaBulkApplyGuess(){
  if(!_sb){ alert('Supabase no disponible.'); return; }
  const hist = Array.isArray(_cachedHistory) ? _cachedHistory : [];
  const candidates = hist.filter(h => !h.ccaa && _isCVRace({localidad:h.localidad, raceName:h.raceName, riders:h.riders}) === true);
  if(!candidates.length){
    alert('No hay pruebas SIN ASIGNAR cuya sugerencia sea CV. Las demás (🟠 y ⚪) requieren marcado manual.');
    return;
  }
  if(!confirm(`Se marcarán ${candidates.length} prueba(s) como "Comunitat Valenciana" (las que la heurística detecta como CV y no tienen marcador manual aún).\n\n¿Continuar?`)) return;
  const status = document.getElementById('_ccaaMgrStatus');
  let ok = 0, fail = 0;
  for(const h of candidates){
    try{
      const { data, error } = await _sb.from('races').select('notes').eq('id', h.id).single();
      if(error || !data){ fail++; continue; }
      let extra = {};
      try{ extra = JSON.parse(data.notes||'{}'); }catch(e){}
      extra.ccaa = 'Comunitat Valenciana';
      const { error: upErr } = await _sb.from('races').update({notes: JSON.stringify(extra)}).eq('id', h.id);
      if(upErr){ fail++; continue; }
      h.ccaa = 'Comunitat Valenciana';
      ok++;
    }catch(e){ fail++; }
  }
  if(typeof _yearRiderIdxKey!=='undefined'){ _yearRiderIdxKey=null; _yearRiderIdxCache=null; }
  if(status) status.innerHTML = `✅ ${ok} marcadas como CV${fail?` · ❌ ${fail} fallos`:''}. Cierra y vuelve a abrir para refrescar la lista.`;
}

// ════════════════════════════════════════════════════════════════════════
// FCCV · Capa Supabase (Fase 2)
//   Sincroniza licencias_fccv y team_settings_fccv con Supabase manteniendo
//   localStorage como caché local. Patrón:
//     - Las funciones existentes (_fccvGetLicencias, _fccvGetFirmante…)
//       siguen siendo SÍNCRONAS y leen de localStorage. No cambia el resto
//       del código.
//     - Al entrar en la vista FCCV se dispara _fccvDbSyncFromCloud() que
//       actualiza localStorage desde Supabase si la nube tiene datos.
//     - Al importar Excel o guardar firmante también se PUSHEA a la nube
//       en segundo plano (best-effort, no bloquea la UI).
//     - Botón "☁️ Subir mis licencias actuales a la nube" para forzar
//       una sincronización local → nube cuando el director quiera.
// ════════════════════════════════════════════════════════════════════════

let _fccvDbLastSync = null; // ISO de la última sincronización exitosa

// — Helper: equipo activo (key para team_settings_fccv) —
function _fccvDbTeamKey(){
  // Usamos el equipo persistente del director como clave única. Si no hay,
  // caemos a 'default' para que la fila exista de todos modos.
  const t = (localStorage.getItem('myTeam')||'').trim();
  return t || 'default';
}

// — Pull desde Supabase y vuelca a localStorage (preserva la caché actual
//   si la nube responde vacía y el local tiene datos: nunca destruimos local
//   por nube vacía, porque podría ser un fallo de RLS o un cambio en curso).
async function _fccvDbSyncFromCloud(){
  if(!_sb) return { ok:false, reason:'sb_unavailable' };
  try{
    const [{data: lic, error: e1}, {data: tset, error: e2}] = await Promise.all([
      _sb.from('licencias_fccv').select('*'),
      _sb.from('team_settings_fccv').select('*').eq('team_key', _fccvDbTeamKey()).limit(1)
    ]);
    if(e1) throw new Error('licencias: '+e1.message);
    if(e2) throw new Error('team_settings: '+e2.message);
    // licencias_fccv: solo sobreescribimos local si la nube TIENE datos.
    if(Array.isArray(lic) && lic.length > 0){
      // Mapear los campos del DB a la forma que usa el código existente.
      const mapped = lic.map(r => ({
        dni:           r.dni||'',
        nombre:        r.nombre||'',
        apellidos:     r.apellidos||'',
        uciId:         r.uci_id||'',
        fechaNac:      r.fecha_nac||'',
        telefono:      r.telefono||'',
        email:         r.email||'',
        provincia:     r.provincia||'',
        localidad:     r.localidad||'',
        domicilio:     r.domicilio||'',
        cp:            r.cp||'',
        temporada:     r.temporada,
        catLicencia:   r.cat_licencia||'',
        especialidad:  r.especialidad||'',
        equipo:        r.equipo||'',
        tipo:          r.tipo||'',
        importedAt:    r.imported_at||'',
      }));
      _fccvSetLicencias(mapped);
    }
    // team_settings_fccv: sobreescribimos local solo si hay fila.
    if(Array.isArray(tset) && tset.length === 1){
      const t = tset[0];
      const firm = {
        nombre:    t.firmante_nombre||'',
        cargo:     t.firmante_cargo||'',
        equipo:    t.firmante_equipo||'',
        localidad: t.firmante_localidad||'',
        telefono:  t.firmante_telefono||'',
        email:     t.firmante_email||'',
        matriculas: t.matriculas_coches||'',
        updatedAt: t.updated_at||''
      };
      localStorage.setItem(FCCV_K_FIRMANTE, JSON.stringify(firm));
    }
    _fccvDbLastSync = new Date().toISOString();
    return { ok:true, n:lic?.length||0 };
  }catch(e){
    console.warn('[fccvDb] syncFromCloud falló', e);
    return { ok:false, reason:'error', message:e.message };
  }
}

// — Push desde localStorage hacia Supabase (upsert por dni+temporada).
//   Pensado para el botón manual "Subir mis licencias actuales a la nube"
//   y para la migración inicial (Fase 3).
async function _fccvDbPushAllFromLocal(){
  if(!_sb) return { ok:false, reason:'sb_unavailable' };
  // Comprobación de rol: solo SUPERADMIN puede escribir (enforce client-side
  // siguiendo el mismo modelo que el resto de la app).
  if(typeof _rbacUser === 'object' && _rbacUser && _rbacUser.role !== 'SUPERADMIN'){
    return { ok:false, reason:'not_superadmin' };
  }
  try{
    const local = _fccvGetLicencias();
    let licOk = 0, licFail = 0;
    if(local && local.length){
      const rows = local.map(l => ({
        dni:           l.dni,
        nombre:        l.nombre||'',
        apellidos:     l.apellidos||'',
        uci_id:        l.uciId||null,
        fecha_nac:     l.fechaNac && /^\d{4}-\d{2}-\d{2}$/.test(l.fechaNac) ? l.fechaNac : null,
        telefono:      l.telefono||null,
        email:         l.email||null,
        provincia:     l.provincia||null,
        localidad:     l.localidad||null,
        domicilio:     l.domicilio||null,
        cp:            l.cp||null,
        temporada:     l.temporada || new Date().getFullYear(),
        cat_licencia:  l.catLicencia||null,
        especialidad:  l.especialidad||null,
        equipo:        l.equipo||null,
        tipo:          l.tipo||'cadete'
      }));
      // Upsert por chunks de 100 para no pasarse del tamaño de payload.
      const CHUNK = 100;
      for(let i=0; i<rows.length; i+=CHUNK){
        const slice = rows.slice(i, i+CHUNK);
        const { error } = await _sb.from('licencias_fccv')
          .upsert(slice, { onConflict:'dni,temporada' });
        if(error){ licFail += slice.length; console.warn('[fccvDb] upsert chunk', error); }
        else licOk += slice.length;
      }
    }
    // Firmante / team_settings
    const firm = _fccvGetFirmante();
    let firmOk = false;
    if(firm && (firm.nombre || firm.equipo || firm.matriculas)){
      const row = {
        team_key:           _fccvDbTeamKey(),
        firmante_nombre:    firm.nombre||null,
        firmante_cargo:     firm.cargo||null,
        firmante_equipo:    firm.equipo||null,
        firmante_localidad: firm.localidad||null,
        firmante_telefono:  firm.telefono||null,
        firmante_email:     firm.email||null,
        matriculas_coches:  firm.matriculas||null
      };
      const { error } = await _sb.from('team_settings_fccv')
        .upsert(row, { onConflict:'team_key' });
      if(error){ console.warn('[fccvDb] upsert team_settings', error); }
      else firmOk = true;
    }
    _fccvDbLastSync = new Date().toISOString();
    return { ok:true, licOk, licFail, firmOk };
  }catch(e){
    console.warn('[fccvDb] pushAll falló', e);
    return { ok:false, reason:'error', message:e.message };
  }
}

// — Push de UN firmante a la nube (best-effort, no bloquea la UI).
//   Hook que llamamos desde _fccvSaveFirmante (Fase 2.b).
async function _fccvDbPushFirmante(){
  if(!_sb) return;
  if(typeof _rbacUser === 'object' && _rbacUser && _rbacUser.role !== 'SUPERADMIN') return;
  const firm = _fccvGetFirmante();
  if(!firm || (!firm.nombre && !firm.equipo)) return;
  try{
    await _sb.from('team_settings_fccv').upsert({
      team_key:           _fccvDbTeamKey(),
      firmante_nombre:    firm.nombre||null,
      firmante_cargo:     firm.cargo||null,
      firmante_equipo:    firm.equipo||null,
      firmante_localidad: firm.localidad||null,
      firmante_telefono:  firm.telefono||null,
      firmante_email:     firm.email||null,
      matriculas_coches:  firm.matriculas||null
    }, { onConflict:'team_key' });
  }catch(e){ console.warn('[fccvDb] pushFirmante', e); }
}

// — Push de licencias importadas a la nube (chunks, async, best-effort).
//   Hook que llamamos desde _fccvImportExcel (Fase 2.c).
async function _fccvDbPushLicencias(licArr){
  if(!_sb || !Array.isArray(licArr) || !licArr.length) return { ok:false };
  if(typeof _rbacUser === 'object' && _rbacUser && _rbacUser.role !== 'SUPERADMIN') return { ok:false, reason:'not_superadmin' };
  const rows = licArr.map(l => ({
    dni:           l.dni,
    nombre:        l.nombre||'',
    apellidos:     l.apellidos||'',
    uci_id:        l.uciId||null,
    fecha_nac:     l.fechaNac && /^\d{4}-\d{2}-\d{2}$/.test(l.fechaNac) ? l.fechaNac : null,
    telefono:      l.telefono||null,
    email:         l.email||null,
    provincia:     l.provincia||null,
    localidad:     l.localidad||null,
    domicilio:     l.domicilio||null,
    cp:            l.cp||null,
    temporada:     l.temporada || new Date().getFullYear(),
    cat_licencia:  l.catLicencia||null,
    especialidad:  l.especialidad||null,
    equipo:        l.equipo||null,
    tipo:          l.tipo||'cadete'
  }));
  try{
    const CHUNK = 100;
    let ok = 0, fail = 0;
    for(let i=0; i<rows.length; i+=CHUNK){
      const slice = rows.slice(i, i+CHUNK);
      const { error } = await _sb.from('licencias_fccv').upsert(slice, { onConflict:'dni,temporada' });
      if(error){ fail += slice.length; }
      else ok += slice.length;
    }
    return { ok:true, pushed:ok, failed:fail };
  }catch(e){
    console.warn('[fccvDb] pushLicencias', e);
    return { ok:false, message:e.message };
  }
}

// — UI: botón "Subir mis licencias actuales a la nube" + estado de sync —
function _fccvRenderDbStatusBar(){
  // Insertamos una barra justo encima del bloque "Importar listados Excel".
  // Solo se monta una vez (idempotente).
  const importBlock = document.querySelector('#fccvPanelLicencias [onchange*="_fccvImportExcel"]');
  if(!importBlock) return; // panel aún no renderizado
  if(document.getElementById('fccvDbStatusBar')) return;
  const container = importBlock.closest('div[style*="background:#eff6ff"]');
  if(!container) return;
  const bar = document.createElement('div');
  bar.id = 'fccvDbStatusBar';
  bar.style.cssText = 'background:#ecfeff;border:1px solid #67e8f9;border-radius:10px;padding:10px 12px;margin-bottom:10px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:12px';
  bar.innerHTML = `
    <div style="flex:1;min-width:200px">
      <div style="font-weight:800;color:#155e75">☁️ Sincronización con la nube (Supabase)</div>
      <div id="fccvDbStatusText" style="font-size:11px;color:#0e7490;margin-top:2px">Comprobando...</div>
    </div>
    <button id="fccvDbBtnPull" class="btn light" onclick="_fccvDbDoPull()" style="font-size:11px;padding:5px 10px;background:#fff;border:1px solid #06b6d4;color:#155e75;font-weight:700">⬇️ Bajar de la nube</button>
    <button id="fccvDbBtnPush" class="btn light" onclick="_fccvDbDoPush()" style="font-size:11px;padding:5px 10px;background:#06b6d4;border:0;color:#fff;font-weight:800">⬆️ Subir mis licencias a la nube</button>
  `;
  container.parentNode.insertBefore(bar, container);
  _fccvDbRefreshStatusText();
}

function _fccvDbRefreshStatusText(){
  const el = document.getElementById('fccvDbStatusText');
  if(!el) return;
  const local = _fccvGetLicencias();
  const last = _fccvDbLastSync ? new Date(_fccvDbLastSync).toLocaleString('es-ES') : 'aún no';
  const isAdmin = (typeof _rbacUser === 'object' && _rbacUser && _rbacUser.role === 'SUPERADMIN');
  el.innerHTML = `Local: <b>${local.length}</b> licencias · Última sincronización: <b>${last}</b>${isAdmin?'':' · <span style="color:#92400e">⚠️ Solo SUPERADMIN puede subir/bajar</span>'}`;
}

async function _fccvDbDoPull(){
  const text = document.getElementById('fccvDbStatusText');
  if(text) text.innerHTML = '⏳ Bajando desde la nube...';
  const r = await _fccvDbSyncFromCloud();
  if(r.ok){
    _fccvRenderLicencias();
    _fccvLoadFirmante();
    const msg = `✅ Bajadas ${r.n} licencias desde la nube · ${new Date().toLocaleTimeString('es-ES')}`;
    if(text) text.innerHTML = msg;
    alert(`☁️ Bajada completada\n\n${msg}`);
  } else {
    const m = `❌ Error bajando: ${r.message||r.reason||'desconocido'}`;
    if(text) text.innerHTML = m;
    alert(m);
  }
}

async function _fccvDbDoPush(){
  const local = _fccvGetLicencias();
  const firm = _fccvGetFirmante();
  if(!local.length && !firm.nombre){
    alert('No tienes licencias ni firmante en local para subir.');
    return;
  }
  if(!confirm(`Vas a subir a la nube:\n\n  • ${local.length} licencias\n  • Datos del firmante: ${firm.nombre||'(vacío)'}\n  • Matrículas: ${firm.matriculas||'(vacías)'}\n\nLas licencias se actualizan por (DNI + temporada): si una ya existe en la nube, se sobreescribe; si no, se crea.\n\n¿Continuar?`)) return;
  const text = document.getElementById('fccvDbStatusText');
  if(text) text.innerHTML = '⏳ Subiendo a la nube...';
  const r = await _fccvDbPushAllFromLocal();
  if(r.ok){
    // Mensaje fijo en la barra (NO llamamos a _fccvDbRefreshStatusText
    // porque pisaba el texto del éxito) + alert claro para que el director
    // no se quede con duda de si pasó algo.
    const msg = `✅ Subidas ${r.licOk} licencias${r.licFail?` · ❌ ${r.licFail} fallos`:''} · firmante: ${r.firmOk?'✅':'(sin cambios)'}`;
    if(text) text.innerHTML = msg;
    alert(`☁️ Subida completada\n\n${msg}\n\nYa puedes acceder a estas licencias desde otros dispositivos (iPad / móvil).`);
  } else if(r.reason === 'not_superadmin'){
    const m = '❌ Solo SUPERADMIN puede subir a la nube. Cambia de usuario en la pantalla de login.';
    if(text) text.innerHTML = m;
    alert(m);
  } else {
    const m = `❌ Error subiendo: ${r.message||r.reason||'desconocido'}`;
    if(text) text.innerHTML = m;
    alert(m);
  }
}

// — Helper compartido: monta la barra de sync y bajada inicial desde la nube.
async function _fccvDbBootLicenciasPanel(){
  // Reintentos cortos por si el DOM aún no está montado del todo (iPad/Safari
  // a veces tarda más en renderizar el panel tras showView).
  let tries = 0;
  while(tries < 6){
    const block = document.querySelector('#fccvPanelLicencias [onchange*="_fccvImportExcel"]');
    if(block){ break; }
    await new Promise(r => setTimeout(r, 100));
    tries++;
  }
  _fccvRenderDbStatusBar();
  // Si por alguna razón no se encuentra el contenedor, intentamos un fallback
  // que inserta la barra al inicio del panel.
  if(!document.getElementById('fccvDbStatusBar')){
    const panel = document.getElementById('fccvPanelLicencias');
    if(panel){
      const bar = document.createElement('div');
      bar.id = 'fccvDbStatusBar';
      bar.style.cssText = 'background:#ecfeff;border:1px solid #67e8f9;border-radius:10px;padding:10px 12px;margin-bottom:14px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:12px';
      bar.innerHTML = `
        <div style="flex:1;min-width:200px">
          <div style="font-weight:800;color:#155e75">☁️ Sincronización con la nube (Supabase)</div>
          <div id="fccvDbStatusText" style="font-size:11px;color:#0e7490;margin-top:2px">Comprobando...</div>
        </div>
        <button id="fccvDbBtnPull" class="btn light" onclick="_fccvDbDoPull()" style="font-size:11px;padding:5px 10px;background:#fff;border:1px solid #06b6d4;color:#155e75;font-weight:700">⬇️ Bajar de la nube</button>
        <button id="fccvDbBtnPush" class="btn light" onclick="_fccvDbDoPush()" style="font-size:11px;padding:5px 10px;background:#06b6d4;border:0;color:#fff;font-weight:800">⬆️ Subir mis licencias a la nube</button>`;
      panel.insertBefore(bar, panel.firstChild);
    }
  }
  // Pull desde la nube. Si trae datos, refresca la tabla y el firmante.
  const r = await _fccvDbSyncFromCloud();
  if(r.ok && r.n > 0){
    try{ _fccvRenderLicencias(); }catch(e){}
    try{ _fccvLoadFirmante(); }catch(e){}
  }
  _fccvDbRefreshStatusText();
}

// — Hook 1: al entrar en la vista FCCV (es la pestaña Licencias por defecto)
(function(){
  const _origShowView = (typeof showView === 'function') ? showView : null;
  if(!_origShowView) return;
  window.showView = function(id){
    const r = _origShowView.apply(this, arguments);
    if(id === 'view-fccv-docs'){
      setTimeout(_fccvDbBootLicenciasPanel, 80);
    }
    return r;
  };
})();

// — Hook 2: al clicar la pestaña Licencias también dispara el boot.
(function(){
  const _origShowTab = (typeof _fccvShowTab === 'function') ? _fccvShowTab : null;
  if(!_origShowTab) return;
  window._fccvShowTab = function(tab){
    _origShowTab.apply(this, arguments);
    if(tab === 'licencias'){
      setTimeout(_fccvDbBootLicenciasPanel, 60);
    }
  };
})();

// — Hook al guardado del firmante para pushear a la nube en segundo plano —
(function(){
  const _origSave = (typeof _fccvSaveFirmante === 'function') ? _fccvSaveFirmante : null;
  if(!_origSave) return;
  window._fccvSaveFirmante = function(){
    const r = _origSave.apply(this, arguments);
    // Push best-effort (no bloquea, no muestra error si falla — el local ya está guardado).
    _fccvDbPushFirmante();
    return r;
  };
})();

// — Hook al importador Excel para pushear las licencias importadas a la nube —
(function(){
  const _origImport = (typeof _fccvImportExcel === 'function') ? _fccvImportExcel : null;
  if(!_origImport) return;
  window._fccvImportExcel = async function(ev, importedAs){
    // Capturamos el snapshot ANTES de la importación para saber qué se añadió/cambió.
    const before = _fccvGetLicencias();
    const beforeKeys = new Set(before.map(l => l.dni+'|'+l.temporada));
    // Ejecutamos el flujo original
    await _origImport.apply(this, [ev, importedAs]);
    // Tras importar, calculamos el delta (cambios o nuevos) y los pusheamos.
    const after = _fccvGetLicencias();
    const delta = after.filter(l => {
      const key = l.dni+'|'+l.temporada;
      if(!beforeKeys.has(key)) return true; // nuevo
      const prev = before.find(x => (x.dni+'|'+x.temporada) === key);
      // Comparación somera por importedAt: si _fccvImportExcel marcó el item como
      // actualizado, su importedAt habrá cambiado.
      return prev && prev.importedAt !== l.importedAt;
    });
    if(delta.length){
      const r = await _fccvDbPushLicencias(delta);
      const text = document.getElementById('fccvDbStatusText');
      if(text && r && r.ok){
        text.innerHTML = `☁️ Subidas <b>${r.pushed}</b> licencias a la nube tras importar${r.failed?` · ❌ ${r.failed} fallos`:''}`;
      }
    }
    _fccvDbRefreshStatusText();
  };
})();

// ════════════════════════════════════════════════════════════════════════
// ROUTE · análisis de archivos GPX/FIT/TCX (Fase 1)
//   - Parser único que normaliza a un track canónico
//   - Cálculo de métricas (distancia, desnivel, terrain_type)
//   - Subida del archivo original + JSON simplificado a Supabase Storage
//   - Persistencia de métricas en races.notes.route
//   - Modal con mapa Leaflet + perfil Chart.js + tarjeta de métricas
//   - Esfuerzos individuales con potencia/HR → rider_efforts_fccv
// ════════════════════════════════════════════════════════════════════════

const ROUTE_BUCKET = 'race-tracks';
let _routeCurrent = null;  // { raceId, race, canonical, effort, sourceMeta }
let _routeMapInstance = null;
let _routeProfileChart = null;
let _routeMapPositionMarker = null;

// — Distancia haversine en metros entre dos puntos lat/lon —
function _routeHaversine(lat1, lon1, lat2, lon2){
  const R = 6371000;
  const toRad = d => d * Math.PI / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1))*Math.cos(toRad(lat2))*Math.sin(dLon/2)**2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

// — Suavizado de altimetría con media móvil (reduce ruido GPS sin perder picos) —
function _routeSmoothElev(points, window){
  window = window || 7;
  const half = Math.floor(window/2);
  const out = points.map(p => ({...p}));
  for(let i = 0; i < points.length; i++){
    let sum = 0, cnt = 0;
    for(let j = Math.max(0, i-half); j <= Math.min(points.length-1, i+half); j++){
      if(points[j].ele != null){ sum += points[j].ele; cnt++; }
    }
    if(cnt > 0) out[i].ele = sum / cnt;
  }
  return out;
}

// — Suma de desnivel positivo (sobre serie suavizada) —
function _routeAccumulatedAscent(points){
  let pos = 0, neg = 0;
  for(let i = 1; i < points.length; i++){
    const a = points[i].ele, b = points[i-1].ele;
    if(a == null || b == null) continue;
    const d = a - b;
    if(d > 0) pos += d;
    else      neg -= d;
  }
  return { pos: Math.round(pos), neg: Math.round(neg) };
}

// — Clasifica el terreno según m de desnivel positivo por km —
function _routeClassifyTerrain(distMeters, ascentMeters, maxGradePct){
  if(distMeters < 100) return 'desconocido';
  const mPerKm = ascentMeters / (distMeters / 1000);
  if(mPerKm < 5)            return 'llana';
  if(mPerKm < 12)           return 'rompepiernas';
  if(mPerKm < 22)           return 'media_montana';
  return 'montanosa';
}

// — Pendiente máxima/media en tramos de subida (con ventana 100 m) —
function _routeGradient(points){
  if(points.length < 2) return { avg: 0, max: 0 };
  // Pendiente cada ~50 metros agregando puntos
  const grads = [];
  let acc_d = 0, acc_dh = 0, base = 0;
  for(let i = 1; i < points.length; i++){
    const d = _routeHaversine(points[i-1].lat, points[i-1].lon, points[i].lat, points[i].lon);
    if(points[i].ele == null || points[i-1].ele == null) continue;
    acc_d += d;
    acc_dh += (points[i].ele - points[i-1].ele);
    if(acc_d >= 50){
      const g = (acc_dh / acc_d) * 100;
      if(isFinite(g) && Math.abs(g) < 35) grads.push(g);
      acc_d = 0; acc_dh = 0;
    }
  }
  if(!grads.length) return { avg: 0, max: 0 };
  const pos = grads.filter(g => g > 0);
  const avg = pos.length ? pos.reduce((s,g)=>s+g, 0) / pos.length : 0;
  const max = Math.max(...grads, 0);
  return { avg: Math.round(avg * 10) / 10, max: Math.round(max * 10) / 10 };
}

// — Construye canonical desde puntos parseados —
function _routeBuildCanonical(rawPoints, sourceMeta){
  // Filtramos puntos sin lat/lon (algunos .fit empiezan con records sin GPS).
  const pts = rawPoints.filter(p => p.lat != null && p.lon != null);
  if(pts.length < 2) throw new Error('Track sin suficientes puntos GPS');

  // Calculamos distancia acumulada si no viene del archivo
  let distSum = 0;
  pts[0].dist = pts[0].dist != null ? pts[0].dist : 0;
  for(let i = 1; i < pts.length; i++){
    const stepD = _routeHaversine(pts[i-1].lat, pts[i-1].lon, pts[i].lat, pts[i].lon);
    distSum += stepD;
    if(pts[i].dist == null) pts[i].dist = distSum;
  }
  const distanceM = pts[pts.length-1].dist || distSum;

  // Suavizado de altimetría + desniveles
  const smoothed = _routeSmoothElev(pts);
  const { pos: ascent, neg: descent } = _routeAccumulatedAscent(smoothed);
  const grad = _routeGradient(smoothed);

  const elevs = smoothed.map(p => p.ele).filter(v => v != null);
  const altMin = elevs.length ? Math.round(Math.min(...elevs)) : null;
  const altMax = elevs.length ? Math.round(Math.max(...elevs)) : null;
  const altAvg = elevs.length ? Math.round(elevs.reduce((s,v)=>s+v, 0) / elevs.length) : null;

  const terrain = _routeClassifyTerrain(distanceM, ascent, grad.max);
  // Difficulty score 0-100: combina desnivel/km + pendiente máxima
  const mPerKm = ascent / (distanceM / 1000);
  const diff = Math.min(100, Math.round(mPerKm * 1.6 + grad.max * 1.8));

  return {
    points: pts,
    summary: {
      source: sourceMeta.kind,
      source_file: sourceMeta.filename,
      source_device: sourceMeta.device || null,
      distance_m: Math.round(distanceM),
      desnivel_pos_m: ascent,
      desnivel_neg_m: descent,
      altitude_min_m: altMin,
      altitude_max_m: altMax,
      altitude_avg_m: altAvg,
      terrain_type: terrain,
      gradient_avg_pct: grad.avg,
      gradient_max_pct: grad.max,
      difficulty_score: diff,
      points_count: pts.length,
      has_altitude: elevs.length > 0,
      uploaded_at: new Date().toISOString()
    },
    effort: sourceMeta.effort || null
  };
}

// — Parser .gpx (XML, sin librería) —
function _routeParseGPX(text){
  const xml = new DOMParser().parseFromString(text, 'application/xml');
  const err = xml.querySelector('parsererror');
  if(err) throw new Error('GPX inválido: '+err.textContent.slice(0, 200));
  // Buscamos cualquier descendiente por localName, ignorando los namespaces
  // (Garmin usa ns3:hr / gpxtpx:hr, Strava no usa prefijo, otros usan power).
  // Para evitar selectores CSS frágiles con namespaces, recorremos a mano.
  const findChildByLocalName = (parent, names) => {
    const wanted = new Set(names);
    const walk = (node) => {
      for(const ch of node.children){
        if(wanted.has(ch.localName)) return ch;
        const deeper = walk(ch);
        if(deeper) return deeper;
      }
      return null;
    };
    return walk(parent);
  };
  const trkpts = xml.getElementsByTagName('trkpt');
  const points = [];
  for(const pt of trkpts){
    const lat = parseFloat(pt.getAttribute('lat'));
    const lon = parseFloat(pt.getAttribute('lon'));
    if(isNaN(lat) || isNaN(lon)) continue;
    const eleNode  = findChildByLocalName(pt, ['ele']);
    const timeNode = findChildByLocalName(pt, ['time']);
    const hrNode   = findChildByLocalName(pt, ['hr','heartrate']);
    const cadNode  = findChildByLocalName(pt, ['cad','cadence']);
    const pwNode   = findChildByLocalName(pt, ['power','watts']);
    const ele = eleNode ? parseFloat(eleNode.textContent) : NaN;
    const timeStr = timeNode ? timeNode.textContent : '';
    const time = timeStr ? new Date(timeStr).getTime() : null;
    const hr  = hrNode  ? parseInt(hrNode.textContent)  : NaN;
    const cad = cadNode ? parseInt(cadNode.textContent) : NaN;
    const pw  = pwNode  ? parseInt(pwNode.textContent)  : NaN;
    points.push({
      lat, lon,
      ele: isNaN(ele) ? null : ele,
      time,
      hr:  isNaN(hr)  ? null : hr,
      cad: isNaN(cad) ? null : cad,
      pw:  isNaN(pw)  ? null : pw
    });
  }
  return points;
}

// — Parser .tcx (Garmin Training Center XML) — similar a GPX —
function _routeParseTCX(text){
  const xml = new DOMParser().parseFromString(text, 'application/xml');
  const err = xml.querySelector('parsererror');
  if(err) throw new Error('TCX inválido');
  const trkpts = xml.querySelectorAll('Trackpoint');
  const points = [];
  trkpts.forEach(pt => {
    const lat = parseFloat(pt.querySelector('Position LatitudeDegrees')?.textContent);
    const lon = parseFloat(pt.querySelector('Position LongitudeDegrees')?.textContent);
    if(isNaN(lat) || isNaN(lon)) return;
    const ele = parseFloat(pt.querySelector('AltitudeMeters')?.textContent);
    const dist = parseFloat(pt.querySelector('DistanceMeters')?.textContent);
    const timeStr = pt.querySelector('Time')?.textContent;
    const time = timeStr ? new Date(timeStr).getTime() : null;
    const hr = parseInt(pt.querySelector('HeartRateBpm Value')?.textContent);
    const cad = parseInt(pt.querySelector('Cadence')?.textContent);
    const pw = parseInt(pt.querySelector('Watts')?.textContent);
    points.push({
      lat, lon,
      ele: isNaN(ele) ? null : ele,
      dist: isNaN(dist) ? null : dist,
      time,
      hr: isNaN(hr) ? null : hr,
      cad: isNaN(cad) ? null : cad,
      pw: isNaN(pw) ? null : pw
    });
  });
  return points;
}

// Lazy ESM load de fit-file-parser. La librería es CommonJS; según el CDN
// que la sirva, puede llegar envuelta una o dos veces en {default: ...}.
// Probamos esm.sh (mejor interop) con fallback a jsdelivr +esm, y
// desenvolvemos defaults hasta encontrar la función constructora real.
let _routeFitParserCtor = null;
async function _routeLoadFitParser(){
  if(_routeFitParserCtor) return _routeFitParserCtor;
  const tryUrls = [
    'https://esm.sh/fit-file-parser@1.21.0',
    'https://cdn.jsdelivr.net/npm/fit-file-parser@1.21.0/+esm'
  ];
  const errs = [];
  for(const url of tryUrls){
    try{
      const mod = await import(url);
      // Búsqueda profunda de la clase: el módulo podría ser la clase
      // directamente, o tener default, o default.default, o exponer
      // FitParser como nombre explícito.
      const candidates = [
        mod,
        mod.default,
        mod.default && mod.default.default,
        mod.FitParser,
        mod.default && mod.default.FitParser
      ];
      for(const c of candidates){
        if(typeof c === 'function'){
          _routeFitParserCtor = c;
          return _routeFitParserCtor;
        }
      }
      errs.push(url + ': no se encontró constructor en el módulo (keys: '+Object.keys(mod||{}).join(',')+')');
    }catch(e){
      errs.push(url + ': '+(e.message||e));
    }
  }
  throw new Error('No se pudo cargar fit-file-parser:\n'+errs.join('\n'));
}

// — Parser .fit —
async function _routeParseFIT(arrayBuffer){
  const FP = await _routeLoadFitParser();
  const parser = new FP({
    force: true,
    speedUnit: 'km/h',
    lengthUnit: 'm',
    temperatureUnit: 'celsius',
    elapsedRecordField: true,
    mode: 'list'
  });
  return new Promise((resolve, reject) => {
    parser.parse(arrayBuffer, (err, data) => {
      if(err) return reject(new Error('FIT inválido: '+err));
      // Records → puntos canónicos
      const recs = data.records || [];
      const points = recs.map(r => ({
        lat: r.position_lat,
        lon: r.position_long,
        // Garmin Edge a veces solo guarda enhanced_altitude
        ele: r.altitude != null ? r.altitude : (r.enhanced_altitude != null ? r.enhanced_altitude : null),
        dist: r.distance,
        time: r.timestamp instanceof Date ? r.timestamp.getTime() : null,
        hr: r.heart_rate,
        cad: r.cadence,
        pw: r.power
      }));
      // Effort summary (datos personales del corredor)
      const s = data.sessions?.[0] || null;
      const effort = s ? {
        start_time: s.start_time instanceof Date ? s.start_time.toISOString() : null,
        duration_s: Math.round(s.total_elapsed_time || s.total_timer_time || 0),
        distance_m: Math.round(s.total_distance || 0),
        hr_avg_bpm: s.avg_heart_rate || null,
        hr_max_bpm: s.max_heart_rate || null,
        power_avg_w: s.avg_power || null,
        power_max_w: s.max_power || null,
        power_norm_w: s.normalized_power || null,
        ftp_w: s.threshold_power || null,
        cadence_avg: s.avg_cadence || null,
        cadence_max: s.max_cadence || null,
        calories: s.total_calories || null,
        work_kj: s.total_work ? Math.round(s.total_work / 1000) : null,
        temperature_avg: s.avg_temperature || null
      } : null;
      const devInfo = (data.file_ids && data.file_ids[0]) || (data.device_infos && data.device_infos[0]) || {};
      resolve({ points, effort, device: { mfg: devInfo.manufacturer || null, product: devInfo.product || null } });
    });
  });
}

// — Carga un archivo en su parser adecuado y devuelve canonical —
async function _routeParseFile(file){
  const ext = (file.name.split('.').pop() || '').toLowerCase();
  if(ext === 'fit'){
    const buf = await file.arrayBuffer();
    const r = await _routeParseFIT(buf);
    const dev = r.device.mfg ? `${r.device.mfg}${r.device.product?'/'+r.device.product:''}` : null;
    return _routeBuildCanonical(r.points, { kind:'fit', filename:file.name, device:dev, effort:r.effort });
  }
  if(ext === 'gpx'){
    const text = await file.text();
    const pts = _routeParseGPX(text);
    return _routeBuildCanonical(pts, { kind:'gpx', filename:file.name });
  }
  if(ext === 'tcx'){
    const text = await file.text();
    const pts = _routeParseTCX(text);
    return _routeBuildCanonical(pts, { kind:'tcx', filename:file.name });
  }
  throw new Error('Formato no soportado: '+ext+'. Sube .fit, .gpx o .tcx');
}

// — Downsample para mapa: cada N metros, suficiente para dibujar línea suave —
function _routeDownsample(points, everyM){
  everyM = everyM || 15;
  if(points.length < 3) return points.slice();
  const out = [points[0]];
  let lastDist = 0;
  for(let i = 1; i < points.length; i++){
    if((points[i].dist || 0) - lastDist >= everyM){
      out.push(points[i]);
      lastDist = points[i].dist || 0;
    }
  }
  out.push(points[points.length-1]);
  return out;
}

// — Sube el archivo original + JSON canónico al bucket Storage —
async function _routeUploadToStorage(raceId, file, canonical){
  if(!_sb) throw new Error('Supabase no disponible');
  const ext = (file.name.split('.').pop() || 'bin').toLowerCase();
  const origKey = `${raceId}/original.${ext}`;
  const courseKey = `${raceId}/course.json`;
  // 1) Original tal cual
  const origRes = await _sb.storage.from(ROUTE_BUCKET).upload(origKey, file, { upsert: true, contentType: 'application/octet-stream' });
  if(origRes.error) throw new Error('Subida original falló: '+origRes.error.message);
  // 2) JSON canónico (puntos downsample para mapa/perfil)
  const courseJson = {
    summary: canonical.summary,
    points: _routeDownsample(canonical.points, 15).map(p => ({ lat: p.lat, lon: p.lon, ele: p.ele, dist: p.dist }))
  };
  const blob = new Blob([JSON.stringify(courseJson)], { type: 'application/json' });
  const courseRes = await _sb.storage.from(ROUTE_BUCKET).upload(courseKey, blob, { upsert: true, contentType: 'application/json' });
  if(courseRes.error) throw new Error('Subida JSON curso falló: '+courseRes.error.message);
  return { origKey, courseKey };
}

// — Descarga el JSON canónico del curso —
async function _routeDownloadCourse(raceId){
  if(!_sb) return null;
  const courseKey = `${raceId}/course.json`;
  const { data, error } = await _sb.storage.from(ROUTE_BUCKET).download(courseKey);
  if(error || !data) return null;
  try{
    const text = await data.text();
    return JSON.parse(text);
  }catch(e){ return null; }
}

// — Persiste métricas del curso en races.notes.route —
async function _routePersistMetrics(raceId, summary){
  if(!_sb) throw new Error('Supabase no disponible');
  const { data, error } = await _sb.from('races').select('notes').eq('id', raceId).single();
  if(error || !data) throw new Error('No se pudo leer la prueba: '+(error?.message||''));
  let extra = {};
  try{ extra = JSON.parse(data.notes||'{}'); }catch(e){}
  extra.route = summary;
  const { error: upErr } = await _sb.from('races').update({notes: JSON.stringify(extra)}).eq('id', raceId);
  if(upErr) throw new Error('Guardado de métricas falló: '+upErr.message);
  // Actualizar caché local también
  if(Array.isArray(_cachedHistory)){
    const h = _cachedHistory.find(x => x.id === raceId);
    if(h) h.route = summary;
  }
}

// — Persiste un esfuerzo individual en rider_efforts_fccv —
// Guard reutilizable: tras el Paso 4 (RLS), escribir requiere sesión de enlace
// mágico. Si no la hay, avisa claro y devuelve false (en vez de un error técnico).
async function _requireAuthWrite(){
  if(!(typeof _AUTH_MAGIC_ENABLED!=='undefined' && _AUTH_MAGIC_ENABLED && _sb && _sb.auth)) return true;
  try{ const r=await _sb.auth.getSession(); if(r && r.data && r.data.session) return true; }catch(_){ return true; }
  alert('🔒 Para guardar o modificar datos ahora hay que entrar con el ENLACE MÁGICO (no con PIN).\n\n1) Pulsa "Salir".\n2) En el login pulsa "✉️ Recibir enlace de acceso por email".\n3) Abre el enlace del correo y entra.\n4) Repite la acción.\n\n(Es por la nueva seguridad: el acceso anónimo ya no puede modificar datos.)');
  return false;
}

async function _routeSaveEffort(raceId, effort, sourceFile, sourceKind, deviceStr, riderHint){
  if(!_sb || !effort) return { ok:false };
  if(!(await _requireAuthWrite())) return { ok:false, auth:false };
  const row = {
    race_id:        raceId,
    rider_dni:      null,
    rider_name_hint: riderHint || (sourceFile ? sourceFile.replace(/\.\w+$/,'') : null),
    source_file:    sourceFile || null,
    source_kind:    sourceKind || 'fit',
    device_mfg:     deviceStr ? deviceStr.split('/')[0] : null,
    device_product: deviceStr && deviceStr.includes('/') ? deviceStr.split('/')[1] : null,
    start_time:     effort.start_time || null,
    duration_s:     effort.duration_s || null,
    distance_m:     effort.distance_m || null,
    hr_avg_bpm:     effort.hr_avg_bpm || null,
    hr_max_bpm:     effort.hr_max_bpm || null,
    power_avg_w:    effort.power_avg_w || null,
    power_max_w:    effort.power_max_w || null,
    power_norm_w:   effort.power_norm_w || null,
    ftp_w:          effort.ftp_w || null,
    intensity_factor: (effort.power_norm_w && effort.ftp_w) ? Math.round((effort.power_norm_w / effort.ftp_w) * 100) / 100 : null,
    cadence_avg:    effort.cadence_avg || null,
    cadence_max:    effort.cadence_max || null,
    calories:       effort.calories || null,
    work_kj:        effort.work_kj || null,
    temperature_avg: effort.temperature_avg || null
  };
  const { error, data } = await _sb.from('rider_efforts_fccv').insert(row).select().single();
  if(error) return { ok:false, error };
  return { ok:true, row: data };
}

async function _routeListEfforts(raceId){
  if(!_sb) return [];
  const { data, error } = await _sb.from('rider_efforts_fccv').select('*').eq('race_id', raceId).order('start_time', { ascending: true });
  if(error){ console.warn('listEfforts', error); return []; }
  return data || [];
}

// ── UI del modal ───────────────────────────────────────────────────────
async function _routeOpenModal(raceId){
  const hist = _cachedHistory || (typeof _sbLoadHistory==='function' ? await _sbLoadHistory() : []);
  if(!Array.isArray(_cachedHistory) || !_cachedHistory.length) _cachedHistory = hist;
  const race = hist.find(h => h.id === raceId);
  if(!race){ alert('No se encontró la prueba'); return; }
  _routeInjectStyles();
  let overlay = document.getElementById('routeOverlay');
  if(!overlay){
    overlay = document.createElement('div');
    overlay.id = 'routeOverlay';
    overlay.className = 'route-overlay';
    overlay.addEventListener('click', e => { if(e.target===overlay) _routeCloseModal(); });
    document.body.appendChild(overlay);
  }
  _routeCurrent = { raceId, race, canonical:null, courseJson:null };
  overlay.innerHTML = `
    <div class="route-modal">
      <div class="route-header">
        <div>
          <h2>🗺️ Recorrido y esfuerzos</h2>
          <div class="route-meta">${escapeHtml(race.raceName||'')} · ${escapeHtml(race.raceDate||'')}${race.localidad?' · '+escapeHtml(race.localidad):''}</div>
        </div>
        <button class="route-close" onclick="_routeCloseModal()">✕</button>
      </div>
      <div id="routeContent" class="route-content"><div class="route-loading">⏳ Cargando…</div></div>
    </div>`;
  document.body.style.overflow = 'hidden';
  await _routeRenderContent();
}

function _routeCloseModal(){
  const ov = document.getElementById('routeOverlay');
  if(ov) ov.remove();
  document.body.style.overflow = '';
  if(_routeMapInstance){ try{ _routeMapInstance.remove(); }catch(e){} _routeMapInstance = null; }
  if(_routeProfileChart){ try{ _routeProfileChart.destroy(); }catch(e){} _routeProfileChart = null; }
  _routeCurrent = null;
}

async function _routeRenderContent(){
  const content = document.getElementById('routeContent');
  if(!content || !_routeCurrent) return;
  const { raceId, race } = _routeCurrent;
  const hasRoute = race.route && race.route.distance_m;
  const efforts = await _routeListEfforts(raceId);

  if(!hasRoute){
    content.innerHTML = `
      <div class="route-empty route-dropzone" id="routeDropzone">
        <div class="route-empty-icon">📂</div>
        <div class="route-empty-title">No hay recorrido cargado para esta prueba</div>
        <div class="route-empty-sub">Sube el archivo <b>.fit</b> del ciclocomputador (Garmin/Wahoo) o el <b>.gpx</b> del organizador.<br>Arrastra y suelta el archivo aquí, o pulsa el botón.</div>
        <label class="route-upload-btn">
          📎 Subir archivo (.fit / .gpx / .tcx)
          <input type="file" accept=".fit,.gpx,.tcx,.FIT,.GPX,.TCX" onchange="_routeOnFileSelected(event)" style="display:none">
        </label>
        ${efforts.length ? `<div class="route-empty-sub" style="margin-top:14px">Sin embargo, hay <b>${efforts.length}</b> esfuerzo(s) subido(s) sin curso de referencia.</div>` : ''}
      </div>`;
    _routeWireDropzone(document.getElementById('routeDropzone'));
    return;
  }

  // Hay curso → cargamos el JSON canónico para pintar mapa+perfil
  let course = _routeCurrent.courseJson;
  if(!course){
    course = await _routeDownloadCourse(raceId);
    _routeCurrent.courseJson = course;
  }
  const r = race.route;
  const terrainLabels = { llana:'🟢 Llana', rompepiernas:'🟡 Rompepiernas', media_montana:'🟠 Media montaña', montanosa:'🔴 Montañosa', desconocido:'⚪ Desconocido' };
  const altRange = (r.altitude_min_m!=null && r.altitude_max_m!=null) ? `${r.altitude_min_m}-${r.altitude_max_m} m` : '—';
  content.innerHTML = `
    <div class="route-grid" id="routeDropzone">
      <div class="route-metrics">
        <div class="route-metric"><div class="rm-v">${(r.distance_m/1000).toFixed(1)}</div><div class="rm-l">km</div></div>
        <div class="route-metric"><div class="rm-v">${r.desnivel_pos_m||0}</div><div class="rm-l">desnivel +</div></div>
        <div class="route-metric"><div class="rm-v" style="font-size:14px;line-height:1.2">${terrainLabels[r.terrain_type]||r.terrain_type}</div><div class="rm-l">terreno</div></div>
        <div class="route-metric"><div class="rm-v">${r.gradient_max_pct||0}%</div><div class="rm-l">pendiente máx</div></div>
        <div class="route-metric"><div class="rm-v">${r.gradient_avg_pct||0}%</div><div class="rm-l">pendiente media</div></div>
        <div class="route-metric"><div class="rm-v">${r.difficulty_score||0}</div><div class="rm-l">dificultad 0-100</div></div>
        <div class="route-metric"><div class="rm-v" style="font-size:14px">${altRange}</div><div class="rm-l">altitud</div></div>
        <div class="route-metric"><div class="rm-v" style="font-size:13px">${escapeHtml(r.source||'')}</div><div class="rm-l">fuente</div></div>
      </div>
      <div class="route-actions">
        <label class="route-upload-btn route-upload-btn-sm" style="background:#0369a1" title="Sube un .fit de otro corredor y guarda solo su esfuerzo (potencia/FC). NO toca el recorrido actual.">
          📎 Añadir solo esfuerzo
          <input type="file" accept=".fit,.FIT" onchange="_routeOnEffortOnlySelected(event)" style="display:none">
        </label>
        <label class="route-upload-btn route-upload-btn-sm" style="background:#92400e" title="Sustituye el recorrido entero por uno nuevo (mapa + perfil + métricas). Úsalo si tienes un archivo mejor del mismo evento.">
          🔄 Sustituir recorrido
          <input type="file" accept=".fit,.gpx,.tcx,.FIT,.GPX,.TCX" onchange="_routeOnFileSelected(event)" style="display:none">
        </label>
        <button class="route-btn route-btn-danger" onclick="_routeDeleteRoute()">🗑️ Quitar recorrido</button>
      </div>
      <div class="route-map-wrap">
        <div id="routeMap" class="route-map"></div>
      </div>
      ${(r.has_altitude && course && course.points && course.points.some(p=>p.ele!=null)) ? '<div class="route-profile-wrap"><canvas id="routeProfile" class="route-profile"></canvas></div>' : '<div class="route-no-altitude">⚠️ Este archivo no trae altimetría por punto. Sube otro (Wahoo, GPX del organizador…) si quieres ver el perfil altimétrico.</div>'}
      <div class="route-efforts">
        <div class="route-efforts-title">📊 Esfuerzos subidos (${efforts.length})</div>
        ${efforts.length ? efforts.map(e => `
          <div class="route-effort-row">
            <span class="re-name">${escapeHtml(e.rider_name_hint||'Sin asignar')}</span>
            <span class="re-meta">${e.source_kind||''}${e.device_mfg?' · '+escapeHtml(e.device_mfg):''}</span>
            ${e.duration_s ? `<span class="re-stat">${Math.floor(e.duration_s/60)}:${String(e.duration_s%60).padStart(2,'0')}</span>` : ''}
            ${e.power_avg_w ? `<span class="re-stat">${e.power_avg_w}W avg</span>` : ''}
            ${e.power_norm_w ? `<span class="re-stat">${e.power_norm_w}W NP</span>` : ''}
            ${e.hr_avg_bpm ? `<span class="re-stat">${e.hr_avg_bpm} bpm</span>` : ''}
            <button class="re-rm" onclick="_routeDeleteEffort('${e.id}')" title="Eliminar este esfuerzo">×</button>
          </div>
        `).join('') : '<div class="route-empty-sub" style="text-align:center;padding:8px">Aún no hay esfuerzos individuales. Sube un .fit para añadir uno.</div>'}
      </div>
    </div>`;

  // Dibujar mapa y perfil
  if(course && course.points && course.points.length > 1){
    setTimeout(() => {
      _routeDrawMap(course.points);
      if(r.has_altitude) _routeDrawProfile(course.points);
    }, 80);
  }
  _routeWireDropzone(document.getElementById('routeDropzone'));
}

// — Engancha drag & drop en una zona del modal. Procesa el primer archivo
//   soltado. Se aplica tanto al placeholder (cuando no hay curso) como al
//   grid con mapa/perfil (para sustituir o añadir esfuerzo).
function _routeWireDropzone(el){
  if(!el || el._routeDropWired) return;
  el._routeDropWired = true;
  const prevent = (ev) => { ev.preventDefault(); ev.stopPropagation(); };
  ['dragenter','dragover'].forEach(ev => el.addEventListener(ev, e => {
    prevent(e);
    el.classList.add('route-drag-active');
  }));
  ['dragleave','drop'].forEach(ev => el.addEventListener(ev, e => {
    prevent(e);
    el.classList.remove('route-drag-active');
  }));
  el.addEventListener('drop', async (e) => {
    const file = e.dataTransfer?.files && e.dataTransfer.files[0];
    if(!file) return;
    await _routeOnFileSelected({ target: { files: [file] } });
  });
}

function _routeDrawMap(points){
  const el = document.getElementById('routeMap');
  if(!el || typeof L === 'undefined') return;
  if(_routeMapInstance){ try{ _routeMapInstance.remove(); }catch(e){} }
  _routeMapInstance = L.map(el, { preferCanvas: true });
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    attribution: '© OpenStreetMap',
    maxZoom: 19
  }).addTo(_routeMapInstance);
  const latlngs = points.map(p => [p.lat, p.lon]);
  L.polyline(latlngs, { color: '#1f6feb', weight: 4, opacity: 0.85 }).addTo(_routeMapInstance);
  // Marcadores inicio y fin
  L.circleMarker(latlngs[0], { color: '#15803d', radius: 7, fillOpacity: 1 }).addTo(_routeMapInstance).bindTooltip('Inicio', {permanent: false});
  L.circleMarker(latlngs[latlngs.length-1], { color: '#b91c1c', radius: 7, fillOpacity: 1 }).addTo(_routeMapInstance).bindTooltip('Fin', {permanent: false});
  // Marcador móvil sincronizado con el perfil
  _routeMapPositionMarker = L.circleMarker(latlngs[0], { color:'#7c3aed', fillColor:'#fff', fillOpacity:1, radius:6, weight:2 });
  _routeMapInstance.fitBounds(L.latLngBounds(latlngs), { padding: [20, 20] });
}

function _routeDrawProfile(points){
  const el = document.getElementById('routeProfile');
  if(!el || typeof Chart === 'undefined') return;
  if(_routeProfileChart){ try{ _routeProfileChart.destroy(); }catch(e){} _routeProfileChart = null; }
  const data = points.filter(p => p.ele != null).map(p => ({ x: (p.dist||0)/1000, y: p.ele, lat: p.lat, lon: p.lon }));
  _routeProfileChart = new Chart(el, {
    type: 'line',
    data: {
      datasets: [{
        label: 'Altitud (m)',
        data: data,
        borderColor: '#1f6feb',
        backgroundColor: 'rgba(31,111,235,0.15)',
        fill: true,
        pointRadius: 0,
        borderWidth: 2,
        tension: 0.2
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        x: { type: 'linear', title: { display: true, text: 'km' } },
        y: { title: { display: true, text: 'metros' } }
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            label: ctx => `km ${ctx.parsed.x.toFixed(2)} · ${Math.round(ctx.parsed.y)} m`
          }
        }
      },
      onHover: (ev, items) => {
        if(items.length && _routeMapInstance && _routeMapPositionMarker){
          const p = data[items[0].index];
          if(p && p.lat != null){
            _routeMapPositionMarker.setLatLng([p.lat, p.lon]);
            if(!_routeMapInstance.hasLayer(_routeMapPositionMarker)) _routeMapPositionMarker.addTo(_routeMapInstance);
          }
        }
      }
    }
  });
}

async function _routeOnFileSelected(ev){
  const file = ev.target.files && ev.target.files[0];
  if(!file || !_routeCurrent) return;
  const content = document.getElementById('routeContent');
  if(content) content.innerHTML = `<div class="route-loading">⏳ Procesando ${escapeHtml(file.name)}…</div>`;
  try{
    const canonical = await _routeParseFile(file);
    const raceId = _routeCurrent.raceId;
    // 1) Subir al Storage (original + JSON canónico)
    if(content) content.innerHTML = `<div class="route-loading">☁️ Subiendo recorrido a la nube…</div>`;
    await _routeUploadToStorage(raceId, file, canonical);
    // 2) Persistir métricas del curso en races.notes.route
    await _routePersistMetrics(raceId, canonical.summary);
    // 3) Si hay esfuerzo individual (potencia/HR), preguntamos a quién pertenece
    if(canonical.effort && (canonical.effort.power_avg_w || canonical.effort.hr_avg_bpm)){
      const riderHint = await _routeAskRider(file.name);
      // Guardar esfuerzo aunque el director no asigne corredor
      await _routeSaveEffort(raceId, canonical.effort, file.name, canonical.summary.source, canonical.summary.source_device, riderHint);
    }
    // 4) Refrescar el modal
    _routeCurrent.canonical = canonical;
    _routeCurrent.courseJson = null;
    _routeCurrent.race.route = canonical.summary;
    await _routeRenderContent();
    if(typeof showToast === 'function') showToast(`✅ Recorrido cargado · ${(canonical.summary.distance_m/1000).toFixed(1)} km · ${canonical.summary.desnivel_pos_m} m D+`, 'ok', 4000);
  }catch(e){
    console.warn('_routeOnFileSelected', e);
    alert('❌ Error procesando el archivo:\n\n'+(e.message||e));
    await _routeRenderContent();
  }
}

// — "Añadir solo esfuerzo" · NO toca el curso, solo guarda la fila en
//   rider_efforts_fccv. Útil cuando ya tienes un buen recorrido con
//   altimetría (ej. Karles) y quieres añadir el FIT de otro corredor sin
//   perder esa altimetría.
async function _routeOnEffortOnlySelected(ev){
  const file = ev.target.files && ev.target.files[0];
  if(!file || !_routeCurrent) return;
  const ext = (file.name.split('.').pop() || '').toLowerCase();
  if(ext !== 'fit'){
    alert('Solo .fit contiene datos de esfuerzo (potencia/FC). Para sustituir el recorrido usa el botón naranja.');
    if(ev.target) ev.target.value = '';
    return;
  }
  const content = document.getElementById('routeContent');
  // Estado de procesando sin destruir el render actual (lo respeta el render
  // y restauramos al final).
  const status = document.createElement('div');
  status.id = 'routeEffortStatus';
  status.style.cssText = 'background:#dbeafe;border:1px solid #93c5fd;color:#1e3a8a;border-radius:8px;padding:8px 12px;font-size:12px;margin-bottom:10px;font-weight:700';
  status.textContent = `⏳ Procesando esfuerzo de ${file.name}…`;
  if(content && content.firstChild) content.insertBefore(status, content.firstChild);
  try{
    // Parsear el .fit (sin construir canónico de curso, solo nos interesa el
    // effort). Reusamos _routeParseFile que devuelve canonical.effort listo.
    const buf = await file.arrayBuffer();
    const r = await _routeParseFIT(buf);
    if(!r.effort || (!r.effort.power_avg_w && !r.effort.hr_avg_bpm)){
      alert('Este archivo no trae datos de esfuerzo (potencia/FC). No se guarda nada.');
      return;
    }
    const riderHint = await _routeAskRider(file.name);
    const dev = r.device && r.device.mfg ? `${r.device.mfg}${r.device.product?'/'+r.device.product:''}` : null;
    status.textContent = `☁️ Guardando esfuerzo de ${riderHint||'Sin asignar'}…`;
    // También subimos el original al Storage para que quede trazable, pero
    // con un nombre que indica que es solo esfuerzo (no curso de referencia).
    const safeName = file.name.replace(/[^a-zA-Z0-9._-]/g,'_');
    const origKey = `${_routeCurrent.raceId}/effort-${Date.now()}-${safeName}`;
    try{
      await _sb.storage.from(ROUTE_BUCKET).upload(origKey, file, { upsert: false, contentType: 'application/octet-stream' });
    }catch(e){ /* si falla la subida del original, seguimos: lo importante es la fila */ }
    const saveRes = await _routeSaveEffort(_routeCurrent.raceId, r.effort, file.name, 'fit', dev, riderHint);
    if(!saveRes.ok){
      alert('No se pudo guardar el esfuerzo: '+(saveRes.error?.message||'error desconocido'));
      return;
    }
    if(typeof showToast === 'function') showToast(`✅ Esfuerzo añadido: ${riderHint||'Sin asignar'}`, 'ok', 3000);
    await _routeRenderContent();
  }catch(e){
    console.warn('_routeOnEffortOnlySelected', e);
    alert('❌ Error procesando el archivo:\n\n'+(e.message||e));
    const s = document.getElementById('routeEffortStatus');
    if(s) s.remove();
  }finally{
    if(ev.target) ev.target.value = '';
  }
}

// — Pregunta al director a qué corredor pertenece el esfuerzo —
function _routeAskRider(filename){
  // Extraer pistas del nombre del archivo:
  //   "KarlesCubedo-24-05-2026.fit"  →  primer segmento "KarlesCubedo"
  //   Split por mayúsculas:  ["Karles", "Cubedo"]
  // Suposición típica: nombre primero, luego apellido.
  const stem = filename.replace(/\.[^.]+$/, '');
  const firstSeg = stem.split(/[\s_\-]+/)[0] || '';
  const camelParts = firstSeg.split(/(?=[A-Z])/).filter(s => s.length > 0);
  let guessName = camelParts[0] || '';
  let guessApellido = camelParts[1] || '';

  // Buscar coincidencia con las licencias importadas para usar el formato
  // canónico de la app: "Apellido1, Nombre" (igual que renderiza el resto).
  let guess = '';
  try{
    if(typeof _fccvGetLicencias === 'function'){
      const norm = s => (s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').trim();
      const np = norm(guessName);
      const ap = norm(guessApellido);
      const all = _fccvGetLicencias();
      // Probamos en orden: (nombre+apellido), (apellido+nombre), (cualquier
      // coincidencia de nombre), (cualquier coincidencia de apellido).
      let match =
        (np && ap && all.find(l => norm(l.nombre).startsWith(np)    && norm(l.apellidos).startsWith(ap)))    ||
        (np && ap && all.find(l => norm(l.apellidos).startsWith(np) && norm(l.nombre).startsWith(ap)))    ||
        (np && all.find(l => norm(l.nombre).startsWith(np)))   ||
        (ap && all.find(l => norm(l.apellidos).startsWith(ap)));
      if(match){
        const ap1 = (match.apellidos||'').trim().split(/\s+/)[0];
        // Capitalizar primero la primera letra del nombre y apellido para
        // ser consistentes con cómo se ve en el resto de la app.
        const titleCase = s => s ? s.split(/\s+/).map(w => w.charAt(0).toUpperCase()+w.slice(1).toLowerCase()).join(' ') : '';
        guess = `${titleCase(ap1)}, ${titleCase(match.nombre||'')}`;
      }
    }
  }catch(e){ /* silencioso */ }

  // Fallback: si no hay match con licencias, formateamos lo que se haya
  // sacado del nombre del archivo siguiendo la convención "Apellido, Nombre".
  if(!guess){
    if(guessApellido) guess = `${guessApellido}, ${guessName}`;
    else              guess = guessName;
  }

  const choice = prompt(
    `Este archivo contiene datos de esfuerzo (potencia/FC).\n\n¿De qué corredor son? · Formato: Apellido, Nombre\n\nDeja vacío para "Sin asignar".`,
    guess
  );
  return (choice||'').trim() || null;
}

async function _routeDeleteRoute(){
  if(!_routeCurrent) return;
  const { raceId } = _routeCurrent;
  if(!confirm('¿Quitar el recorrido de esta prueba?\n\nSe borrarán las métricas, el mapa y el perfil. Los esfuerzos individuales (potencia/FC) se conservan.\n\nPuedes volver a subir otro archivo en cualquier momento.')) return;
  try{
    // Borrar de Storage
    await _sb.storage.from(ROUTE_BUCKET).remove([`${raceId}/original.fit`, `${raceId}/original.gpx`, `${raceId}/original.tcx`, `${raceId}/course.json`]);
    // Quitar de notes
    const { data } = await _sb.from('races').select('notes').eq('id', raceId).single();
    let extra = {};
    try{ extra = JSON.parse(data?.notes||'{}'); }catch(e){}
    delete extra.route;
    await _sb.from('races').update({ notes: JSON.stringify(extra) }).eq('id', raceId);
    if(Array.isArray(_cachedHistory)){
      const h = _cachedHistory.find(x => x.id === raceId);
      if(h) h.route = null;
    }
    _routeCurrent.race.route = null;
    _routeCurrent.canonical = null;
    _routeCurrent.courseJson = null;
    await _routeRenderContent();
    if(typeof showToast === 'function') showToast('🗑️ Recorrido eliminado','ok',2500);
  }catch(e){
    alert('Error al borrar: '+(e.message||e));
  }
}

async function _routeDeleteEffort(effortId){
  if(!confirm('¿Eliminar este esfuerzo?')) return;
  if(!(await _requireAuthWrite())) return;
  const { error } = await _sb.from('rider_efforts_fccv').delete().eq('id', effortId);
  if(error){ alert('Error: '+error.message); return; }
  await _routeRenderContent();
}

