// Colores configurables de las categorías del calendario anual
const _INF_CAL_COLORS = { cv:'#2B91C8', fuera:'#f59e0b', challenge:'#dc2626', planned:'#94a3b8' };

// Nombre del equipo a usar en el informe
function _infTeamName(){
  let t = '';
  try{ t = (localStorage.getItem('myTeam')||'').trim(); }catch(_){}
  if(!t && typeof myTeam !== 'undefined' && myTeam && myTeam.trim()) t = myTeam.trim();
  return t || 'TBG-WIXUM';
}

// Comparación flexible de equipos para el informe (mismo criterio que el
// resto de la app: teamKey + tokens significativos compartidos). Evita que
// "TBG-WIXUM" no case con "TBG WIXUM CC" o variantes.
function _infTeamMatcher(teamName){
  const myKey = (typeof teamKey==='function') ? teamKey(teamName) : (teamName||'').toLowerCase().trim();
  const myTokens = (typeof teamSignificantTokens==='function') ? teamSignificantTokens(teamName) : [];
  const mySet = new Set(myTokens);
  return function(rawTeam){
    if(!rawTeam) return false;
    const rk = (typeof teamKey==='function') ? teamKey(rawTeam) : String(rawTeam).toLowerCase().trim();
    if(!rk) return false;
    if(rk === myKey) return true;
    if(myKey && (rk.includes(myKey) || myKey.includes(rk))) return true;
    // Token-match: comparten TODOS los tokens significativos de mi equipo
    if(mySet.size){
      const rTokens = (typeof teamSignificantTokens==='function') ? teamSignificantTokens(rawTeam) : rk.split(/\s+/);
      const rSet = new Set(rTokens);
      let allShared = true;
      for(const t of mySet){ if(!rSet.has(t)){ allShared=false; break; } }
      if(allShared) return true;
    }
    return false;
  };
}

// Deriva el tipo de prueba a partir del nombre + categoría
function _infTipoPrueba(name, cat){
  const t = ((name||'')+' '+(cat||'')).toLowerCase();
  if(/crono|contrarreloj|\bcri\b|c\.?r\.?i|cronoescalada/.test(t)) return 'Contrarreloj';
  if(/criteri/.test(t)) return 'Criterium';
  if(/ciclo.?cross|\bcx\b/.test(t)) return 'Ciclocross';
  if(/gravel/.test(t)) return 'Gravel';
  if(/\bbtt\b|xco|rally|\bmtb\b|enduro/.test(t)) return 'BTT';
  if(/\bpista\b|velodrom/.test(t)) return 'Pista';
  if(/\bbmx\b/.test(t)) return 'BMX';
  if(/vuelta|volta/.test(t)) return 'Vuelta por etapas';
  if(/challenge/.test(t)) return 'Challenge';
  if(/marcha|cicloturist|gran fondo|fondo/.test(t)) return 'Marcha cicloturista';
  return 'Ruta en línea';
}

// Normaliza texto: minúsculas, sin acentos, sin signos
function _infNorm(s){ return String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9 ]+/g,' ').replace(/\s+/g,' ').trim(); }

// Mapa COMPLETO de provincias españolas → Comunidad Autónoma (clave normalizada)
const _INF_PROV_CCAA = {
  // Comunitat Valenciana
  'alicante':'Comunitat Valenciana','alacant':'Comunitat Valenciana',
  'castellon':'Comunitat Valenciana','castello':'Comunitat Valenciana',
  'valencia':'Comunitat Valenciana',
  // Andalucía
  'almeria':'Andalucía','cadiz':'Andalucía','cordoba':'Andalucía','granada':'Andalucía','huelva':'Andalucía','jaen':'Andalucía','malaga':'Andalucía','sevilla':'Andalucía',
  // Aragón
  'huesca':'Aragón','teruel':'Aragón','zaragoza':'Aragón',
  // Asturias
  'asturias':'Asturias','oviedo':'Asturias',
  // Illes Balears
  'baleares':'Illes Balears','illes balears':'Illes Balears','mallorca':'Illes Balears',
  // Canarias
  'las palmas':'Canarias','santa cruz de tenerife':'Canarias','tenerife':'Canarias',
  // Cantabria
  'cantabria':'Cantabria','santander':'Cantabria',
  // Castilla-La Mancha
  'albacete':'Castilla-La Mancha','ciudad real':'Castilla-La Mancha','cuenca':'Castilla-La Mancha','guadalajara':'Castilla-La Mancha','toledo':'Castilla-La Mancha',
  // Castilla y León
  'avila':'Castilla y León','burgos':'Castilla y León','leon':'Castilla y León','palencia':'Castilla y León','salamanca':'Castilla y León','segovia':'Castilla y León','soria':'Castilla y León','valladolid':'Castilla y León','zamora':'Castilla y León',
  // Cataluña
  'barcelona':'Cataluña','girona':'Cataluña','gerona':'Cataluña','lleida':'Cataluña','lerida':'Cataluña','tarragona':'Cataluña',
  // Extremadura
  'badajoz':'Extremadura','caceres':'Extremadura',
  // Galicia
  'a coruna':'Galicia','la coruna':'Galicia','coruna':'Galicia','lugo':'Galicia','ourense':'Galicia','orense':'Galicia','pontevedra':'Galicia',
  // Madrid
  'madrid':'Comunidad de Madrid',
  // Murcia
  'murcia':'Región de Murcia',
  // Navarra
  'navarra':'Navarra','pamplona':'Navarra',
  // País Vasco
  'alava':'País Vasco','araba':'País Vasco','guipuzcoa':'País Vasco','gipuzkoa':'País Vasco','vizcaya':'País Vasco','bizkaia':'País Vasco',
  // La Rioja
  'la rioja':'La Rioja','rioja':'La Rioja','logrono':'La Rioja',
  // Ceuta / Melilla
  'ceuta':'Ceuta','melilla':'Melilla'
};

// Palabras clave (en nombre o localidad) que identifican CCAA fuera de la lista de provincias.
// Cada entrada: [regex sobre texto normalizado, CCAA]. Orden: lo más específico primero.
const _INF_CCAA_KW = [
  [/\bextremadura\b/, 'Extremadura'],
  [/\bbajo aragon\b|\baragon\b|\bmaestrazgo turolense\b/, 'Aragón'],
  [/\bvinedos\b|\bvillarrobledo\b|\bla mancha\b|\bmancha\b/, 'Castilla-La Mancha'],
  [/\bcastilla y leon\b/, 'Castilla y León'],
  [/\bcatalunya\b|\bcataluna\b/, 'Cataluña'],
  [/\bandalucia\b/, 'Andalucía'],
  [/\bregion de murcia\b|\bmurcia\b/, 'Región de Murcia'],
  [/\bpais vasco\b|\beuskadi\b/, 'País Vasco'],
  [/\bgalicia\b/, 'Galicia'],
  [/\bnavarra\b/, 'Navarra'],
  [/\bla rioja\b/, 'La Rioja'],
  [/\bcomunidad de madrid\b|\bmadrid\b/, 'Comunidad de Madrid'],
  [/\basturias\b/, 'Asturias'],
  [/\bcantabria\b/, 'Cantabria'],
  [/\billes balears\b|\bislas baleares\b|\bmallorca\b/, 'Illes Balears'],
  [/\bcanarias\b|\btenerife\b/, 'Canarias']
];

// Parsea provincia (y CCAA) de la localidad si viene como "PUEBLO (PROVINCIA)"
function _infProvincia(loc){
  if(!loc) return {prov:'', ccaa:''};
  const m = String(loc).match(/\(([^)]+)\)\s*$/);
  if(!m) return {prov:'', ccaa:''};
  const prov = m[1].trim();
  const ccaa = _INF_PROV_CCAA[_infNorm(prov)] || '';
  return {prov, ccaa};
}

// Determina la CCAA de una prueba combinando todas las señales disponibles.
// Devuelve '' solo si no hay ninguna pista (entonces se asume CV por ser calendario FCCV).
function _infDetectCCAA(name, localidad, prov, ccaaField){
  if(ccaaField && String(ccaaField).trim()) return String(ccaaField).trim();
  if(prov){ const c=_INF_PROV_CCAA[_infNorm(prov)]; if(c) return c; }
  const txt = _infNorm((name||'') + ' ' + (localidad||''));
  // Provincia mencionada en el texto (palabra completa)
  for(const k in _INF_PROV_CCAA){ if(new RegExp('\\b'+k.replace(/ /g,'\\s')+'\\b').test(txt)) return _INF_PROV_CCAA[k]; }
  // Palabras clave de región
  for(const [re,c] of _INF_CCAA_KW){ if(re.test(txt)) return c; }
  return '';
}
// Limpia la localidad quitando el paréntesis de provincia
function _infLimpiaLoc(loc){
  return String(loc||'').replace(/\s*\([^)]*\)\s*$/,'').trim();
}

/* ── Paleta para comparativas ─────────────────────────────────────────── */
const _INF_PALETTE = ['#2B91C8','#dc2626','#10b981','#f59e0b','#7c3aed','#0891b2','#db2777','#65a30d'];
const _INF_DISCLAIMER = 'Este informe se basa únicamente en los datos registrados en la aplicación. Si faltan pruebas o participaciones de algún equipo, los resultados pueden no reflejar la totalidad de su calendario.';

// ── Lista de equipos presentes en los datos (agrupados por teamKey) ──────
// Devuelve [{key, name, count}] ordenado por nº de participaciones desc.
// 'name' es la grafía más frecuente tal cual está en la base de datos.
function _infCollectTeams(history, year){
  const groups = {}; // key -> {names:{raw:count}, total}
  for(const race of (history||[])){
    const ry = (_parseSpanishDate(race.raceDate)||'').slice(0,4);
    if(year && ry!==year) continue;
    for(const r of (race.riders||[])){
      const raw = (r.team||'').trim();
      if(!raw) continue;
      const k = (typeof teamKey==='function') ? teamKey(raw) : raw.toLowerCase();
      if(!k) continue;
      if(!groups[k]) groups[k] = {names:{}, total:0};
      groups[k].names[raw] = (groups[k].names[raw]||0)+1;
      groups[k].total++;
    }
  }
  return Object.entries(groups).map(([key,g])=>{
    // grafía más frecuente
    const name = Object.entries(g.names).sort((a,b)=>b[1]-a[1])[0][0];
    return {key, name, count:g.total};
  }).sort((a,b)=> b.count-a.count || a.name.localeCompare(b.name));
}

// ── Núcleo: construye los datos del informe para UN equipo (por teamKey) ──
// opts: {teamKey, teamName, year, catSel, includePlanned, onlyPlanned, tipo, prov, dateFrom, dateTo}
function _infBuildDataByKey(history, opts){
  const o = opts||{};
  const wantKey = o.teamKey || '';
  const isTeam = (raw)=>{
    if(!raw) return false;
    const k = (typeof teamKey==='function') ? teamKey(raw) : String(raw).toLowerCase().trim();
    return k === wantKey;
  };
  const catMatch = (c)=>{
    if(!o.catSel) return true;
    const cc = (c||'').toLowerCase();
    if(o.catSel==='cadete')  return /cadet|\bcad\b|\bcad-?\d/.test(cc);
    if(o.catSel==='juvenil') return /juv|junior|j[uú]nior|\bjun\b/.test(cc);
    return true;
  };
  // Resuelve la categoría de un corredor en una carrera con varios respaldos:
  // override → cat del corredor → categoría/clase de la carrera → nombre de la
  // prueba. Devuelve {cat, known}. Si no se puede determinar, known=false.
  const resolveCat = (r, race, ry)=>{
    let c = (typeof getRiderCorrectCat==='function'
      ? getRiderCorrectCat(r.name, ry?parseInt(ry):null, r.cat) : '') || '';
    if(!c) c = (r.cat||'').trim();
    if(c) return {cat:c, known:true};
    // Respaldo a nivel de carrera
    const rc = (race.cat||race.category||race.categoria||'').trim();
    if(rc) return {cat:rc, known:true};
    // Inferir del nombre de la prueba
    const nm = (race.raceName||'').toLowerCase();
    if(/cadet/.test(nm)) return {cat:'Cadete', known:true};
    if(/juvenil|junior|j[uú]nior/.test(nm)) return {cat:'Juvenil', known:true};
    return {cat:'', known:false};
  };
  const inDate = (iso)=>{
    if(o.dateFrom && iso && iso < o.dateFrom) return false;
    if(o.dateTo   && iso && iso > o.dateTo)   return false;
    return true;
  };
  const tipoMatch = (t)=> !o.tipo || t===o.tipo;
  const provMatch = (p)=> !o.prov || p===o.prov;

  const realizadas = [];
  if(!o.onlyPlanned){
    for(const race of (history||[])){
      const iso = (_parseSpanishDate(race.raceDate)||'');
      const ry = iso.slice(0,4);
      if(o.year && ry!==o.year) continue;
      if(!inDate(iso)) continue;
      // Clasificados (finishers) de mi equipo
      const mine = [];
      for(const r of (race.riders||[])){
        if(!isTeam(r.team||'')) continue;
        const {cat:rcat, known} = resolveCat(r, race, ry);
        // Si hay filtro de categoría: descartar solo cuando la categoría es
        // CONOCIDA y no coincide. Si es desconocida, no se descarta (mejor
        // mostrar la prueba que ocultar el calendario del equipo).
        if(o.catSel && known && !catMatch(rcat)) continue;
        mine.push({ name:r.name||'', pos:r.pos, cat:rcat });
      }
      // Inscritos de mi equipo (lista de salida). Permite reflejar la
      // participación real: muchas veces se inscriben más de los que
      // terminan/clasifican (abandonos, descalificaciones de jueces, etc.).
      const insList = Array.isArray(race.inscritos) ? race.inscritos : [];
      const hasIns = insList.length>0;
      const mineIns = [];
      for(const ins of insList){
        if(!isTeam(ins.team||'')) continue;
        const ic = (ins.cat||'').trim();
        if(o.catSel && ic && !catMatch(ic)) continue; // solo excluye si la cat es conocida y no casa
        mineIns.push({ name: ins.name||'', cat: ic });
      }
      // La prueba cuenta si el equipo estuvo presente: clasificó o se inscribió
      if(!mine.length && !mineIns.length) continue;
      const {prov, ccaa} = _infProvincia(race.localidad);
      const cats = [...new Set([...mine.map(m=>m.cat), ...mineIns.map(m=>m.cat)].filter(Boolean))];
      const tipo = _infTipoPrueba(race.raceName, cats.join(' '));
      if(!tipoMatch(tipo)) continue;
      if(!provMatch(prov)) continue;
      realizadas.push({
        iso,
        fecha: race.raceDate || (iso? iso.split('-').reverse().join('/'):''),
        name: race.raceName||'',
        localidad: _infLimpiaLoc(race.localidad),
        prov, ccaa, cats, tipo,
        challengeCV: !!race.challengeCV,
        km: (race.km && String(race.km).trim()) ? String(race.km).trim() : '',
        totalParticipantes: (race.riders||[]).length,
        totalInscritos: hasIns ? insList.length : null,
        misCorredores: mine.length,                 // clasificados (finishers)
        misInscritos: hasIns ? mineIns.length : null, // inscritos del equipo
        nombresMios: (mine.length? mine.map(m=>m.name) : mineIns.map(m=>m.name)),
        // Estado SOLO por fecha: si la prueba aún no ha llegado (clasificación con
        // fecha futura = pre-inscripción adelantada), es "pendiente", no "realizada".
        estado: _raceIsRealizadaISO(iso) ? 'realizada' : 'pendiente'
      });
    }
    realizadas.sort((a,b)=> (a.iso||'').localeCompare(b.iso||''));
  }

  const planificadas = [];
  if((o.includePlanned || o.onlyPlanned) && typeof _calPlanned!=='undefined' && Array.isArray(_calPlanned)){
    for(const p of _calPlanned){
      const iso = p.dateStr || (p.date instanceof Date ? p.date.toISOString().slice(0,10):'');
      const ry = (iso||'').slice(0,4);
      if(o.year && ry!==o.year) continue;
      if(!inDate(iso)) continue;
      if(o.catSel && !catMatch(p.cat)) continue;
      const {prov, ccaa} = _infProvincia(p.localidad);
      const tipo = _infTipoPrueba(p.name, p.cat);
      if(!tipoMatch(tipo)) continue;
      if(!provMatch(prov)) continue;
      planificadas.push({
        iso, fecha: iso? iso.split('-').reverse().join('/'):'',
        name: p.name||'', localidad:_infLimpiaLoc(p.localidad),
        prov, ccaa: ccaa||p.ccaa||'', cats:p.cat?[p.cat]:[], tipo,
        challengeCV: !!p.challengeCV,
        km:'', totalParticipantes:0, totalInscritos:null, misCorredores:0, misInscritos:null, nombresMios:[], estado:'planificada'
      });
    }
    planificadas.sort((a,b)=> (a.iso||'').localeCompare(b.iso||''));
  }

  const locs = [...new Set(realizadas.map(r=>r.localidad).filter(Boolean))];
  const provs = [...new Set(realizadas.map(r=>r.prov).filter(Boolean))];
  const ccaas = [...new Set(realizadas.map(r=>r.ccaa).filter(Boolean))];
  const tipos = [...new Set(realizadas.map(r=>r.tipo).filter(Boolean))];
  const totalPart = realizadas.reduce((s,r)=>s+r.misCorredores,0);
  const kmList = realizadas.map(r=>parseFloat(String(r.km).replace(',','.'))).filter(v=>!isNaN(v)&&v>0);
  const kmTotal = kmList.reduce((s,v)=>s+v,0);
  const vueltas = realizadas.filter(r=>/vuelta|volta|etapa|challenge/i.test(r.name) || r.tipo==='Vuelta por etapas').length;
  const nombresUnicos = [...new Set(realizadas.flatMap(r=>r.nombresMios).map(n=>(typeof _evolNormName==='function'?_evolNormName(n):n)).filter(Boolean))];
  const con3 = realizadas.filter(r=>r.misCorredores>=3).length;
  const menos3 = realizadas.length - con3;
  // Inscritos (solo pruebas con lista de inscritos disponible)
  const conInscritos = realizadas.filter(r=>r.misInscritos!=null);
  const totalInscritos = conInscritos.reduce((s,r)=>s+r.misInscritos,0);
  const pruebasConInscritos = conInscritos.length;

  return {
    realizadas, planificadas,
    resumen:{
      totalPruebas: realizadas.length,
      vueltas,
      localidades: locs, provincias: provs, ccaas,
      participaciones: totalPart,               // clasificados (finishers)
      mediaPorPrueba: realizadas.length ? (totalPart/realizadas.length) : 0,
      inscripciones: totalInscritos,            // inscritos del equipo (donde hay lista)
      pruebasConInscritos,
      mediaInscritos: pruebasConInscritos ? (totalInscritos/pruebasConInscritos) : 0,
      tipos,
      kmTotal: kmList.length ? kmTotal : null,
      kmConDato: kmList.length,
      ciclistasUnicos: nombresUnicos,
      con3, menos3
    }
  };
}

// ════════════════════════════ MODAL ═════════════════════════════════════
