async function _infCopyPost(){
  const opts=_infReadOpts();
  const st=document.getElementById('_infStatus');
  if(!opts.teams.length){ if(st) st.textContent='⚠️ Selecciona un equipo.'; return; }
  let history=[]; try{ history=await _ensureHistory(); }catch(_){ history=(typeof _cachedHistory!=='undefined'?_cachedHistory:[])||[]; }
  const team=opts.teams[0];
  const D=_infBuildDataByKey(history, _infFilters(opts, team)); const R=D.resumen;
  if(!R.totalPruebas){ if(st) st.innerHTML=_infDiagNoData(history, opts.year, team.key); return; }
  const teamName=team.name;
  const tipos=R.tipos.length?R.tipos.join(', '):'';
  const post=`🚴 UNA TEMPORADA DE OPORTUNIDADES — ${teamName} ${opts.year}

En ${teamName} seguimos apostando por el desarrollo de nuestros jóvenes ciclistas dándoles calendario, planificación y competición real.

📊 Temporada ${opts.year} en cifras:
🏁 ${R.totalPruebas} pruebas disputadas
📍 ${R.localidades.length} localidades visitadas${R.provincias.length?`\n🗺️ ${R.provincias.length} provincias`:''}
👥 ${R.participaciones} participaciones
🚲 Media de ${R.mediaPorPrueba.toFixed(1)} corredores por prueba${tipos?`\n🏆 ${tipos}`:''}

El desarrollo de un ciclista también se construye compitiendo. 💪

#${teamName.replace(/[^a-z0-9]+/gi,'')} #ciclismo #ciclismobase #cantera #FCCV #ComunitatValenciana`;
  try{ await navigator.clipboard.writeText(post); if(st) st.textContent='✅ Texto copiado al portapapeles.'; }
  catch(_){
    const oldb=document.getElementById('_infPostBox'); if(oldb) oldb.remove();
    const box=document.createElement('div'); box.id='_infPostBox'; box.style.cssText='margin-top:12px';
    box.innerHTML=`<textarea readonly style="width:100%;height:170px;border:1.5px solid #cbd5e1;border-radius:10px;padding:10px;font-size:12px;font-family:inherit" onclick="this.select()">${escapeHtml(post)}</textarea>`;
    document.getElementById('_infBtnsInd')?.parentNode?.appendChild(box);
    if(st) st.textContent='ℹ️ Copia el texto del cuadro de abajo.';
  }
}

// ════════════════════════ INFORME COMPARATIVO ═══════════════════════════
function _infRaceKey(r){
  const nm=(r.name||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9 ]/g,'').replace(/\s+/g,' ').trim().slice(0,28);
  return (r.iso||'')+'|'+nm;
}
function _infBuildComparative(history, opts){
  const teamsData = opts.teams.map(t=>({ team:t, D:_infBuildDataByKey(history, _infFilters(opts, t)) }));
  // Conjuntos de claves de prueba por equipo (realizadas)
  teamsData.forEach(td=>{ td.keys=new Set(td.D.realizadas.map(_infRaceKey)); td.byKey={}; td.D.realizadas.forEach(r=>{ td.byKey[_infRaceKey(r)]=r; }); });
  // Comunes a TODOS
  let comunes=[];
  if(teamsData.length>=2){
    const base=teamsData[0];
    for(const k of base.keys){
      if(teamsData.every(td=>td.keys.has(k))) comunes.push(base.byKey[k]);
    }
    comunes.sort((a,b)=>(a.iso||'').localeCompare(b.iso||''));
  }
  // Exclusivas por equipo (solo ese equipo la tiene)
  teamsData.forEach((td,i)=>{
    td.exclusivas = td.D.realizadas.filter(r=>{
      const k=_infRaceKey(r);
      return teamsData.every((o,j)=> j===i || !o.keys.has(k));
    });
  });
  return { teamsData, comunes };
}

async function _infGenerateComparativePDF(){
  const opts=_infReadOpts();
  const st=document.getElementById('_infStatus');
  if(opts.teams.length<2){ if(st) st.textContent='⚠️ Selecciona al menos 2 equipos para comparar.'; return; }
  if(st) st.textContent='⏳ Preparando comparativa…';
  let history=[]; try{ history=await _ensureHistory(); }catch(_){ history=(typeof _cachedHistory!=='undefined'?_cachedHistory:[])||[]; }
  const C=_infBuildComparative(history, opts);
  const anyData=C.teamsData.some(td=>td.D.realizadas.length);
  if(!anyData){ if(st) st.innerHTML=_infDiagNoData(history, opts.year); return; }
  if(st) st.textContent='✅ Abriendo la comparativa…';
  const hoy=new Date().toLocaleDateString('es-ES',{day:'2-digit',month:'long',year:'numeric'});

  // Tabla comparativa. Distinguimos INSCRITOS (lista de salida) de
  // CLASIFICADOS (finishers en resultados), porque el nº de finalizados suele
  // ser menor que el de inscritos (abandonos, descalificaciones, etc.).
  const insVal = td => td.D.resumen.pruebasConInscritos ? String(td.D.resumen.inscripciones) : 's/d';
  const mediaInsVal = td => td.D.resumen.pruebasConInscritos ? td.D.resumen.mediaInscritos.toFixed(1) : 's/d';
  const cols=[
    ['Pruebas realizadas', td=>td.D.resumen.totalPruebas],
    ['Vueltas / etapas', td=>td.D.resumen.vueltas],
    ['Localidades', td=>td.D.resumen.localidades.length],
    ['Provincias', td=>td.D.resumen.provincias.length],
    ['Inscripciones (lista de salida)', insVal],
    ['Clasificaciones (finalizadas)', td=>td.D.resumen.participaciones],
    ['Media inscritos/prueba', mediaInsVal],
    ['Media clasificados/prueba', td=>td.D.resumen.mediaPorPrueba?td.D.resumen.mediaPorPrueba.toFixed(1):'—'],
    ['Pruebas con ≥3 clasificados', td=>td.D.resumen.con3],
    ['Puntuables por equipos (≥3)', td=>td.D.resumen.con3],
    ['Sin equipo completo (<3)', td=>td.D.resumen.menos3]
  ];
  const headTeams=C.teamsData.map((td,i)=>`<th style="background:${_INF_PALETTE[i%_INF_PALETTE.length]};color:#fff">${escapeHtml(td.team.name)}</th>`).join('');
  const bodyRows=cols.map(c=>`<tr><td class="metric">${c[0]}</td>${C.teamsData.map(td=>`<td>${escapeHtml(String(c[1](td)))}</td>`).join('')}</tr>`).join('');
  // Tipos por equipo
  const tiposRow=`<tr><td class="metric">Tipos de prueba</td>${C.teamsData.map(td=>`<td style="font-size:9.5px">${td.D.resumen.tipos.map(escapeHtml).join(', ')||'—'}</td>`).join('')}</tr>`;

  // Gráfico de barras (Pruebas realizadas y Participaciones) en HTML
  const maxPr=Math.max(1,...C.teamsData.map(td=>td.D.resumen.totalPruebas));
  const maxPa=Math.max(1,...C.teamsData.map(td=>td.D.resumen.participaciones));
  const barChart=(titulo, val, max)=>`<div class="chart"><div class="chart-t">${titulo}</div>${C.teamsData.map((td,i)=>{
    const v=val(td); const pct=Math.round(v/max*100);
    return `<div class="bar-row"><div class="bar-lab">${escapeHtml(td.team.name)}</div><div class="bar-track"><div class="bar-fill" style="width:${pct}%;background:${_INF_PALETTE[i%_INF_PALETTE.length]}">${v}</div></div></div>`;
  }).join('')}</div>`;

  // Coincidencias
  const comunesList = C.comunes.length
    ? `<ul class="lst">${C.comunes.map(r=>`<li><b>${escapeHtml(r.fecha)}</b> — ${escapeHtml(r.name)}${r.localidad?` <span style="color:#94a3b8">(${escapeHtml(r.localidad)})</span>`:''}</li>`).join('')}</ul>`
    : `<p style="color:#94a3b8;font-size:12px">No hay pruebas disputadas por todos los equipos seleccionados (según los datos registrados).</p>`;
  const exclusivasBlocks = C.teamsData.map((td,i)=>`<div style="margin-bottom:10px"><div style="font-weight:800;color:${_INF_PALETTE[i%_INF_PALETTE.length]};font-size:12.5px;margin-bottom:3px">Solo ${escapeHtml(td.team.name)} (${td.exclusivas.length})</div>${td.exclusivas.length?`<ul class="lst">${td.exclusivas.slice(0,40).map(r=>`<li><b>${escapeHtml(r.fecha)}</b> — ${escapeHtml(r.name)}</li>`).join('')}${td.exclusivas.length>40?`<li style="color:#94a3b8">… y ${td.exclusivas.length-40} más</li>`:''}</ul>`:`<p style="color:#94a3b8;font-size:11.5px;margin:2px 0">—</p>`}</div>`).join('');

  // Resumen objetivo (solo datos)
  const resumenObj = C.teamsData.map(td=>{
    const R=td.D.resumen;
    const insTxt = R.pruebasConInscritos ? `${R.inscripciones} inscripciones, ` : '';
    return `<li><b>${escapeHtml(td.team.name)}</b>: ${R.totalPruebas} pruebas, ${insTxt}${R.participaciones} clasificaciones, ${R.localidades.length} localidades, media ${R.mediaPorPrueba?R.mediaPorPrueba.toFixed(1):'—'} clasificados/prueba.</li>`;
  }).join('');

  // Listas por equipo
  const listasEquipo = C.teamsData.map((td,i)=>`<div class="sec-block"><h2 class="sec-t" style="border-color:${_INF_PALETTE[i%_INF_PALETTE.length]}">📋 ${escapeHtml(td.team.name)} — pruebas (${td.D.realizadas.length})</h2>${td.D.realizadas.length?`<table class="lt"><thead><tr><th>Fecha</th><th>Prueba</th><th>Localidad</th><th>Tipo</th><th title="Inscritos del equipo">Insc.</th><th title="Clasificados del equipo">Clasif.</th></tr></thead><tbody>${td.D.realizadas.map(r=>`<tr><td>${escapeHtml(r.fecha)}</td><td>${escapeHtml(r.name)}</td><td>${escapeHtml(r.localidad||'—')}</td><td>${escapeHtml(r.tipo)}</td><td style="text-align:center">${r.misInscritos!=null?r.misInscritos:'s/d'}</td><td style="text-align:center">${r.misCorredores}</td></tr>`).join('')}</tbody></table>`:`<p style="color:#94a3b8">Sin pruebas registradas con los filtros aplicados.</p>`}</div>`).join('');

  const w=window.open('','_blank');
  if(!w){ alert('El navegador bloqueó la ventana. Permite ventanas emergentes e inténtalo de nuevo.'); return; }
  w.document.write(`<!DOCTYPE html><html lang="es"><head><meta charset="utf-8">
  <title>Comparativa de calendario y participación</title>
  <style>
    @page{size:A4 portrait;margin:0}
    *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;box-sizing:border-box}
    html,body{margin:0;padding:0;font-family:'Segoe UI',Arial,sans-serif;color:#1f2937}
    .page-wrap{padding:15mm 12mm 16mm;-webkit-box-decoration-break:clone;box-decoration-break:clone}
    .no-print{text-align:right;margin-bottom:10px}
    .no-print button{background:#2B91C8;color:#fff;border:none;border-radius:8px;padding:9px 16px;font-weight:800;cursor:pointer;margin-left:8px;font-size:13px}
    .no-print button.sec{background:#f3f4f6;color:#374151;border:1px solid #d0d5dd}
    .hd{background:linear-gradient(135deg,#0e4d73,#2B91C8);color:#fff;border-radius:14px;padding:22px 24px;margin-bottom:18px}
    .hd h1{margin:0 0 4px;font-size:24px;font-weight:900}
    .hd .sub{font-size:13px;opacity:.9}
    h2.sec-t{color:#0e4d73;font-size:18px;font-weight:900;margin:18px 0 10px;border-bottom:3px solid #2B91C8;padding-bottom:7px}
    table.cmp{width:100%;border-collapse:collapse;font-size:11.5px;margin-bottom:8px}
    table.cmp th,table.cmp td{border:1px solid #e2e8f0;padding:7px 8px;text-align:center}
    table.cmp th{font-size:11px}
    table.cmp td.metric{text-align:left;font-weight:700;color:#334155;background:#f8fafc}
    .chart{margin:14px 0;break-inside:avoid}
    .chart-t{font-weight:800;color:#0e4d73;font-size:13px;margin-bottom:8px}
    .bar-row{display:flex;align-items:center;gap:10px;margin-bottom:6px}
    .bar-lab{width:32%;font-size:11px;font-weight:700;color:#334155;text-align:right;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
    .bar-track{flex:1;background:#f1f5f9;border-radius:6px;height:24px;overflow:hidden}
    .bar-fill{height:100%;border-radius:6px;color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:flex-end;padding-right:8px;min-width:28px}
    .lst{margin:4px 0 0;padding-left:18px;font-size:11.5px;color:#334155}
    .lst li{margin-bottom:2px}
    table.lt{width:100%;border-collapse:collapse;font-size:10.5px}
    table.lt th{background:#f0f4f8;padding:6px 7px;text-align:left;font-size:9.5px;text-transform:uppercase;color:#475467}
    table.lt td{padding:5px 7px;border-bottom:1px solid #f3f4f6}
    .disc{background:#fff7ed;border:1px solid #fdba74;border-radius:10px;padding:11px 13px;font-size:11px;color:#9a3412;line-height:1.45;margin:14px 0}
    .interno{background:#fee2e2;border:1px solid #fca5a5;color:#991b1b;font-weight:800;font-size:11px;border-radius:8px;padding:7px 11px;display:inline-block;margin-bottom:12px}
    .sec-block{page-break-before:always}
    .footer{position:fixed;bottom:5mm;left:12mm;right:12mm;display:flex;justify-content:space-between;font-size:9px;color:#94a3b8;border-top:1px solid #e5e7eb;padding-top:4px}
  </style></head><body>
  <div class="no-print"><button onclick="window.print()">🖨️ Imprimir / Guardar PDF</button><button class="sec" onclick="window.close()">✕ Cerrar</button></div>
  <div class="page-wrap">
    <div class="hd"><h1>⚖️ Comparativa de calendario y participación</h1><div class="sub">Temporada ${escapeHtml(opts.year)} · ${escapeHtml(_infCatLabel(opts.catSel))} · Generado el ${hoy}</div></div>
    <span class="interno">🔒 DOCUMENTO DE USO INTERNO</span>
    <div class="disc">⚠️ ${_INF_DISCLAIMER}</div>

    <h2 class="sec-t">📊 Tabla comparativa</h2>
    <table class="cmp"><thead><tr><th style="text-align:left">Métrica</th>${headTeams}</tr></thead><tbody>${bodyRows}${tiposRow}</tbody></table>
    <p style="font-size:10px;color:#94a3b8">* <b>Inscripciones</b> = ciclistas en la lista de salida; <b>Clasificaciones</b> = ciclistas que finalizaron y aparecen en resultados. El nº de clasificados suele ser menor (abandonos, descalificaciones, etc.). "s/d" = no hay lista de inscritos registrada para esa prueba. "Puntuable por equipos" se considera a partir de 3 ciclistas clasificados (ajustable según el reglamento de cada prueba).</p>

    ${barChart('Pruebas realizadas', td=>td.D.resumen.totalPruebas, maxPr)}
    ${C.teamsData.some(td=>td.D.resumen.pruebasConInscritos)?barChart('Inscripciones (lista de salida)', td=>td.D.resumen.inscripciones, Math.max(1,...C.teamsData.map(td=>td.D.resumen.inscripciones))):''}
    ${barChart('Clasificaciones (ciclistas finalizados)', td=>td.D.resumen.participaciones, maxPa)}

    <h2 class="sec-t">🔗 Coincidencias</h2>
    <div style="font-weight:800;color:#0e4d73;font-size:12.5px;margin-bottom:4px">Pruebas disputadas por TODOS los equipos (${C.comunes.length})</div>
    ${comunesList}
    <div style="font-weight:800;color:#0e4d73;font-size:12.5px;margin:12px 0 4px">Pruebas exclusivas de cada equipo</div>
    ${exclusivasBlocks}

    <h2 class="sec-t">🧾 Resumen objetivo</h2>
    <ul class="lst">${resumenObj}</ul>
    <div class="disc">Este resumen presenta exclusivamente cifras verificables a partir de los datos registrados. No incluye valoraciones sobre la calidad o el rendimiento de ningún equipo.</div>

    ${listasEquipo}
  </div>
  <div class="footer"><span>Comparativa de calendario · uso interno</span><span>Temporada ${escapeHtml(opts.year)}</span></div>
  <script>window.onload=function(){setTimeout(function(){window.print();},300);};<\/script>
  </body></html>`);
  w.document.close();
}

async function _infGenerateComparativeInfografia(){
  const opts=_infReadOpts();
  const st=document.getElementById('_infStatus');
  if(opts.teams.length<2){ if(st) st.textContent='⚠️ Selecciona al menos 2 equipos para comparar.'; return; }
  if(st) st.textContent='⏳ Generando infografía comparativa…';
  let history=[]; try{ history=await _ensureHistory(); }catch(_){ history=(typeof _cachedHistory!=='undefined'?_cachedHistory:[])||[]; }
  const C=_infBuildComparative(history, opts);
  if(!C.teamsData.some(td=>td.D.realizadas.length)){ if(st) st.innerHTML=_infDiagNoData(history, opts.year); return; }

  const W=1200,H=Math.max(675, 280+C.teamsData.length*120);
  const cv=document.createElement('canvas'); cv.width=W; cv.height=H;
  const ctx=cv.getContext('2d');
  ctx.fillStyle='#0f172a'; ctx.fillRect(0,0,W,H);
  // Cabecera
  ctx.fillStyle='#fff'; ctx.textAlign='left'; ctx.font='900 34px "Segoe UI",Arial';
  ctx.fillText('Comparativa de calendario', 50, 56);
  ctx.fillStyle='#94a3b8'; ctx.font='700 18px "Segoe UI",Arial';
  ctx.fillText('Temporada '+opts.year+' · '+_infCatLabel(opts.catSel), 50, 84);
  // Banner uso interno
  ctx.fillStyle='#dc2626'; _infRoundRect(ctx, W-310, 30, 260, 38, 8); ctx.fill();
  ctx.fillStyle='#fff'; ctx.textAlign='center'; ctx.font='800 15px "Segoe UI",Arial';
  ctx.fillText('🔒 USO INTERNO', W-180, 55);

  // Barras: pruebas realizadas
  const maxPr=Math.max(1,...C.teamsData.map(td=>td.D.resumen.totalPruebas));
  let y=140;
  ctx.textAlign='left'; ctx.fillStyle='#e2e8f0'; ctx.font='800 18px "Segoe UI",Arial';
  ctx.fillText('Pruebas realizadas', 50, y-12);
  const trackX=320, trackW=W-trackX-90;
  C.teamsData.forEach((td,i)=>{
    const col=_INF_PALETTE[i%_INF_PALETTE.length];
    ctx.fillStyle='#cbd5e1'; ctx.textAlign='right'; ctx.font='700 16px "Segoe UI",Arial';
    ctx.fillText(td.team.name.slice(0,28), trackX-14, y+26);
    ctx.fillStyle='#1e293b'; _infRoundRect(ctx,trackX,y,trackW,34,8); ctx.fill();
    const pct=td.D.resumen.totalPruebas/maxPr;
    ctx.fillStyle=col; _infRoundRect(ctx,trackX,y,Math.max(36,trackW*pct),34,8); ctx.fill();
    ctx.fillStyle='#fff'; ctx.textAlign='left'; ctx.font='800 16px "Segoe UI",Arial';
    ctx.fillText(String(td.D.resumen.totalPruebas), trackX+Math.max(36,trackW*pct)+10, y+24);
    y+=52;
  });

  // Mini-cifras: participaciones y localidades
  y+=10;
  ctx.fillStyle='#e2e8f0'; ctx.font='800 18px "Segoe UI",Arial'; ctx.textAlign='left';
  ctx.fillText('Participaciones · Localidades · Media ciclistas/prueba', 50, y); y+=12;
  C.teamsData.forEach((td,i)=>{
    y+=34;
    const col=_INF_PALETTE[i%_INF_PALETTE.length];
    ctx.fillStyle=col; _infRoundRect(ctx,50,y-18,12,12,3); ctx.fill();
    ctx.fillStyle='#cbd5e1'; ctx.font='700 15px "Segoe UI",Arial';
    ctx.fillText(`${td.team.name.slice(0,26)}:  ${td.D.resumen.participaciones} part.  ·  ${td.D.resumen.localidades.length} local.  ·  ${td.D.resumen.mediaPorPrueba?td.D.resumen.mediaPorPrueba.toFixed(1):'—'} cicl./prueba`, 72, y-6);
  });

  // Disclaimer pie
  ctx.fillStyle='#fb923c'; ctx.font='600 12px "Segoe UI",Arial'; ctx.textAlign='center';
  const disc='Basado únicamente en los datos registrados en la aplicación. Pueden faltar pruebas o participaciones.';
  ctx.fillText(disc, W/2, H-22);

  cv.toBlob((blob)=>{
    const url=URL.createObjectURL(blob); const a=document.createElement('a');
    a.href=url; a.download=`comparativa_${opts.year}_uso-interno.png`;
    document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),1000);
    if(st) st.textContent='✅ Infografía comparativa descargada (uso interno).';
  },'image/png');
}

// ── Diagnóstico cuando no se encuentran pruebas ──────────────────────────
function _infDiagNoData(history, year, teamKeyWanted){
  const counts={};
  // Categorías reales del equipo seleccionado, para detectar discrepancias
  const teamCats={};
  for(const race of (history||[])){
    const ry=(_parseSpanishDate(race.raceDate)||'').slice(0,4);
    if(year && ry!==year) continue;
    for(const r of (race.riders||[])){
      const t=(r.team||'').trim(); if(t) counts[t]=(counts[t]||0)+1;
      if(teamKeyWanted && typeof teamKey==='function' && teamKey(t)===teamKeyWanted){
        const c=(r.cat||'').trim()||'(sin categoría)';
        teamCats[c]=(teamCats[c]||0)+1;
      }
    }
  }
  if(!Object.keys(counts).length) return `⚠️ No hay datos cargados para ${escapeHtml(year)}. Comprueba que el historial de esa temporada está cargado.`;
  // Si el equipo SÍ tiene participaciones pero el filtro las descarta, muéstralo
  if(teamKeyWanted && Object.keys(teamCats).length){
    const cats=Object.entries(teamCats).sort((a,b)=>b[1]-a[1]).map(([c,n])=>escapeHtml(c)+' ('+n+')').join(', ');
    return `⚠️ El equipo tiene participaciones en ${escapeHtml(year)}, pero ningún resultado pasa los filtros (probablemente la <b>categoría</b>).<br><span style="color:#64748b">Categorías registradas para este equipo: ${cats}.</span><br>Prueba con <b>categoría «Ambas»</b> o ajusta el estado/filtros.`;
  }
  const top=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,8);
  return `⚠️ No se encontraron pruebas con los filtros aplicados.<br><span style="color:#64748b">Equipos con más participaciones en ${escapeHtml(year)}: ${top.map(([t,n])=>escapeHtml(t)+' ('+n+')').join(', ')}.</span><br>Ajusta el equipo, la categoría o los filtros y vuelve a intentarlo.`;
}

/* ═══════════════════════ CALENDARIO ANUAL DE TEMPORADA ══════════════════
   12 meses en una sola página A4 apaisada, días coloreados por categoría
   (Comunitat Valenciana / Fuera CV / Challenge CV), leyenda cronológica,
   logo y título. Exporta PDF (impresión A4 horizontal) y PNG alta resolución.
   Se construye una sola vez como SVG y se usa para ambos formatos.
   ═══════════════════════════════════════════════════════════════════════ */
const _INF_MESES = ['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'];
const _INF_MES_CORTO = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
const _INF_DOW = ['L','M','X','J','V','S','D'];

function _infIsCVProv(prov){
  const p=(prov||'').toUpperCase();
  return /ALICANTE|ALACANT|CASTELL|VALENCIA|VAL[ÈE]NCIA/.test(p);
}
// Clasifica una prueba en una de las 3 categorías visuales
function _infRaceCategoria(r){
  // Challenge CV = SOLO las pruebas con el checkbox "Challenge CV" activado al introducirlas
  if(r.challengeCV) return {cat:3, label:'Challenge CV', color:_INF_CAL_COLORS.challenge};
  // Determina la comunidad por todas las señales (ccaa guardada, provincia, nombre, localidad)
  const ccaa = _infDetectCCAA(r.name, r.localidad, r.prov, r.ccaa);
  // Fuera de CV solo si se ha identificado una comunidad distinta de la Valenciana.
  // Si no hay ninguna pista, se asume CV (calendario de la federación valenciana).
  if(ccaa && ccaa!=='Comunitat Valenciana'){
    return {cat:2, label:'Fuera Comunidad Valenciana', color:_INF_CAL_COLORS.fuera};
  }
  return {cat:1, label:'Comunidad Valenciana', color:_INF_CAL_COLORS.cv};
}

// Construye el SVG completo del calendario anual (A4 apaisado, viewBox 1123x794)
function _infBuildAnnualSVG(year, teamName, races, catLabel){
  const W=1123, H=794, esTBG=/tbg|wixum/i.test(teamName);
  // Mapa: monthIdx -> { day -> {color, planned, items:[...]} }
  const byMonth = Array.from({length:12},()=>({}));
  races.forEach(r=>{
    if(!r.iso) return;
    const [y,m,d] = r.iso.split('-').map(Number);
    if(String(y)!==String(year)) return;
    const mi=m-1, day=d;
    const catInfo = r._catInfo;
    const cell = byMonth[mi][day] || (byMonth[mi][day]={color:null, planned:true, items:[], cat:0});
    cell.items.push(r);
    if(r.estado==='realizada'){
      cell.planned=false;
      // prioridad: Challenge(3) > Fuera(2) > CV(1)
      if(catInfo.cat >= cell.cat){ cell.cat=catInfo.cat; cell.color=catInfo.color; }
    } else if(cell.color==null){
      cell.color=_INF_CAL_COLORS.planned;
    }
  });

  // Layout meses: 4 columnas x 3 filas
  const cols=4, rows=3;
  const gridTop=120, gridLeft=24, gridRight=24, gridBottom=H-250;
  const cellW=(W-gridLeft-gridRight)/cols;
  const cellH=(gridBottom-gridTop)/rows;
  const pad=10;

  let svg='';
  // Fondo
  svg+=`<rect x="0" y="0" width="${W}" height="${H}" fill="#ffffff"/>`;
  // Cabecera
  svg+=`<rect x="0" y="0" width="${W}" height="92" fill="#0e4d73"/>`;
  svg+=`<rect x="0" y="92" width="${W}" height="6" fill="#f5c518"/>`;
  svg+=`<text x="40" y="44" font-family="Segoe UI,Arial,sans-serif" font-size="30" font-weight="900" fill="#ffffff">CALENDARIO DE COMPETICIONES</text>`;
  svg+=`<text x="40" y="76" font-family="Segoe UI,Arial,sans-serif" font-size="20" font-weight="700" fill="#cde8f7">TEMPORADA ${year} · ${_infEsc(teamName)}${catLabel?' · '+_infEsc(catLabel):''}</text>`;
  // Logo arriba derecha
  if(esTBG){ svg+=`<g transform="translate(${W-104},10)"><rect x="-6" y="-2" width="84" height="84" rx="12" fill="#ffffff"/><svg x="2" y="6" width="64" height="64" viewBox="0 0 310 310">${_infLogoInner()}</svg></g>`; }
  else { svg+=`<circle cx="${W-58}" cy="46" r="34" fill="#ffffff"/><text x="${W-58}" y="56" font-family="Segoe UI,Arial" font-size="26" font-weight="900" fill="#0e4d73" text-anchor="middle">${_infEsc((teamName||'').slice(0,2).toUpperCase())}</text>`; }

  // Leyenda de colores (bajo cabecera)
  const leg=[['Comunidad Valenciana',_INF_CAL_COLORS.cv],['Fuera Comunidad Valenciana',_INF_CAL_COLORS.fuera],['Challenge CV',_INF_CAL_COLORS.challenge]];
  let lx=40;
  leg.forEach(([lab,col])=>{
    svg+=`<rect x="${lx}" y="103" width="16" height="16" rx="3" fill="${col}"/>`;
    svg+=`<text x="${lx+22}" y="116" font-family="Segoe UI,Arial" font-size="13" font-weight="700" fill="#334155">${_infEsc(lab)}</text>`;
    lx += 30 + lab.length*7.2;
  });

  // Meses
  for(let mi=0; mi<12; mi++){
    const c=mi%cols, rRow=Math.floor(mi/cols);
    const mx=gridLeft+c*cellW, my=gridTop+rRow*cellH;
    const innerW=cellW-pad*2, innerX=mx+pad;
    // Cabecera del mes
    svg+=`<rect x="${innerX}" y="${my}" width="${innerW}" height="22" rx="5" fill="#0e4d73"/>`;
    svg+=`<text x="${innerX+innerW/2}" y="${my+15}" font-family="Segoe UI,Arial" font-size="12.5" font-weight="800" fill="#fff" text-anchor="middle">${_INF_MESES[mi]}</text>`;
    // Cuadrícula de días
    const gx=innerX, gy=my+26;
    const dcw=innerW/7, dch=(cellH-34)/7; // 1 fila cabecera + 6 filas
    // Cabecera días
    for(let i=0;i<7;i++){
      svg+=`<text x="${gx+dcw*i+dcw/2}" y="${gy+9}" font-family="Segoe UI,Arial" font-size="9" font-weight="800" fill="#94a3b8" text-anchor="middle">${_INF_DOW[i]}</text>`;
    }
    // Días
    const first=new Date(year,mi,1); let dow=first.getDay()-1; if(dow<0) dow=6;
    const ndays=new Date(year,mi+1,0).getDate();
    for(let day=1; day<=ndays; day++){
      const idx=dow+day-1; const col=idx%7, row=Math.floor(idx/7);
      const x=gx+col*dcw, y=gy+12+row*dch;
      const cell=byMonth[mi][day];
      let numColor='#475569';
      if(cell){
        if(cell.planned && cell.color===_INF_CAL_COLORS.planned){
          svg+=`<rect x="${x+1}" y="${y}" width="${dcw-2}" height="${dch-1}" rx="3" fill="none" stroke="${cell.color}" stroke-width="1.5" stroke-dasharray="2,2"/>`;
          numColor='#475569';
        } else {
          svg+=`<rect x="${x+1}" y="${y}" width="${dcw-2}" height="${dch-1}" rx="3" fill="${cell.color}"/>`;
          numColor='#ffffff';
        }
      }
      svg+=`<text x="${x+dcw/2}" y="${y+dch/2+3}" font-family="Segoe UI,Arial" font-size="10" font-weight="${cell?'800':'600'}" fill="${numColor}" text-anchor="middle">${day}</text>`;
    }
  }

  // ── Leyenda inferior: relación cronológica de todas las pruebas ──
  const legY=gridBottom+14;
  svg+=`<line x1="40" y1="${legY-6}" x2="${W-40}" y2="${legY-6}" stroke="#e2e8f0" stroke-width="1.5"/>`;
  svg+=`<text x="40" y="${legY+18}" font-family="Segoe UI,Arial" font-size="14" font-weight="900" fill="#0e4d73">RELACIÓN DE COMPETICIONES (${races.length})</text>`;
  // Separación clara entre la línea/cabecera y el listado de pruebas
  const listTop=legY+42;
  const ncols=3, colGap=22;
  const colW=(W-80-(ncols-1)*colGap)/ncols;
  const fontPx=9, charW=4.95, boxOff=14;
  const perCol=Math.max(1, Math.ceil(races.length/ncols));
  const lineH=Math.min(15, Math.max(11,(H-listTop-16)/perCol));
  const maxChars=Math.max(8, Math.floor((colW-boxOff)/charW));
  races.forEach((r,i)=>{
    const col=Math.floor(i/perCol), row=i%perCol;
    if(col>=ncols) return;
    const x=40+col*(colW+colGap), y=listTop+row*lineH;
    const ci=r._catInfo;
    svg+=`<rect x="${x}" y="${y-7}" width="9" height="9" rx="2" fill="${r.estado==='realizada'?ci.color:_INF_CAL_COLORS.planned}"/>`;
    const fecha=`${(r.iso.split('-')[2])} ${_INF_MES_CORTO[parseInt(r.iso.split('-')[1])-1]}`;
    let txt=`${fecha} · ${r.name}`;
    if(txt.length>maxChars) txt=txt.slice(0,maxChars-1).trimEnd()+'…';
    svg+=`<text x="${x+boxOff}" y="${y}" font-family="Segoe UI,Arial" font-size="${fontPx}" font-weight="700" fill="#1f2937">${_infEsc(txt)}</text>`;
  });

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" font-family="Segoe UI,Arial,sans-serif">${svg}</svg>`;
}
function _infEsc(s){ return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

// Estado del calendario anual ya generado (para exportar sin recalcular)
let _infAnnualSVG=null, _infAnnualYear=null, _infAnnualTeam=null;

// Botón único → genera el SVG y abre la previsualización dentro de la app
async function _infGenerateAnnual(){
  const opts=_infReadOpts();
  const st=document.getElementById('_infStatus');
  if(!opts.teams.length){ if(st) st.textContent='⚠️ Selecciona un equipo.'; return; }
  if(st) st.textContent='⏳ Generando calendario anual…';
  let history=[]; try{ history=await _ensureHistory(); }catch(_){ history=(typeof _cachedHistory!=='undefined'?_cachedHistory:[])||[]; }
  const team=opts.teams[0];
  // Para el calendario anual incluimos realizadas + planificadas si procede
  const D=_infBuildDataByKey(history, Object.assign(_infFilters(opts, team), {includePlanned:true}));
  let races=[...D.realizadas, ...D.planificadas].filter(r=>r.iso);
  races.sort((a,b)=>(a.iso||'').localeCompare(b.iso||''));
  if(!races.length){ if(st) st.innerHTML=_infDiagNoData(history, opts.year, team.key); return; }
  races.forEach(r=>{ r._catInfo=_infRaceCategoria(r); });

  const catLabel = opts.catSel ? _infCatLabel(opts.catSel) : '';
  _infAnnualSVG=_infBuildAnnualSVG(opts.year, team.name, races, catLabel);
  _infAnnualYear=opts.year; _infAnnualTeam=team.name;
  _infShowAnnualPreview();
  if(st) st.textContent='✅ Calendario anual generado. Revísalo y expórtalo.';
}

// Modal de previsualización: muestra el calendario y ofrece exportar a PDF o PNG
function _infShowAnnualPreview(){
  let ov=document.getElementById('_infAnnualOverlay');
  if(ov) ov.remove();
  ov=document.createElement('div');
  ov.id='_infAnnualOverlay';
  ov.style.cssText='position:fixed;inset:0;z-index:100000;background:rgba(15,23,42,.75);display:flex;flex-direction:column;align-items:center;justify-content:flex-start;padding:18px;overflow:auto;font-family:Segoe UI,Arial,sans-serif';
  ov.innerHTML=`
    <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:12px">
      <span style="color:#fff;font-weight:800;font-size:15px;margin-right:6px">📅 Calendario ${escapeHtml(_infAnnualTeam)} · ${escapeHtml(_infAnnualYear)}</span>
      <button id="_infAnnBtnPDF" style="background:linear-gradient(135deg,#0e4d73,#2B91C8);color:#fff;border:none;border-radius:9px;padding:10px 16px;font-weight:800;font-size:13px;cursor:pointer">🖨️ Imprimir / Guardar PDF</button>
      <button id="_infAnnBtnPNG" style="background:#0e4d73;color:#fff;border:none;border-radius:9px;padding:10px 16px;font-weight:800;font-size:13px;cursor:pointer">🖼️ Descargar PNG</button>
      <button id="_infAnnBtnClose" style="background:#f3f4f6;color:#374151;border:1px solid #d0d5dd;border-radius:9px;padding:10px 16px;font-weight:800;font-size:13px;cursor:pointer">✕ Cerrar</button>
    </div>
    <div style="background:#fff;border-radius:8px;box-shadow:0 12px 40px rgba(0,0,0,.4);width:min(100%,1123px);max-width:1123px">
      <div style="width:100%">${_infAnnualSVG}</div>
    </div>`;
  // El SVG ya trae width/height fijos; lo hacemos responsive dentro del contenedor
  const svgEl=ov.querySelector('svg'); if(svgEl){ svgEl.removeAttribute('width'); svgEl.removeAttribute('height'); svgEl.style.width='100%'; svgEl.style.height='auto'; svgEl.style.display='block'; }
  document.body.appendChild(ov);
  ov.querySelector('#_infAnnBtnClose').onclick=()=>ov.remove();
  ov.addEventListener('click',(e)=>{ if(e.target===ov) ov.remove(); });
  ov.querySelector('#_infAnnBtnPDF').onclick=_infAnnualToPDF;
  ov.querySelector('#_infAnnBtnPNG').onclick=_infAnnualToPNG;
}

function _infAnnualToPDF(){
  if(!_infAnnualSVG) return;
  const w=window.open('','_blank');
  if(!w){ alert('El navegador bloqueó la ventana. Permite ventanas emergentes e inténtalo de nuevo.'); return; }
  w.document.write(`<!DOCTYPE html><html lang="es"><head><meta charset="utf-8">
  <title>Calendario de competiciones ${escapeHtml(_infAnnualYear)} – ${escapeHtml(_infAnnualTeam)}</title>
  <style>
    @page{size:A4 landscape;margin:0}
    *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}
    html,body{margin:0;padding:0}
    .cal{width:100%;height:100vh;display:flex;align-items:center;justify-content:center}
    .cal svg{width:100%;height:auto;max-height:100vh}
  </style></head><body>
  <div class="cal">${_infAnnualSVG}</div>
  <script>window.onload=function(){setTimeout(function(){window.print();},350);};<\/script>
  </body></html>`);
  w.document.close();
}

async function _infAnnualToPNG(){
  if(!_infAnnualSVG) return;
  const scale=2.2, W=1123, H=794;
  const cv=document.createElement('canvas'); cv.width=Math.round(W*scale); cv.height=Math.round(H*scale);
  const ctx=cv.getContext('2d');
  ctx.fillStyle='#fff'; ctx.fillRect(0,0,cv.width,cv.height);
  ctx.scale(scale,scale);
  await _infDrawSVGToCanvas(ctx, _infAnnualSVG, 0,0,W,H);
  cv.toBlob((blob)=>{
    const url=URL.createObjectURL(blob); const a=document.createElement('a');
    const safe=String(_infAnnualTeam).replace(/[^a-z0-9]+/gi,'-');
    a.href=url; a.download=`calendario_${safe}_${_infAnnualYear}.png`;
    document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),1000);
  },'image/png');
}

/* ═══════════════════════════════════════════════════════════════════════════
   MÓDULO: EXPORTACIÓN MASIVA DE DATOS (DATA LAKE) PARA MODELO PREDICTIVO
   Genera un CSV tabular "sábana": 1 fila = 1 ciclista en 1 carrera.
   JOIN de races + notes(clima/track) + race_results + rider_efforts_fccv.
   Aplana dinámicamente cualquier campo escalar presente en notes.
   No inventa datos: lo que no existe queda vacío.
   ═══════════════════════════════════════════════════════════════════════════ */

// Orden y nombres de las columnas OBLIGATORIAS (el resto se añaden tras estas)
const _DX_BASE_COLS = [
  'ID_Carrera','Fecha','Nombre_Prueba','Localidad','Comunidad_Autonoma',
  'Categoria_Prueba','Modalidad','Es_Challenge',
  'Ciclistas_Inscritos','Ciclistas_Finalizados',
  'Inscritos_Categoria','Finalizados_Categoria',
  'ID_Ciclista','Nombre_Ciclista','Equipo_Ciclista','Categoria_Ciclista','Region_Ciclista',
  'Posicion_Final','Puntos_Obtenidos',
  'Dorsal','Tiempo','Gap_Segundos','Tiempo_Total_Segundos'
];

function _dxNormName(s){ return String(s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,' ').trim(); }
function _dxYield(){ return new Promise(r=>setTimeout(r,0)); }

// Normalización ESTRICTA de categoría a formato con guion: CAD-1 / CAD-2 / JUV-1 / JUV-2.
// Si es cadete/juvenil pero no se puede determinar el año, devuelve CADETE / JUVENIL.
// Cualquier otra categoría se devuelve tal cual (sin inventar).
function _dxNormCat(raw){
  const s=String(raw||'').trim();
  if(!s) return '';
  const up=s.toUpperCase();
  const ym=up.match(/[12]/);            // primer dígito 1 o 2 = año (CAD-1, "-2,00 CAD", "Cadete 2º"…)
  const year=ym?ym[0]:null;
  if(/JUV|JUNIOR|J[UÚ]NIOR/.test(up)) return year?('JUV-'+year):'JUVENIL';
  if(/CAD/.test(up))                  return year?('CAD-'+year):'CADETE';
  return s;
}

// Aplana escalares de un objeto a target con prefijo. Recurre en objetos planos. Ignora arrays.
function _dxAddScalars(target, obj, prefix, skip){
  if(!obj || typeof obj!=='object') return;
  for(const k in obj){
    if(skip && skip.has(k)) continue;
    const v = obj[k];
    if(v==null){ target[prefix+k]=''; continue; }
    const t = typeof v;
    if(t==='string'||t==='number'||t==='boolean'){ target[prefix+k]=v; }
    else if(Array.isArray(v)){ /* arrays: se tratan aparte (inscritos, regions, points) */ }
    else if(t==='object'){ _dxAddScalars(target, v, prefix+k+'_', skip); }
  }
}

// Abre el modal de exportación
